def _is_audited_moria_sanctuary_capacity_candidate(
    candidate: HuntCandidate,
    object_vnums: Collection[int],
) -> bool:
    """Return whether a candidate matches the audited two-room source."""
    return bool(
        candidate.mobile_vnum == _MORIA_SANCTUARY_CARRIER_MOBILE_VNUM
        and candidate.room_vnum in _MORIA_SANCTUARY_CAPACITY_SOURCE_ROOMS
        and _MORIA_SANCTUARY_POTION_OBJECT_VNUM in {
            int(vnum) for vnum in object_vnums
        }
        and candidate.source_spawn_limit == 2
        and candidate.room_spawn_count == 1
        and candidate.autonomy_rejections
        == ("target reset capacity exceeds one",)
        and not candidate.specials
    )


def _moria_deep_sanctuary_requires_flight(
    character_class: str,
    character_level: int | None,
) -> bool:
    """Keep deep-route flight requirements aligned between policy and runner."""
    level = character_level or 0
    return level >= 19 or (
        character_class.casefold() == "mage" and level >= 16
    )


def _moria_sanctuary_flight_reserve_sufficient(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_class: str,
    character_level: int | None,
    has_flight: bool,
) -> bool:
    """Require enough verified flight duration for the deep Moria route."""
    route_requires_flight = bool(
        candidate.requires_flight
        or _moria_deep_sanctuary_requires_flight(
            character_class,
            character_level,
        )
    )
    if not route_requires_flight:
        return True
    duration = _state_flight_duration(state.get("affects"))
    minimum_duration = max(
        2,
        _source_ranked_candidate_required_flight_duration(candidate) or 0,
    )
    return bool(
        has_flight
        and duration is not None
        and duration >= minimum_duration
    )


def _moria_sanctuary_capacity_probe_allowed(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    object_vnums: Collection[int],
    *,
    automatic_reset_wait: bool = False,
) -> bool:
    """Allow one reset-aged capacity probe only for the exact Moria carrier.

    This source-narrowed entitlement is separate from the exhausted general
    sanctuary retry and does not reopen that recovery policy.
    """
    return bool(
        _moria_sanctuary_capacity_reset_wait_available(
            state,
            automatic_reset_wait=automatic_reset_wait,
        )
        and _is_audited_moria_sanctuary_capacity_candidate(
            candidate,
            object_vnums,
        )
    )


def _moria_sanctuary_capacity_reset_wait_available(
    state: Mapping[str, Any],
    *,
    automatic_reset_wait: bool = False,
) -> bool:
    """Keep a terminal one-shot sanctuary recheck closed at both gates."""
    return bool(
        _source_capacity_reset_wait_available(
            state,
            automatic_reset_wait=automatic_reset_wait,
        )
        and not _sanctuary_area_reset_recheck_spent_for_policy(
            state,
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
        )
    )


