def _research_retry_cooldown_active(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether same-reboot research evidence still blocks a retry."""
    if (
        policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and _sanctuary_recovery_attempts_exhausted(state, policy_id=policy_id)
    ):
        return True
    if (
        (
            policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            and _sanctuary_resource_revalidation_pending(state)
        )
        or _sanctuary_combat_only_transit_revalidation_pending(
            state,
            policy_id=policy_id,
        )
    ):
        return False
    result = _campaign_research_results(dict(state)).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("completed_kill") is not True
    ):
        return False
    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = state.get(key) or {}
        try:
            if int(cooldowns.get(policy_id) or 0) > 0:
                return True
        except (AttributeError, TypeError, ValueError):
            continue
    return False


def _research_fatal_failure_active(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Keep a fatal live attempt blocked until level or reboot changes."""
    if (
        policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
        and _sanctuary_recovery_attempts_exhausted(state, policy_id=policy_id)
    ):
        return True
    if (
        (
            policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            and _sanctuary_resource_revalidation_pending(state)
        )
        or _sanctuary_combat_only_transit_revalidation_pending(
            state,
            policy_id=policy_id,
        )
    ):
        return False
    result = _campaign_research_results(dict(state)).get(policy_id)
    if (
        policy_id == _SOURCE_RANKED_DWARVEN_SANCTUARY_POLICY.policy_id
        and isinstance(result, Mapping)
        and result.get("dwarven_locked_key_gate") is True
        and _dwarven_key_gate_key_acquired(state)
    ):
        return False
    return bool(
        isinstance(result, Mapping)
        and result.get("fatal_failure") is True
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("level") == _level(state)
        and result.get("completed_kill") is not True
    )


def _sanctuary_policy_retry_terminal(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Keep a same-boot Sanctuary resource result from hiding its fallback."""
    if (
        _research_retry_cooldown_active(state, policy_id)
        or _research_fatal_failure_active(state, policy_id)
    ):
        return True
    if policy_id not in _SANCTUARY_RESOURCE_POLICY_IDS:
        return False
    carrier_stop = {
        _SOURCE_RANKED_OLYMPUS_SANCTUARY_POLICY.policy_id: (
            _OLYMPUS_SANCTUARY_CARRIER_MOBILE_VNUM,
            _OLYMPUS_SANCTUARY_CARRIER_ROOM_VNUM,
        ),
        _SOURCE_RANKED_OLYMPUS_ADEPT_SANCTUARY_POLICY.policy_id: (
            _OLYMPUS_ADEPT_SANCTUARY_CARRIER_MOBILE_VNUM,
            _OLYMPUS_ADEPT_SANCTUARY_CARRIER_ROOM_VNUM,
        ),
        _SOURCE_RANKED_OLYMPUS_HEPHAESTUS_SANCTUARY_POLICY.policy_id: (
            _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_MOBILE_VNUM,
            _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_ROOM_VNUM,
        ),
    }.get(policy_id)
    if carrier_stop is not None and _source_ranked_xp_loss_for_stop(
        state,
        mobile_vnum=carrier_stop[0],
        room_vnum=carrier_stop[1],
    ) is not None:
        return True
    result = _campaign_research_results(dict(state)).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("completed_kill") is not True
        and result.get("viable") is False
    )


def _is_retryable_source_ranked_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize dynamic source-ranked hazards that may clear after reset."""
    return bool(
        (
            policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            or policy_id.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX)
            or policy_id
            in {
                _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
                _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
                _SOURCE_RANKED_DWARVEN_SANCTUARY_POLICY.policy_id,
                _SOURCE_RANKED_FLIGHT_RESERVE_POLICY.policy_id,
                _SOURCE_RANKED_SANCTUARY_GROUND_POLICY.policy_id,
            }
        )
        and isinstance(route_hazard, str)
        and (
            route_hazard in {
                "summon familiar was not positively confirmed",
                "familiar group ownership was not positively confirmed",
                "familiar preparation exceeded its confirmation deadline",
                "summon familiar exhausted three recitation attempts",
                "insufficient observed mana for summon familiar",
            }
            or route_hazard.startswith((
                _SOURCE_RANKED_LOCATOR_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_ADJACENT_SCAN_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_REQUIRED_LOOT_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_LOW_RESERVE_ROUTE_HAZARD_PREFIX,
                "field route watchdog stopped:",
                _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD,
                _SOURCE_RANKED_RECALL_RECOVERY_ROUTE_HAZARD_PREFIX,
            ))
            or (
                route_hazard.startswith(_FIXED_ROUTE_DRUNK_PREFLIGHT_PREFIX)
                and route_hazard.endswith(_FIXED_ROUTE_DRUNK_PREFLIGHT_SUFFIX)
            )
        )
    )


def _is_retryable_dynamic_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize route hazards that may clear without a reboot."""
    return bool(
        route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        or _is_retryable_source_ranked_route_hazard(
            policy_id,
            route_hazard,
        )
    )


def _source_ranked_runtime_boundary_result(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Recognize a bounded route timeout that never inspected its target."""
    result = _campaign_research_results(dict(state)).get(policy_id)
    if not (
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("completed_kill") is not True
        and result.get("absent") is not True
    ):
        return False
    route_hazard = result.get("route_hazard")
    if route_hazard == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD:
        return True
    if not (
        isinstance(route_hazard, str)
        and route_hazard.startswith("field route endpoint not observed:")
    ):
        return False
    # A worker can record the same safe timeout twice: the first record keeps
    # the runtime-boundary reason, while recovery later replaces the result
    # text with a generic endpoint failure. Reconcile that wording change
    # only when the durable marker proves it was the same zero-kill timeout.
    records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if not isinstance(records, (list, tuple)):
        return False
    current_level = state.get("level")
    return any(
        isinstance(record, Mapping)
        and record.get("boot_id") == state.get("world_boot_id")
        and record.get("policy_id") == policy_id
        and record.get("level") in {None, current_level}
        and record.get("reason") == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD
        and record.get("objective_kill_count") in {None, 0}
        for record in records
    )


def _source_ranked_runtime_boundary_consider_result(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Recognize a timeout after a target was seen but before combat began."""
    result = _campaign_research_results(dict(state)).get(policy_id)
    raw_xp_delta = result.get("xp_delta", 0) if isinstance(result, Mapping) else 0
    try:
        xp_delta = int(raw_xp_delta or 0)
    except (TypeError, ValueError):
        return False
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is False
        and result.get("completed_kill") is False
        and result.get("retryable_failure") is True
        and result.get("xp_loss_observed") is not True
        and xp_delta >= 0
    ):
        return False
    return not any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
            "fatal_failure",
        )
    )


def _source_ranked_consider_fuzz_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    marker = state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY)
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if not (
        isinstance(marker, Mapping)
        and marker.get("status") == "pending"
        and marker.get("policy_id") == policy_id
        and marker.get("mobile_vnum") == candidate.mobile_vnum
        and marker.get("room_vnum") == candidate.room_vnum
        and marker.get("level") == character_level == state.get("level")
        and marker.get("world_boot_id") == state.get("world_boot_id")
        and marker.get("campaign_source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("xp") == state.get("xp")
        and marker.get("campaign_xp_loss_total")
        == state.get("campaign_xp_loss_total")
        and marker.get("source_level_range")
        == list(candidate.estimated_level_range)
        and marker.get("source_hp_ceiling")
        == candidate.estimated_base_hp_range[1]
        and marker.get("route") == list(candidate.route)
        and _source_ranked_xp_loss_record(state, policy_id) is None
        and policy_id not in _source_ranked_timeout_policy_ids(state)
    ):
        return False
    try:
        marker_offset = int(marker.get("maximum_level_offset"))
    except (TypeError, ValueError):
        return False
    expected_offset = max(
        5,
        candidate.estimated_level_range[1] - character_level,
    )
    return marker_offset == expected_offset


def _consume_source_ranked_consider_fuzz_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    if not _source_ranked_consider_fuzz_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = dict(state[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY])
    marker["status"] = "attempted"
    marker["attempted_at"] = datetime.now(timezone.utc).isoformat()
    state[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY] = marker
    history: list[dict[str, Any]] = []
    raw_history = state.get(
        _SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY
    )
    if isinstance(raw_history, (list, tuple)):
        history = [
            dict(record)
            for record in raw_history
            if isinstance(record, Mapping)
        ]
    receipt = {
        "world_boot_id": marker.get("world_boot_id"),
        "level": character_level,
        "policy_id": marker.get("policy_id"),
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "campaign_source_revision": marker.get("campaign_source_revision"),
        "reset_after_segment_id": marker.get("reset_after_segment_id"),
    }
    history = [
        record
        for record in history
        if not (
            record.get("world_boot_id") == receipt["world_boot_id"]
            and record.get("level") == receipt["level"]
            and record.get("policy_id") == receipt["policy_id"]
            and record.get("mobile_vnum") == receipt["mobile_vnum"]
            and record.get("room_vnum") == receipt["room_vnum"]
        )
    ]
    history.append(receipt)
    state[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY] = history[
        -_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_LIMIT:
    ]
    return True


def _close_source_ranked_consider_fuzz_revalidation(
    state: dict[str, Any],
    *,
    reason: str,
) -> bool:
    """Close an unselectable one-shot consider recheck before rotation.

    A pending marker is a contract for one exact source reset. If the
    ordinary selector can no longer surface that reset, leaving the marker
    pending would make a later, unrelated target fail at dispatch time.
    """
    marker = state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY)
    if not isinstance(marker, Mapping) or marker.get("status") != "pending":
        return False
    state[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "closed",
        "closed_at": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
    }
    return True


def _repair_source_ranked_consider_fuzz_revalidation_history(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover same-boot consider rechecks from bounded segment snapshots.

    The history field was added after some current-boot probes had already
    been recorded. Rebuild only the current level, boot, and source revision
    from recent end states so an unrelated later reset cannot reopen those
    exact negatives.
    """
    boot_id = state.get("world_boot_id")
    try:
        character_level = int(state.get("level"))
    except (TypeError, ValueError):
        return dict(state)
    source_revision = str(state.get(_SOURCE_REVISION_KEY) or "")
    if not boot_id:
        return dict(state)

    history: list[dict[str, Any]] = []

    def append_marker(marker: object) -> None:
        if not isinstance(marker, Mapping):
            return
        if marker.get("status") not in {"attempted", "closed"}:
            return
        if marker.get("world_boot_id") != boot_id:
            return
        try:
            marker_level = int(marker.get("level"))
        except (TypeError, ValueError):
            return
        if marker_level != character_level:
            return
        marker_revision = str(
            marker.get("campaign_source_revision") or ""
        )
        if source_revision and marker_revision and marker_revision != source_revision:
            return
        policy_id = str(marker.get("policy_id") or "")
        if not policy_id:
            return
        receipt: dict[str, Any] = {
            "world_boot_id": boot_id,
            "level": character_level,
            "policy_id": policy_id,
            "campaign_source_revision": marker_revision or source_revision,
        }
        for field in (
            "mobile_vnum",
            "room_vnum",
            "reset_after_segment_id",
        ):
            if marker.get(field) is not None:
                receipt[field] = marker[field]
        history[:] = [
            record
            for record in history
            if not (
                record.get("world_boot_id") == receipt["world_boot_id"]
                and record.get("level") == receipt["level"]
                and record.get("policy_id") == receipt["policy_id"]
                and record.get("mobile_vnum") == receipt.get("mobile_vnum")
                and record.get("room_vnum") == receipt.get("room_vnum")
            )
        ]
        history.append(receipt)

    raw_history = state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY)
    if isinstance(raw_history, (list, tuple)):
        for record in raw_history:
            if isinstance(record, Mapping):
                append_marker({**dict(record), "status": "attempted"})

    for raw_segment in tuple(segments)[-_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:]:
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {
                    key: raw_segment[key] for key in raw_segment.keys()
                }
            except (AttributeError, KeyError, TypeError):
                continue
        raw_end_state = segment.get("end_state_json")
        if not raw_end_state:
            continue
        try:
            end_state = (
                json.loads(raw_end_state)
                if isinstance(raw_end_state, str)
                else raw_end_state
            )
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        append_marker(
            end_state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY)
        )

    append_marker(state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY))
    repaired = dict(state)
    if history:
        repaired[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY] = history[
            -_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_LIMIT:
        ]
    else:
        repaired.pop(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY, None)
    return repaired


def _arm_source_ranked_consider_revalidation_after_reset(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
    excluded_policy_ids: Collection[str] = (),
    blocked_policy_ids: Collection[str] = (),
) -> dict[str, Any]:
    """Open one exact live ``consider`` recheck after an area-reset wait.

    A negative live consider remains durable evidence for this reboot. The
    explicit reset wait is the only event that can open a single fresh check,
    because DD4 reloads mobile instances during area resets. This helper never
    authorizes combat; the selected route still has to pass live identity,
    isolation, and consider gates again.
    """
    reset_marker = state.get(_SOURCE_RANKED_CONSIDER_RESET_WAIT_KEY)
    if not (
        isinstance(reset_marker, Mapping)
        and reset_marker.get("boot_id") == state.get("world_boot_id")
        and reset_marker.get("level") == character_level
        and type(reset_marker.get("after_segment_id")) is int
    ):
        return state
    existing = state.get(_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY)
    if isinstance(existing, Mapping):
        if existing.get("status") == "pending":
            return state
        if existing.get("reset_after_segment_id") == reset_marker.get(
            "after_segment_id"
        ):
            return state
    attempted_revalidation_policy_ids: set[str] = set()
    if (
        isinstance(existing, Mapping)
        and existing.get("status") in {"attempted", "closed"}
        and existing.get("world_boot_id") == state.get("world_boot_id")
        and existing.get("level") == character_level
    ):
        existing_policy_id = str(existing.get("policy_id") or "")
        if existing_policy_id:
            attempted_revalidation_policy_ids.add(existing_policy_id)
    raw_history = state.get(
        _SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_HISTORY_KEY
    )
    if isinstance(raw_history, (list, tuple)):
        attempted_revalidation_policy_ids.update(
            str(record.get("policy_id") or "")
            for record in raw_history
            if (
                isinstance(record, Mapping)
                and record.get("world_boot_id") == state.get("world_boot_id")
                and record.get("level") == character_level
                and record.get("policy_id")
            )
        )
    if (
        source_world is None
        or not state.get("world_boot_id")
        or not state.get(_SOURCE_REVISION_KEY)
        or not isinstance(state.get("xp"), int)
        or not isinstance(state.get("campaign_xp_loss_total"), int)
        or state.get("dead")
        or state.get("in_combat")
    ):
        return state

    excluded = {str(value) for value in excluded_policy_ids}
    blocked = {str(value) for value in blocked_policy_ids}
    matches: list[tuple[HuntCandidate, str, Mapping[str, Any]]] = []
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if policy_id in excluded or policy_id in blocked:
            continue
        if (
            policy_id in attempted_revalidation_policy_ids
            and _source_ranked_candidate_excluded_by_below_band_evidence(
                candidate,
                state,
                character_level=character_level,
            )
        ):
            # A second area reset does not erase an exact live negative that
            # already consumed this candidate's one revalidation. Let the
            # next source-ranked candidate own the new reset probe.
            continue
        if (
            not candidate.autonomous_safe
            or candidate.is_coin_stash
            or candidate.specials
            or candidate.equipped_weapons
            or candidate.source_spawn_limit != 1
            or candidate.room_spawn_count != 1
            or candidate.route_hard_hazard_targets
            or candidate.route_preflight_hard_hazard
            or candidate.estimated_level_range[1] > character_level + 5
            or _source_ranked_xp_loss_record(state, policy_id) is not None
            or not _source_ranked_candidate_excluded_by_below_band_evidence(
                candidate,
                state,
                character_level=character_level,
            )
            or not _source_ranked_candidate_in_current_band(
                candidate,
                state,
                world=source_world,
                character_level=character_level,
                character_max_hp=(
                    int(state["max_hp"])
                    if isinstance(state.get("max_hp"), (int, float))
                    and state.get("max_hp", 0) > 0
                    else None
                ),
            )
        ):
            continue
        mobile = source_world.mobiles.get(candidate.mobile_vnum)
        if (
            mobile is None
            or mobile.aggressive
            or mobile.fear_aura
            or mobile.non_corporeal
            or mobile.programs
            or source_world.mobile_specials.get(candidate.mobile_vnum)
        ):
            continue
        result = _campaign_research_results(state).get(policy_id)
        if isinstance(result, Mapping):
            try:
                xp_delta = int(result.get("xp_delta") or 0)
            except (TypeError, ValueError):
                continue
            if not (
                result.get("boot_id") == state.get("world_boot_id")
                and result.get("observed") is True
                and result.get("consider_viable") is False
                and result.get("completed_kill") is False
                and result.get("viable") is False
                and not result.get("crowded")
                and not result.get("route_hazard")
                and not result.get("fatal_failure")
                and not result.get("target_vnum_mismatch")
                and xp_delta <= 0
            ):
                continue
        else:
            # Later evidence repair may compact the original research row,
            # but the exact source-keyed below-band exclusion is retained.
            # The source identity, level, boot and no-loss checks above still
            # make this a one-candidate recheck rather than a generic retry.
            result = {
                "reason": "persisted source-keyed below-band exclusion",
            }
        matches.append((candidate, policy_id, result))
    if not matches:
        return state

    candidate, policy_id, result = max(
        matches,
        key=lambda item: (
            _source_ranked_useful_fuzz_probability(
                item[0],
                character_level=character_level,
            ),
            float(item[0].score) / max(1, len(item[0].route)),
            float(item[0].estimated_level_range[1]),
            -len(item[0].route),
            int(item[0].mobile_vnum),
            int(item[0].room_vnum),
        ),
    )
    state[_SOURCE_RANKED_CONSIDER_FUZZ_REVALIDATION_KEY] = {
        "level": character_level,
        "world_boot_id": state.get("world_boot_id"),
        "campaign_source_revision": state.get(_SOURCE_REVISION_KEY),
        "xp": state.get("xp"),
        "campaign_xp_loss_total": state.get("campaign_xp_loss_total"),
        "status": "pending",
        "policy_id": policy_id,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "maximum_level_offset": max(
            5,
            candidate.estimated_level_range[1] - character_level,
        ),
        "source_level_range": list(candidate.estimated_level_range),
        "source_hp_ceiling": int(candidate.estimated_base_hp_range[1]),
        "route": list(candidate.route),
        "prior_result": dict(result),
        "reset_after_segment_id": reset_marker.get("after_segment_id"),
        "reason": "one live consider recheck after an explicit area-reset wait",
    }
    return state


def _source_ranked_consider_fuzz_revalidation_should_defer(
    exact_candidate: HuntCandidate,
    selected_candidate: HuntCandidate | None,
    selected_status: str | None,
    *,
    character_level: int,
    other_revalidation_selected: bool = False,
) -> bool:
    """Keep a weak reset probe from starving a likely-current hunt.

    An area reset can make one old below-band ``consider`` worth checking
    again, but that check is a fallback. If the ordinary selector already
    found a different candidate with at least a 50% chance of landing in the
    useful band, spending a whole segment on a weaker edge-level probe is
    counterproductive. The pending marker remains valid and will be used
    after the ordinary candidate changes or becomes unavailable.
    """
    if (
        selected_candidate is None
        or other_revalidation_selected
        or selected_status not in {"fresh", "productive", "retryable"}
    ):
        return False
    if _source_ranked_policy_id(
        exact_candidate,
        character_level=character_level,
    ) == _source_ranked_policy_id(
        selected_candidate,
        character_level=character_level,
    ):
        return False
    exact_probability = _source_ranked_useful_fuzz_probability(
        exact_candidate,
        character_level=character_level,
    )
    selected_probability = _source_ranked_useful_fuzz_probability(
        selected_candidate,
        character_level=character_level,
    )
    return (
        exact_probability < _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
        and selected_probability
        >= _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
    )


def _repair_retryable_dynamic_route_hazards(state: dict[str, Any]) -> dict[str, Any]:
    """Classify temporary failures without clearing their bounded retry evidence."""
    results = _campaign_research_results(state)
    migrated = dict(results)
    for policy_id, result in results.items():
        if (
            (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                or policy_id.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX)
            )
            and isinstance(result, Mapping)
            and result.get("completed_kill") is not True
            and result.get("fatal_failure") is not True
            and result.get("consider_viable") is not False
            and result.get("retryable_failure") is not True
            and _is_retryable_dynamic_route_hazard(policy_id, result.get("route_hazard"))
        ):
            migrated[policy_id] = {**result, "retryable_failure": True}
    updated = (
        {**state, "campaign_research_results": migrated}
        if migrated != results
        else state
    )
    timeout_policy_ids = _source_ranked_timeout_policy_ids(updated)
    for policy_id, result in migrated.items():
        if not _source_ranked_runtime_boundary_result(updated, policy_id):
            continue
        if policy_id not in timeout_policy_ids:
            try:
                level = int(
                    result.get("level")
                    or updated.get("level")
                    or 0
                )
            except (AttributeError, TypeError, ValueError):
                level = 0
            if level > 0:
                updated = _remember_source_ranked_timeout(
                    updated,
                    policy_id=policy_id,
                    level=level,
                    boot_id=result.get("boot_id"),
                    reason=_SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD,
                )
                timeout_policy_ids.add(policy_id)
        current_cooldowns = updated.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        if policy_id in current_cooldowns:
            updated = dict(updated)
            absence_cooldowns = dict(current_cooldowns)
            absence_cooldowns.pop(policy_id, None)
            if absence_cooldowns:
                updated[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
            else:
                updated.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    return updated


def _campaign_has_shadow_grove_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Return whether this reboot has blocked the shared Shadow Grove route."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return False
    marker = state.get(_SHADOW_GROVE_ROUTE_HAZARD_KEY)
    if isinstance(marker, Mapping) and marker.get("boot_id") == boot_id:
        return True
    last_policy_id = str(state.get("campaign_last_policy") or "")
    research_results = _campaign_research_results(dict(state))
    for policy_id, result in research_results.items():
        if not isinstance(result, Mapping) or result.get("boot_id") != boot_id:
            continue
        route_hazard = str(result.get("route_hazard") or "")
        if "shadow guardian" in route_hazard.casefold():
            return True
        if (
            policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        ):
            # Older live checkpoints recorded the dynamic attacker only as a
            # generic no-combat abort. The policy identity still proves which
            # shared route was crossed, so preserve that evidence.
            return True
    if last_policy_id not in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS:
        return False
    route_hazards = state.get("campaign_fastwalk_route_hazards") or ()
    if isinstance(route_hazards, (list, tuple, set, frozenset)) and any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(hazard).casefold()
        for hazard in route_hazards
    ):
        return True
    return (
        str(state.get("campaign_fastwalk_abort_reason") or "")
        == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
    )


def _legacy_fastwalk_training_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Recognize an older checkpoint that retraced the training route."""
    if state.get("campaign_fastwalk_training_complete") is not False:
        return False
    if str(state.get("room_vnum") or "") != "3054":
        return False
    route_hazards = state.get("campaign_fastwalk_route_hazards") or ()
    if not isinstance(route_hazards, (list, tuple, set, frozenset)):
        return False
    if not any(
        str(hazard).startswith("transit below-band attacker:")
        for hazard in route_hazards
    ):
        return False
    return str(state.get("campaign_fastwalk_abort_reason") or "").startswith(
        _FASTWALK_TRAINING_ROUTE_HAZARD_ABORT_PREFIX
    )


def _fastwalk_training_route_hazard_marker(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the reboot-and-level-scoped record for a deferred trainer trip."""
    return {
        "boot_id": state.get("world_boot_id"),
        "level": _level(dict(state)),
        "reason": (
            "defer class-aware training after a source-known transit attacker "
            "interrupted the distant trainer route"
        ),
        "route_hazards": [
            str(hazard)
            for hazard in (state.get("campaign_fastwalk_route_hazards") or ())
        ],
    }


def _campaign_fastwalk_training_deferred_after_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Return whether same-level training should wait for a safer route."""
    marker = state.get(_FASTWALK_TRAINING_ROUTE_HAZARD_KEY)
    if isinstance(marker, Mapping):
        boot_id = state.get("world_boot_id")
        try:
            marker_level = int(marker.get("level"))
        except (TypeError, ValueError):
            marker_level = -1
        return bool(
            boot_id
            and marker.get("boot_id") == boot_id
            and marker_level == _level(dict(state))
        )
    return _legacy_fastwalk_training_route_hazard(state)


def _source_ranked_candidate_uses_shadow_grove_route(
    candidate: HuntCandidate,
) -> bool:
    """Identify generated candidates whose route preflight crosses room 1300."""
    route_target = str(candidate.route_preflight_target or "").casefold()
    if _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in route_target:
        return True
    return any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(target).casefold()
        for target in candidate.route_hard_hazard_targets
    )


def _state_uses_shadow_grove_route(state: Mapping[str, Any]) -> bool:
    """Identify a saved fixed or generated route that crosses Shadow Grove."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS:
        return True
    candidate = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    if not isinstance(candidate, Mapping):
        return False
    route_target = str(candidate.get("route_preflight_target") or "").casefold()
    if _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in route_target:
        return True
    return any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(target).casefold()
        for target in (candidate.get("route_hard_hazard_targets") or ())
    )


def _shadow_grove_route_hazard_observed(
    policy_id: str,
    state: Mapping[str, Any],
    route_hazard: str,
) -> bool:
    """Return whether one live result proves the shared route is unsafe."""
    normalized_hazard = route_hazard.casefold()
    return bool(
        "shadow guardian" in normalized_hazard
        or (
            policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        )
        or (
            _state_uses_shadow_grove_route(state)
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        )
    )


def _repair_shadow_grove_route_hazard(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Rebuild a lost Shadow Grove quarantine from durable segment evidence."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)
    existing = state.get(_SHADOW_GROVE_ROUTE_HAZARD_KEY)
    if isinstance(existing, Mapping) and existing.get("boot_id") == boot_id:
        return dict(state)

    evidence: dict[str, Any] | None = None
    normalized_segments: list[Mapping[str, Any]] = []
    for raw_segment in segments:
        if isinstance(raw_segment, Mapping):
            normalized_segments.append(raw_segment)
            continue
        try:
            normalized_segments.append(
                {key: raw_segment[key] for key in raw_segment.keys()}
            )
        except (AttributeError, KeyError, TypeError):
            continue
    ordered_segments = sorted(
        normalized_segments,
        key=lambda segment: int(segment.get("sequence") or 0),
        reverse=True,
    )
    for segment in ordered_segments:
        phase = str(segment.get("phase") or "")
        for state_field in ("end_state_json", "start_state_json"):
            raw_state = segment.get(state_field)
            try:
                segment_state = json.loads(raw_state or "{}")
            except (TypeError, json.JSONDecodeError):
                continue
            if not isinstance(segment_state, Mapping):
                continue
            if segment_state.get("world_boot_id") != boot_id:
                continue
            route_hazard = str(
                segment_state.get("campaign_fastwalk_abort_reason") or ""
            )
            result = _campaign_research_results(dict(segment_state)).get(phase)
            if isinstance(result, Mapping) and result.get("route_hazard"):
                route_hazard = str(result["route_hazard"])
            if not route_hazard:
                continue
            if not _shadow_grove_route_hazard_observed(
                phase,
                segment_state,
                route_hazard,
            ):
                continue
            evidence = {
                "boot_id": boot_id,
                "policy_id": phase,
                "route_hazard": route_hazard,
                "source": "campaign_segment_history",
            }
            break
        if evidence is not None:
            break
    if evidence is None:
        if isinstance(existing, Mapping):
            repaired = dict(state)
            repaired.pop(_SHADOW_GROVE_ROUTE_HAZARD_KEY, None)
            return repaired
        return dict(state)

    repaired = dict(state)
    repaired[_SHADOW_GROVE_ROUTE_HAZARD_KEY] = evidence
    policy_id = str(evidence.get("policy_id") or "")
    results = _campaign_research_results(repaired)
    if policy_id and policy_id not in results:
        results[policy_id] = {
            "observed": False,
            "viable": False,
            "route_hazard": evidence["route_hazard"],
            "boot_id": boot_id,
        }
        repaired["campaign_research_results"] = results
    return repaired


def _is_capability_blocked_source_ranked_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize a route blocked by an unowned movement capability."""
    return bool(
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(route_hazard, str)
        and route_hazard.startswith("field route movement blocked:")
    )


