@lru_cache(maxsize=4)
def _cached_dd4_source_revision(source_directory: str) -> str | None:
    """Return the immutable source revision used by one campaign process."""
    source_path = Path(source_directory).resolve()
    repository = next(
        (
            parent
            for parent in (source_path, *source_path.parents)
            if (parent / ".git").exists()
        ),
        None,
    )
    if repository is None:
        return None
    try:
        result = subprocess.run(
            ["git", "-C", str(repository), "rev-parse", "HEAD"],
            capture_output=True,
            check=True,
            text=True,
            timeout=2,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    revision = result.stdout.strip()
    return revision or None


def _current_dd4_source_revision() -> str | None:
    """Read the source mirror revision without modifying the mirror."""
    source_directory = current_source_directory()
    if not source_directory.is_dir():
        return None
    return _cached_dd4_source_revision(str(source_directory))


def _synchronize_source_revision(
    state: dict[str, Any],
    source_revision: str | None,
) -> bool:
    """Invalidate source-derived route evidence after an upstream source pull."""
    if not source_revision:
        return False
    previous_revision = str(state.get(_SOURCE_REVISION_KEY) or "")
    state[_SOURCE_REVISION_KEY] = source_revision
    if previous_revision == source_revision:
        return False

    source_results = dict(state.get("campaign_research_results") or {})
    boot_id = state.get("world_boot_id")
    same_boot_absences = {
        str(policy_id): result
        for policy_id, result in source_results.items()
        if boot_id is not None
        and str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("absent") is True
    }
    same_boot_absence_ids = frozenset(same_boot_absences)
    # A source update cannot undo a live same-boot crowd at this exact reset.
    same_boot_crowds = {
        str(policy_id): result
        for policy_id, result in source_results.items()
        if boot_id is not None
        and str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and (
            result.get("crowded") is True
            or result.get("crowd_exhausted") is True
        )
    }
    same_boot_crowd_ids = frozenset(same_boot_crowds)
    had_source_evidence = bool(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY)
        or any(
            str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
            for policy_id in source_results
        )
    )
    state.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    state.pop(_SOURCE_RANKED_TRANSIT_HAZARDS_KEY, None)
    state.pop(_FAME_RECOVERY_SOURCE_RANKED_KEY, None)
    state.pop(_SOURCE_RANKED_FRONTIER_RETRY_KEY, None)
    state.pop(_SOURCE_RANKED_RETRY_EXHAUSTED_KEY, None)
    state.pop(_SOURCE_RANKED_RETRY_EXHAUSTED_BOOT_KEY, None)
    state.pop(_SOURCE_RANKED_DAMAGE_WINDOW_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_SPECIAL_HP_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_PROTECTED_ARMED_OPENER_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_UNPROTECTED_HP_OPENER_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_PRODUCTIVE_TRANSIT_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_FRESH_TRANSIT_PROBE_KEY, None)
    state.pop(_MORIA_SANCTUARY_SOURCE_REFRESH_REVALIDATION_KEY, None)
    state.pop(_MORIA_SANCTUARY_SECOND_SOURCE_REFRESH_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY, None)
    state.pop(_SOURCE_RANKED_DISPLACED_SENTINEL_REVALIDATION_KEY, None)
    _archive_source_refresh_marker(state)
    state.pop(_SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY, None)
    _archive_catacombs_source_refresh_marker(state)
    state.pop(_CATACOMBS_SOURCE_REFRESH_REVALIDATION_KEY, None)
    state.pop(_FIELD_CITY_CORRECTION_REVALIDATION_KEY, None)
    state.pop(_ABYSS_SAFE_FIDO_REVALIDATION_KEY, None)
    # A source refresh invalidates derived route decisions, not live losses
    # observed in the current MUD boot. Keep those exact-policy records so a
    # local checkout update cannot silently reopen a failed fight.
    current_boot_losses = _source_ranked_xp_loss_records(state)
    if current_boot_losses:
        state[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = [
            dict(record) for record in current_boot_losses
        ]
    else:
        state.pop(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY, None)
    state.pop(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, None)
    state.pop(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY, None)
    state.pop(_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY, None)
    state.pop(_SOURCE_CAPACITY_RESET_WAIT_KEY, None)
    state.pop(_SOURCE_COMBAT_DAMAGE_GATE_EVIDENCE_KEY, None)
    # Dedicated source gear routes carry their own reboot-local retry markers
    # and do not use the generic source-ranked policy prefix.  A refreshed
    # checkout must reopen those audits too; otherwise an old route attempt or
    # cooldown can suppress a newly valid weapon/source contract indefinitely.
    for key in (
        _SOURCE_GEAR_ATTEMPTS_KEY,
        _PIERCING_WEAPON_UPGRADE_BOOT_KEY,
        _PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY,
        _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY,
        _PIERCING_WEAPON_UPGRADE_FRONTIER_RETRY_KEY,
        _FOREST_ROUTE_GATE_CROWD_RECHECK_KEY,
        _FOREST_ROUTE_GATE_POISON_REVALIDATION_KEY,
        _PIERCING_WEAPON_UPGRADE_DAMAGE_GATE_KEY,
        _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_DAMAGE_GATE_KEY,
    ):
        state.pop(key, None)
    # A trainer-route hazard is source-derived too; do not carry its deferral
    # across a source refresh where the route may have changed.
    state.pop(_FASTWALK_TRAINING_ROUTE_HAZARD_KEY, None)

    for key in (_RESEARCH_ABSENCE_COOLDOWN_KEY, _RESEARCH_CROWD_COOLDOWN_KEY):
        values = dict(state.get(key) or {})
        values = {
            policy_id: value
            for policy_id, value in values.items()
            if not str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
            or (
                key == _RESEARCH_ABSENCE_COOLDOWN_KEY
                and str(policy_id) in same_boot_absence_ids
            )
            or (
                key == _RESEARCH_CROWD_COOLDOWN_KEY
                and str(policy_id) in same_boot_crowd_ids
            )
        }
        if values:
            state[key] = values
        else:
            state.pop(key, None)

    if source_results:
        source_results = {
            policy_id: value
            for policy_id, value in source_results.items()
            if not str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
            or str(policy_id) in same_boot_absence_ids
            or str(policy_id) in same_boot_crowd_ids
        }
        if source_results:
            state["campaign_research_results"] = source_results
        else:
            state.pop("campaign_research_results", None)

    for key in (_CLEARED_RESEARCH_POLICIES_KEY, _BELOW_BAND_POLICY_EXCLUSIONS_KEY):
        values = state.get(key)
        if not isinstance(values, (list, tuple, set, frozenset)):
            continue
        filtered = [
            value
            for value in values
            if not str(value).startswith(_SOURCE_RANKED_POLICY_PREFIX)
        ]
        if filtered:
            state[key] = filtered
        else:
            state.pop(key, None)

    for key in ("campaign_last_policy", _LAST_PRODUCTIVE_POLICY_KEY, _POLICY_HANDOFF_KEY):
        value = state.get(key)
        if isinstance(value, str) and value.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            state.pop(key, None)

    history = state.get(_PRODUCTIVE_POLICY_HISTORY_KEY)
    if isinstance(history, (list, tuple)):
        filtered_history = [
            value
            for value in history
            if not str(value).startswith(_SOURCE_RANKED_POLICY_PREFIX)
        ]
        if filtered_history:
            state[_PRODUCTIVE_POLICY_HISTORY_KEY] = filtered_history
        else:
            state.pop(_PRODUCTIVE_POLICY_HISTORY_KEY, None)
    return had_source_evidence


@dataclass(frozen=True)
class CampaignSpec:
    name: str
    character_profile: Path
    character: CharacterSpec
    target_level: int = 100
    max_segments: int = 100
    max_total_runtime: float = 86_400.0
    max_total_commands: int = 25_000
    max_stalled_segments: int = 3
    source_directory: Path = current_source_directory()

    @property
    def database(self) -> Path:
        return self.character.database

    @classmethod
    def from_mapping(cls, data: dict[str, Any], *, path: Path) -> "CampaignSpec":
        profile_value = data.get("character_profile")
        legacy_profile = False
        if not profile_value:
            is_character_profile = (
                all(data.get(key) for key in ("name", "race", "gender"))
                and any(data.get(key) for key in ("class", "character_class", "subclass"))
            )
            if not is_character_profile:
                raise ValueError("character_profile is required")
            character_profile = path.resolve()
            legacy_profile = True
        else:
            character_profile = Path(str(profile_value))
            if not character_profile.is_absolute():
                character_profile = path.parent / character_profile
            character_profile = character_profile.resolve()
        if not character_profile.exists():
            raise ValueError(f"character_profile does not exist: {character_profile}")

        character = load_character_spec(character_profile)
        campaign_name = data.get("campaign_name")
        if campaign_name is None and legacy_profile:
            campaign_name = f"{character.name} to HERO"
        name = str(campaign_name or data.get("name", character.name)).strip()
        if not name:
            raise ValueError("name must not be empty")
        source_value = data.get("source_directory")
        if source_value:
            source_directory = Path(str(source_value))
            if not source_directory.is_absolute():
                source_directory = path.parent / source_directory
            source_directory = source_directory.resolve()
        else:
            source_directory = current_source_directory()
        target_level = int(data.get("target_level", 100))
        max_segments = int(data.get("max_segments", 100))
        max_total_runtime = float(data.get("max_total_runtime", 86_400))
        max_total_commands = int(data.get("max_total_commands", 25_000))
        max_stalled_segments = int(data.get("max_stalled_segments", 3))

        if not 2 <= target_level <= 100:
            raise ValueError("target_level must be between 2 and 100")
        if max_segments < 1:
            raise ValueError("max_segments must be positive")
        if max_total_runtime <= 0:
            raise ValueError("max_total_runtime must be positive")
        if max_total_commands < 1:
            raise ValueError("max_total_commands must be positive")
        if max_stalled_segments < 1:
            raise ValueError("max_stalled_segments must be positive")

        return cls(
            name=name,
            character_profile=character_profile,
            character=character,
            source_directory=source_directory,
            target_level=target_level,
            max_segments=max_segments,
            max_total_runtime=max_total_runtime,
            max_total_commands=max_total_commands,
            max_stalled_segments=max_stalled_segments,
        )


@dataclass(frozen=True)
class CampaignResult:
    campaign_id: int
    status: str
    checkpoint_id: int | None
    message: str | None
    state: dict[str, Any]
    execution_status: str | None = None
    objective_outcome: str | None = None
    safety_outcome: str | None = None
    target_outcome: str | None = None

    @property
    def outcomes(self) -> dict[str, str]:
        """Return the three independent results of the campaign work unit."""
        return {
            "execution": self.execution_status or self.status,
            "objective": self.objective_outcome or "unknown",
            "safety": self.safety_outcome or "unknown",
        }

    @property
    def objective_achieved(self) -> bool:
        return self.objective_outcome == "achieved"

    @property
    def ran_safely(self) -> bool:
        return self.safety_outcome == "safe"

    @property
    def target_achieved(self) -> bool:
        """Return whether the campaign's requested level target was reached."""
        return self.target_outcome == "achieved"

    @property
    def ready_for_next_segment(self) -> bool:
        message = (self.message or "").casefold()
        if self.status != "ready" or self.awaiting_area_reset:
            return False
        # These outcomes have already returned the character to a durable
        # checkpoint and explicitly leave policy rotation safe to resume.
        return any(
            marker in message
            for marker in (
                "checkpointed for the next verified segment",
                "checkpointed for resumption",
                "campaign rotation will continue",
                "campaign rotation can continue",
                "campaign rotation resumed",
                "segment deferred after a bounded city-shop route hazard",
                "field departure deferred at the healer by a current city-route obstruction",
                "try source-ranked current-band targets before waiting",
            )
        )

    @property
    def awaiting_area_reset(self) -> bool:
        return bool(
            self.status == "ready"
            and self.message
            and "awaiting" in self.message.casefold()
            and "area reset" in self.message.casefold()
        )


def _sanctuary_invisible_carrier_revalidation_evidence(
    state: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Return the exact revision-243 endpoint that the new graph can widen."""
    policy_id = _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
    boot_id = state.get("world_boot_id")
    level = _level(state)
    prior_marker = state.get(_SANCTUARY_VISIBILITY_REVALIDATION_KEY)
    result = _campaign_research_results(dict(state)).get(policy_id)
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    attempts = state.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY)
    attempt = attempts.get(policy_id) if isinstance(attempts, Mapping) else None
    known_skills = state.get("campaign_known_skill_levels")
    invisibility_cost = learned_invisibility_mana_cost(
        str(state.get("character_class") or ""),
        str(state.get("subclass") or ""),
        known_skills if isinstance(known_skills, Mapping) else {},
    )
    where_checks = state.get("campaign_fastwalk_where_area_checks")
    location = (
        next(
            (
                dict(check)
                for check in where_checks
                if (
                    isinstance(check, Mapping)
                    and str(check.get("source_mobile_vnum") or "")
                    == str(_MORIA_SANCTUARY_CARRIER_MOBILE_VNUM)
                    and str(check.get("area_file") or "").casefold()
                    == "moria.are"
                    and str(check.get("scope") or "").casefold()
                    == "current_area"
                    and str(check.get("result") or "").casefold()
                    == "present"
                    and str(check.get("target") or "").casefold()
                    == "large hobgoblin"
                )
            ),
            None,
        )
        if isinstance(where_checks, Collection)
        and not isinstance(where_checks, (str, bytes))
        else None
    )
    route_preflight_locations = state.get(
        "campaign_fastwalk_route_preflight_locations"
    )
    city_route_preflight_proved = bool(
        state.get("campaign_fastwalk_route_preflight_complete") is True
        and state.get("campaign_fastwalk_route_preflight_hazard_observed") is False
        and state.get("campaign_fastwalk_route_preflight_inconclusive") is False
        and isinstance(route_preflight_locations, (list, tuple))
    )
    try:
        attempt_count = int(attempt.get("count") or 0)
    except (AttributeError, TypeError, ValueError):
        attempt_count = 0
    try:
        protection_xp_delta = int(protection.get("xp_delta") or 0)
    except (AttributeError, TypeError, ValueError):
        protection_xp_delta = 0
    try:
        result_xp_delta = int(result.get("xp_delta") or 0)
    except (AttributeError, TypeError, ValueError):
        result_xp_delta = -1
    try:
        hp = int(state.get("hp") or 0)
    except (TypeError, ValueError):
        hp = 0
    raw_room_flags = state.get("room_flags")
    room_flags = (
        {str(flag).casefold() for flag in raw_room_flags}
        if isinstance(raw_room_flags, Collection)
        and not isinstance(raw_room_flags, (str, bytes))
        else set()
    )
    if not (
        int(state.get("campaign_policy_revision") or 0)
        <= _SANCTUARY_INVISIBLE_CARRIER_REVALIDATION_REVISION
        and not state.get(_SANCTUARY_INVISIBLE_CARRIER_REVALIDATION_KEY)
        and isinstance(prior_marker, Mapping)
        and prior_marker.get("policy_revision")
        == _SANCTUARY_VISIBILITY_REVALIDATION_REVISION
        and prior_marker.get("policy_id") == policy_id
        and prior_marker.get("boot_id") == boot_id
        and prior_marker.get("level") == level
        and prior_marker.get("status") == "failed"
        and prior_marker.get("outcome")
        == _SANCTUARY_VISIBILITY_REVALIDATION_FAILED_OUTCOME
        and isinstance(prior_marker.get("superseded_result"), Mapping)
        and prior_marker["superseded_result"].get("route_hazard")
        == _OBSOLETE_SANCTUARY_GREET_HAZARD
        and isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("level") == level
        and result.get("observed") is True
        and result.get("viable") is False
        and result.get("completed_kill") is False
        and result.get("fatal_failure") is True
        and result.get("route_hazard")
        == _SANCTUARY_RESOURCE_EXHAUSTED_HAZARD
        and result.get("required_object_acquired") is not True
        and result.get("xp_loss_observed") is not True
        and result_xp_delta >= 0
        and isinstance(protection, Mapping)
        and protection.get("boot_id") == boot_id
        and protection.get("level") in {None, level}
        and protection_xp_delta < 0
        and isinstance(attempt, Mapping)
        and attempt.get("boot_id") == boot_id
        and attempt.get("level") == level
        and attempt_count > _SANCTUARY_RESOURCE_MAX_ATTEMPTS
        and invisibility_cost is not None
        and state.get("campaign_last_policy") == policy_id
        and state.get("campaign_fastwalk_target_present_observed") is True
        and state.get("campaign_fastwalk_target_absent") is False
        and location is not None
        and state.get("campaign_fastwalk_where_relocation_attempts") == 1
        and state.get("campaign_fastwalk_route_hazards") == []
        and city_route_preflight_proved
        and not state.get("campaign_fastwalk_abort_reason")
        and state.get("campaign_fastwalk_consider_outcomes") == {}
        and state.get("campaign_objective_kills") == []
        and state.get("campaign_fastwalk_required_object_vnums") == []
        and _verified_combat_potion_count(state, "purple") == 0
        and not _state_has_sanctuary_reserve(state)
        and state.get("campaign_died_during_segment") is False
        and str(state.get("room_vnum") or "") == "3054"
        and {"healing", "safe"}.issubset(room_flags)
        and hp > 0
    ):
        return None
    return {
        "source_mobile_vnum": _MORIA_SANCTUARY_CARRIER_MOBILE_VNUM,
        "area_file": location["area_file"],
        "scope": location["scope"],
        "where_relocation_attempts": 1,
        "city_route_preflight_locations": list(route_preflight_locations),
    }


