def _world_time_probe_message(
    previous_boot_id: str | None,
    observed_boot_id: str | None,
    *,
    reset_wait_completed: bool,
    defer_policy_selection: bool,
    field_city_observation: Mapping[str, Any] | None = None,
    field_city_preflight: Mapping[str, Any] | None = None,
) -> str:
    if field_city_observation is not None:
        if (
            field_city_observation.get("status") == "completed"
            and isinstance(field_city_preflight, Mapping)
            and field_city_preflight.get("complete") is True
            and field_city_preflight.get("blocked") is False
            and field_city_preflight.get("run_id") == field_city_observation.get("run_id")
        ):
            return (
                "The healer-side city observation found the wandering blocker off the saved departure route. "
                "Campaign checkpointed for the next verified segment; normal source and live hunting checks still apply."
            )
        return (
            "The bounded healer-side city observation did not prove a clear departure route. "
            "Campaign checkpointed; the saved route and combat failures remain closed."
        )
    if isinstance(observed_boot_id, str) and observed_boot_id.strip():
        if observed_boot_id != previous_boot_id:
            detail = f"refreshed the DD4 reboot identity to {observed_boot_id!r}"
        elif reset_wait_completed:
            detail = "confirmed the existing DD4 reboot after the completed area-reset wait"
        else:
            detail = None
        if detail is not None:
            message = (
                f"world-time probe {detail}. Campaign checkpointed for the next "
                "verified segment"
            )
            if reset_wait_completed and observed_boot_id == previous_boot_id:
                message += (
                    "; no reboot is required for XP in general, but this "
                    "frontier remains closed by same-reboot level/protection evidence"
                )
            if defer_policy_selection:
                message += "; next policy selection is deferred to the next invocation"
            return message + "."
    return (
        "world-time probe found no new DD4 reboot marker. No "
        "autonomous-safe current-band route remains after the live "
        "protection and route-evidence gates. Campaign checkpointed while "
        "awaiting the field area reset; a reboot is not a general XP "
        "requirement."
    )


def _automatic_world_time_probe_due(
    state: Mapping[str, Any],
    policy: Any,
    checkpoint: Mapping[str, Any] | None,
    *,
    reset_wait_completed: bool,
    segment_runner: object | None,
    now: datetime | None = None,
) -> bool:
    """Allow a bounded reboot check for a blocked healer checkpoint.

    The first check is still one-shot for an observed boot. Once that marker
    is older than the maintenance interval, a new check may learn whether DD4
    rebooted without reopening any target or treating the reboot as an XP
    requirement.
    """
    if segment_runner is not None or reset_wait_completed:
        return False
    if (
        getattr(policy, "status", None) != "unavailable"
        or getattr(policy, "execution", None) is not None
    ):
        return False
    if str(state.get("room_vnum") or "") not in _MIDGAARD_HEALER_CHECKPOINT_ROOMS:
        return False
    if state.get("dead") or state.get("in_combat"):
        return False
    try:
        if int(state.get("hp") or 0) <= 0:
            return False
    except (TypeError, ValueError):
        return False
    attempt = state.get(_AUTOMATIC_WORLD_TIME_PROBE_KEY)
    if isinstance(attempt, Mapping):
        try:
            same_level = int(attempt.get("level")) == _level(state)
        except (TypeError, ValueError):
            same_level = False
        if (
            same_level
            and attempt.get("boot_id") == state.get("world_boot_id")
        ):
            attempted_at = _world_time_probe_attempt_at(attempt)
            if attempted_at is None:
                # Preserve the old conservative behavior for legacy markers
                # whose age cannot be established.
                return False
            current_time = now or datetime.now(timezone.utc)
            if current_time.tzinfo is None:
                current_time = current_time.replace(tzinfo=timezone.utc)
            elapsed = (current_time - attempted_at).total_seconds()
            if elapsed < _AUTOMATIC_WORLD_TIME_PROBE_INTERVAL_SECONDS:
                return False
    # The probe itself is a durable maintenance segment. Do not reconnect on
    # every bounded invocation when the last attempt already recorded its
    # outcome, including a transport failure.
    return not (
        checkpoint is not None
        and str(checkpoint["phase"]) == "world-time-probe"
    )


def _world_time_probe_attempt_at(marker: Mapping[str, Any]) -> datetime | None:
    """Parse the durable timestamp used to bound repeat world-time checks."""
    raw = marker.get("attempted_at")
    if not isinstance(raw, str) or not raw.strip():
        return None
    try:
        value = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _deity_protection_probe_due(
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Allow one prayer attempt per reboot from the verified healer room."""
    boot_id = state.get("world_boot_id")
    if (
        character_level < 15
        or not boot_id
        or str(state.get("room_vnum") or "") != "3054"
        or state.get("dead")
        or state.get("in_combat")
        or not _enemy_snapshot_empty(state.get("enemies"))
        or _state_has_sanctuary_reserve(state)
    ):
        return False
    try:
        if int(state.get("hp") or 0) <= 0:
            return False
    except (TypeError, ValueError):
        return False
    attempt = state.get(_DEITY_PROTECTION_PROBE_KEY)
    return not (
        isinstance(attempt, Mapping)
        and attempt.get("boot_id") == boot_id
        and attempt.get("status") != "not_dispatched"
    )


def _deity_protection_probe_result_state(
    state: Mapping[str, Any],
    *,
    storage: RunStorage,
    run_id: int | None,
    final_state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Persist whether the single prayer command was actually dispatched."""
    result = dict(state)
    attempt = result.get(_DEITY_PROTECTION_PROBE_KEY)
    if not isinstance(attempt, Mapping):
        return result
    dispatched = False
    if run_id is not None:
        for event in storage.list_recent_events(run_id, limit=256):
            if str(event["kind"]) != "command":
                continue
            try:
                payload = json.loads(str(event["payload_json"]))
            except (TypeError, ValueError):
                continue
            if (
                isinstance(payload, Mapping)
                and payload.get("command") == "pray protection"
            ):
                dispatched = True
                break
    result[_DEITY_PROTECTION_PROBE_KEY] = {
        **dict(attempt),
        "status": "attempted" if dispatched else "not_dispatched",
        "command_dispatched": dispatched,
        "run_id": run_id,
    }
    if final_state is not None:
        result[_DEITY_PROTECTION_PROBE_KEY]["sanctuary_observed"] = (
            _has_named_affect(final_state.get("affects"), "sanctuary")
        )
        result[_DEITY_PROTECTION_PROBE_KEY]["sanctuary_reserve_available"] = (
            _state_has_sanctuary_reserve(final_state)
        )
        result[_DEITY_PROTECTION_PROBE_KEY]["end_room_vnum"] = str(
            final_state.get("room_vnum") or ""
        )
    return result


def _restore_world_time_probe_marker(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> dict[str, Any]:
    """Recover legacy same-boot probe evidence from durable segment history."""
    boot_id = state.get("world_boot_id")
    if not boot_id:
        return dict(state)
    level = _level(state)
    marker = state.get(_AUTOMATIC_WORLD_TIME_PROBE_KEY)

    def matching_segment_marker() -> dict[str, Any] | None:
        for raw_segment in reversed(tuple(segments)):
            try:
                segment = dict(raw_segment)
            except (TypeError, ValueError):
                continue
            if str(segment.get("phase") or "") != "world-time-probe":
                continue
            raw_attempted_at = segment.get("finished_at") or segment.get(
                "started_at"
            )
            attempted_at = (
                str(raw_attempted_at)
                if _world_time_probe_attempt_at(
                    {"attempted_at": raw_attempted_at}
                )
                is not None
                else None
            )
            for field in ("start_state_json", "end_state_json"):
                raw_snapshot = segment.get(field)
                if not raw_snapshot:
                    continue
                try:
                    snapshot = (
                        json.loads(raw_snapshot)
                        if isinstance(raw_snapshot, str)
                        else raw_snapshot
                    )
                except (TypeError, ValueError):
                    continue
                if not isinstance(snapshot, Mapping):
                    continue
                if (
                    snapshot.get("world_boot_id") != boot_id
                    or _level(snapshot) != level
                ):
                    continue
                recovered_marker = {
                    "boot_id": boot_id,
                    "level": level,
                    "policy_id": "world-time-probe",
                    "recovered_from_segment_id": segment.get("id"),
                }
                if attempted_at is not None:
                    recovered_marker["attempted_at"] = attempted_at
                return recovered_marker
        return None

    if isinstance(marker, Mapping):
        try:
            marker_level = int(marker.get("level"))
        except (TypeError, ValueError):
            marker_level = None
        if marker.get("boot_id") == boot_id and marker_level == level:
            if _world_time_probe_attempt_at(marker) is not None:
                return dict(state)
            recovered_marker = matching_segment_marker()
            if recovered_marker is None:
                return dict(state)
            recovered = dict(state)
            recovered[_AUTOMATIC_WORLD_TIME_PROBE_KEY] = {
                **dict(marker),
                **recovered_marker,
            }
            return recovered
    recovered_marker = matching_segment_marker()
    if recovered_marker is not None:
        recovered = dict(state)
        recovered[_AUTOMATIC_WORLD_TIME_PROBE_KEY] = recovered_marker
        return recovered
    return dict(state)


def _field_city_route_policy_id_from_segment(
    segment: Mapping[str, Any],
    start_state: Mapping[str, Any],
    end_state: Mapping[str, Any],
) -> str | None:
    phase = str(segment.get("phase") or "")
    evidence = end_state.get("campaign_field_city_preflight")
    recorded_policy_id = (
        str(evidence.get("policy_id") or "").strip()
        if isinstance(evidence, Mapping)
        else ""
    )
    if recorded_policy_id:
        return recorded_policy_id
    if phase.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX):
        return phase
    if (
        phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and not phase.startswith(f"{_SOURCE_RANKED_POLICY_PREFIX}unavailable-")
    ):
        return phase
    if phase in {
        _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
        _SOURCE_RANKED_SANCTUARY_GROUND_POLICY.policy_id,
    }:
        return phase
    if phase != "provision-funding":
        return None
    record = end_state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    if not isinstance(record, Mapping):
        record = start_state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    candidate = _source_ranked_candidate_from_record(
        record,
        source_revision=(
            end_state.get(_SOURCE_REVISION_KEY)
            or start_state.get(_SOURCE_REVISION_KEY)
        ),
    )
    if candidate is None:
        return None
    return _source_ranked_policy_id(
        candidate,
        character_level=_level(dict(end_state)) or _level(dict(start_state)),
    )


def _field_city_correction_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str | None = None,
) -> bool:
    marker = state.get(_FIELD_CITY_CORRECTION_REVALIDATION_KEY)
    if not isinstance(marker, Mapping):
        return False
    current_revision = state.get(_SOURCE_REVISION_KEY)
    return bool(
        marker.get("status") == "pending"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(dict(state))
        and marker.get("source_revision") == current_revision
        and current_revision
        and type(marker.get("blocked_run_id")) is int
        and marker.get("blocked_run_id", 0) > 0
        and isinstance(marker.get("prior_detour"), Mapping)
        and isinstance(marker.get("changed_locations"), (list, tuple))
        and marker.get("changed_locations")
        and str(marker.get("policy_id") or "").startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        )
        and (policy_id is None or marker.get("policy_id") == policy_id)
    )


def _field_city_correction_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    marker = state.get(_FIELD_CITY_CORRECTION_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("status") == "attempted"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == _level(dict(state))
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
    )


def _mark_field_city_correction_revalidation(
    state: dict[str, Any],
    *,
    policy_id: str,
) -> bool:
    if not _field_city_correction_revalidation_pending(
        state,
        policy_id=policy_id,
    ):
        return False
    marker = state.get(_FIELD_CITY_CORRECTION_REVALIDATION_KEY)
    assert isinstance(marker, Mapping)
    state[_FIELD_CITY_CORRECTION_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _field_city_correction_revalidation_from_segment(
    state: Mapping[str, Any],
    start_state: Mapping[str, Any],
    end_state: Mapping[str, Any],
    segment: Mapping[str, Any],
    *,
    policy_id: str,
) -> dict[str, Any] | None:
    evidence = end_state.get("campaign_field_city_preflight")
    current_evidence = state.get("campaign_field_city_preflight")
    start_move = start_state.get("move")
    end_move = end_state.get("move")
    if type(start_move) not in {int, float} or type(end_move) not in {
        int,
        float,
    }:
        return None
    if not isinstance(evidence, Mapping):
        return None
    prior_detour = evidence.get("detour")
    prior_locations = (
        prior_detour.get("blocked_locations")
        if isinstance(prior_detour, Mapping)
        else None
    )
    latest_locations = evidence.get("locations")
    if not (
        _field_city_departure_was_deferred(start_state, end_state)
        and _field_city_departure_checkpoint_current_reboot(state)
        and start_state.get("world_boot_id") == state.get("world_boot_id")
        and _level(dict(start_state)) == _level(dict(state))
        and start_state.get(_SOURCE_REVISION_KEY)
        == state.get(_SOURCE_REVISION_KEY)
        and evidence.get("policy_id") == policy_id
        and evidence.get("route_correction_attempted") is False
        and evidence.get("route_correction") is None
        and isinstance(evidence.get("wait_attempts"), int)
        and evidence.get("wait_attempts", 0) >= 3
        and isinstance(prior_detour, Mapping)
        and isinstance(prior_locations, (list, tuple))
        and isinstance(latest_locations, (list, tuple))
        and prior_locations
        and latest_locations
        and policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and end_state.get("world_boot_id") == state.get("world_boot_id")
        and end_state.get("level") == _level(dict(state))
        and end_state.get(_SOURCE_REVISION_KEY)
        == state.get(_SOURCE_REVISION_KEY)
        and state.get(_SOURCE_REVISION_KEY)
        and evidence.get("run_id") == segment.get("run_id")
        and isinstance(current_evidence, Mapping)
        and current_evidence.get("run_id") == evidence.get("run_id")
        and current_evidence.get("policy_id") == policy_id
        and current_evidence.get("locations") == latest_locations
        and current_evidence.get("detour") == prior_detour
        and current_evidence.get("route_correction_attempted") is False
        and start_move == end_move
        and policy_id not in _field_city_route_attempted_policy_ids(state)
    ):
        return None
    prior_set = {
        _normalise_room_label(location) for location in prior_locations
    }
    latest_set = {
        _normalise_room_label(location) for location in latest_locations
    }
    if not prior_set or not latest_set or "" in prior_set | latest_set:
        return None
    if prior_set == latest_set:
        return None
    return {
        "boot_id": state.get("world_boot_id"),
        "level": _level(dict(state)),
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "policy_id": policy_id,
        "blocked_run_id": segment.get("run_id"),
        "prior_detour": dict(prior_detour),
        "changed_locations": list(latest_locations),
        "status": "pending",
        "reason": (
            "one source-checked field-route correction after the wandering "
            "greeter moved onto the first detour"
        ),
    }


def _field_city_alternate_route_revalidation_record(
    state: Mapping[str, Any],
    *,
    policy_id: str | None = None,
) -> tuple[str, Mapping[str, Any]] | None:
    for marker_key in (
        _FIELD_CITY_ALTERNATE_ROUTE_REVALIDATION_KEY,
        _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY,
        _FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY,
    ):
        marker = state.get(marker_key)
        if not isinstance(marker, Mapping):
            continue
        rooms = marker.get("blocked_room_vnums")
        try:
            extra_steps = int(marker.get("max_extra_steps"))
            mobile_vnum = int(marker.get("source_mobile_vnum"))
            room_vnum = int(marker.get("source_room_vnum"))
        except (TypeError, ValueError):
            continue
        valid = bool(
            marker.get("status") == "pending"
            and marker.get("attempted") is not True
            and marker.get("boot_id") == state.get("world_boot_id")
            and marker.get("level") == _level(dict(state))
            and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
            and state.get(_SOURCE_REVISION_KEY)
            and marker.get("policy_id")
            and str(marker.get("policy_id")).startswith(
                _SOURCE_RANKED_POLICY_PREFIX
            )
            and (policy_id is None or marker.get("policy_id") == policy_id)
            and type(marker.get("prior_segment_id")) is int
            and marker.get("prior_segment_id", 0) > 0
            and 0 < mobile_vnum
            and 0 < room_vnum
            and extra_steps == _FIELD_CITY_ALTERNATE_ROUTE_MAX_EXTRA_STEPS
            and isinstance(rooms, (list, tuple))
            and bool(rooms)
            and all(type(value) is int and value > 0 for value in rooms)
        )
        if marker_key == _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY:
            prior_revision = marker.get("prior_source_revision")
            valid = bool(
                valid
                and marker.get("source_refresh") is True
                and isinstance(prior_revision, str)
                and prior_revision
                and prior_revision != marker.get("source_revision")
                and marker.get("observation_source_revision") == prior_revision
                and type(marker.get("observation_segment_id")) is int
                and marker.get("observation_segment_id", 0)
                > marker.get("prior_segment_id", 0)
                and type(marker.get("prior_run_id")) is int
                and marker.get("prior_run_id", 0) > 0
                and type(marker.get("observation_run_id")) is int
                and marker.get("observation_run_id", 0)
                > marker.get("prior_run_id", 0)
            )
            if marker.get("route_clear_recheck") is True:
                prior_blocked_rooms = marker.get("prior_blocked_room_vnums")
                valid = bool(
                    valid
                    and isinstance(marker.get("source_route"), list)
                    and bool(marker.get("source_route"))
                    and isinstance(prior_blocked_rooms, list)
                    and bool(prior_blocked_rooms)
                    and all(
                        type(value) is int and value > 0
                        for value in prior_blocked_rooms
                    )
                    and marker.get("observation_source_revision")
                    == prior_revision
                )
        if marker_key == _FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY:
            valid = bool(
                valid
                and marker.get("route_clear_recheck") is True
                and marker.get("observation_source_revision")
                == marker.get("source_revision")
                and type(marker.get("prior_run_id")) is int
                and marker.get("prior_run_id", 0) > 0
                and type(marker.get("observation_run_id")) is int
                and marker.get("observation_run_id", 0)
                > marker.get("prior_run_id", 0)
                and isinstance(marker.get("source_route"), list)
                and bool(marker["source_route"])
            )
        if marker.get("route_clear_recheck") is True:
            proof = marker.get("productive_clearance")
            if proof is not None:
                ledger = state.get(PRODUCTIVE_CITY_CLEARANCE_KEY)
                saved = ((ledger.get("policies") or {}).get(marker.get("policy_id"))
                         if isinstance(ledger, Mapping) else None)
                valid = bool(
                    valid and isinstance(proof, Mapping) and isinstance(saved, Mapping)
                    and ledger.get("boot_id") == state.get("world_boot_id")
                    and ledger.get("level") == _level(dict(state))
                    and saved.get("status") == "pending"
                    and saved.get("blocked_run_id") == marker.get("prior_run_id")
                    and saved.get("observation_run_id") == marker.get("observation_run_id")
                    and all(saved.get(key) == proof.get(key) for key in (
                        "productive_run_id", "productive_segment_id", "xp", "xp_loss_total", "prior_result",
                    ))
                    and proof.get("xp") == state.get("xp")
                    and proof.get("xp_loss_total") == state.get("campaign_xp_loss_total")
                    and proof.get("prior_result")
                    == _campaign_research_results(dict(state)).get(marker.get("policy_id"))
                )
        if marker.get("fastwalk_route_preflight_revalidation") is True:
            prior_run_id = marker.get("prior_run_id")
            prior_locations = marker.get("prior_locations")
            hazard = str(marker.get("route_hazard") or "")
            valid = bool(
                valid
                and type(prior_run_id) is int
                and prior_run_id > 0
                and type(marker.get("observation_run_id")) is int
                and marker.get("observation_run_id", 0) > prior_run_id
                and isinstance(prior_locations, (list, tuple))
                and bool(prior_locations)
                and all(_normalise_room_label(value) for value in prior_locations)
                and isinstance(marker.get("source_route"), (list, tuple))
                and bool(marker.get("source_route"))
                and hazard.startswith(
                    _SOURCE_RANKED_PREFLIGHT_ROUTE_HAZARD_PREFIX
                )
                and hazard.endswith("while observing from room 3001")
                and marker.get("evidence_kind")
                == "fastwalk_route_preflight"
            )
        if valid:
            return marker_key, marker
    return None


def _field_city_alternate_route_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str | None = None,
) -> bool:
    return (
        _field_city_alternate_route_revalidation_record(
            state,
            policy_id=policy_id,
        )
        is not None
    )


def _mark_field_city_alternate_route_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    record = _field_city_alternate_route_revalidation_record(
        state,
        policy_id=policy_id,
    )
    if record is None:
        return False
    marker_key, marker = record
    state[marker_key] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    if marker.get("productive_clearance"):
        ledger = state.get(PRODUCTIVE_CITY_CLEARANCE_KEY) or {}
        policies = dict(ledger.get("policies") or {})
        policies[policy_id] = {**dict(policies[policy_id]), "status": "attempted"}
        state[PRODUCTIVE_CITY_CLEARANCE_KEY] = {**dict(ledger), "policies": policies}
    return True


def _plain_population_city_recheck_pending(
    state: Mapping[str, Any], candidate: HuntCandidate, *,
    character_level: int, source_world: WorldSource | None,
) -> bool:
    record = _field_city_alternate_route_revalidation_record(
        state, policy_id=_source_ranked_policy_id(candidate, character_level=character_level),
    )
    if (
        record is None
        or record[0] not in {
            _FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY,
            _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY,
        }
        or record[1].get("route_clear_recheck") is not True
        or source_world is None
    ):
        return False
    marker = record[1]
    result = _campaign_research_results(state).get(marker["policy_id"])
    return bool(
        marker.get("source_route") == list(candidate.route)
        and marker.get("source_mobile_vnum") == candidate.mobile_vnum
        and marker.get("source_room_vnum") == candidate.room_vnum
        and (candidate.boot_kills < 3 or marker.get("repeat_after_kill_cap") is True)
        and plain_bounded_population(candidate, source_world)
        and _source_ranked_xp_loss_record(state, marker["policy_id"]) is None
        and not _source_ranked_crowd_attempts_exhausted(state, marker["policy_id"])
        and isinstance(result, Mapping) and result.get("boot_id") == state.get("world_boot_id")
        and result.get("previously_productive") is True and result.get("consider_viable") is True
        and type(result.get("max_objective_kill_xp")) is int
        and result["max_objective_kill_xp"] > character_level * 10
        and not any(result.get(key) for key in (
            "absent", "crowded", "crowd_exhausted", "fatal", "fatal_failure",
            "xp_loss_observed", "hazard", "route_hazard",
            "unattackable", "target_vnum_mismatch", "low_reward",
        ))
        and _source_ranked_post_loss_plain_probe_allowed(
            candidate, state, character_level=character_level, source_world=source_world,
        )
    )


def _field_city_preflight_observation_run_id(
    current: Mapping[str, Any],
    segments: Collection[Any],
    *,
    boot_id: str,
    character_level: int,
    source_revision: str,
) -> int | None:
    raw_current_locations = current.get("locations")
    if not (
        current.get("complete") is True
        and current.get("blocked") is False
        and current.get("boot_id") == boot_id
        and current.get("level") == character_level
        and isinstance(raw_current_locations, (list, tuple))
    ):
        return None
    current_locations = {
        _normalise_room_label(value)
        for value in raw_current_locations
    }
    if not current_locations or "" in current_locations:
        return None

    for raw_segment in reversed(
        tuple(segments)[-_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:]
    ):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {
                    key: raw_segment[key] for key in raw_segment.keys()
                }
            except (AttributeError, KeyError, TypeError):
                continue
        if segment.get("status") != "success":
            continue
        try:
            run_id = int(segment.get("run_id"))
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if (
            run_id < 1
            or not isinstance(start, Mapping)
            or not isinstance(end, Mapping)
        ):
            continue
        try:
            start_xp = int(start.get("xp"))
            end_xp = int(end.get("xp"))
            start_loss = int(start.get("xp_loss_total"))
            end_loss = int(end.get("xp_loss_total"))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue

        start_city = start.get("campaign_field_city_preflight")
        end_city = end.get("campaign_field_city_preflight")
        if not isinstance(end_city, Mapping):
            continue
        raw_observation_run_id = end_city.get("run_id")
        if raw_observation_run_id is None:
            observation_run_matches = False
        else:
            try:
                observation_run_matches = (
                    int(raw_observation_run_id) == run_id
                )
            except (TypeError, ValueError):
                continue
            if not observation_run_matches:
                continue
        raw_end_locations = end_city.get("locations")
        if not isinstance(raw_end_locations, (list, tuple)):
            continue
        end_locations = {
            _normalise_room_label(value)
            for value in raw_end_locations
        }
        if isinstance(start_city, Mapping):
            raw_start_locations = start_city.get("locations", ())
            if not isinstance(raw_start_locations, (list, tuple)):
                continue
            start_locations = {
                _normalise_room_label(value)
                for value in raw_start_locations
            }
        else:
            start_locations = set()
        if not (
            end_city.get("complete") is True
            and end_city.get("blocked") is False
            and end_city.get("boot_id") == boot_id
            and end_city.get("level") == character_level
            and end_locations == current_locations
            and (
                start_locations != current_locations
                or observation_run_matches
            )
            and start.get(_SOURCE_REVISION_KEY) == source_revision
            and end.get(_SOURCE_REVISION_KEY) == source_revision
            and start.get("world_boot_id") == boot_id
            and end.get("world_boot_id") == boot_id
            and _level(dict(start)) == character_level
            and _level(dict(end)) == character_level
            and start_xp == end_xp
            and start_loss == end_loss
            and end.get("xp_loss_observed") not in {True, 1}
            and start.get("dead") is not True
            and end.get("dead") is not True
            and (start.get("campaign_completed_kills") or [])
            == (end.get("campaign_completed_kills") or [])
            and (start.get("campaign_objective_kills") or [])
            == (end.get("campaign_objective_kills") or [])
        ):
            continue
        return run_id
    return None


def _field_city_revalidation_segment(
    policy_id: str,
    segments: Collection[Any],
    *,
    storage: RunStorage | None,
    campaign_id: int | None,
) -> tuple[Mapping[str, Any], Mapping[str, Any], Mapping[str, Any]] | None:
    """Find the latest successful policy segment without loading broad history."""
    for raw_segment in reversed(tuple(segments)):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {key: raw_segment[key] for key in raw_segment.keys()}
            except (AttributeError, KeyError, TypeError):
                continue
        if (
            segment.get("phase") != policy_id
            or segment.get("status") != "success"
        ):
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError):
            continue
        if isinstance(start, Mapping) and isinstance(end, Mapping):
            return segment, start, end

    if storage is None or campaign_id is None:
        return None
    segment_loader = getattr(
        storage,
        "get_latest_campaign_segment_for_phase",
        None,
    )
    if not callable(segment_loader):
        return None
    try:
        raw_segment = segment_loader(
            campaign_id,
            policy_id,
            search_limit=256,
        )
    except (OSError, sqlite3.Error, TypeError, ValueError):
        return None
    if raw_segment is None:
        return None
    if isinstance(raw_segment, Mapping):
        segment = raw_segment
    else:
        try:
            segment = {key: raw_segment[key] for key in raw_segment.keys()}
        except (AttributeError, KeyError, TypeError):
            return None
    if (
        segment.get("phase") != policy_id
        or segment.get("status") != "success"
    ):
        return None
    try:
        start = json.loads(segment.get("start_state_json") or "{}")
        end = json.loads(segment.get("end_state_json") or "{}")
    except (TypeError, ValueError):
        return None
    if not isinstance(start, Mapping) or not isinstance(end, Mapping):
        return None
    return segment, start, end


def _fastwalk_route_block_revalidation_record(
    policy_id: str,
    candidate: HuntCandidate,
    segment: Mapping[str, Any],
    start: Mapping[str, Any],
    end: Mapping[str, Any],
    result: Mapping[str, Any] | None,
    *,
    boot_id: str,
    level: int,
    source_revision: str,
) -> Mapping[str, Any] | None:
    """Normalize one exact, no-combat fastwalk block for route revalidation."""
    if not isinstance(result, Mapping):
        return None
    try:
        run_id = int(segment.get("run_id"))
        start_xp = int(start.get("xp"))
        end_xp = int(end.get("xp"))
        start_loss = int(start.get("xp_loss_total"))
        end_loss = int(end.get("xp_loss_total"))
        hp = int(end.get("hp"))
        max_hp = int(end.get("max_hp"))
    except (TypeError, ValueError):
        return None
    locations = end.get("campaign_fastwalk_route_preflight_locations")
    hazard = str(end.get("campaign_fastwalk_abort_reason") or "")
    attempts = end.get("campaign_fastwalk_route_preflight_retry_attempts")
    timing = end.get("campaign_combat_timing")
    if not (
        segment.get("status") == "success"
        and segment.get("phase") == policy_id
        and run_id > 0
        and start.get("world_boot_id") == boot_id
        and end.get("world_boot_id") == boot_id
        and _level(dict(start)) == level
        and _level(dict(end)) == level
        and start.get(_SOURCE_REVISION_KEY) == source_revision
        and end.get(_SOURCE_REVISION_KEY) == source_revision
        and start_xp == end_xp
        and start_loss == end_loss
        and result.get("boot_id") == boot_id
        and result.get("observed") is False
        and result.get("retryable_failure") is True
        and result.get("viable") is False
        and result.get("route_hazard") == hazard
        and (
            result.get("run_id") is None
            or result.get("run_id") == run_id
        )
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
                "completed_kill",
            )
        )
        and str(end.get("room_vnum") or "") == "3054"
        and max_hp > 0
        and hp == max_hp
        and end.get("dead") not in {True, 1}
        and end.get("in_combat") not in {True, 1}
        and end.get("xp_loss_observed") not in {True, 1}
        and end.get("campaign_xp_loss_observed") not in {True, 1}
        and end.get("campaign_died_during_segment") not in {True, 1}
        and isinstance(timing, Mapping)
        and type(timing.get("sent")) is int
        and timing.get("sent") == 0
        and type(timing.get("acknowledged")) is int
        and timing.get("acknowledged") == 0
        and end.get("campaign_fastwalk_route_preflight_complete") is True
        and end.get("campaign_fastwalk_route_preflight_hazard_observed")
        in {True, 1}
        and end.get("campaign_fastwalk_route_preflight_inconclusive")
        in {False, 0}
        and type(attempts) is int
        and attempts >= 3
        and isinstance(locations, (list, tuple))
        and bool(locations)
        and all(_normalise_room_label(value) for value in locations)
        and hazard.startswith(_SOURCE_RANKED_PREFLIGHT_ROUTE_HAZARD_PREFIX)
        and hazard.endswith("while observing from room 3001")
        and end.get("campaign_fastwalk_target_present_observed")
        in {False, 0}
        and end.get("campaign_consider_result") is None
        and (start.get("campaign_completed_kills") or [])
        == (end.get("campaign_completed_kills") or [])
        and (start.get("campaign_objective_kills") or [])
        == (end.get("campaign_objective_kills") or [])
    ):
        return None
    recorded = _source_ranked_candidate_from_record(
        start.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=source_revision,
    )
    if (
        recorded is None
        or _source_ranked_policy_id(recorded, character_level=level)
        != policy_id
        or recorded.mobile_vnum != candidate.mobile_vnum
        or recorded.room_vnum != candidate.room_vnum
        or list(recorded.route) != list(candidate.route)
    ):
        return None
    return {
        "policy_id": policy_id,
        "boot_id": boot_id,
        "level": level,
        "complete": True,
        "blocked": True,
        "stopped_before_departure": True,
        "outbound_index": 0,
        "wait_attempts": attempts,
        "detour": None,
        "route_correction": None,
        "route_correction_attempted": False,
        "locations": list(locations),
        "run_id": run_id,
        "evidence_kind": "fastwalk_route_preflight",
        "route_hazard": hazard,
    }


def _fastwalk_alternate_route_candidate_allowed(
    candidate: HuntCandidate,
    marker: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Match the exact marked target to its bounded source detour."""
    if source_world is None:
        return False
    try:
        mobile_vnum = int(marker.get("source_mobile_vnum"))
        room_vnum = int(marker.get("source_room_vnum"))
        max_extra_steps = int(marker.get("max_extra_steps"))
        blocked_rooms = {
            int(value) for value in marker.get("blocked_room_vnums", ())
        }
    except (TypeError, ValueError):
        return False
    source_route = marker.get("source_route")
    if not (
        marker.get("fastwalk_route_preflight_revalidation") is True
        and marker.get("policy_id")
        == _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        and candidate.mobile_vnum == mobile_vnum
        and candidate.room_vnum == room_vnum
        and isinstance(source_route, (list, tuple))
        and blocked_rooms
        and max_extra_steps == _FIELD_CITY_ALTERNATE_ROUTE_MAX_EXTRA_STEPS
    ):
        return False
    direct = _shortest_paths_from(
        source_world.rooms,
        candidate.route_origin_room_vnum,
    ).get(candidate.room_vnum)
    alternate = _shortest_paths_from(
        source_world.rooms,
        candidate.route_origin_room_vnum,
        blocked_rooms=blocked_rooms,
    ).get(candidate.room_vnum)
    return bool(
        direct is not None
        and alternate is not None
        and list(direct[0]) == list(source_route)
        and list(candidate.route) == list(alternate[0])
        and alternate[1][-1] == candidate.room_vnum
        and not blocked_rooms.intersection(alternate[1][:-1])
        and len(alternate[0])
        > len(direct[0]) + _MAX_SOURCE_ROUTE_DETOUR_STEPS
        and len(alternate[0]) <= len(direct[0]) + max_extra_steps
    )


def _field_city_segment_by_id(
    segment_id: int,
    segments: Collection[Any],
    *,
    storage: RunStorage | None,
    campaign_id: int | None,
) -> tuple[Mapping[str, Any], Mapping[str, Any], Mapping[str, Any]] | None:
    for raw_segment in reversed(
        tuple(segments)[-_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:]
    ):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {key: raw_segment[key] for key in raw_segment.keys()}
            except (AttributeError, KeyError, TypeError):
                continue
        if segment.get("id") != segment_id:
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
        if isinstance(start, Mapping) and isinstance(end, Mapping):
            return segment, start, end
        return None

    if storage is None or campaign_id is None:
        return None
    loader = getattr(storage, "get_campaign_segment_by_id", None)
    if not callable(loader):
        return None
    try:
        raw_segment = loader(campaign_id, segment_id)
    except (OSError, sqlite3.Error, TypeError, ValueError):
        return None
    if raw_segment is None:
        return None
    if isinstance(raw_segment, Mapping):
        segment = raw_segment
    else:
        try:
            segment = {key: raw_segment[key] for key in raw_segment.keys()}
        except (AttributeError, KeyError, TypeError):
            return None
    try:
        start = json.loads(segment.get("start_state_json") or "{}")
        end = json.loads(segment.get("end_state_json") or "{}")
    except (TypeError, ValueError, json.JSONDecodeError):
        return None
    if not isinstance(start, Mapping) or not isinstance(end, Mapping):
        return None
    return segment, start, end


def _field_city_source_refresh_observation(
    marker: Mapping[str, Any],
    segments: Collection[Any],
    *,
    boot_id: str,
    character_level: int,
    source_revision: str,
    blocked_segment_id: int,
    blocked_run_id: int,
    storage: RunStorage | None,
    campaign_id: int | None,
) -> tuple[int, int, Mapping[str, Any]] | None:
    raw_locations = marker.get("changed_locations")
    if not isinstance(raw_locations, (list, tuple)):
        return None
    expected_locations = {
        _normalise_room_label(value) for value in raw_locations
    }
    if not expected_locations or "" in expected_locations:
        return None

    recent_segments = tuple(segments)[
        -_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:
    ]
    projection_loader = getattr(
        storage,
        "list_recent_campaign_segment_state_projections",
        None,
    ) if storage is not None else None
    if campaign_id is not None and callable(projection_loader):
        try:
            projected = projection_loader(
                campaign_id,
                state_fields=(
                    _SOURCE_REVISION_KEY,
                    "world_boot_id",
                    "level",
                    "xp",
                    "xp_loss_total",
                    "xp_loss_observed",
                    "dead",
                    "campaign_completed_kills",
                    "campaign_objective_kills",
                    "campaign_field_city_preflight",
                ),
                limit=_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT,
            )
        except (OSError, sqlite3.Error, TypeError, ValueError):
            projected = ()
        if projected:
            recent_segments = tuple(projected)

    for raw_segment in reversed(
        recent_segments
    ):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {key: raw_segment[key] for key in raw_segment.keys()}
            except (AttributeError, KeyError, TypeError):
                continue
        if segment.get("status") != "success":
            continue
        try:
            segment_id = int(segment.get("id"))
            run_id = int(segment.get("run_id"))
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if (
            segment_id <= blocked_segment_id
            or run_id <= blocked_run_id
            or not isinstance(start, Mapping)
            or not isinstance(end, Mapping)
            or start.get(_SOURCE_REVISION_KEY) != source_revision
            or end.get(_SOURCE_REVISION_KEY) != source_revision
        ):
            continue
        observation = end.get("campaign_field_city_preflight")
        if not isinstance(observation, Mapping):
            continue
        locations = observation.get("locations")
        if not isinstance(locations, (list, tuple)):
            continue
        normalized_locations = {
            _normalise_room_label(value) for value in locations
        }
        if normalized_locations != expected_locations:
            continue
        observed_run_id = _field_city_preflight_observation_run_id(
            observation,
            (raw_segment,),
            boot_id=boot_id,
            character_level=character_level,
            source_revision=source_revision,
        )
        if observed_run_id == run_id:
            return segment_id, run_id, observation
    return None


def _arm_field_city_alternate_route_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    source_world: WorldSource | None,
    segments: Collection[Any],
    storage: RunStorage | None = None,
    campaign_id: int | None = None,
    excluded_policy_ids: Collection[str] = (),
    allow_repeated_policy_ids: Collection[str] = (),
) -> str | None:
    """Arm one long source route after its prior city block has moved."""
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    level = _level(state)
    try:
        hp = int(state.get("hp"))
        max_hp = int(state.get("max_hp"))
    except (TypeError, ValueError):
        return None
    if (
        source_world is None
        or not boot_id
        or not source_revision
        or not _is_safe_healer_checkpoint(state)
        or max_hp <= 0
        or hp < max_hp * 0.95
    ):
        return None

    current = state.get("campaign_field_city_preflight")
    if not (
        isinstance(current, Mapping)
        and current.get("boot_id") == boot_id
        and current.get("level") == level
        and current.get("complete") is True
        and current.get("blocked") is False
        and isinstance(current.get("locations"), (list, tuple))
        and current.get("locations")
    ):
        return None
    current_locations = {
        _normalise_room_label(value)
        for value in current.get("locations", ())
    }
    if not current_locations or "" in current_locations:
        return None

    existing = state.get(_FIELD_CITY_ALTERNATE_ROUTE_REVALIDATION_KEY)
    refresh_existing = state.get(_FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY)
    source_refresh_attempt: Mapping[str, Any] | None = None
    if (
        isinstance(refresh_existing, Mapping)
        and refresh_existing.get("boot_id") == boot_id
        and refresh_existing.get("level") == level
        and refresh_existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return None
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") == level
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        if (
            existing.get("status") != "attempted"
            or existing.get("attempted") is not True
            or not isinstance(existing.get("source_revision"), str)
            or existing.get("source_revision") == source_revision
            or existing.get("prior_source_revision")
            != existing.get("source_revision")
            or type(existing.get("prior_segment_id")) is not int
            or type(existing.get("prior_run_id")) is not int
        ):
            return None
        source_refresh_attempt = existing

    blocked_policy_ids = _field_city_departure_blocked_policy_ids(state)
    attempted_policy_ids = _field_city_route_attempted_policy_ids(state)
    explicitly_excluded = {str(value) for value in excluded_policy_ids}
    segments_tail = tuple(segments)[-_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:]
    current_run_id = _field_city_preflight_observation_run_id(
        current,
        segments_tail,
        boot_id=str(boot_id),
        character_level=level,
        source_revision=str(source_revision),
    )
    healer = source_world.rooms.get(3054)
    if healer is None:
        return None

    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=level,
        )
        use_saved_refresh_attempt = bool(
            source_refresh_attempt is not None
            and source_refresh_attempt.get("policy_id") == policy_id
        )
        if (
            (
                source_refresh_attempt is not None
                and source_refresh_attempt.get("policy_id") != policy_id
            )
            or (
                policy_id in attempted_policy_ids
                and not use_saved_refresh_attempt
            )
            or policy_id in explicitly_excluded
            or not candidate.autonomous_safe
            or candidate.requires_flight
            or not _source_ranked_candidate_in_current_band(
                candidate,
                state,
                world=source_world,
                character_level=level,
                character_max_hp=max_hp,
                allow_repeated_kills=policy_id in allow_repeated_policy_ids,
            )
        ):
            continue
        direct = _shortest_paths_from(
            source_world.rooms,
            candidate.route_origin_room_vnum,
        ).get(candidate.room_vnum)
        if direct is None or direct[0] != candidate.route:
            continue

        if use_saved_refresh_attempt:
            assert source_refresh_attempt is not None
            try:
                prior_segment_id = int(
                    source_refresh_attempt.get("prior_segment_id")
                )
            except (TypeError, ValueError):
                continue
            matching = _field_city_segment_by_id(
                prior_segment_id,
                segments_tail,
                storage=storage,
                campaign_id=campaign_id,
            )
        else:
            matching = _field_city_revalidation_segment(
                policy_id,
                segments_tail,
                storage=storage,
                campaign_id=campaign_id,
            )
        if matching is None:
            continue
        matching_segment, matching_start, matching_end = matching
        if (
            matching_segment.get("phase") != policy_id
            or matching_segment.get("status") != "success"
        ):
            continue

        prior = matching_end.get("campaign_field_city_preflight")
        fastwalk_route_revalidation = False
        if not isinstance(prior, Mapping):
            prior = _fastwalk_route_block_revalidation_record(
                policy_id,
                candidate,
                matching_segment,
                matching_start,
                matching_end,
                _campaign_research_results(state).get(policy_id),
                boot_id=str(boot_id),
                level=level,
                source_revision=str(source_revision),
            )
            fastwalk_route_revalidation = prior is not None
        if not isinstance(prior, Mapping):
            continue
        if (
            policy_id not in blocked_policy_ids
            and not fastwalk_route_revalidation
        ):
            continue
        if (
            not fastwalk_route_revalidation
            and _source_ranked_result_status(
                candidate,
                state,
                character_level=level,
            )
            != "fresh"
        ):
            continue
        prior_locations = prior.get("locations")
        try:
            prior_run_id = int(prior.get("run_id"))
            start_xp = int(matching_start.get("xp"))
            end_xp = int(matching_end.get("xp"))
            start_loss = int(matching_start.get("xp_loss_total"))
            end_loss = int(matching_end.get("xp_loss_total"))
        except (TypeError, ValueError):
            continue
        prior_source_revision = matching_start.get(_SOURCE_REVISION_KEY)
        if (
            not isinstance(prior_source_revision, str)
            or not prior_source_revision
            or matching_end.get(_SOURCE_REVISION_KEY)
            != prior_source_revision
        ):
            continue
        if use_saved_refresh_attempt and (
            prior_source_revision
            != source_refresh_attempt.get("prior_source_revision")
        ):
            continue
        observation_city: Mapping[str, Any] = current
        observation_segment_id: int | None = None
        if use_saved_refresh_attempt:
            assert source_refresh_attempt is not None
            refresh_observation = _field_city_source_refresh_observation(
                source_refresh_attempt,
                segments_tail,
                boot_id=str(boot_id),
                character_level=level,
                source_revision=prior_source_revision,
                blocked_segment_id=int(matching_segment.get("id") or 0),
                blocked_run_id=prior_run_id,
                storage=storage,
                campaign_id=campaign_id,
            )
            if refresh_observation is None:
                continue
            (
                observation_segment_id,
                observation_run_id,
                observation_city,
            ) = refresh_observation
        elif prior_source_revision != source_revision:
            refresh_observation = _field_city_source_refresh_observation(
                {"changed_locations": list(current.get("locations", ()))},
                segments_tail,
                boot_id=str(boot_id),
                character_level=level,
                source_revision=prior_source_revision,
                blocked_segment_id=int(matching_segment.get("id") or 0),
                blocked_run_id=prior_run_id,
                storage=storage,
                campaign_id=campaign_id,
            )
            if refresh_observation is None:
                continue
            (
                observation_segment_id,
                observation_run_id,
                observation_city,
            ) = refresh_observation
        else:
            observation_run_id = current_run_id
        observation_locations = observation_city.get("locations", ())
        observed_locations = {
            _normalise_room_label(value)
            for value in observation_locations
        } if isinstance(observation_locations, (list, tuple)) else set()
        old_locations = {
            _normalise_room_label(value)
            for value in prior_locations
        } if isinstance(prior_locations, (list, tuple)) else set()
        if not (
            prior.get("policy_id") == policy_id
            and prior.get("boot_id") == boot_id
            and prior.get("level") == level
            and prior.get("complete") is True
            and prior.get("blocked") is True
            and prior.get("stopped_before_departure") is True
            and prior.get("outbound_index") == 0
            and isinstance(prior.get("wait_attempts"), int)
            and prior.get("wait_attempts", 0) >= 3
            and prior.get("detour") is None
            and prior.get("route_correction") is None
            and prior.get("route_correction_attempted") is not True
            and prior_run_id > 0
            and observation_run_id is not None
            and observation_run_id > prior_run_id
            and old_locations
            and "" not in old_locations
            and old_locations != observed_locations
            and start_xp == end_xp
            and start_loss == end_loss
            and matching_start.get("world_boot_id") == boot_id
            and matching_end.get("world_boot_id") == boot_id
            and _level(dict(matching_start)) == level
            and _level(dict(matching_end)) == level
            and matching_end.get("xp_loss_observed") not in {True, 1}
            and (matching_start.get("campaign_completed_kills") or [])
            == (matching_end.get("campaign_completed_kills") or [])
            and (matching_start.get("campaign_objective_kills") or [])
            == (matching_end.get("campaign_objective_kills") or [])
        ):
            continue

        recorded_candidate = _source_ranked_candidate_from_record(
            matching_start.get(_SOURCE_RANKED_CANDIDATE_KEY),
            source_revision=prior_source_revision,
        )
        if (
            recorded_candidate is None
            or _source_ranked_policy_id(
                recorded_candidate,
                character_level=level,
            )
            != policy_id
            or recorded_candidate.mobile_vnum != candidate.mobile_vnum
            or recorded_candidate.room_vnum != candidate.room_vnum
            or recorded_candidate.route != candidate.route
        ):
            continue

        if fastwalk_route_revalidation:
            blocked_rooms = _source_ranked_observed_route_blocked_room_vnums(
                matching_end,
                source_world,
            )
        else:
            blocked_probe = {
                "world_boot_id": boot_id,
                "level": level,
                "campaign_field_city_preflight": {
                    "boot_id": boot_id,
                    "level": level,
                    "stopped_before_departure": True,
                    "outbound_index": 0,
                    "complete": True,
                    "blocked": True,
                    "locations": list(prior_locations),
                },
            }
            blocked_rooms = _source_ranked_observed_route_blocked_room_vnums(
                blocked_probe,
                source_world,
            )
        if not blocked_rooms or not set(blocked_rooms).intersection(direct[1][:-1]):
            continue
        alternate = _shortest_paths_from(
            source_world.rooms,
            candidate.route_origin_room_vnum,
            blocked_rooms=set(blocked_rooms),
        ).get(candidate.room_vnum)
        if (
            alternate is None
            or set(blocked_rooms).intersection(alternate[1][:-1])
            or len(alternate[0])
            <= len(direct[0]) + _MAX_SOURCE_ROUTE_DETOUR_STEPS
            or len(alternate[0])
            > len(direct[0]) + _FIELD_CITY_ALTERNATE_ROUTE_MAX_EXTRA_STEPS
        ):
            continue

        source_refresh = prior_source_revision != source_revision
        marker_key = (
            _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY
            if source_refresh
            else _FIELD_CITY_ALTERNATE_ROUTE_REVALIDATION_KEY
        )
        marker = {
            "boot_id": boot_id,
            "level": level,
            "source_revision": source_revision,
            "prior_source_revision": prior_source_revision,
            "policy_id": policy_id,
            "source_mobile_vnum": candidate.mobile_vnum,
            "source_room_vnum": candidate.room_vnum,
            "source_route": list(candidate.route),
            "prior_segment_id": matching_segment.get("id"),
            "prior_run_id": matching_segment.get("run_id"),
            "observation_run_id": observation_run_id,
            "blocked_room_vnums": list(blocked_rooms),
            "prior_locations": list(prior_locations),
            "fastwalk_route_preflight_revalidation": (
                fastwalk_route_revalidation
            ),
            "evidence_kind": (
                "fastwalk_route_preflight"
                if fastwalk_route_revalidation
                else "field_city_preflight"
            ),
            "route_hazard": prior.get("route_hazard"),
            "changed_locations": list(observation_locations),
            "max_extra_steps": _FIELD_CITY_ALTERNATE_ROUTE_MAX_EXTRA_STEPS,
            "repeat_after_kill_cap": (
                candidate.boot_kills >= 3
                and policy_id in allow_repeated_policy_ids
            ),
            "status": "pending",
            "attempted": False,
            "reason": (
                "one source-checked long route after the exact fastwalk or "
                "city block moved and the ordinary route-detour limit was "
                "insufficient"
                if not source_refresh
                else "one source-refresh revalidation for the exact "
                "city-blocked target; dispatch still requires a fresh "
                "live city preflight"
            ),
        }
        if source_refresh:
            if observation_segment_id is None or observation_run_id is None:
                continue
            marker.update(
                {
                    "source_refresh": True,
                    "prior_source_revision": prior_source_revision,
                    "observation_source_revision": prior_source_revision,
                    "observation_segment_id": observation_segment_id,
                    "observation_run_id": observation_run_id,
                }
            )
        state[marker_key] = marker
        return policy_id
    return None


def _arm_field_city_clear_route_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    source_world: WorldSource | None,
    segments: Collection[Any],
    storage: RunStorage | None = None,
    campaign_id: int | None = None,
    excluded_policy_ids: Collection[str] = (),
    allow_repeated_policy_ids: Collection[str] = (),
) -> str | None:
    """Recheck one unchanged plain route after its observed city block moves."""
    boot_id = state.get("world_boot_id")
    revision = state.get(_SOURCE_REVISION_KEY)
    level = _level(state)
    current = state.get("campaign_field_city_preflight")
    existing = state.get(_FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY)
    if (
        source_world is None or not boot_id or not revision
        or not _is_safe_healer_checkpoint(state)
        or _campaign_needs_healer_recovery(state)
        or not isinstance(current, Mapping)
    ):
        return None
    observation_run_id = _field_city_preflight_observation_run_id(
        current, segments, boot_id=str(boot_id), character_level=level,
        source_revision=str(revision),
    )
    source_refresh_mode = observation_run_id is None
    existing_refresh = state.get(_FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY)
    if source_refresh_mode and (
        isinstance(existing_refresh, Mapping)
        and existing_refresh.get("boot_id") == boot_id
        and existing_refresh.get("level") == level
        and existing_refresh.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return None
    if not (
        current.get("complete") is True
        and current.get("blocked") is False
        and current.get("boot_id") == boot_id
        and current.get("level") == level
    ):
        return None
    healer = source_world.rooms.get(3054)
    if healer is None:
        return None

    def city_rooms(locations: Any) -> set[int] | None:
        if not isinstance(locations, (list, tuple)) or not locations:
            return None
        mapped: set[int] = set()
        for label in locations:
            normalized = _normalise_room_label(label)
            matches = {
                room.vnum for room in source_world.rooms.values()
                if room.area_file == healer.area_file
                and normalized and _normalise_room_label(room.name) == normalized
            }
            if not matches:
                return None
            mapped.update(matches)
        return mapped

    clear_rooms = city_rooms(current.get("locations"))
    if not clear_rooms:
        return None
    blocked_ids = _field_city_departure_blocked_policy_ids(state)
    excluded = set(excluded_policy_ids)
    attempted = _field_city_route_attempted_policy_ids(state)
    marker_spent = bool(
        not source_refresh_mode
        and isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") == level
    )

    def revalidation_priority(
        candidate: HuntCandidate,
    ) -> tuple[float, float, float, int]:
        useful_probability = _source_ranked_useful_fuzz_probability(
            candidate,
            character_level=level,
        )
        score_per_step = max(0.0, float(candidate.score)) / max(
            1, len(candidate.route)
        )
        return (
            useful_probability,
            score_per_step,
            float(candidate.score),
            -len(candidate.route),
        )

    for candidate in sorted(
        candidates,
        key=revalidation_priority,
        reverse=True,
    ):
        policy_id = _source_ranked_policy_id(candidate, character_level=level)
        productive_proof = None
        if marker_spent or policy_id in attempted:
            from .campaign_migrations import productive_city_clearance_proof

            productive_proof = productive_city_clearance_proof(
                state, candidate, policy_id=policy_id, segments=segments,
                summary_loader=getattr(storage, "get_run_summary", None),
            )
            if productive_proof is None:
                continue
        if (
            policy_id not in blocked_ids or policy_id in excluded
            or (
                not candidate.autonomous_safe
                and not plain_bounded_population(candidate, source_world)
            ) or candidate.specials
            or candidate.equipped_weapons or candidate.is_coin_stash
            or _source_ranked_xp_loss_record(state, policy_id) is not None
            or not _source_ranked_candidate_in_current_band(
                candidate, state, world=source_world, character_level=level,
                character_max_hp=state.get("max_hp"),
                allow_repeated_kills=policy_id in allow_repeated_policy_ids,
            ) and not (
                plain_bounded_population(candidate, source_world)
                and (candidate.boot_kills < 3 or policy_id in allow_repeated_policy_ids)
                and _source_candidate_fits_movement(candidate, state, world=source_world)
                and _source_ranked_post_loss_plain_probe_allowed(
                    candidate, state, character_level=level, source_world=source_world,
                )
            )
            or not _source_ranked_level_admission_available(
                candidate, state, character_level=level, source_world=source_world,
            )
            or _source_ranked_candidate_requires_sanctuary_for_state(
                candidate, state, character_level=level, source_world=source_world,
            )
            or (
                candidate.requires_flight and not any(
                    _state_has_active_affect(state.get("affects"), effect)
                    for effect in ("fly", "levitation")
                )
            )
        ):
            continue
        route_rooms = _source_route_room_vnums(
            source_world, candidate.route_origin_room_vnum, candidate.route,
        )
        if (
            not route_rooms or route_rooms[-1] != candidate.room_vnum
            or clear_rooms.intersection(route_rooms)
        ):
            continue
        saved = _field_city_revalidation_segment(
            policy_id, segments, storage=storage, campaign_id=campaign_id,
        )
        if saved is None and storage is not None and campaign_id is not None:
            indexed_identity = getattr(storage, "get_indexed_campaign_phase_segment_id", None)
            if callable(indexed_identity):
                try:
                    segment_id = indexed_identity(campaign_id, policy_id)
                except (OSError, sqlite3.Error, TypeError, ValueError):
                    segment_id = None
                if type(segment_id) is int and segment_id > 0:
                    saved = _field_city_segment_by_id(
                        segment_id, segments, storage=storage, campaign_id=campaign_id,
                    )
        if saved is None:
            continue
        segment, start, end = saved
        if segment.get("phase") != policy_id or segment.get("status") != "success":
            continue
        prior = end.get("campaign_field_city_preflight")
        recorded = _source_ranked_candidate_from_record(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY),
            source_revision=start.get(_SOURCE_REVISION_KEY),
        )
        if not isinstance(prior, Mapping) or recorded is None:
            continue
        try:
            prior_run_id = int(segment.get("run_id"))
            unchanged = (
                int(start.get("xp")) == int(end.get("xp"))
                and int(start.get("xp_loss_total")) == int(end.get("xp_loss_total"))
            )
        except (TypeError, ValueError):
            continue
        observation = current
        observed_run_id = observation_run_id
        observation_segment_id: int | None = None
        prior_source_revision = start.get(_SOURCE_REVISION_KEY)
        source_refresh = False
        if source_refresh_mode:
            if (
                not isinstance(prior_source_revision, str)
                or not prior_source_revision
                or prior_source_revision == revision
            ):
                continue
            refresh_observation = _field_city_source_refresh_observation(
                {"changed_locations": list(current.get("locations", ()))},
                segments,
                boot_id=str(boot_id),
                character_level=level,
                source_revision=prior_source_revision,
                blocked_segment_id=int(segment.get("id") or 0),
                blocked_run_id=prior_run_id,
                storage=storage,
                campaign_id=campaign_id,
            )
            if refresh_observation is None:
                continue
            observation_segment_id, observed_run_id, observation = (
                refresh_observation
            )
            source_refresh = True
        if observed_run_id is None:
            continue
        if not (
            unchanged and prior_run_id > 0 and observed_run_id > prior_run_id
            and prior.get("run_id") == prior_run_id
            and prior.get("policy_id") == policy_id
            and prior.get("boot_id") == boot_id and prior.get("level") == level
            and prior.get("complete") is True and prior.get("blocked") is True
            and prior.get("stopped_before_departure") is True
            and prior.get("outbound_index") == 0
            and type(prior.get("wait_attempts")) is int and prior["wait_attempts"] >= 3
            and prior.get("detour") is None and prior.get("route_correction") is None
            and prior.get("route_correction_attempted") is not True
            and start.get("world_boot_id") == end.get("world_boot_id") == boot_id
            and _level(dict(start)) == _level(dict(end)) == level
            and start.get(_SOURCE_REVISION_KEY)
            and start.get(_SOURCE_REVISION_KEY) == end.get(_SOURCE_REVISION_KEY)
            and str(start.get("room_vnum")) == str(end.get("room_vnum")) == "3054"
            and end.get("xp_loss_observed") not in {True, 1}
            and end.get("dead") is not True and end.get("in_combat") is not True
            and (start.get("campaign_completed_kills") or [])
            == (end.get("campaign_completed_kills") or [])
            and (start.get("campaign_objective_kills") or [])
            == (end.get("campaign_objective_kills") or [])
            and recorded.mobile_vnum == candidate.mobile_vnum
            and recorded.room_vnum == candidate.room_vnum
            and recorded.route == candidate.route
            and _source_ranked_policy_id(recorded, character_level=level) == policy_id
        ):
            continue
        old_rooms = city_rooms(prior.get("locations"))
        observed_rooms = city_rooms(observation.get("locations"))
        if (
            not old_rooms or not observed_rooms
            or old_rooms == observed_rooms
            or not old_rooms.intersection(route_rooms)
            or observed_rooms != clear_rooms
        ):
            continue
        if productive_proof is not None:
            if (
                productive_proof["productive_run_id"] >= prior_run_id
                or start.get(_SOURCE_REVISION_KEY) != revision
            ):
                continue
        marker_key = (
            _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY
            if source_refresh
            else _FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY
        )
        marker = {
            "boot_id": boot_id, "level": level, "source_revision": revision,
            "prior_source_revision": prior_source_revision,
            "policy_id": policy_id, "source_mobile_vnum": candidate.mobile_vnum,
            "source_room_vnum": candidate.room_vnum, "source_route": list(candidate.route),
            "prior_segment_id": segment.get("id"), "prior_run_id": prior_run_id,
            "observation_run_id": observed_run_id,
            "observation_source_revision": (
                prior_source_revision if source_refresh else revision
            ),
            "blocked_room_vnums": sorted(clear_rooms),
            "prior_blocked_room_vnums": sorted(old_rooms),
            "prior_locations": list(prior["locations"]),
            "changed_locations": list(observation["locations"]),
            "max_extra_steps": _FIELD_CITY_ALTERNATE_ROUTE_MAX_EXTRA_STEPS,
            "repeat_after_kill_cap": candidate.boot_kills >= 3
            and policy_id in allow_repeated_policy_ids,
            "route_clear_recheck": True, "status": "pending", "attempted": False,
            "reason": (
                "one source-refresh unchanged-route recheck after a later "
                "same-revision locator observed the city blocker outside "
                "the entire current source route"
                if source_refresh
                else "one unchanged-route recheck after a later run observed "
                "the city blocker outside the entire source route"
            ),
        }
        if source_refresh:
            if observation_segment_id is None:
                continue
            marker.update(
                {
                    "source_refresh": True,
                    "observation_segment_id": observation_segment_id,
                }
            )
        state[marker_key] = marker
        if productive_proof is not None:
            marker["productive_clearance"] = productive_proof
            if isinstance(existing, Mapping):
                marker["superseded_clearance"] = dict(existing)
            ledger = state.get(PRODUCTIVE_CITY_CLEARANCE_KEY)
            policies = dict(ledger.get("policies") or {}) if isinstance(ledger, Mapping) and (
                ledger.get("boot_id") == boot_id and ledger.get("level") == level
            ) else {}
            policies[policy_id] = {**productive_proof, "blocked_run_id": prior_run_id,
                                   "observation_run_id": observed_run_id, "status": "pending"}
            state[PRODUCTIVE_CITY_CLEARANCE_KEY] = {
                "boot_id": boot_id, "level": level, "policies": policies,
            }
        return policy_id
    return None


def _verify_field_city_clear_route_revalidation(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> dict[str, Any]:
    """Promote only an exact successful hunt-and-healer return, not a retry."""
    restored = dict(state)
    recent_segments = tuple(segments)[-_PRODUCTIVE_HUNT_ABSENCE_WAIT_TAIL_LIMIT:]
    for marker_key in (
        _FIELD_CITY_CLEAR_ROUTE_REVALIDATION_KEY,
        _FIELD_CITY_SOURCE_REFRESH_REVALIDATION_KEY,
    ):
        marker = state.get(marker_key)
        if not (
            isinstance(marker, Mapping)
            and marker.get("route_clear_recheck") is True
            and marker.get("status") == "attempted"
            and marker.get("attempted") is True
            and marker.get("boot_id") == state.get("world_boot_id")
            and marker.get("level") == _level(dict(state))
            and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        ):
            continue
        policy_id = marker.get("policy_id")
        for raw_segment in reversed(recent_segments):
            segment = dict(raw_segment)
            if segment.get("phase") != policy_id or segment.get("status") != "success":
                continue
            try:
                run_id = int(segment.get("run_id"))
                start = json.loads(segment.get("start_state_json") or "{}")
                end = json.loads(segment.get("end_state_json") or "{}")
                if not isinstance(start, Mapping) or not isinstance(end, Mapping):
                    continue
                gain = int(end.get("xp")) - int(start.get("xp"))
                unchanged_loss = int(start.get("xp_loss_total")) == int(end.get("xp_loss_total"))
            except (TypeError, ValueError):
                continue
            city = end.get("campaign_field_city_preflight")
            start_marker = start.get(marker_key)
            candidate = _source_ranked_candidate_from_record(
                start.get(_SOURCE_RANKED_CANDIDATE_KEY),
                source_revision=marker.get("source_revision"),
            )
            kills = end.get("campaign_objective_kills")
            if not (
                run_id > 0 and gain > 0 and unchanged_loss
                and isinstance(start_marker, Mapping) and dict(start_marker) == dict(marker)
                and candidate is not None
                and candidate.mobile_vnum == marker.get("source_mobile_vnum")
                and candidate.room_vnum == marker.get("source_room_vnum")
                and list(candidate.route) == marker.get("source_route")
                and isinstance(kills, list)
                and any(
                    isinstance(kill, Mapping) and kill.get("source_policy_id") == policy_id
                    and kill.get("source_mobile_vnum") == candidate.mobile_vnum
                    and isinstance(kill.get("xp_gained"), int) and kill["xp_gained"] > 0
                    for kill in kills
                )
                and isinstance(city, Mapping) and city.get("run_id") == run_id
                and city.get("complete") is True and city.get("blocked") is False
                and city.get("outbound_index") == len(candidate.route)
                and city.get("boot_id") == marker.get("boot_id")
                and city.get("level") == marker.get("level")
                and start.get("world_boot_id") == end.get("world_boot_id") == marker.get("boot_id")
                and _level(dict(start)) == _level(dict(end)) == marker.get("level")
                and start.get(_SOURCE_REVISION_KEY) == end.get(_SOURCE_REVISION_KEY)
                == marker.get("source_revision")
                and _is_safe_healer_checkpoint(end)
                and not end.get("xp_loss_observed")
                and not end.get("campaign_fastwalk_abort_reason")
            ):
                continue
            restored[marker_key] = {
                **dict(marker), "status": "succeeded", "verified_run_id": run_id,
                "verified_segment_id": segment.get("id"), "verified_net_xp": gain,
            }
            return restored
    return restored


def _restore_field_city_route_state(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> dict[str, Any]:
    """Recover route cooldowns and unfinished attempts from segment history."""
    restored = _verify_field_city_clear_route_revalidation(state, segments)
    if not _field_city_departure_checkpoint_current_reboot(restored):
        return restored
    evidence = restored.get("campaign_field_city_preflight")
    attempted = set(_field_city_route_attempted_policy_ids(restored))
    blocked = set(_field_city_departure_blocked_policy_ids(restored))
    newest_recovered_policy_id: str | None = None
    correction_revalidation: dict[str, Any] | None = None
    for raw_segment in reversed(tuple(segments)):
        try:
            segment = dict(raw_segment)
        except (TypeError, ValueError):
            continue
        raw_start = segment.get("start_state_json")
        raw_end = segment.get("end_state_json")
        try:
            start_state = (
                json.loads(raw_start)
                if isinstance(raw_start, str)
                else raw_start
            )
            end_state = (
                json.loads(raw_end)
                if isinstance(raw_end, str)
                else raw_end
            )
        except (TypeError, ValueError):
            continue
        if not isinstance(start_state, Mapping):
            start_state = {}
        if isinstance(end_state, Mapping):
            if (
                segment.get("status") in {"success", "ready"}
                and _field_city_departure_was_deferred(
                    start_state,
                    end_state,
                )
                and end_state.get("world_boot_id")
                == restored.get("world_boot_id")
                and _level(dict(end_state)) == _level(restored)
            ):
                policy_id = _field_city_route_policy_id_from_segment(
                    segment,
                    start_state,
                    end_state,
                )
                if policy_id:
                    blocked.add(policy_id)
                    if newest_recovered_policy_id is None:
                        newest_recovered_policy_id = policy_id
                    if correction_revalidation is None:
                        correction_revalidation = (
                            _field_city_correction_revalidation_from_segment(
                                restored,
                                start_state,
                                end_state,
                                segment,
                                policy_id=policy_id,
                            )
                        )
        elif segment.get("status") == "failed":
            marker = start_state.get(_FIELD_CITY_ROUTE_ATTEMPTS_KEY)
            if (
                not isinstance(marker, Mapping)
                or marker.get("status") != "attempted"
                or marker.get("boot_id") != restored.get("world_boot_id")
                or marker.get("level") != _level(restored)
            ):
                continue
            raw_policy_ids = marker.get("policy_ids")
            if isinstance(raw_policy_ids, (list, tuple, set, frozenset)):
                attempted.update(
                    str(value)
                    for value in raw_policy_ids
                    if str(value).strip()
                )
    if blocked:
        restored[_FIELD_CITY_BLOCKED_POLICIES_KEY] = {
            "boot_id": restored.get("world_boot_id"),
            "level": _level(restored),
            "policy_ids": sorted(blocked),
        }
    if (
        newest_recovered_policy_id
        and isinstance(evidence, Mapping)
        and not str(evidence.get("policy_id") or "").strip()
    ):
        restored["campaign_field_city_preflight"] = {
            **dict(evidence),
            "policy_id": newest_recovered_policy_id,
        }
    if attempted:
        restored[_FIELD_CITY_ROUTE_ATTEMPTS_KEY] = {
            "boot_id": restored.get("world_boot_id"),
            "level": _level(restored),
            "status": "attempted",
            "policy_ids": sorted(attempted),
        }
    existing_revalidation = restored.get(
        _FIELD_CITY_CORRECTION_REVALIDATION_KEY
    )
    existing_revalidation_current = bool(
        isinstance(existing_revalidation, Mapping)
        and existing_revalidation.get("boot_id")
        == restored.get("world_boot_id")
        and existing_revalidation.get("level") == _level(restored)
        and existing_revalidation.get("source_revision")
        == restored.get(_SOURCE_REVISION_KEY)
        and existing_revalidation.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    )
    if correction_revalidation is not None and not existing_revalidation_current:
        restored[_FIELD_CITY_CORRECTION_REVALIDATION_KEY] = (
            correction_revalidation
        )
    return restored


def _stale_post_kill_familiar_abort(state: Mapping[str, Any]) -> bool:
    """Identify the exact successful sortie polluted by a second-target probe."""
    reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    policy_id = str(state.get("campaign_last_policy") or "")
    result = _campaign_research_results(dict(state)).get(policy_id)
    withdrawal = state.get("campaign_familiar_withdrawal")
    objective_kills = state.get("campaign_objective_kills")
    room_flags = {
        str(flag).casefold()
        for flag in state.get("room_flags") or ()
    }
    try:
        hp = int(state.get("hp") or 0)
    except (TypeError, ValueError):
        hp = 0
    matching_kill = False
    if isinstance(objective_kills, Collection) and not isinstance(
        objective_kills, (str, bytes)
    ):
        for kill in objective_kills:
            if not isinstance(kill, Mapping):
                continue
            try:
                xp_gained = int(kill.get("xp_gained") or 0)
            except (TypeError, ValueError):
                xp_gained = 0
            if (
                kill.get("source_policy_id") == policy_id
                and xp_gained >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
            ):
                matching_kill = True
                break
    return bool(
        reason.startswith(_FAMILIAR_POST_KILL_ABORT_PREFIX)
        and reason.endswith(_FAMILIAR_POST_KILL_ABORT_SUFFIX)
        and policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and policy_id == state.get(_LAST_PRODUCTIVE_POLICY_KEY)
        and matching_kill
        and isinstance(result, Mapping)
        and result.get("observed") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
        and isinstance(withdrawal, Mapping)
        and withdrawal.get("confirmed") is True
        and not withdrawal.get("failure")
        and state.get("campaign_fastwalk_route_hazards") == []
        and state.get("campaign_died_during_segment") is False
        and state.get("dead") is not True
        and state.get("xp_loss_observed") is not True
        and state.get("campaign_xp_loss_observed") is not True
        and str(state.get("room_vnum") or "") == "3054"
        and {"healing", "safe"}.issubset(room_flags)
        and state.get("enemies") == []
        and state.get("position") in {5, 6, 7}
        and hp > 0
    )


