def _source_ranked_candidate_from_record(
    value: object,
    *,
    source_revision: str | None = None,
) -> HuntCandidate | None:
    """Restore a selected source candidate after a disconnect or process exit."""
    if not isinstance(value, Mapping):
        return None
    if source_revision is not None and value.get("source_revision") != source_revision:
        return None

    def text_tuple(key: str) -> tuple[str, ...]:
        raw = value.get(key)
        if not isinstance(raw, (list, tuple)):
            return ()
        return tuple(str(item) for item in raw)

    def int_pair(key: str) -> tuple[int, int]:
        raw = value.get(key)
        if not isinstance(raw, (list, tuple)) or len(raw) != 2:
            return (0, 0)
        try:
            return int(raw[0]), int(raw[1])
        except (TypeError, ValueError):
            return (0, 0)

    try:
        area_file = str(value.get("area_file") or "")
        target = str(value.get("target") or "")
        target_keyword = str(value.get("target_keyword") or "")
        if not area_file or not target or not target_keyword:
            return None
        return HuntCandidate(
            status=str(value.get("status") or "caution"),
            score=float(value.get("score") or 0),
            area_file=area_file,
            mobile_vnum=int(value.get("mobile_vnum") or 0),
            target=target,
            target_identity=str(value.get("target_identity") or ""),
            target_keyword=target_keyword,
            rank=str(value.get("rank") or "common"),
            level=int(value.get("level") or 0),
            room_vnum=int(value.get("room_vnum") or 0),
            room_name=str(value.get("room_name") or ""),
            route=text_tuple("route"),
            source_spawn_limit=int(value.get("source_spawn_limit") or 0),
            room_spawn_count=int(value.get("room_spawn_count") or 0),
            boot_kills=int(value.get("boot_kills") or 0),
            loot=text_tuple("loot"),
            source_value=int(value.get("source_value") or 0),
            contained_coins=int(value.get("contained_coins") or 0),
            hazards=text_tuple("hazards"),
            equipped_weapons=text_tuple("equipped_weapons"),
            target_body_form_flags=(
                int(value["target_body_form_flags"])
                if value.get("target_body_form_flags") is not None
                else None
            ),
            estimated_level_range=int_pair("estimated_level_range"),
            estimated_base_hp_range=int_pair("estimated_base_hp_range"),
            source_damage_modifier=(
                int(value["source_damage_modifier"])
                if value.get("source_damage_modifier") is not None
                else 0
                if "source_damage_modifier" not in value
                else None
            ),
            estimated_peak_round_damage=int(
                value.get("estimated_peak_round_damage") or 0
            ),
            estimated_min_peak_round_damage=int(
                value.get("estimated_min_peak_round_damage") or 0
            ),
            estimated_critical_hit_damage=int(
                value.get("estimated_critical_hit_damage") or 0
            ),
            autonomy_rejections=text_tuple("autonomy_rejections"),
            combat_readiness=str(
                value.get("combat_readiness") or "unassessed"
            ),
            combat_readiness_bonus=int(
                value.get("combat_readiness_bonus") or 0
            ),
            specials=text_tuple("specials"),
            route_preflight_room_vnum=(
                str(value["route_preflight_room_vnum"])
                if value.get("route_preflight_room_vnum") is not None
                else None
            ),
            route_preflight_command=(
                str(value["route_preflight_command"])
                if value.get("route_preflight_command") is not None
                else None
            ),
            route_preflight_target=(
                str(value["route_preflight_target"])
                if value.get("route_preflight_target") is not None
                else None
            ),
            route_preflight_checks=tuple(
                (str(pair[0]), str(pair[1]))
                for pair in (value.get("route_preflight_checks") or ())
                if isinstance(pair, (list, tuple)) and len(pair) >= 2
            ),
            route_preflight_level_range=int_pair(
                "route_preflight_level_range"
            ),
            route_preflight_hard_hazard=bool(
                value.get("route_preflight_hard_hazard", False)
            ),
            route_preflight_route_room_names=text_tuple(
                "route_preflight_route_room_names"
            ),
            route_hard_hazard_targets=text_tuple("route_hard_hazard_targets"),
            route_hazard_mobile_vnums=tuple(
                int(item) for item in (value.get("route_hazard_mobile_vnums") or ())
            ),
            route_aggressive_mobile_vnums=tuple(
                int(item)
                for item in (value.get("route_aggressive_mobile_vnums") or ())
            ),
            route_attack_program_mobile_vnums=tuple(
                int(item)
                for item in (
                    value.get("route_attack_program_mobile_vnums") or ()
                )
            ),
            route_special_mobile_vnums=tuple(
                int(item) for item in (value.get("route_special_mobile_vnums") or ())
            ),
            route_economic_hunt_mobile_vnums=tuple(
                int(item) for item in (value.get("route_economic_hunt_mobile_vnums") or ())
            ),
            route_economic_population=bool(
                value.get("route_economic_population", False)
            ),
            route_economic_source_rejections=text_tuple("route_economic_source_rejections"),
            undead=bool(value.get("undead", False)),
            sentinel=bool(value["sentinel"])
            if "sentinel" in value
            else True,
            stay_area=bool(value["stay_area"])
            if "stay_area" in value
            else True,
            estimated_move_cost=int(value.get("estimated_move_cost") or 0),
            estimated_flying_move_cost=int(
                value.get("estimated_flying_move_cost") or 0
            ),
            requires_flight=bool(value.get("requires_flight", False)),
            requires_water_breathing=bool(
                value.get("requires_water_breathing", False)
            ),
            requires_detect_invisibility=bool(
                value.get("requires_detect_invisibility", False)
            ),
            ground_loot_keywords=text_tuple("ground_loot_keywords"),
            ground_loot_object_vnums=tuple(
                int(item)
                for item in (
                    value.get("ground_loot_object_vnums") or ()
                )
            ),
            is_coin_stash=bool(value.get("is_coin_stash", False)),
            is_food_stash=bool(value.get("is_food_stash", False)),
            route_origin_recall_index=int(
                value.get("route_origin_recall_index") or 0
            ),
            route_origin_room_vnum=int(
                value.get("route_origin_room_vnum") or 3001
            ),
        )
    except (TypeError, ValueError):
        return None


def _source_ranked_circuit_from_record(
    value: object,
    *,
    source_revision: str | None = None,
) -> tuple[HuntCandidate, ...]:
    """Restore supplementary source targets from a checkpointed candidate."""
    if not isinstance(value, Mapping):
        return ()
    raw_circuit = value.get("circuit")
    if not isinstance(raw_circuit, (list, tuple)):
        return ()
    restored = []
    for raw_candidate in raw_circuit:
        candidate = _source_ranked_candidate_from_record(
            raw_candidate,
            source_revision=source_revision,
        )
        if candidate is not None:
            restored.append(candidate)
    return tuple(restored)


def _refresh_source_ranked_candidate_keyword(
    candidate: HuntCandidate,
    world: WorldSource | None,
) -> HuntCandidate:
    """Repair a persisted target keyword from the current source prototypes."""
    if world is None:
        return candidate
    mobile = world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return candidate
    keyword = _least_ambiguous_source_keyword(world, mobile)
    if not keyword or keyword == candidate.target_keyword:
        return candidate
    return replace(candidate, target_keyword=keyword)


def _source_mobile_progress_from_kill_records(
    records: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> tuple[Counter[int], dict[int, int], dict[int, int]]:
    """Summarize durable, reboot-local objective kills by source prototype."""
    counts: Counter[int] = Counter()
    latest_xp: dict[int, int] = {}
    best_xp: dict[int, int] = {}
    for record in records:
        if boot_id is not None and record.get("boot_id") != boot_id:
            continue
        policy_id = str(record.get("source_policy_id") or "")
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if (
            not bool(record.get("objective_eligible", True))
            or bool(record.get("below_useful_band"))
            or bool(record.get("route_gate"))
        ):
            continue
        try:
            mobile_vnum = int(record.get("source_mobile_vnum") or 0)
            xp_gained = int(record.get("xp_gained") or 0)
        except (TypeError, ValueError):
            continue
        if mobile_vnum <= 0:
            continue
        reward = max(0, xp_gained)
        counts[mobile_vnum] += 1
        latest_xp[mobile_vnum] = reward
        best_xp[mobile_vnum] = max(best_xp.get(mobile_vnum, 0), reward)
    return counts, latest_xp, best_xp


def _source_policy_latest_xp_from_kill_records(
    records: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> dict[str, int]:
    """Return the latest eligible same-boot XP result for each exact policy."""
    latest_xp: dict[str, int] = {}
    for record in records:
        if boot_id is not None and record.get("boot_id") != boot_id:
            continue
        policy_id = str(record.get("source_policy_id") or "")
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if (
            not bool(record.get("objective_eligible", True))
            or bool(record.get("below_useful_band"))
            or bool(record.get("route_gate"))
        ):
            continue
        try:
            xp_gained = int(record.get("xp_gained") or 0)
        except (TypeError, ValueError):
            continue
        latest_xp[policy_id] = max(0, xp_gained)
    return latest_xp


def _source_mobile_kill_counts_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> Counter[int]:
    """Count source-ranked kills by mobile prototype, not display name.

    DD4 can have distinct mobile prototypes with the same short description.
    Campaign segment evidence retains the selected source VNUM, so use that
    identity when applying reboot-local kill caps to source candidates.
    """
    counts: Counter[int] = Counter()
    for segment in segments:
        if not _execution_records_objective_kills(
            str(segment.get("phase") or "")
        ):
            continue
        try:
            start_raw = segment.get("start_state_json")
            end_raw = segment.get("end_state_json")
        except AttributeError:
            continue
        if not isinstance(end_raw, str):
            continue
        try:
            start = json.loads(start_raw) if isinstance(start_raw, str) else {}
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        candidate_record = end.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            continue
        try:
            mobile_vnum = int(candidate_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        if mobile_vnum <= 0:
            continue
        # A field run can kill an incidental mobile while its selected source
        # target is rejected.  Only deliberate objective kills may consume
        # the selected source mobile's reboot-local cap.  Preserve the legacy
        # fallback for older segment records that did not persist the
        # objective-kill field.
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if not isinstance(kills, list) or not kills:
            continue
        untagged_kills = 0
        for kill in kills:
            if not isinstance(kill, Mapping):
                untagged_kills += 1
                continue
            try:
                kill_mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
            except (TypeError, ValueError):
                kill_mobile_vnum = 0
            if kill_mobile_vnum > 0:
                counts[kill_mobile_vnum] += 1
            else:
                untagged_kills += 1
        # Preserve source-VNUM accounting for historical records and for any
        # incidental objective entry that predates per-stop identity tags.
        counts[mobile_vnum] += untagged_kills
    return counts


def _source_capacity_research_mobile_keys_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> frozenset[tuple[str, int]]:
    """Quarantine failed capacity probes by source area and mobile.

    Capacity research is intentionally consider-only. Once a segment has
    spent a field opportunity on a multi-instance prototype without an
    objective kill, trying another reset room for the same prototype in the
    same reboot is redundant and can consume another full route budget.
        Preserve the segment evidence, but let the selector rotate to an
        independent source mobile or wait for a fresh reboot.
    """
    blocked: set[tuple[str, int]] = set()
    for segment in segments:
        def segment_value(key: str) -> Any:
            if isinstance(segment, Mapping):
                return segment.get(key)
            try:
                return segment[key]
            except (KeyError, IndexError, TypeError):
                return None

        if not str(segment_value("phase") or "").startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            continue
        start_raw = segment_value("start_state_json")
        end_raw = segment_value("end_state_json")
        if not isinstance(end_raw, str):
            continue
        try:
            start = json.loads(start_raw) if isinstance(start_raw, str) else {}
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        candidate_record = end.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            continue
        try:
            source_spawn_limit = int(
                candidate_record.get("source_spawn_limit") or 0
            )
            mobile_vnum = int(candidate_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        area_file = str(candidate_record.get("area_file") or "")
        rejections = candidate_record.get("autonomy_rejections") or ()
        if (
            not area_file
            or mobile_vnum <= 0
            or source_spawn_limit <= 1
            or "target reset capacity exceeds one" not in rejections
        ):
            continue
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if isinstance(kills, (list, tuple)) and kills:
            # A later objective kill is stronger evidence than an earlier
            # consider-only capacity probe.  Reopen this source mobile while
            # retaining any subsequent failed probe as the latest boundary.
            blocked.discard((area_file, mobile_vnum))
            continue
        blocked.add((area_file, mobile_vnum))
    return frozenset(blocked)


def _source_capacity_research_candidate_record(record: object) -> bool:
    """Return whether a persisted candidate is a capacity-only probe."""
    if not isinstance(record, Mapping):
        return False
    try:
        source_spawn_limit = int(record.get("source_spawn_limit") or 0)
    except (TypeError, ValueError):
        source_spawn_limit = 0
    rejections = record.get("autonomy_rejections") or ()
    if isinstance(rejections, str):
        rejections = (rejections,)
    return bool(
        source_spawn_limit > 1
        and "target reset capacity exceeds one" in rejections
    )


def _source_capacity_reset_wait_available(
    state: Mapping[str, Any],
    *,
    automatic_reset_wait: bool = False,
) -> bool:
    """Return whether one automatic reset has opened a capacity probe."""
    boot_id = state.get("world_boot_id")
    marker = state.get(_SOURCE_CAPACITY_RESET_WAIT_KEY)
    if isinstance(marker, Mapping) and marker.get("boot_id") == boot_id:
        return marker.get("consumed") is not True
    return bool(automatic_reset_wait and boot_id is not None)


def _sanctuary_capacity_reset_probe_available(
    state: Mapping[str, Any],
    *,
    automatic_reset_wait: bool = False,
) -> bool:
    """Keep automatic capacity evidence behind the sanctuary retry gate."""
    return bool(
        _source_capacity_reset_wait_available(
            state,
            automatic_reset_wait=automatic_reset_wait,
        )
        and not _sanctuary_recovery_attempts_exhausted(state)
    )


def _arm_source_capacity_research_after_reset(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Persist one capacity-probe entitlement after an automatic wait."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)
    armed = dict(state)
    armed[_SOURCE_CAPACITY_RESET_WAIT_KEY] = {
        "boot_id": boot_id,
        "consumed": False,
        "reason": "automatic area reset wait completed",
    }
    return armed


def _preserve_source_capacity_entitlement_for_maintenance(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Keep a reset-aged capacity probe armed through world-time maintenance."""
    marker = state.get(_SOURCE_CAPACITY_RESET_WAIT_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("consumed") is True
        and marker.get("reason") == "capacity probe dispatched"
    ):
        return dict(state)
    preserved = _arm_source_capacity_research_after_reset(dict(state))
    if _source_capacity_research_candidate_record(
        preserved.get(_SOURCE_RANKED_CANDIDATE_KEY)
    ):
        preserved.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    return preserved


def _repair_source_capacity_reset_wait(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
    checkpoints: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover an unconsumed automatic reset entitlement after a restart."""
    def row_value(row: object, key: str) -> Any:
        if isinstance(row, Mapping):
            return row.get(key)
        try:
            return row[key]  # type: ignore[index]
        except (KeyError, IndexError, TypeError):
            return None

    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)
    marker = state.get(_SOURCE_CAPACITY_RESET_WAIT_KEY)
    if (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == boot_id
    ):
        return dict(state)

    reset_boundary: int | None = None
    for raw_checkpoint in checkpoints:
        reason = row_value(raw_checkpoint, "reason")
        if reason != _CAMPAIGN_RESEARCH_RESET_WAIT_REASON:
            continue
        raw_state = row_value(raw_checkpoint, "state_json")
        if not isinstance(raw_state, str):
            continue
        try:
            checkpoint_state = json.loads(raw_state)
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(checkpoint_state, Mapping):
            continue
        if checkpoint_state.get("world_boot_id") != boot_id:
            continue
        raw_boundary = row_value(raw_checkpoint, "segment_id")
        try:
            reset_boundary = int(raw_boundary) if raw_boundary is not None else 0
        except (TypeError, ValueError):
            reset_boundary = 0

    if reset_boundary is None:
        repaired = dict(state)
        if marker is not None:
            repaired.pop(_SOURCE_CAPACITY_RESET_WAIT_KEY, None)
        return repaired

    consumed = False
    consumed_policy_id = ""
    for raw_segment in segments:
        try:
            segment_id = int(row_value(raw_segment, "id") or 0)
        except (TypeError, ValueError):
            segment_id = 0
        if segment_id <= reset_boundary:
            continue
        end_state: Mapping[str, Any] = {}
        start_state: Mapping[str, Any] = {}
        for field, target in (
            ("end_state_json", "end"),
            ("start_state_json", "start"),
        ):
            raw_state = row_value(raw_segment, field)
            if not isinstance(raw_state, str):
                continue
            try:
                parsed = json.loads(raw_state)
            except (TypeError, json.JSONDecodeError):
                continue
            if target == "end" and isinstance(parsed, Mapping):
                end_state = parsed
            elif target == "start" and isinstance(parsed, Mapping):
                start_state = parsed
        segment_boot_id = end_state.get("world_boot_id") or start_state.get(
            "world_boot_id"
        )
        if segment_boot_id != boot_id:
            continue
        for segment_state in (start_state, end_state):
            candidate_record = segment_state.get(_SOURCE_RANKED_CANDIDATE_KEY)
            if not _source_capacity_research_candidate_record(candidate_record):
                continue
            consumed = True
            consumed_policy_id = str(
                segment_state.get("campaign_last_policy") or ""
            )
            break
        if consumed:
            break

    repaired = dict(state)
    repaired[_SOURCE_CAPACITY_RESET_WAIT_KEY] = {
        "boot_id": boot_id,
        "consumed": consumed,
        "reason": "reconstructed from automatic area reset wait",
    }
    if consumed_policy_id:
        repaired[_SOURCE_CAPACITY_RESET_WAIT_KEY]["policy_id"] = (
            consumed_policy_id
        )
    return repaired


def _consume_source_capacity_reset_wait(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    automatic_reset_wait: bool = False,
    source_object_vnums: Collection[int] = (),
    allow_exact_moria_capacity: bool = False,
    allow_bounded_route_program: bool = False,
) -> None:
    """Consume the reset entitlement when a capacity probe is dispatched."""
    exact_moria_capacity = bool(
        allow_exact_moria_capacity
        and _is_audited_moria_sanctuary_capacity_candidate(
            candidate,
            source_object_vnums,
        )
    )
    if not (
        exact_moria_capacity
        or _source_ranked_capacity_research_candidate(
            candidate,
            character_level=character_level,
            allow_bounded_route_program=allow_bounded_route_program,
        )
    ) or not _source_capacity_reset_wait_available(
        state,
        automatic_reset_wait=automatic_reset_wait,
    ):
        return
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return
    state[_SOURCE_CAPACITY_RESET_WAIT_KEY] = {
        "boot_id": boot_id,
        "consumed": True,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "reason": "capacity probe dispatched",
    }


def _source_mobile_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
    best: bool,
) -> dict[int, int]:
    """Return each source mobile's latest or best objective reward this reboot."""
    latest: dict[int, int] = {}
    for segment in segments:
        if not _execution_records_objective_kills(
            str(segment.get("phase") or "")
        ):
            continue
        end_raw = segment.get("end_state_json")
        if not isinstance(end_raw, str):
            continue
        start_raw = segment.get("start_state_json")
        try:
            start = json.loads(start_raw) if isinstance(start_raw, str) else {}
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            start = {}
            end = {}
        if not isinstance(start, Mapping):
            start = {}
        if not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        candidate_record = end.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not isinstance(candidate_record, Mapping):
            candidate_record = None
        try:
            selected_mobile_vnum = int(
                (candidate_record or {}).get("mobile_vnum") or 0
            )
        except (TypeError, ValueError):
            selected_mobile_vnum = 0
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if not isinstance(kills, list):
            continue
        for kill in kills:
            if not isinstance(kill, Mapping):
                continue
            try:
                mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
                xp_gained = int(kill.get("xp_gained") or 0)
            except (TypeError, ValueError):
                mobile_vnum = 0
                xp_gained = 0
            if mobile_vnum <= 0:
                # Older source-ranked segments stored the selected target's
                # name and XP but not its prototype VNUM. The selected
                # candidate is the same durable identity used by the legacy
                # kill-count fallback, so carry that reward across a level
                # boundary without assigning it to an unrelated mobile.
                mobile_vnum = selected_mobile_vnum
            if mobile_vnum > 0:
                reward = max(0, xp_gained)
                if best:
                    latest[mobile_vnum] = max(
                        latest.get(mobile_vnum, 0),
                        reward,
                    )
                else:
                    latest[mobile_vnum] = reward
    return latest


def _source_mobile_latest_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> dict[int, int]:
    """Return each source mobile's latest objective reward this reboot."""
    return _source_mobile_xp_from_segments(
        segments,
        boot_id=boot_id,
        best=False,
    )


def _source_mobile_best_xp_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
) -> dict[int, int]:
    """Return each source mobile's best objective reward this reboot."""
    return _source_mobile_xp_from_segments(
        segments,
        boot_id=boot_id,
        best=True,
    )


def _source_mobile_recent_kill_vnums_from_segments(
    segments: Collection[Mapping[str, Any]],
    *,
    boot_id: str | int | None,
    cooldown_segments: int = _SOURCE_RANKED_POST_KILL_COOLDOWN_SEGMENTS,
) -> frozenset[int]:
    """Block a killed source prototype for two later source hunt segments."""
    if cooldown_segments <= 0:
        return frozenset()
    recent: set[int] = set()
    later_source_segments = 0
    for segment in reversed(tuple(segments)):
        if later_source_segments >= cooldown_segments:
            break
        phase = str(segment.get("phase") or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if str(segment.get("status") or "") not in {"success", "ready"}:
            continue
        end_raw = segment.get("end_state_json")
        if not isinstance(end_raw, str):
            continue
        try:
            end = json.loads(end_raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(end, Mapping):
            continue
        if boot_id is not None and end.get("world_boot_id") != boot_id:
            continue
        if "campaign_objective_kills" in end:
            kills = end.get("campaign_objective_kills")
        elif "campaign_completed_kills" in end:
            kills = end.get("campaign_completed_kills")
        else:
            kills = end.get("completed_kills")
        if isinstance(kills, list):
            for kill in kills:
                if not isinstance(kill, Mapping):
                    continue
                try:
                    mobile_vnum = int(kill.get("source_mobile_vnum") or 0)
                except (TypeError, ValueError):
                    continue
                if mobile_vnum > 0:
                    recent.add(mobile_vnum)
        later_source_segments += 1
    return frozenset(recent)


def _source_ranked_kill_policy_ids(kills: object) -> tuple[str, ...]:
    """Return distinct source policy identities attached to objective kills."""
    if not isinstance(kills, (list, tuple)):
        return ()
    policy_ids = []
    for kill in kills:
        if not isinstance(kill, Mapping):
            continue
        policy_id = str(kill.get("source_policy_id") or "")
        if (
            policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and policy_id not in policy_ids
        ):
            policy_ids.append(policy_id)
    return tuple(policy_ids)


def _objective_kill_xp_stats(kills: object) -> tuple[int, int, bool]:
    """Return total, best, and presence of explicit XP evidence."""
    if not isinstance(kills, (list, tuple)):
        return 0, 0, False
    values: list[int] = []
    saw_xp = False
    for kill in kills:
        if not isinstance(kill, Mapping):
            continue
        saw_xp = saw_xp or "xp_gained" in kill
        try:
            values.append(max(0, int(kill.get("xp_gained") or 0)))
        except (TypeError, ValueError):
            continue
    return sum(values), max(values, default=0), saw_xp


def _source_ranked_target_tokens(candidate: HuntCandidate) -> frozenset[str]:
    identity_tokens = frozenset(
        token
        for token in re.findall(
            r"[a-z0-9]+",
            _source_ranked_target_identity(candidate),
        )
        if token not in {"a", "an", "the"}
    )
    keyword_tokens = frozenset(
        token
        for token in re.findall(r"[a-z0-9]+", candidate.target_keyword.casefold())
        if token not in {"a", "an", "the"}
    )
    if keyword_tokens and keyword_tokens.issubset(identity_tokens):
        return keyword_tokens
    return identity_tokens


def _source_ranked_crowd_attempts_exhausted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Use durable crowd attempts when the transient result was aged out."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return False
    attempts = state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    record = attempts.get(policy_id) if isinstance(attempts, Mapping) else None
    if not (
        isinstance(record, Mapping)
        and record.get("boot_id") == state.get("world_boot_id")
    ):
        return False
    try:
        return (
            int(record.get("count") or 0)
            >= _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD
        )
    except (TypeError, ValueError):
        return False


def _source_ranked_crowded_circuit_evidence(
    state: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Capture only the fixed reset stops explicitly observed as crowded."""
    candidate = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    if not (
        isinstance(candidate, Mapping)
        and candidate.get("sentinel") is True
        and state.get("campaign_fastwalk_crowded") is True
        and state.get("campaign_fastwalk_target_present_observed") is True
        and boot_id
        and source_revision
        and candidate.get("source_revision") == source_revision
    ):
        return None
    try:
        level = int(state.get("level"))
        mobile_vnum = int(candidate.get("mobile_vnum"))
        recall_index = int(candidate.get("route_origin_recall_index") or 0)
    except (TypeError, ValueError):
        return None
    if level <= 0 or mobile_vnum <= 0:
        return None
    area_file = str(candidate.get("area_file") or "").strip()
    target = _source_ranked_normalized_target(
        candidate.get("target_identity") or candidate.get("target")
    )
    if not area_file or not target:
        return None

    searched_policy_ids: set[str] = set()
    for key in (_SOURCE_ABSENT_SIGHTINGS_KEY, _SOURCE_PRESENT_SIGHTINGS_KEY):
        sightings = state.get(key)
        if not isinstance(sightings, (list, tuple, set, frozenset)):
            continue
        for sighting in sightings:
            if not isinstance(sighting, Mapping):
                continue
            if _source_ranked_normalized_target(sighting.get("target")) != target:
                continue
            raw_room = sighting.get("room_vnum")
            if raw_room is None:
                continue
            expected_policy_id = _source_identity_policy_id(
                area_file,
                mobile_vnum,
                str(raw_room).strip(),
                level,
                recall_index,
            )
            if str(sighting.get("policy_id") or "") != expected_policy_id:
                continue
            searched_policy_ids.add(expected_policy_id)

    crowded_policy_ids = _source_ranked_crowded_policy_ids(
        state,
    )
    if not crowded_policy_ids:
        return None
    return {
        "boot_id": boot_id,
        "level": level,
        "source_revision": source_revision,
        "area_file": area_file.casefold(),
        "mobile_vnum": mobile_vnum,
        "scope": "exact_reset_stops_v1",
        "policy_ids": list(crowded_policy_ids),
        "searched_policy_ids": sorted(searched_policy_ids),
    }


def _source_ranked_candidate_in_crowded_circuit(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Match only fixed reset stops already checked in this exact circuit."""
    if not candidate.sentinel:
        return False
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    attempts = state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY)
    if not isinstance(attempts, Mapping):
        return False
    for attempt in attempts.values():
        if not isinstance(attempt, Mapping):
            continue
        circuit = attempt.get("crowded_circuit")
        if (
            not isinstance(circuit, Mapping)
            or circuit.get("scope") != "exact_reset_stops_v1"
        ):
            continue
        policy_ids = circuit.get("policy_ids")
        if not isinstance(policy_ids, (list, tuple, set, frozenset)):
            continue
        if (
            circuit.get("boot_id") == state.get("world_boot_id")
            and circuit.get("level") == character_level
            and circuit.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
            and str(circuit.get("area_file") or "").casefold()
            == candidate.area_file.casefold()
            and circuit.get("mobile_vnum") == candidate.mobile_vnum
            and candidate_policy_id in {str(value) for value in policy_ids}
        ):
            return True
    return False


def _source_ranked_crowded_policy_ids(
    state: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return explicit crowd stops matching the current source identity."""
    raw_ids = state.get(_SOURCE_CROWDED_POLICY_IDS_KEY)
    if not isinstance(raw_ids, (list, tuple, set, frozenset)):
        return ()
    candidate = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    if not isinstance(candidate, Mapping):
        return ()
    try:
        mobile_vnum = int(candidate.get("mobile_vnum"))
        level = int(state.get("level"))
        recall_index = int(candidate.get("route_origin_recall_index") or 0)
    except (TypeError, ValueError):
        return ()
    area_file = str(candidate.get("area_file") or "").strip()
    if not area_file or mobile_vnum <= 0 or level <= 0 or recall_index < 0:
        return ()
    area = re.sub(
        r"[^a-z0-9]+",
        "-",
        Path(area_file).stem.casefold(),
    ).strip("-") or "area"
    prefix = f"{_SOURCE_RANKED_POLICY_PREFIX}{area}-{mobile_vnum}-"
    valid_policy_ids: set[str] = set()
    for raw_policy_id in raw_ids:
        policy_id = str(raw_policy_id)
        if not policy_id.startswith(prefix):
            continue
        match = re.fullmatch(
            rf"(\d+)-{level}(?:-recall-(\d+))?",
            policy_id[len(prefix):],
        )
        if match is None:
            continue
        room_vnum = int(match.group(1))
        observed_recall_index = int(match.group(2) or 0)
        if observed_recall_index != recall_index:
            continue
        if policy_id == _source_identity_policy_id(
            area_file,
            mobile_vnum,
            room_vnum,
            level,
            recall_index,
        ):
            valid_policy_ids.add(policy_id)
    return tuple(
        sorted(
            {
                str(policy_id)
                for policy_id in raw_ids
                if str(policy_id) in valid_policy_ids
            }
        )
    )


def _source_ranked_segment_crowded_policy_ids(
    state: Mapping[str, Any],
    *,
    phase: str,
    objective_kills: object,
) -> tuple[str, ...]:
    """Scope legacy run-wide crowd flags only when the primary stop is clear."""
    if _SOURCE_CROWDED_POLICY_IDS_KEY in state:
        return _source_ranked_crowded_policy_ids(
            state,
        )
    if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return ()
    kills = objective_kills if isinstance(objective_kills, (list, tuple)) else ()
    if any(
        isinstance(kill, Mapping)
        and str(kill.get("source_policy_id") or "") == phase
        for kill in kills
    ):
        return ()
    absent = set(
        _source_ranked_absent_policy_ids(
            state,
            primary_policy_id=phase,
        )
    )
    if phase in absent:
        return ()
    observed_policy_ids = set(absent)
    observed_policy_ids.update(
        _source_ranked_present_policy_ids(
            state,
            primary_policy_id=phase,
        )
    )
    if observed_policy_ids and observed_policy_ids != {phase}:
        return ()
    return (phase,) if state.get("campaign_fastwalk_crowded") is True else ()


def _campaign_policy_crowded_in_state(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Keep source-ranked crowd evidence attached to its exact reset stop."""
    if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        primary_policy_id = str(
            state.get("campaign_last_policy") or policy_id
        )
        crowded_policy_ids = _source_ranked_segment_crowded_policy_ids(
            state,
            phase=primary_policy_id,
            objective_kills=state.get("campaign_objective_kills"),
        )
        return policy_id in crowded_policy_ids
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    return bool(
        state.get("campaign_fastwalk_crowded")
        or any(
            abort_reason.startswith(prefix)
            for prefix in _FIELD_CROWD_ABORT_PREFIXES
        )
    )


def _reconcile_source_ranked_exact_crowd_observations(
    state: dict[str, Any],
    end_state: Mapping[str, Any],
    *,
    phase: str,
    circuit: Mapping[str, Any],
    segment_id: int | None = None,
) -> dict[str, Any]:
    """Repair per-stop crowd, presence, and absence markers from one run."""
    if circuit.get("scope") != "exact_reset_stops_v1":
        return state
    crowded_policy_ids = {
        str(policy_id)
        for policy_id in circuit.get("policy_ids", ())
        if isinstance(policy_id, str)
    }
    absent_policy_ids = set(
        _source_ranked_absent_policy_ids(
            end_state,
            primary_policy_id=phase,
        )
    )
    present_policy_ids = set(
        _source_ranked_present_policy_ids(
            end_state,
            primary_policy_id=phase,
        )
    )
    killed_policy_ids = set(
        _source_ranked_kill_policy_ids(
            end_state.get("campaign_objective_kills")
            or end_state.get("campaign_completed_kills")
        )
    )
    if segment_id is not None:
        segment_ref = {"id": segment_id}
        crowded_policy_ids = {
            policy_id
            for policy_id in crowded_policy_ids
            if not _research_evidence_is_before_reset_boundary(
                state,
                policy_id,
                segment_ref,
            )
        }
        absent_policy_ids = {
            policy_id
            for policy_id in absent_policy_ids
            if not _research_evidence_is_before_reset_boundary(
                state,
                policy_id,
                segment_ref,
            )
        }
        present_policy_ids = {
            policy_id
            for policy_id in present_policy_ids
            if not _research_evidence_is_before_reset_boundary(
                state,
                policy_id,
                segment_ref,
            )
        }
        killed_policy_ids = {
            policy_id
            for policy_id in killed_policy_ids
            if not _research_evidence_is_before_reset_boundary(
                state,
                policy_id,
                segment_ref,
            )
        }
    noncrowded_absences = (
        absent_policy_ids - crowded_policy_ids - killed_policy_ids
    )
    reconciled = (
        _with_source_ranked_absence_results(state, noncrowded_absences)
        if noncrowded_absences
        else dict(state)
    )
    noncrowded_present = (
        (present_policy_ids | killed_policy_ids)
        - crowded_policy_ids
        - noncrowded_absences
    )
    results = _campaign_research_results(reconciled)
    absence_cooldowns = dict(
        reconciled.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        reconciled.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    attempts = dict(reconciled.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {})
    boot_id = end_state.get("world_boot_id")
    for policy_id in noncrowded_present:
        result = results.get(policy_id)
        if isinstance(result, Mapping) and result.get("boot_id") == boot_id:
            corrected = dict(result)
            corrected.pop("crowded", None)
            corrected.pop("crowd_exhausted", None)
            if not corrected.get("completed_kill") and not corrected.get(
                "consider_viable"
            ):
                corrected.pop("viable", None)
                corrected["observed"] = True
            results[policy_id] = corrected
        absence_cooldowns.pop(policy_id, None)
        crowd_cooldowns.pop(policy_id, None)
        attempts.pop(policy_id, None)
    for policy_id in crowded_policy_ids:
        result = results.get(policy_id)
        if not (
            isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("viable") is True
            and result.get("completed_kill") is True
        ):
            results[policy_id] = {
                "observed": False,
                "viable": False,
                "crowded": True,
                "boot_id": boot_id,
            }
        else:
            positive = dict(result)
            positive["crowded"] = True
            results[policy_id] = positive
        absence_cooldowns.pop(policy_id, None)
        crowd_cooldowns[policy_id] = _DEFAULT_RESEARCH_CROWD_COOLDOWN
        previous_attempt = attempts.get(policy_id)
        attempt = (
            dict(previous_attempt)
            if isinstance(previous_attempt, Mapping)
            and previous_attempt.get("boot_id") == boot_id
            else {"boot_id": boot_id, "count": 0}
        )
        try:
            attempt["count"] = max(1, int(attempt.get("count") or 0))
        except (TypeError, ValueError):
            attempt["count"] = 1
        attempt["crowded_circuit"] = dict(circuit)
        attempts[policy_id] = attempt
    updated = dict(reconciled)
    if results:
        updated["campaign_research_results"] = results
    if absence_cooldowns:
        updated[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        updated.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        updated[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        updated.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if attempts:
        updated[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = attempts
    else:
        updated.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    return updated


def _repair_source_ranked_crowded_circuit_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover exact crowd-circuit receipts from a bounded segment tail."""
    try:
        level = int(state.get("level"))
    except (TypeError, ValueError):
        return state
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    if not boot_id or not source_revision:
        return state

    attempts = dict(state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {})
    changed = False
    legacy_crowd_policy_ids: set[str] = set()
    legacy_crowd_candidates: dict[str, Mapping[str, Any]] = {}
    reconciliation_inputs: list[
        tuple[int, int, Mapping[str, Any], str, Mapping[str, Any] | None]
    ] = []
    for raw_segment in reversed(tuple(segments)[-_CAMPAIGN_RUNTIME_CHECKPOINT_LIMIT:]):
        segment = dict(raw_segment)
        policy_id = str(segment.get("phase") or "")
        if (
            not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            or segment.get("safety_outcome") != "safe"
        ):
            continue
        try:
            end_state = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        candidate = end_state.get(_SOURCE_RANKED_CANDIDATE_KEY)
        if not (
            isinstance(candidate, Mapping)
            and candidate.get("policy_id") == policy_id
            and end_state.get("world_boot_id") == boot_id
            and end_state.get(_SOURCE_REVISION_KEY) == source_revision
        ):
            continue
        try:
            if int(end_state.get("level")) != level:
                continue
        except (TypeError, ValueError):
            continue
        absent_policy_ids = _source_ranked_absent_policy_ids(
            end_state,
            primary_policy_id=policy_id,
        )
        try:
            segment_id = int(segment.get("id") or 0)
        except (TypeError, ValueError):
            segment_id = 0
        absent_policy_ids = tuple(
            absent_id
            for absent_id in absent_policy_ids
            if not _research_evidence_is_before_reset_boundary(
                state,
                absent_id,
                {"id": segment_id},
            )
        )
        circuit = _source_ranked_crowded_circuit_evidence(end_state)
        if circuit is not None:
            eligible_crowded_ids = [
                str(crowded_id)
                for crowded_id in circuit.get("policy_ids", ())
                if not _research_evidence_is_before_reset_boundary(
                    state,
                    str(crowded_id),
                    {"id": segment_id},
                )
            ]
            if eligible_crowded_ids:
                circuit = {
                    **circuit,
                    "policy_ids": eligible_crowded_ids,
                    "searched_policy_ids": [
                        str(searched_id)
                        for searched_id in circuit.get(
                            "searched_policy_ids", ()
                        )
                        if not _research_evidence_is_before_reset_boundary(
                            state,
                            str(searched_id),
                            {"id": segment_id},
                        )
                    ],
                }
            else:
                circuit = None
        if (
            circuit is None
            and end_state.get("campaign_fastwalk_crowded") is True
            and end_state.get("campaign_fastwalk_target_present_observed")
            is True
            and not end_state.get("campaign_died_during_segment")
            and not end_state.get("xp_loss_observed")
            and policy_id
            in _source_ranked_present_policy_ids(
                end_state,
                primary_policy_id=policy_id,
            )
        ):
            # Older failed field segments persisted the exact crowd and
            # source-present sighting, but omitted the explicit circuit list.
            # Reconstruct that single-stop receipt so the selector can rotate
            # without replaying an already-audited crowded room.
            legacy_crowd_policy_ids.add(policy_id)
            legacy_crowd_candidates[policy_id] = dict(candidate)
        if circuit is None and not absent_policy_ids:
            if policy_id not in legacy_crowd_policy_ids:
                continue
        try:
            sequence = int(segment.get("sequence") or 0)
        except (TypeError, ValueError):
            sequence = 0
        reconciliation_inputs.append(
            (sequence, segment_id, end_state, policy_id, circuit)
        )
        if circuit is None:
            continue
        for crowded_policy_id in circuit["policy_ids"]:
            previous_attempt = attempts.get(crowded_policy_id)
            if (
                isinstance(previous_attempt, Mapping)
                and previous_attempt.get("boot_id") == boot_id
                and previous_attempt.get("crowded_circuit") == circuit
            ):
                continue
            attempt = (
                dict(previous_attempt)
                if isinstance(previous_attempt, Mapping)
                and previous_attempt.get("boot_id") == boot_id
                else {"boot_id": boot_id, "count": 0}
            )
            try:
                attempt["count"] = max(1, int(attempt.get("count") or 0))
            except (TypeError, ValueError):
                attempt["count"] = 1
            attempt["crowded_circuit"] = circuit
            attempts[crowded_policy_id] = attempt
            changed = True

    if not changed and not reconciliation_inputs and not legacy_crowd_policy_ids:
        return state
    repaired = dict(state)
    if changed:
        repaired[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = attempts
    if legacy_crowd_policy_ids:
        results = _campaign_research_results(repaired)
        crowd_cooldowns = dict(
            repaired.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
        )
        absence_cooldowns = dict(
            repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        )
        for policy_id in sorted(legacy_crowd_policy_ids):
            existing = results.get(policy_id)
            if not (
                isinstance(existing, Mapping)
                and existing.get("boot_id") == boot_id
                and existing.get("viable") is True
                and existing.get("completed_kill") is True
            ):
                results[policy_id] = {
                    "observed": False,
                    "viable": False,
                    "crowded": True,
                    "boot_id": boot_id,
                }
            crowd_cooldowns[policy_id] = _DEFAULT_RESEARCH_CROWD_COOLDOWN
            absence_cooldowns.pop(policy_id, None)
            candidate = legacy_crowd_candidates.get(policy_id)
            previous_attempt = attempts.get(policy_id)
            attempt = (
                dict(previous_attempt)
                if isinstance(previous_attempt, Mapping)
                and previous_attempt.get("boot_id") == boot_id
                else {"boot_id": boot_id, "count": 0}
            )
            try:
                attempt["count"] = max(1, int(attempt.get("count") or 0))
            except (TypeError, ValueError):
                attempt["count"] = 1
            if isinstance(candidate, Mapping):
                attempt["crowded_circuit"] = {
                    "boot_id": boot_id,
                    "level": level,
                    "source_revision": source_revision,
                    "area_file": str(candidate.get("area_file") or "").casefold(),
                    "mobile_vnum": candidate.get("mobile_vnum"),
                    "scope": "exact_reset_stops_v1",
                    "policy_ids": [policy_id],
                    "searched_policy_ids": [policy_id],
                }
            attempts[policy_id] = attempt
            changed = True
        repaired["campaign_research_results"] = results
        if crowd_cooldowns:
            repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
        if absence_cooldowns:
            repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
        else:
            repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        repaired[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = attempts
    for _, segment_id, end_state, phase, circuit in sorted(
        reconciliation_inputs,
        key=lambda item: item[0],
    ):
        if circuit is None:
            absent_policy_ids = _source_ranked_absent_policy_ids(
                end_state,
                primary_policy_id=phase,
            )
            absent_policy_ids = tuple(
                absent_id
                for absent_id in absent_policy_ids
                if not _research_evidence_is_before_reset_boundary(
                    repaired,
                    absent_id,
                    {"id": segment_id},
                )
            )
            repaired = _with_source_ranked_absence_results(
                repaired,
                absent_policy_ids,
            )
        else:
            repaired = _reconcile_source_ranked_exact_crowd_observations(
                repaired,
                end_state,
                phase=phase,
                circuit=circuit,
                segment_id=segment_id,
            )
    return repaired


def _source_ranked_multi_kill_reward_allowed(
    result: Mapping[str, Any],
) -> bool:
    """Keep a productive multi-kill route above the low-reward floor.

    DD4 can award several modest objective kills in one bounded field segment.
    The per-kill ceiling alone must not quarantine that route when its measured
    segment reward is useful; a lone 10-XP kill remains low reward.
    """
    try:
        total_xp = int(result.get("objective_xp") or 0)
        max_kill_xp = int(result.get("max_objective_kill_xp") or 0)
    except (TypeError, ValueError):
        return False
    raw_count = result.get("objective_kill_count")
    try:
        kill_count = int(raw_count) if raw_count is not None else 0
    except (TypeError, ValueError):
        kill_count = 0
    if kill_count <= 0 and max_kill_xp > 0 and total_xp > max_kill_xp:
        # Older checkpoints did not persist the count. A total above the
        # observed single-kill maximum is sufficient to infer two kills.
        kill_count = 2
    return bool(
        kill_count >= 2
        and total_xp >= _MEANINGFUL_FIELD_SEGMENT_XP
        and max_kill_xp > 0
    )


def _source_ranked_below_band_exclusion_reopened_by_productive_result(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Return whether exact productive evidence reopens one source reset."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    productive_result = _campaign_research_results(dict(state)).get(policy_id)
    if not (
        isinstance(productive_result, Mapping)
        and productive_result.get("boot_id") == state.get("world_boot_id")
        and productive_result.get("viable") is True
        and productive_result.get("completed_kill") is True
        and not productive_result.get("crowded")
        and not productive_result.get("fatal_failure")
    ):
        return False
    multi_kill_reward = _source_ranked_multi_kill_reward_allowed(
        productive_result
    )
    try:
        max_kill_xp = int(productive_result.get("max_objective_kill_xp") or 0)
    except (TypeError, ValueError):
        max_kill_xp = 0
    return bool(
        multi_kill_reward
        or max_kill_xp >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
    )


def _source_ranked_maze_index_revalidation_evidence(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any] | None:
    """Recognize the exact old detour/index mismatch before target contact."""
    if source_world is None or not candidate.autonomous_safe:
        return None
    if candidate.route_hard_hazard_targets:
        return None
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("completed_kill") is not True
        and result.get("consider_viable") is None
        and result.get("objective_xp") in (None, 0)
        and result.get("xp_delta") in (None, 0)
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "unattackable",
                "target_vnum_mismatch",
            )
        )
        and _source_ranked_xp_loss_record(state, policy_id) is None
    ):
        return None
    route_hazard = result.get("route_hazard")
    match = re.fullmatch(
        r"field route movement blocked: live maze navigation reached "
        r"unregistered room '(\d+)' while seeking (\d+)",
        str(route_hazard or ""),
    )
    if match is None:
        return None
    try:
        observed_room_vnum, maze_target_vnum = map(int, match.groups())
        route_origin = int(candidate.route_origin_room_vnum or 3001)
    except (TypeError, ValueError):
        return None
    navigation = _source_ranked_route_live_navigation(
        source_world,
        candidate,
        character_level=character_level,
    )
    if (
        not navigation
        or str(navigation.get("live_navigation_target") or "")
        != str(maze_target_vnum)
        or observed_room_vnum not in source_world.rooms
        or maze_target_vnum not in source_world.rooms
    ):
        return None
    route_rooms = _source_route_room_vnums(
        source_world,
        route_origin,
        candidate.route,
    )
    entry_room_vnum = str(navigation.get("live_navigation_entry_room") or "")
    if route_rooms is None:
        return None
    route_room_labels = tuple(str(room_vnum) for room_vnum in route_rooms)
    try:
        observed_index = route_room_labels.index(str(observed_room_vnum))
        entry_index = route_room_labels.index(entry_room_vnum)
        target_index = route_room_labels.index(str(maze_target_vnum))
    except ValueError:
        return None
    if not observed_index < entry_index < target_index:
        return None

    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
    crowd_cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY)
    try:
        existing_cooldown = max(
            int(cooldowns.get(policy_id) or 0)
            if isinstance(cooldowns, Mapping)
            else 0,
            int(crowd_cooldowns.get(policy_id) or 0)
            if isinstance(crowd_cooldowns, Mapping)
            else 0,
        )
    except (TypeError, ValueError):
        return None
    if (
        existing_cooldown > 0
        or _source_ranked_crowd_attempts_exhausted(state, policy_id)
    ):
        return None
    return {
        "policy_id": policy_id,
        "route_hazard": str(route_hazard),
        "observed_room_vnum": observed_room_vnum,
        "maze_target_vnum": maze_target_vnum,
        "mobile_vnum": candidate.mobile_vnum,
        "reset_room_vnum": candidate.room_vnum,
    }


def _source_ranked_maze_index_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    marker = state.get(_SOURCE_RANKED_MAZE_INDEX_REVALIDATION_KEY)
    if not isinstance(marker, Mapping):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    return bool(
        marker.get("status") == "pending"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("mobile_vnum") == candidate.mobile_vnum
        and marker.get("reset_room_vnum") == candidate.room_vnum
        and isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("viable") is False
        and result.get("route_hazard") == marker.get("route_hazard")
    )


def _arm_source_ranked_maze_index_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any]:
    """Arm one exact route retry after the city-detour index correction."""
    boot_id = state.get("world_boot_id")
    if not boot_id or source_world is None:
        return state
    existing = state.get(_SOURCE_RANKED_MAZE_INDEX_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") == character_level
    ):
        return state
    matches = [
        (candidate, evidence)
        for candidate in candidates
        if (
            evidence := _source_ranked_maze_index_revalidation_evidence(
                candidate,
                state,
                character_level=character_level,
                source_world=source_world,
            )
        )
        is not None
    ]
    if len(matches) != 1:
        return state
    candidate, evidence = matches[0]
    state[_SOURCE_RANKED_MAZE_INDEX_REVALIDATION_KEY] = {
        **evidence,
        "boot_id": boot_id,
        "level": character_level,
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "status": "pending",
        "reason": (
            "one source-checked retry after the city detour's corrected "
            "live-maze command indexes"
        ),
    }
    return state


def _mark_source_ranked_maze_index_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    if not _source_ranked_maze_index_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = state.get(_SOURCE_RANKED_MAZE_INDEX_REVALIDATION_KEY)
    assert isinstance(marker, Mapping)
    state[_SOURCE_RANKED_MAZE_INDEX_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _source_ranked_locator_rebase_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    marker = state.get(_SOURCE_RANKED_LOCATOR_REBASE_REVALIDATION_KEY)
    if not isinstance(marker, Mapping) or source_world is None:
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    prior_target = _source_ranked_normalized_target(
        marker.get("prior_locator_target")
    )
    candidate_target = _source_ranked_normalized_target(
        _source_ranked_target_identity(candidate)
    )
    return bool(
        marker.get("status") == "pending"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("mobile_vnum") == candidate.mobile_vnum
        and marker.get("reset_room_vnum") == candidate.room_vnum
        and prior_target
        and all(token in candidate_target.split() for token in prior_target.split())
        and mobile is not None
        and mobile.wanders
        and not mobile.confused
        and str(state.get("room_vnum") or "") == "3054"
        and int(state.get("hp") or 0) > 0
        and int(state.get("hp") or 0) >= int(state.get("max_hp") or 0)
        and state.get("dead") not in {True, 1}
        and state.get("in_combat") not in {True, 1}
        and state.get("enemies") in (None, [])
    )


