def _mark_source_ranked_protected_peak_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> None:
    """Consume the protected-peak retry immediately before live dispatch."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    ):
        return
    state[_SOURCE_RANKED_PROTECTED_PEAK_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
    }


def _source_ranked_protected_peak_probe_in_current_band(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None = None,
    allow_repeated_kills: bool = False,
) -> bool:
    """Apply reboot, movement, and useful-XP gates to a protected probe."""
    if not _source_ranked_protected_peak_probe_allowed(
        candidate,
        state=state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ) or not _source_ranked_protected_peak_output_fits(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        return False
    return not (
        (candidate.boot_kills >= 3 and not allow_repeated_kills)
        or not _source_candidate_fits_movement(candidate, state)
        or _funding_candidate_is_below_band(
            dict(state),
            candidate,
            character_level=character_level,
            boot_id=state.get("world_boot_id"),
        )
    )


def _source_ranked_candidate_has_only_safe_noncombat_special_rejections(
    candidate: HuntCandidate,
) -> bool:
    """Recognize source-safe specials in legacy serialized candidates."""
    specials = set(candidate.specials)
    if not specials or not specials <= SAFE_NONCOMBAT_SPECIALS:
        return False
    return set(candidate.autonomy_rejections) <= {
        f"target has special procedure {special}" for special in specials
    }


def _source_ranked_healer_recovery_route_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    source_world: WorldSource | None,
    expected_specials: Collection[str],
    required_effects: Collection[str],
    allowed_effects: Collection[str],
    maximum_level_exclusive: int | None = None,
) -> bool:
    """Prove one exact special can return to the Midgaard healer."""
    if source_world is None or set(candidate.specials) != set(expected_specials):
        return False
    if str(state.get("room_vnum") or "") != str(_SOURCE_HEALER_ROOM_VNUM):
        return False
    if any(
        _has_named_affect(state.get("affects"), effect)
        for effect in ("curse", "no recall", "no_recall")
    ):
        return False

    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.programs
        or set(source_world.mobile_specials.get(mobile.vnum, ()))
        != set(expected_specials)
    ):
        return False
    source_level_range = _mobile_level_range(mobile.level)
    if candidate.estimated_level_range != source_level_range:
        return False
    maximum_level = source_level_range[1]
    source_effects = {
        effect
        for special in expected_specials
        for effect in source_special_status_effects(
            special,
            level=maximum_level,
        )
    }
    if (
        not set(required_effects) <= source_effects
        or not source_effects <= set(allowed_effects)
        or (
            maximum_level_exclusive is not None
            and maximum_level >= maximum_level_exclusive
        )
    ):
        return False

    healer = source_world.mobiles.get(_SOURCE_HEALER_MOBILE_VNUM)
    healer_room = source_world.rooms.get(_SOURCE_HEALER_ROOM_VNUM)
    if (
        healer is None
        or healer_room is None
        or healer_room.no_recall
        or healer.wanders
        or set(source_world.mobile_specials.get(healer.vnum, ()))
        != {"spec_cast_adept"}
        or not any(
            reset.mobile_vnum == healer.vnum
            and reset.room_vnum == _SOURCE_HEALER_ROOM_VNUM
            for reset in source_world.mob_resets
        )
    ):
        return False

    reset_rooms = {
        reset.room_vnum
        for reset in source_world.mob_resets
        if reset.mobile_vnum == mobile.vnum
    }
    if not reset_rooms or candidate.room_vnum not in reset_rooms:
        return False
    if mobile.wanders:
        if set(expected_specials) != {"spec_cast_cleric"}:
            return False
        if (
            candidate.mobile_vnum == _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
            and candidate.room_vnum == _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        ):
            # Caerlin wanders inside Mirror Realm, but the carrier reset room
            # itself is recallable. Do not let unrelated no-recall rooms in
            # the same area veto the exact healer return from this endpoint.
            carrier_room = source_world.rooms.get(candidate.room_vnum)
            return bool(
                carrier_room is not None
                and not carrier_room.no_recall
                and not carrier_room.random_exits
                and carrier_room.exits
            )
        area_rooms = tuple(
            room
            for room in source_world.rooms.values()
            if room.area_file == mobile.area_file
        )
        return bool(area_rooms) and not any(room.no_recall for room in area_rooms)
    for room_vnum in reset_rooms:
        room = source_world.rooms.get(room_vnum)
        if (
            room is None
            or room.no_recall
            or room.random_exits
            or not room.exits
        ):
            return False
        traversable_exit = False
        for exit_source in room.exits.values():
            destination = source_world.rooms.get(exit_source.destination)
            if destination is None or destination.no_recall:
                return False
            if (
                not exit_source.closed
                and _source_ranked_route_is_traversable(
                    source_world,
                    (room_vnum, exit_source.destination),
                    state,
                )
            ):
                traversable_exit = True
        if not traversable_exit:
            return False
    return True


def _source_ranked_healer_blindness_recovery_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    source_world: WorldSource | None,
) -> bool:
    """Prove a low-level mage-special escape to Midgaard's healer."""
    if _source_caerlin_staff_candidate_shape_allowed(candidate, source_world):
        return _source_ranked_healer_recovery_route_allowed(
            candidate,
            state,
            source_world=source_world,
            expected_specials=(_CAERLIN_STAFF_SPECIAL,),
            required_effects=("blindness",),
            allowed_effects=("blindness", "curse", "dispel magic"),
            maximum_level_exclusive=40,
        )
    specials = set(candidate.specials)
    if specials == {"spec_cast_mage"}:
        return _source_ranked_healer_recovery_route_allowed(
            candidate,
            state,
            source_world=source_world,
            expected_specials=("spec_cast_mage",),
            required_effects=("blindness",),
            allowed_effects=_SOURCE_HEALER_BLINDNESS_RECOVERY_EFFECTS,
            maximum_level_exclusive=20,
        )
    if specials == {"spec_cast_cleric"}:
        return _source_ranked_healer_recovery_route_allowed(
            candidate,
            state,
            source_world=source_world,
            expected_specials=("spec_cast_cleric",),
            required_effects=("blindness",),
            allowed_effects=("blindness",),
            maximum_level_exclusive=12,
        )
    return False


def _source_caerlin_staff_candidate_shape_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Match the exact Mirror Realm Sanctuary staff carrier contract."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(_CAERLIN_STAFF_CARRIER_MOBILE_VNUM)
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
    ]
    staff = source_world.objects.get(_CAERLIN_STAFF_OBJECT_VNUM)
    route_specials = set(
        candidate.route_economic_hunt_mobile_vnums
        or candidate.route_special_mobile_vnums
    )
    return bool(
        candidate.mobile_vnum == _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        and candidate.room_vnum == _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and not candidate.equipped_weapons
        and set(candidate.specials) == {_CAERLIN_STAFF_SPECIAL}
        and route_specials == {_CAERLIN_STAFF_ROUTE_ECONOMIC_MOBILE_VNUM}
        and not candidate.route_hard_hazard_targets
        and mobile is not None
        and mobile.level == 35
        and (mobile.sentinel or (mobile.wanders and mobile.stay_area))
        and not mobile.aggressive
        and not mobile.fear_aura
        and not mobile.confused
        and not mobile.programs
        and not mobile.non_corporeal
        and not mobile.costs_fame
        and set(
            source_world.mobile_specials.get(
                _CAERLIN_STAFF_CARRIER_MOBILE_VNUM,
                (),
            )
        ) == {_CAERLIN_STAFF_SPECIAL}
        and len(resets) == 1
        and resets[0].room_vnum == _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        and resets[0].maximum_count == 1
        and any(
            object_vnum == _CAERLIN_STAFF_OBJECT_VNUM
            for _slot, object_vnum in resets[0].equipment
        )
        and staff is not None
        and staff.item_type == ITEM_STAFF
        and resource_activation_for_object(
            staff,
            effect="sanctuary",
        ) is not None
    )


def _source_hephaestus_sanctuary_candidate_shape_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Match Olympus's exact lightning-breath Sanctuary nectar carrier."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(
        _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_MOBILE_VNUM
    )
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_MOBILE_VNUM
    ]
    nectar = source_world.objects.get(_OLYMPUS_HEPHAESTUS_SANCTUARY_OBJECT_VNUM)
    companion = source_world.mobiles.get(909)
    companion_resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == 909
    ]
    return bool(
        candidate.mobile_vnum
        == _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_MOBILE_VNUM
        and candidate.room_vnum
        == _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_ROOM_VNUM
        and candidate.area_file.casefold() == "olympus.are"
        and candidate.level == 38
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and not candidate.equipped_weapons
        and tuple(candidate.specials) == (_OLYMPUS_HEPHAESTUS_SANCTUARY_SPECIAL,)
        and not candidate.route_hard_hazard_targets
        and mobile is not None
        and mobile.level == 38
        and mobile.sentinel
        and not mobile.wanders
        and not mobile.aggressive
        and not mobile.fear_aura
        and not mobile.confused
        and not mobile.programs
        and not mobile.non_corporeal
        and not mobile.costs_fame
        and set(
            source_world.mobile_specials.get(
                _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_MOBILE_VNUM,
                (),
            )
        ) == {_OLYMPUS_HEPHAESTUS_SANCTUARY_SPECIAL}
        and len(resets) == 1
        and resets[0].room_vnum
        == _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_ROOM_VNUM
        and resets[0].maximum_count == 1
        and _OLYMPUS_HEPHAESTUS_SANCTUARY_OBJECT_VNUM in resets[0].object_vnums
        and all(
            (item := source_world.objects.get(object_vnum)) is not None
            and item.item_type != ITEM_WEAPON
            for _slot, object_vnum in resets[0].equipment
        )
        and nectar is not None
        and resource_activation_for_object(nectar, effect="sanctuary") is not None
        and companion is not None
        and companion.level + 10 <= mobile.level
        and companion.sentinel
        and not companion.wanders
        and not companion.aggressive
        and not companion.fear_aura
        and not companion.programs
        and not companion.non_corporeal
        and not companion.costs_fame
        and set(source_world.mobile_specials.get(909, ())) == {"spec_guard"}
        and len(companion_resets) == 2
        and all(
            reset.room_vnum
            == _OLYMPUS_HEPHAESTUS_SANCTUARY_CARRIER_ROOM_VNUM
            and reset.maximum_count == 4
            and not reset.equipment
            for reset in companion_resets
        )
    )


def _source_ancient_gold_dragon_breath_shape_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Match the one passive ``spec_breath_any`` XP target we have audited.

    Generic breathers stay closed because acid, fire, frost, steam, and gas
    can damage carried objects or apply nausea.  Ofcol's dragon is different
    only in the narrow sense that its source reset, room, non-aggressive
    prototype, and armed loadout are all fixed and independently verifiable;
    live isolation and the player's health floor still decide the fight.
    """
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(
        _NEW_OFCOL_ANCIENT_GOLD_DRAGON_MOBILE_VNUM
    )
    room = source_world.rooms.get(_NEW_OFCOL_ANCIENT_GOLD_DRAGON_ROOM_VNUM)
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_MOBILE_VNUM
    ]
    companion_resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == 632
        and reset.room_vnum == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_ROOM_VNUM
    ]
    if (
        mobile is None
        or room is None
        or len(resets) != 1
        or len(companion_resets) != 2
    ):
        return False
    reset = resets[0]
    equipment = tuple(sorted((int(slot), int(vnum)) for slot, vnum in reset.equipment))
    companion = source_world.mobiles.get(632)
    return bool(
        candidate.mobile_vnum == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_MOBILE_VNUM
        and candidate.room_vnum == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_ROOM_VNUM
        and candidate.area_file.casefold() == "new_ofcol.are"
        and candidate.level == 37
        and candidate.estimated_level_range == _mobile_level_range(37)
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and candidate.specials == (_NEW_OFCOL_ANCIENT_GOLD_DRAGON_SPECIAL,)
        and set(candidate.autonomy_rejections)
        == {
            "target has special procedure "
            f"{_NEW_OFCOL_ANCIENT_GOLD_DRAGON_SPECIAL}"
        }
        and candidate.equipped_weapons == ("the Golden Claw",)
        and mobile.level == 37
        and mobile.sentinel
        and not mobile.wanders
        and not mobile.aggressive
        and not mobile.fear_aura
        and not mobile.confused
        and not mobile.programs
        and not mobile.attack_programs
        and not mobile.non_corporeal
        and not mobile.costs_fame
        and mobile.alignment >= 700
        and set(
            source_world.mobile_specials.get(
                _NEW_OFCOL_ANCIENT_GOLD_DRAGON_MOBILE_VNUM,
                (),
            )
        )
        == {_NEW_OFCOL_ANCIENT_GOLD_DRAGON_SPECIAL}
        and not room.no_recall
        and not room.random_exits
        and bool(room.exits)
        and reset.room_vnum == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_ROOM_VNUM
        and reset.maximum_count == 1
        and equipment
        == (
            (1, _NEW_OFCOL_ANCIENT_GOLD_DRAGON_SIGNET_VNUM),
            (16, _NEW_OFCOL_ANCIENT_GOLD_DRAGON_CLAW_VNUM),
            (17, _NEW_OFCOL_ANCIENT_GOLD_DRAGON_ORB_VNUM),
        )
        and (
            claw := source_world.objects.get(
                _NEW_OFCOL_ANCIENT_GOLD_DRAGON_CLAW_VNUM
            )
        )
        is not None
        and claw.item_type == ITEM_WEAPON
        and source_world.objects.get(_NEW_OFCOL_ANCIENT_GOLD_DRAGON_ORB_VNUM)
        is not None
        and companion is not None
        and companion.level == 21
        and not companion.aggressive
        and not companion.wanders
        and not companion.programs
        and not companion.attack_programs
        and not companion.non_corporeal
        # ``spec_cast_mage`` only chooses a victim already fighting the
        # attendant; unlike a guard special it cannot join the dragon fight.
        # Keep this exact two-attendant reset shape audited rather than
        # treating arbitrary endpoint casters as harmless.
        and set(source_world.mobile_specials.get(632, ()))
        == {"spec_cast_mage"}
        and all(
            attendant_reset.maximum_count == 2
            and attendant_reset.room_vnum
            == _NEW_OFCOL_ANCIENT_GOLD_DRAGON_ROOM_VNUM
            and tuple(attendant_reset.equipment)
            == ((1, 620), (12, 664))
            for attendant_reset in companion_resets
        )
    )


def _source_ranked_mirror_realm_gardener_transit_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    allow_aggressive_target: bool = False,
) -> bool:
    """Admit Mirror Realm targets behind one audited economic transit risk.

    The gardener carries source object 19084 in its wield slot, which made
    the generic ``spec_thief`` route test reject the whole Mirror Realm.  The
    source special only transfers coins and never attacks; the exact transit
    shape below also audits the low-level fido and the route's known guards.
    This is a route exception, not permission to fight the gardener.
    """
    if (
        source_world is None
        or not isinstance(state.get("currencies"), Mapping)
        or candidate.area_file.casefold() != "mirror_realm.are"
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.requires_flight
        or candidate.requires_water_breathing
        or candidate.requires_detect_invisibility
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or set(candidate.route_special_mobile_vnums)
        != {_MIRROR_REALM_GARDENER_TRANSIT_MOBILE_VNUM}
        or set(candidate.route_aggressive_mobile_vnums)
        != {_MIRROR_REALM_TRANSIT_FIDO_MOBILE_VNUM}
        or set(candidate.route_hazard_mobile_vnums)
        != {
            3060,
            _MIRROR_REALM_TRANSIT_FIDO_MOBILE_VNUM,
            3068,
            _MIRROR_REALM_GARDENER_TRANSIT_MOBILE_VNUM,
        }
    ):
        return False
    expected_rejections = {
        "an economic special mobile can reach the route",
    }
    if allow_aggressive_target:
        expected_rejections.add("target is aggressive")
    if set(candidate.autonomy_rejections) != expected_rejections:
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if not (
        candidate.level > 0
        and minimum_level > 0
        and minimum_level <= maximum_level
        and maximum_level > character_level - 5
        and minimum_level <= character_level + 5
    ):
        return False
    if allow_aggressive_target and minimum_level <= character_level - 5:
        # An aggressive endpoint attacks before live ``consider`` can prove
        # its actual level. Its lower source bound must therefore stay above
        # the useful-XP floor; ordinary targets can still use live consider
        # to reject a below-band instance after arrival.
        return False
    if _state_copper_value(dict(state)) > (
        _SPEC_THIEF_MAX_EXPOSURE_COINS * 100 // 20
    ):
        return False
    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False

    gardener = source_world.mobiles.get(
        _MIRROR_REALM_GARDENER_TRANSIT_MOBILE_VNUM
    )
    gardener_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _MIRROR_REALM_GARDENER_TRANSIT_MOBILE_VNUM
    )
    gardener_clippers = source_world.objects.get(
        _MIRROR_REALM_GARDENER_TRANSIT_OBJECT_VNUM
    )
    if not (
        gardener is not None
        and gardener.level == 25
        and not gardener.aggressive
        and gardener.wanders
        and gardener.stay_area
        and not gardener.fear_aura
        and not gardener.confused
        and not gardener.programs
        and not gardener.attack_programs
        and not gardener.non_corporeal
        and not gardener.costs_fame
        and set(
            source_world.mobile_specials.get(
                _MIRROR_REALM_GARDENER_TRANSIT_MOBILE_VNUM,
                (),
            )
        )
        == {"spec_thief"}
        and len(gardener_resets) == 1
        and gardener_resets[0].room_vnum
        == _MIRROR_REALM_GARDENER_TRANSIT_ROOM_VNUM
        and gardener_resets[0].maximum_count == 1
        and gardener_resets[0].object_vnums
        == (_MIRROR_REALM_GARDENER_TRANSIT_OBJECT_VNUM,)
        and gardener_resets[0].equipment
        == ((WEAR_WIELD, _MIRROR_REALM_GARDENER_TRANSIT_OBJECT_VNUM),)
        and gardener_clippers is not None
        and gardener_clippers.item_type == ITEM_WEAPON
    ):
        return False

    fido = source_world.mobiles.get(_MIRROR_REALM_TRANSIT_FIDO_MOBILE_VNUM)
    fido_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _MIRROR_REALM_TRANSIT_FIDO_MOBILE_VNUM
    )
    if not (
        fido is not None
        and fido.level == 0
        and fido.aggressive
        and fido.wanders
        and not fido.stay_area
        and not fido.fear_aura
        and not fido.confused
        and not fido.programs
        and not fido.attack_programs
        and not fido.non_corporeal
        and not fido.costs_fame
        and set(source_world.mobile_specials.get(fido.vnum, ()))
        == {"spec_fido"}
        and sorted(
            (reset.room_vnum, reset.maximum_count, reset.object_vnums, reset.equipment)
            for reset in fido_resets
        )
        == [
            (3012, 15, (), ()),
            (3016, 15, (), ()),
            (3024, 15, (), ()),
            (3025, 15, (), ()),
        ]
        and source_mobile_route_aggressor_is_bounded(
            source_world,
            fido,
            character_level=character_level,
            character_max_hp=character_max_hp,
        )
    ):
        return False

    target = source_world.mobiles.get(candidate.mobile_vnum)
    target_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if target is None or not target_resets or len(target_resets) > 2:
        return False
    if any(reset.maximum_count != 1 for reset in target_resets):
        return False
    if len({reset.room_vnum for reset in target_resets}) != len(target_resets):
        return False
    # A few Mirror Realm lords have the same source-safe singleton reset in
    # two separate rooms.  Treat those as per-room singletons only when the
    # complete object/equipment loadout is identical in every reset.
    reset_shapes = {
        (
            frozenset(reset.object_vnums),
            frozenset(reset.equipment),
        )
        for reset in target_resets
    }
    if len(reset_shapes) != 1:
        return False
    target_reset = next(
        (
            reset
            for reset in target_resets
            if reset.room_vnum == candidate.room_vnum
        ),
        None,
    )
    if target_reset is None:
        return False
    if not (
        target_reset.room_vnum == candidate.room_vnum
        and target_reset.maximum_count == 1
        and target.level == candidate.level
        and not target.programs
        and not target.attack_programs
        and not target.fear_aura
        and not target.confused
        and not target.non_corporeal
        and not target.costs_fame
        and not target.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        and tuple(source_world.mobile_specials.get(target.vnum, ()))
        == tuple(candidate.specials)
    ):
        return False
    target_is_grey_fox = (
        candidate.mobile_vnum == _MIRROR_REALM_GREY_FOX_MOBILE_VNUM
        and candidate.room_vnum == _MIRROR_REALM_GREY_FOX_ROOM_VNUM
        and candidate.specials == (_MIRROR_REALM_GREY_FOX_SPECIAL,)
        and target.aggressive
        and target.sentinel
        and not target.wanders
        and not target_resets[0].equipment
        and not target_resets[0].object_vnums
    )
    if allow_aggressive_target != target_is_grey_fox:
        return False
    if allow_aggressive_target and not candidate.equipped_weapons:
        pass
    elif not allow_aggressive_target and target.aggressive:
        return False
    elif not allow_aggressive_target and candidate.specials:
        return False

    equipped_items = {
        object_vnum
        for _slot, object_vnum in target_reset.equipment
    }
    all_target_objects = set(target_reset.object_vnums) | equipped_items
    if any(
        source_world.objects.get(object_vnum) is None
        for object_vnum in all_target_objects
    ):
        return False
    if any(
        source_world.objects[object_vnum].item_type
        in {ITEM_POTION, ITEM_PILL, ITEM_SCROLL, ITEM_STAFF, ITEM_WAND}
        for object_vnum in equipped_items
    ):
        return False
    if any(slot == WEAR_DUAL for slot, _object_vnum in target_reset.equipment):
        return False
    wielded = [
        object_vnum
        for slot, object_vnum in target_reset.equipment
        if slot == WEAR_WIELD
    ]
    if candidate.equipped_weapons:
        if (
            len(candidate.equipped_weapons) != 1
            or len(wielded) != 1
        ):
            return False
    elif wielded:
        return False
    return True


def _caerlin_staff_retry_open(
    state: Mapping[str, Any],
    attempt: Mapping[str, Any] | None,
    *,
    locator_retry: bool,
    handoff_repair: bool,
    locator_revalidation: bool = False,
) -> bool:
    """Keep one closed carrier attempt closed until its evidence scope changes."""
    if locator_retry or locator_revalidation or handoff_repair:
        return True
    return not (
        isinstance(attempt, Mapping)
        and attempt.get("boot_id") == state.get("world_boot_id")
        and attempt.get("level") == _level(dict(state))
        and attempt.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and attempt.get("status")
        in {"attempted", "succeeded", "failed", "closed"}
    )


def _caerlin_staff_reserve_reacquisition_allowed(
    state: Mapping[str, Any],
) -> bool:
    """Allow one repair after a verified staff was lost after acquisition."""
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(attempt, Mapping):
        return False
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
        or attempt.get("status") != "succeeded"
        or attempt.get("outcome") != "staff_acquired"
        or attempt.get(_CAERLIN_STAFF_RESERVE_REACQUISITION_KEY) is True
        or _campaign_has_caerlin_staff(state)
    ):
        return False
    raw_reserves = state.get(_SOURCE_RESOURCE_RESERVES_KEY)
    if isinstance(raw_reserves, Mapping):
        sanctuary = raw_reserves.get("sanctuary")
        if isinstance(sanctuary, Mapping):
            try:
                if int(sanctuary.get("object_vnum")) == _CAERLIN_STAFF_OBJECT_VNUM:
                    return False
            except (TypeError, ValueError):
                pass
    return not (
        state.get("campaign_died_during_segment") is True
        or state.get("xp_loss_observed") is True
        or state.get("campaign_xp_loss_observed") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
    )


def _caerlin_staff_source_revision_retry_allowed(
    state: Mapping[str, Any],
) -> bool:
    """Revalidate one old Caerlin attempt after the source revision changes."""
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    current_revision = state.get(_SOURCE_REVISION_KEY)
    if not isinstance(attempt, Mapping) or not current_revision:
        return False
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") in {None, current_revision}
        or attempt.get("status") not in {"attempted", "succeeded", "failed", "closed"}
        or _campaign_has_caerlin_staff(state)
    ):
        return False
    raw_reserves = state.get(_SOURCE_RESOURCE_RESERVES_KEY)
    if isinstance(raw_reserves, Mapping):
        sanctuary = raw_reserves.get("sanctuary")
        if isinstance(sanctuary, Mapping):
            try:
                if int(sanctuary.get("object_vnum") or 0) == _CAERLIN_STAFF_OBJECT_VNUM:
                    return False
            except (TypeError, ValueError):
                pass
    return not (
        state.get("campaign_died_during_segment") is True
        or state.get("xp_loss_observed") is True
        or state.get("campaign_xp_loss_observed") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
    )


def _caerlin_staff_locator_retry_allowed(state: Mapping[str, Any]) -> bool:
    """Allow one exact retry after a safe positive-where wandering miss."""
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(attempt, Mapping):
        return False
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
        or attempt.get("status") not in {"attempted", "closed"}
    ):
        return False
    try:
        retry_count = int(attempt.get("retry_count") or 0)
    except (TypeError, ValueError):
        return False
    if retry_count >= _CAERLIN_STAFF_LOCATOR_RETRY_LIMIT:
        return False
    if (
        state.get("campaign_fastwalk_target_present_observed") is not True
        or state.get("campaign_fastwalk_target_absent") is True
        or state.get("campaign_died_during_segment") is True
        or state.get("xp_loss_observed") is True
        or state.get("campaign_xp_loss_observed") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
    ):
        return False
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    if not any(
        abort_reason.startswith(prefix)
        for prefix in _CAERLIN_STAFF_LOCATOR_MISS_PREFIXES
    ):
        return False
    sightings = state.get(_SOURCE_ABSENT_SIGHTINGS_KEY)
    if not isinstance(sightings, (list, tuple, set, frozenset)) or not any(
        isinstance(sighting, Mapping)
        and str(sighting.get("target") or "").casefold() == "caerlin"
        and str(sighting.get("room_vnum") or "").strip()
        for sighting in sightings
    ):
        return False
    decisions = state.get("campaign_fastwalk_where_decisions")
    return bool(
        isinstance(decisions, (list, tuple, set, frozenset))
        and any(
            isinstance(decision, Mapping)
            and decision.get("source_mobile_vnum")
            == _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
            and str(decision.get("target") or "").casefold() == "caerlin"
            and decision.get("locations")
            for decision in decisions
        )
    )


def _caerlin_staff_locator_revalidation_allowed(
    state: Mapping[str, Any],
) -> bool:
    """Allow one repair for the historical closed-door ``The Path`` miss."""
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(attempt, Mapping):
        return False
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
        or attempt.get("status") != "closed"
        or attempt.get("outcome") != "locator_retry_missed"
        or attempt.get("locator_revalidation_revision")
        == _CAERLIN_STAFF_LOCATOR_REPAIR_REVISION
    ):
        return False
    if (
        state.get("campaign_died_during_segment") is True
        or state.get("xp_loss_observed") is True
        or state.get("campaign_xp_loss_observed") is True
        or state.get("campaign_objective_kills")
        or state.get("campaign_completed_kills")
        or _campaign_has_caerlin_staff(state)
    ):
        return False
    try:
        return int(attempt.get("retry_count") or 0) == _CAERLIN_STAFF_LOCATOR_RETRY_LIMIT
    except (TypeError, ValueError):
        return False


def _caerlin_staff_handoff_repair_allowed(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> bool:
    """Reopen one carrier attempt that never dispatched its exact handoff.

    Older recovery segments recorded the Caerlin marker during policy
    selection, then entered the generic Moria fallback.  That is not a live
    Caerlin attempt and must not consume the one real route attempt.
    """
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(attempt, Mapping):
        return False
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("object_vnums") != [_CAERLIN_STAFF_OBJECT_VNUM]
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
        or attempt.get("status") != "attempted"
        or attempt.get("handoff_repair_consumed") is True
    ):
        return False
    try:
        if int(attempt.get("retry_count") or 0) != 0:
            return False
    except (TypeError, ValueError):
        return False
    if _research_fatal_failure_active(
        state,
        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
    ):
        # A same-boot, same-level source result saying that Caerlin has no
        # safe relocation route closes the old preparation handoff repair.
        # Reopening it here would create a fresh level marker and send the
        # live worker back into a route already proven unavailable.
        return False
    reserve_reacquisition_handoff = (
        attempt.get(_CAERLIN_STAFF_RESERVE_REACQUISITION_KEY) is True
    )

    for raw_segment in segments:
        try:
            segment = dict(raw_segment)
        except (TypeError, ValueError):
            continue
        if reserve_reacquisition_handoff:
            if segment.get("phase") not in {
                _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
                "return-home",
            }:
                continue
        elif segment.get("phase") != _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id:
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        start_attempt = start.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
        if not isinstance(start_attempt, Mapping):
            continue
        if any(
            start_attempt.get(key) != attempt.get(key)
            for key in (
                "boot_id",
                "level",
                "source_revision",
                "mobile_vnum",
                "room_vnum",
                "object_vnums",
            )
        ):
            continue
        if (
            end.get("world_boot_id") != state.get("world_boot_id")
            or _level(dict(end)) != _level(dict(state))
            or end.get(_SOURCE_CONSUMABLE_SPELL_KEY) is not None
            or end.get("campaign_source_resource_reserve") is not None
            or end.get("campaign_source_consumable_candidate") is not None
            or end.get("campaign_source_consumable_object_vnums") is not None
        ):
            continue
        fastwalk_route = str(end.get("fastwalk_route") or "").casefold()
        if reserve_reacquisition_handoff:
            if segment.get("status") != "success" or fastwalk_route:
                continue
            if (
                end.get("campaign_died_during_segment") is True
                or end.get("xp_loss_observed") is True
                or end.get("campaign_xp_loss_observed") is True
                or end.get("campaign_objective_kills")
                or end.get("campaign_completed_kills")
            ):
                continue
            if _campaign_has_caerlin_staff(end):
                continue
            return True
        pre_dispatch_interruption = bool(
            not fastwalk_route
            and segment.get("status") == "ready"
            and segment.get("execution_status") == "interrupted"
        )
        if fastwalk_route != "moria" and not pre_dispatch_interruption:
            continue
        if _campaign_has_caerlin_staff(end):
            continue
        return True
    return False


def _campaign_has_caerlin_staff(state: Mapping[str, Any]) -> bool:
    """Recognize the exact source object in the compact live inventory view."""
    target = "staff of the bard"
    # Char.Items is itself a JSON string and may be nested as ``[[...]]``;
    # applying normalize_item_name to that whole payload can consume the
    # beginning of the JSON as a display prefix and miss an early item.
    # Reuse the structured item walker so ANSI-wrapped live inventory and
    # ordinary test fixtures follow the same exact-object path.
    for key in ("inventory", "campaign_worn_equipment", "acquired_items"):
        if _state_has_item(state.get(key), target):
            return True
    return False


def _repair_stale_caerlin_staff_reserve(
    state: Mapping[str, Any],
    live_state: Mapping[str, Any] | None,
    *,
    source_revision: str | None,
) -> dict[str, Any]:
    """Reopen one Caerlin repair when newer live inventory disproves a reserve.

    Campaign metadata intentionally survives standalone maintenance runs, but
    a liquidation run can still be newer than the campaign checkpoint.  Do
    not let that merge resurrect a sold Sanctuary staff: a non-depleted source
    reserve is valid only while the exact object remains in live inventory or
    worn equipment.
    """
    if not isinstance(live_state, Mapping) or _campaign_has_caerlin_staff(live_state):
        return dict(state)
    raw_reserves = state.get(_SOURCE_RESOURCE_RESERVES_KEY)
    if not isinstance(raw_reserves, Mapping):
        return dict(state)
    sanctuary = raw_reserves.get("sanctuary")
    if not isinstance(sanctuary, Mapping):
        return dict(state)
    try:
        object_vnum = int(sanctuary.get("object_vnum") or 0)
        charges_remaining = int(sanctuary.get("charges_remaining") or 0)
    except (TypeError, ValueError):
        return dict(state)
    if (
        object_vnum != _CAERLIN_STAFF_OBJECT_VNUM
        or charges_remaining <= 0
    ):
        return dict(state)
    repaired = dict(state)
    reserves = dict(raw_reserves)
    reserves.pop("sanctuary", None)
    repaired[_SOURCE_RESOURCE_RESERVES_KEY] = reserves
    prior_attempt = repaired.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    attempt = dict(prior_attempt) if isinstance(prior_attempt, Mapping) else {}
    attempt.update(
        {
            "boot_id": repaired.get("world_boot_id"),
            "level": _level(repaired),
            "source_revision": source_revision,
            "status": "succeeded",
            "outcome": "staff_acquired",
            "retry_count": max(1, int(attempt.get("retry_count") or 0)),
            "mobile_vnum": _CAERLIN_STAFF_CARRIER_MOBILE_VNUM,
            "room_vnum": _CAERLIN_STAFF_CARRIER_ROOM_VNUM,
            "object_vnums": [_CAERLIN_STAFF_OBJECT_VNUM],
            _CAERLIN_STAFF_RESERVE_REACQUISITION_KEY: False,
            "repair_reason": (
                "newer live inventory disproved the campaign's non-depleted "
                "Sanctuary staff reserve after standalone maintenance"
            ),
        }
    )
    repaired[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = attempt
    return repaired


def _caerlin_staff_dispatch_evidence(
    state: Mapping[str, Any],
) -> tuple[bool, str]:
    """Recognize a dispatched Caerlin attempt that did not acquire the staff."""
    route = str(
        state.get("fastwalk_route")
        or state.get("campaign_fastwalk_route")
        or ""
    ).strip().casefold()
    if route != "source sanctuary reserve caerlin 19068":
        return False, ""
    if (
        state.get("campaign_fastwalk_target_present_observed") is not True
        or state.get("campaign_fastwalk_target_absent") is True
    ):
        return False, ""
    consider_outcomes = state.get("campaign_fastwalk_consider_outcomes")
    if not isinstance(consider_outcomes, Mapping) or (
        consider_outcomes.get("caerlin") is not True
    ):
        return False, ""
    source_consider_outcomes = state.get(
        "campaign_fastwalk_source_consider_outcomes"
    )
    if not isinstance(source_consider_outcomes, Mapping) or not any(
        value is True
        and "19004" in str(policy_id)
        and "19068" in str(policy_id)
        for policy_id, value in source_consider_outcomes.items()
    ):
        return False, ""
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "").strip()
    if not abort_reason or any(
        abort_reason.startswith(prefix)
        for prefix in _CAERLIN_STAFF_LOCATOR_MISS_PREFIXES
    ):
        return False, ""
    return True, abort_reason


def _repair_caerlin_staff_attempt_metadata(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> dict[str, Any]:
    """Close a stale attempt marker after a recorded, exact carrier dispatch."""
    attempt = state.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(attempt, Mapping) or attempt.get("status") != "attempted":
        return dict(state)
    if (
        attempt.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM
        or attempt.get("room_vnum") != _CAERLIN_STAFF_CARRIER_ROOM_VNUM
        or attempt.get("boot_id") != state.get("world_boot_id")
        or attempt.get("level") != _level(dict(state))
        or attempt.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
    ):
        return dict(state)
    try:
        if int(attempt.get("retry_count") or 0) != 0:
            return dict(state)
    except (TypeError, ValueError):
        return dict(state)
    for raw_segment in reversed(tuple(segments)):
        segment = _campaign_segment_mapping(raw_segment)
        if not isinstance(segment, Mapping):
            continue
        if (
            segment.get("phase")
            not in {_SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id}
            or segment.get("status") != "success"
        ):
            continue
        end = _campaign_segment_end_mapping(segment)
        if not isinstance(end, Mapping):
            continue
        if (
            end.get("world_boot_id") != state.get("world_boot_id")
            or _level(dict(end)) != _level(dict(state))
            or end.get(_SOURCE_REVISION_KEY) != state.get(_SOURCE_REVISION_KEY)
            or _campaign_has_caerlin_staff(end)
        ):
            continue
        end_attempt = end.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
        if not isinstance(end_attempt, Mapping) or any(
            end_attempt.get(key) != attempt.get(key)
            for key in (
                "boot_id",
                "level",
                "source_revision",
                "mobile_vnum",
                "room_vnum",
                "object_vnums",
                "retry_count",
            )
        ):
            continue
        dispatched, abort_reason = _caerlin_staff_dispatch_evidence(end)
        if not dispatched:
            continue
        outcome = (
            "combat_aborted_no_acquisition"
            if "field combat aborted" in abort_reason.casefold()
            else "no_acquisition"
        )
        repaired = dict(state)
        repaired[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = {
            **dict(attempt),
            "status": "closed",
            "outcome": outcome,
            "closed_segment_id": segment.get("id"),
        }
        return repaired
    return dict(state)


def _finalize_caerlin_staff_recovery_attempt(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
    merged: dict[str, Any],
    *,
    execution: str,
) -> None:
    """Record acquisition or close the one retry after a locator miss."""
    marker = merged.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(marker, Mapping):
        marker = previous.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY)
    if not isinstance(marker, Mapping):
        return
    if marker.get("mobile_vnum") != _CAERLIN_STAFF_CARRIER_MOBILE_VNUM:
        return
    if execution not in {"moria-sanctuary-hunt", "moria-deep-sanctuary-hunt"}:
        return
    if _campaign_has_caerlin_staff(current) or _campaign_has_caerlin_staff(merged):
        merged[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = {
            **dict(marker),
            "status": "succeeded",
            "outcome": "staff_acquired",
        }
        return
    try:
        retry_count = int(marker.get("retry_count") or 0)
    except (TypeError, ValueError):
        retry_count = 0
    locator_probe = dict(current)
    locator_probe[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = dict(marker)
    if retry_count >= _CAERLIN_STAFF_LOCATOR_RETRY_LIMIT:
        merged[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = {
            **dict(marker),
            "status": "closed",
            "outcome": (
                "reserve_reacquisition_missed"
                if marker.get(_CAERLIN_STAFF_RESERVE_REACQUISITION_KEY)
                else "locator_retry_missed"
            ),
        }
    elif _caerlin_staff_dispatch_evidence(current)[0]:
        _dispatched, abort_reason = _caerlin_staff_dispatch_evidence(current)
        merged[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = {
            **dict(marker),
            "status": "closed",
            "outcome": (
                "combat_aborted_no_acquisition"
                if "field combat aborted" in abort_reason.casefold()
                else "no_acquisition"
            ),
        }
    elif _caerlin_staff_locator_retry_allowed(locator_probe):
        # Preserve the attempted marker so the next segment can consume the
        # one retry only for a genuine safe positive-where locator miss.
        if merged.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY) is None:
            merged[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = dict(marker)
    elif merged.get(_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY) is None:
        merged[_CAERLIN_STAFF_RECOVERY_ATTEMPT_KEY] = dict(marker)


def _source_ranked_healer_poison_recovery_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    source_world: WorldSource | None,
) -> bool:
    """Prove Midgaard's passive adept can clear gas-breath nausea."""
    return _source_ranked_healer_recovery_route_allowed(
        candidate,
        state,
        source_world=source_world,
        expected_specials=("spec_breath_gas",),
        required_effects=("nausea",),
        allowed_effects=_SOURCE_HEALER_POISON_RECOVERY_EFFECTS,
    )


def _source_ranked_demon_summoner_room_companion_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Prove Underdark's one non-aggressive mage companion is bounded.

    The companion wanders, but it is not aggressive, is not grouped with the
    summoner, carries only a bracer, and ``spec_cast_mage`` selects only a
    victim already fighting that individual caster. Keep this exception tied
    to the exact room/reset shape; it is not a general room-companion waiver.
    """
    if source_world is None:
        return False
    target = source_world.mobiles.get(
        _SOURCE_UNDERDARK_DEMON_SUMMONER_MOBILE_VNUM
    )
    companion = source_world.mobiles.get(
        _SOURCE_UNDERDARK_DEMON_SUMMONER_COMPANION_VNUM
    )
    target_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_MOBILE_VNUM
        and reset.room_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_ROOM_VNUM
    )
    companion_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_COMPANION_VNUM
        and reset.room_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_ROOM_VNUM
    )
    companion_object = source_world.objects.get(
        _SOURCE_UNDERDARK_DEMON_SUMMONER_COMPANION_OBJECT_VNUM
    )
    return bool(
        candidate.mobile_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_MOBILE_VNUM
        and candidate.room_vnum == _SOURCE_UNDERDARK_DEMON_SUMMONER_ROOM_VNUM
        and candidate.area_file.casefold() == "underdark.are"
        and candidate.level == 37
        and candidate.estimated_level_range == _mobile_level_range(37)
        and candidate.source_spawn_limit == 3
        and candidate.room_spawn_count == 1
        and not candidate.equipped_weapons
        and candidate.specials == ("spec_cast_mage",)
        and target is not None
        and target.level == 37
        and not target.aggressive
        and not target.wanders
        and target.sentinel
        and target.stay_area
        and not target.programs
        and not target.attack_programs
        and not target.fear_aura
        and not target.confused
        and not target.non_corporeal
        and not target.costs_fame
        and tuple(
            source_world.mobile_specials.get(target.vnum, ())
        ) == ("spec_cast_mage",)
        and len(target_resets) == 1
        and target_resets[0].maximum_count == 3
        and target_resets[0].object_vnums
        == (16087,)
        and target_resets[0].equipment == ((17, 16087),)
        and companion is not None
        and companion.level == 31
        and not companion.aggressive
        and companion.wanders
        and not companion.sentinel
        and companion.stay_area
        and not companion.programs
        and not companion.attack_programs
        and not companion.fear_aura
        and not companion.confused
        and not companion.non_corporeal
        and not companion.costs_fame
        and tuple(
            source_world.mobile_specials.get(companion.vnum, ())
        ) == ("spec_cast_mage",)
        and len(companion_resets) == 1
        and companion_resets[0].maximum_count == 3
        and companion_resets[0].object_vnums
        == (_SOURCE_UNDERDARK_DEMON_SUMMONER_COMPANION_OBJECT_VNUM,)
        and companion_resets[0].equipment
        == ((14, _SOURCE_UNDERDARK_DEMON_SUMMONER_COMPANION_OBJECT_VNUM),)
        and companion_object is not None
        and companion_object.item_type != ITEM_WEAPON
    )


def _source_ranked_kaladim_cave_beast_route_risk_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Keep the productive Cave beast route open behind one known knife.

    This is deliberately narrower than the generic route-risk fallback. It
    applies only to the exact Kaladim Cave beast reset, after that reset has
    already produced a useful same-boot kill and the only remembered crossing
    is the source-bounded level-34 knife. A new live absence, crowd, route
    failure, or XP loss closes it again.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or character_level != 40
        or candidate.area_file.casefold() != _SOURCE_KALADIM_CAVE_BEAST_AREA_FILE
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.mobile_vnum != _SOURCE_KALADIM_CAVE_BEAST_MOBILE_VNUM
        or candidate.room_vnum != _SOURCE_KALADIM_CAVE_BEAST_ROOM_VNUM
        or candidate.estimated_level_range != (37, 41)
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.requires_flight
        or candidate.requires_water_breathing
        or candidate.requires_detect_invisibility
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or _source_ranked_xp_loss_record(
            state,
            _source_ranked_policy_id(candidate, character_level=character_level),
        )
        is not None
    ):
        return False

    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    target_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        mobile is None
        or not mobile.aggressive
        or mobile.programs
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or source_world.mobile_specials.get(mobile.vnum)
        or mobile.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        or _source_ranked_target_identity(candidate)
        != _source_ranked_normalized_target(mobile.short_description)
        or len(target_resets) != 1
        or target_resets[0].room_vnum != candidate.room_vnum
        or target_resets[0].maximum_count != 1
        or target_resets[0].object_vnums
        or target_resets[0].equipment
    ):
        return False

    try:
        route_rooms = _source_route_room_vnums(
            source_world,
            candidate.route_origin_room_vnum,
            candidate.route,
        )
    except (KeyError, TypeError, ValueError):
        return False
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    if _source_ranked_borderline_route_aggressor_vnums(
        candidate,
        source_world,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ) != (_SOURCE_KALADIM_CAVE_BEAST_TRANSIT_MOBILE_VNUM,):
        return False

    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("completed_kill") is True
        and result.get("viable") is True
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "route_hazard",
                "target_vnum_mismatch",
                "xp_loss_observed",
            )
        )
    ):
        return False

    raw_records = state.get(_SOURCE_RANKED_TRANSIT_HAZARDS_KEY)
    if not isinstance(raw_records, Mapping):
        return False
    route_room_ids = {int(room_vnum) for room_vnum in route_rooms[:-1]}
    source_revision = state.get(_SOURCE_REVISION_KEY)
    matched = False
    for raw_record in raw_records.values():
        if not isinstance(raw_record, Mapping):
            continue
        if (
            raw_record.get("boot_id") != state.get("world_boot_id")
            or raw_record.get("level") != character_level
            or (
                source_revision
                and raw_record.get("source_revision")
                and raw_record.get("source_revision") != source_revision
            )
        ):
            continue
        try:
            mobile_vnum = int(raw_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        hazard_rooms = {
            reset.room_vnum
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        }
        if not hazard_rooms.intersection(route_room_ids):
            continue
        if mobile_vnum != _SOURCE_KALADIM_CAVE_BEAST_TRANSIT_MOBILE_VNUM:
            return False
        source_policy_ids = {
            str(value)
            for value in raw_record.get("source_policy_ids") or ()
            if str(value)
        }
        if policy_id not in source_policy_ids:
            return False
        matched = True
    return matched


def _source_ranked_kaladim_mirror_route_risk_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Keep Kaladim's plain mirror reachable behind one bounded route risk.

    The mirror is a single, unarmed, non-aggressive sentinel at level 36.
    Its recall-origin route crosses the source reset for the level-34 knife,
    which has already been observed on this reboot.  This exception allows
    that exact route to be retried while preserving the live crowd, identity,
    consider, combat and return-home gates.  It does not admit the cave
    beast, the Master Elf, or arbitrary Kaladim mobiles.
    """
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.area_file.casefold() != _SOURCE_KALADIM_MIRROR_AREA_FILE
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.mobile_vnum != _SOURCE_KALADIM_MIRROR_MOBILE_VNUM
        or candidate.room_vnum != _SOURCE_KALADIM_MIRROR_ROOM_VNUM
        or candidate.estimated_level_range != (34, 38)
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.autonomy_rejections
        or candidate.requires_flight
        or candidate.requires_water_breathing
        or candidate.requires_detect_invisibility
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or _SOURCE_KALADIM_MIRROR_TRANSIT_MOBILE_VNUM
        not in set(candidate.route_aggressive_mobile_vnums)
    ):
        return False

    route_rooms = _source_route_room_vnums(
        source_world,
        candidate.route_origin_room_vnum,
        candidate.route,
    )
    if not route_rooms or route_rooms[-1] != candidate.room_vnum:
        return False
    route_room_ids = set(route_rooms[:-1])
    if _SOURCE_KALADIM_MIRROR_TRANSIT_MOBILE_VNUM not in {
        reset.mobile_vnum
        for reset in source_world.mob_resets
        if reset.room_vnum in route_room_ids
    }:
        return False

    target = source_world.mobiles.get(candidate.mobile_vnum)
    target_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    )
    if (
        target is None
        or target.aggressive
        or target.wanders
        or not target.sentinel
        or not target.stay_area
        or target.programs
        or target.attack_programs
        or target.fear_aura
        or target.confused
        or target.non_corporeal
        or target.costs_fame
        or source_world.mobile_specials.get(target.vnum)
        or target.act_flags & (ACT_NO_EXPERIENCE | ACT_NO_FIGHT)
        or len(target_resets) != 1
        or target_resets[0].room_vnum != candidate.room_vnum
        or target_resets[0].maximum_count != 1
        or target_resets[0].object_vnums
        or target_resets[0].equipment
        or not _source_ranked_route_aggressors_are_bounded(
            candidate,
            character_level=character_level,
            source_world=source_world,
            character_max_hp=character_max_hp,
        )
    ):
        return False

    knife = source_world.mobiles.get(
        _SOURCE_KALADIM_MIRROR_TRANSIT_MOBILE_VNUM
    )
    knife_resets = tuple(
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _SOURCE_KALADIM_MIRROR_TRANSIT_MOBILE_VNUM
    )
    if (
        knife is None
        or not knife.aggressive
        or knife.sentinel
        or not knife.wanders
        or not knife.stay_area
        or knife.programs
        or knife.attack_programs
        or knife.fear_aura
        or knife.confused
        or knife.non_corporeal
        or knife.costs_fame
        or source_world.mobile_specials.get(knife.vnum)
        or len(knife_resets) != 1
        or knife_resets[0].room_vnum not in route_room_ids
        or knife_resets[0].maximum_count != 1
        or knife_resets[0].object_vnums
        or knife_resets[0].equipment
    ):
        return False

    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, policy_id) is not None:
        return False
    result = _campaign_research_results(state).get(policy_id)
    if isinstance(result, Mapping) and result.get("boot_id") == state.get(
        "world_boot_id"
    ) and any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "fatal_failure",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
            "xp_loss_observed",
        )
    ):
        return False

    # Existing transit receipts are authoritative only for the current level,
    # reboot, and source revision.  The knife receipt must belong to this
    # exact mirror policy; another target's route evidence is not permission
    # to retry this route.  The known Midgaard Drunk exception remains narrow.
    raw_records = state.get(_SOURCE_RANKED_TRANSIT_HAZARDS_KEY)
    if not isinstance(raw_records, Mapping):
        return True
    source_revision = state.get(_SOURCE_REVISION_KEY)
    for raw_record in raw_records.values():
        if not isinstance(raw_record, Mapping):
            continue
        if (
            raw_record.get("boot_id") != state.get("world_boot_id")
            or raw_record.get("level") != character_level
            or (
                source_revision
                and raw_record.get("source_revision")
                and raw_record.get("source_revision") != source_revision
            )
        ):
            continue
        try:
            mobile_vnum = int(raw_record.get("mobile_vnum") or 0)
        except (TypeError, ValueError):
            continue
        hazard_rooms = {
            reset.room_vnum
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile_vnum
        }
        if not hazard_rooms.intersection(route_room_ids):
            continue
        if mobile_vnum == _SOURCE_KALADIM_MIRROR_TRANSIT_MOBILE_VNUM:
            source_policy_ids = {
                str(value)
                for value in raw_record.get("source_policy_ids") or ()
            }
            if policy_id not in source_policy_ids:
                return False
            continue
        if mobile_vnum == _MIDGAARD_DRUNK_MOBILE_VNUM:
            drunk = source_world.mobiles.get(mobile_vnum)
            if (
                drunk is not None
                and _mobile_level_range(drunk.level)[1]
                <= character_level - 5
                and source_mobile_route_program_attacker_is_bounded(
                    source_world,
                    drunk,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                )
            ):
                continue
        return False
    return True


def _source_ranked_high_level_mage_risk_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    source_world: WorldSource | None,
) -> bool:
    """Allow one bounded pre-40 mage-special route with real reserves.

    ``spec_cast_mage`` can energy-drain from level 25 onward, so this is a
    deliberate risk frontier rather than an ordinary fallback. Keep it
    narrower than the source's broad candidate list: the mobile must be a
    stationary, unarmed, non-aggressive source reset with no room companion,
    the player must be at the healer with two verified purple potions and a
    Sanctuary reserve, and the source graph must prove a route back to recall.
    The live runner still owns identity, consider, isolation, output, and the
    player's health-floor decisions.
    """
    if source_world is None or str(state.get("room_vnum") or "") != str(
        _SOURCE_HEALER_ROOM_VNUM
    ):
        return False
    if set(candidate.specials) != {"spec_cast_mage"}:
        return False
    if (
        candidate.estimated_level_range[1]
        > _SOURCE_HIGH_LEVEL_MAGE_RISK_MAXIMUM_LEVEL
    ):
        return False
    if candidate.equipped_weapons or candidate.route_hard_hazard_targets:
        return False
    if (
        candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
    ):
        return False
    if set(candidate.autonomy_rejections) != {
        "target has special procedure spec_cast_mage"
    }:
        return False
    has_room_companion = any(
        "room companion:" in str(hazard).casefold()
        for hazard in candidate.hazards
    )
    if has_room_companion and not _source_ranked_demon_summoner_room_companion_allowed(
        candidate,
        source_world,
    ):
        return False
    if not (
        _state_has_sanctuary_reserve(state)
        and _state_has_blindness_recovery_reserve(
            state,
            required_purple_count=_SOURCE_HIGH_LEVEL_MAGE_REQUIRED_PURPLE_COUNT,
        )
    ):
        return False

    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.programs
        or mobile.aggressive
        or mobile.wanders
        or not mobile.sentinel
        or not mobile.stay_area
        or candidate.room_vnum not in {
            reset.room_vnum
            for reset in source_world.mob_resets
            if reset.mobile_vnum == mobile.vnum
        }
        or set(source_world.mobile_specials.get(mobile.vnum, ()))
        != {"spec_cast_mage"}
    ):
        return False

    # The target room is no-recall. Prove that the return leg can reach the
    # source recall room using ordinary exits; ``open`` is acceptable, while
    # an unverified key or lockpick requirement is not.
    return_path = _shortest_paths_from(
        source_world.rooms,
        candidate.room_vnum,
    ).get(RECALL_VNUM)
    if return_path is None or not _source_ranked_route_is_traversable(
        source_world,
        return_path[1],
        state,
    ):
        return False
    return not any(
        str(command).casefold().startswith(("pick ", "unlock "))
        for command in return_path[0]
    )


def _source_ranked_vampire_target_shape_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Prove the singleton, unarmed shape used by the vampire special bound."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    resets = [
        reset for reset in source_world.mob_resets
        if reset.mobile_vnum == candidate.mobile_vnum
    ]
    if (
        mobile is None
        or mobile.aggressive
        or mobile.fear_aura
        or mobile.confused
        or mobile.costs_fame
        or not mobile.sentinel
        or mobile.attack_programs
        or not noncombat_echo_programs_only(mobile.programs)
        or mobile.rank.casefold() not in {"common", "none"}
        or candidate.area_file != mobile.area_file
        or candidate.room_vnum not in {reset.room_vnum for reset in resets}
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.equipped_weapons
        or candidate.estimated_level_range != _mobile_level_range(mobile.level)
        or tuple(source_world.mobile_specials.get(mobile.vnum, ()))
        != ("spec_vampire",)
        or len(resets) != 1
        or resets[0].room_vnum != candidate.room_vnum
        or resets[0].maximum_count != 1
    ):
        return False

    reset = resets[0]
    if not reset.object_vnums and not reset.equipment:
        return True
    if (
        len(reset.object_vnums) != 1
        or len(reset.equipment) != 1
        or reset.equipment[0][0] != 21
        or reset.object_vnums[0] != reset.equipment[0][1]
    ):
        return False
    ranged_weapon = source_world.objects.get(reset.equipment[0][1])
    return bool(
        ranged_weapon is not None
        and ranged_weapon.item_type == ITEM_WEAPON
        and is_bow(ranged_weapon)
    )


def _source_ranked_master_elf_risk_shape_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
) -> bool:
    """Match Kaladim's exact, single-reset Master Elf risk contract."""
    if source_world is None:
        return False
    mobile = source_world.mobiles.get(_SOURCE_MASTER_ELF_MOBILE_VNUM)
    weapon = source_world.objects.get(_SOURCE_MASTER_ELF_WHIP_OBJECT_VNUM)
    resets = [
        reset
        for reset in source_world.mob_resets
        if reset.mobile_vnum == _SOURCE_MASTER_ELF_MOBILE_VNUM
    ]
    room_resets = [
        reset
        for reset in source_world.mob_resets
        if reset.room_vnum == _SOURCE_MASTER_ELF_ROOM_VNUM
    ]
    companion = source_world.mobiles.get(9928)
    if (
        mobile is None
        or weapon is None
        or mobile.level != 40
        or not mobile.aggressive
        or not mobile.sentinel
        or not mobile.stay_area
        or mobile.wanders
        or mobile.programs
        or mobile.attack_programs
        or mobile.area_file.casefold() != _SOURCE_MASTER_ELF_AREA_FILE
        or tuple(source_world.mobile_specials.get(mobile.vnum, ()))
        != ("spec_cast_undead",)
        or candidate.mobile_vnum != _SOURCE_MASTER_ELF_MOBILE_VNUM
        or candidate.room_vnum != _SOURCE_MASTER_ELF_ROOM_VNUM
        or candidate.area_file.casefold() != _SOURCE_MASTER_ELF_AREA_FILE
        or candidate.estimated_level_range != _mobile_level_range(mobile.level)
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or len(candidate.equipped_weapons) != 1
        or candidate.equipped_weapons[0] != weapon.short_description
        or weapon.item_type != ITEM_WEAPON
        or len(resets) != 1
        or resets[0].room_vnum != _SOURCE_MASTER_ELF_ROOM_VNUM
        or resets[0].maximum_count != 1
        or resets[0].equipment != ((16, _SOURCE_MASTER_ELF_WHIP_OBJECT_VNUM),)
        or tuple(_reset_object_vnums(resets[0]))
        != (_SOURCE_MASTER_ELF_WHIP_OBJECT_VNUM,)
        or set(reset.mobile_vnum for reset in room_resets)
        != {_SOURCE_MASTER_ELF_MOBILE_VNUM, 9928}
        or companion is None
        or companion.aggressive
        or companion.programs
        or companion.attack_programs
        or source_world.mobile_specials.get(companion.vnum)
    ):
        return False
    return True


def _source_ranked_master_elf_route_risk_allowed(
    candidate: HuntCandidate,
    source_world: WorldSource | None,
    *,
    character_level: int,
) -> bool:
    """Allow only the audited below-band transit hazards to Kaladim."""
    if not _source_ranked_master_elf_risk_shape_allowed(candidate, source_world):
        return False
    if candidate.route_hard_hazard_targets:
        return False
    if source_world is None:
        return False
    for mobile_vnum in candidate.route_aggressive_mobile_vnums:
        mobile = source_world.mobiles.get(mobile_vnum)
        if (
            mobile is None
            or mobile.level > min(
                character_level - 5,
                _SOURCE_MASTER_ELF_ROUTE_MAX_BELOW_BAND_LEVEL,
            )
            or mobile.attack_programs
            or mobile.fear_aura
            or mobile.costs_fame
            or any(
                not source_special_is_transit_safe(special)
                for special in source_world.mobile_specials.get(
                    mobile_vnum, ()
                )
            )
        ):
            return False
    return True


def _source_ranked_psionic_candidate_requires_protection(
    candidate: HuntCandidate,
    *,
    source_world: WorldSource | None = None,
) -> bool:
    """Keep stale psionic targets behind the source protection boundary.

    The ordinary special admission path already applies this rule. This
    helper also covers saved candidates, whose compact records can otherwise
    reach the selector's fast path without another special audit.
    """
    if "spec_cast_psionicist" not in set(candidate.specials):
        return False
    maximum_level = candidate.estimated_level_range[1]
    if maximum_level <= 0 and source_world is not None:
        mobile = source_world.mobiles.get(candidate.mobile_vnum)
        if mobile is not None:
            maximum_level = _mobile_level_range(mobile.level)[1]
    # Energy drain begins before disintegrate. No generic carried item or
    # affect is source-proven as protection for either effect, so unknown and
    # level-14-plus psionicists stay closed rather than being replayed from
    # stale state.
    return maximum_level <= 0 or maximum_level >= PSIONICIST_ENERGY_DRAIN_LEVEL


def _source_ranked_psionic_protection_effects(
    candidate: HuntCandidate,
    *,
    source_world: WorldSource | None = None,
) -> tuple[str, ...]:
    """Describe the source spell exposure behind a psionic protection gate."""
    if "spec_cast_psionicist" not in set(candidate.specials):
        return ()
    maximum_level = candidate.estimated_level_range[1]
    if maximum_level <= 0 and source_world is not None:
        mobile = source_world.mobiles.get(candidate.mobile_vnum)
        if mobile is not None:
            maximum_level = _mobile_level_range(mobile.level)[1]
    if maximum_level <= 0:
        return ("unknown psionic spell exposure",)
    effects = source_special_status_effects(
        "spec_cast_psionicist",
        level=maximum_level,
    )
    return effects or ("mind-affecting psionic spells",)


def _source_ranked_psionic_protection_requirement(
    candidate: HuntCandidate,
    *,
    source_world: WorldSource | None = None,
) -> str:
    """Return a concise, source-derived explanation for a closed psionicist."""
    effects = _source_ranked_psionic_protection_effects(
        candidate,
        source_world=source_world,
    )
    if not effects:
        return "fresh psionic protection receipt required"
    return "fresh psionic protection receipt required for " + "/".join(effects)


def _audited_source_special_candidate_allowed(
    candidate: HuntCandidate,
    *,
    state: Mapping[str, Any],
    character_max_hp: int | None,
    source_world: WorldSource | None = None,
    protected_incoming_damage: bool = False,
    route_preflight_admitted: bool = False,
) -> bool:
    """Allow a source-audited, bounded special procedure as fallback."""
    specials = set(candidate.specials)
    rejections = set(candidate.autonomy_rejections)
    if route_preflight_admitted:
        target_rejections = {
            f"target has special procedure {special}"
            for special in candidate.specials
        }
        route_rejections = rejections - target_rejections
        if not route_rejections.issubset(_SOURCE_WANDERER_PREFLIGHT_REJECTIONS):
            return False
        rejections = target_rejections
    if not specials or not specials <= _AUDITED_SOURCE_SPECIALS:
        return False
    famous_gas_recovery = (
        source_world is not None
        and _source_ranked_famous_gas_recovery_allowed(
            candidate,
            source_world,
            state,
        )
    )
    ancient_gold_dragon_breath = (
        source_world is not None
        and _source_ancient_gold_dragon_breath_shape_allowed(
            candidate,
            source_world,
        )
    )
    protected_incoming_peak_override: int | None = None
    if specials & _SOURCE_POISONING_BREATH_SPECIALS:
        # special.c's spec_breath_gas invokes gas breath only while fighting,
        # and spec_breath_any includes that branch among its random choices.
        # magic.c can apply poison-backed nausea; sanctuary reduces damage but
        # does not remove that affect.  The exact famous gas exception has a
        # source-proven passive healer route and an immediate recall boundary;
        # generic gas remains blocked. One exact passive Ofcol dragon is the
        # deliberate risky XP exception; its source reset is checked above and
        # the live runner still owns isolation, consider, and health stops.
        if not (
            (specials == {"spec_breath_gas"} and famous_gas_recovery)
            or ancient_gold_dragon_breath
        ):
            return False
    maximum_level = candidate.estimated_level_range[1]
    if maximum_level <= 0:
        # Registered-mobile candidates are intentionally minimal until the
        # route builder enriches them. Never let that placeholder range make a
        # source special look safer than the mobile prototype actually is.
        source_mobile = (
            source_world.mobiles.get(candidate.mobile_vnum)
            if source_world is not None
            else None
        )
        maximum_level = _mobile_level_range(
            source_mobile.level if source_mobile is not None else candidate.level
        )[1]
    if "spec_cast_psionicist" in specials and maximum_level <= 0:
        # An unknown psionicist level cannot prove that disintegrate is absent.
        return False
    source_effects = {
        effect
        for special in specials
        for effect in source_special_status_effects(
            special,
            level=maximum_level,
        )
    }
    healer_blindness_recovery = (
        _source_ranked_healer_blindness_recovery_allowed(
            candidate,
            state,
            source_world=source_world,
        )
    )
    if (
        "blindness" in source_effects
        and not (
            specials & _SOURCE_SANCTUARY_SPECIALS
            and _has_named_affect(state.get("affects"), "sanctuary")
        )
        and not _state_has_blindness_recovery_reserve(
            state,
            required_purple_count=1,
        )
        and not healer_blindness_recovery
    ):
        # Non-sanctuary status specials need one verified cure reserve; caster
        # specials retain their stricter two-copy sanctuary-opening gate below.
        return False
    if (
        _source_ranked_candidate_requires_blindness_recovery_reserve(candidate)
        and not _has_named_affect(state.get("affects"), "sanctuary")
        and not _state_has_blindness_recovery_reserve(state)
        and not healer_blindness_recovery
    ):
        # These audited specials can blind before the first protected round.
        # If sanctuary will be consumed as the opener, the selector must also
        # see a trained cure or a second source-verified potion.
        return False
    if (
        specials & _SOURCE_BREATH_SPECIALS
        and not _state_has_sanctuary_reserve(state)
    ):
        # Breath variants are direct damage pulses.  Sanctuary halves that
        # damage, while gas breath's poison-backed nausea remains covered by
        # the field runner's immediate healer-return path.
        return False
    if specials == {"spec_cast_mage"} and not _state_has_sanctuary_reserve(
        state
    ):
        # The source damage bound covers one pulse, not repeated spell casts.
        # Require an active or carried sanctuary reserve before exposing a
        # character to a source mage special.
        return False
    if specials == {"spec_cast_mage"} and rejections == {
        "target has special procedure spec_cast_mage"
    }:
        # special.c can choose fireball at levels below 25; magic.c bounds its
        # direct damage at 6d6. At level 25 the source also opens acid blast,
        # dispel magic, and energy drain. The narrow pre-40 frontier below is
        # deliberately reserve- and return-route-gated; it is not a generic
        # admission for every high-level caster.
        if maximum_level >= 25:
            if not _source_ranked_high_level_mage_risk_allowed(
                candidate,
                state,
                source_world=source_world,
            ):
                return False
        worst_special_damage = maximum_level * 6
    elif specials == {"spec_cast_cleric"} and rejections == {
        "target has special procedure spec_cast_cleric"
    }:
        if (
            not _state_has_sanctuary_reserve(state)
            and not healer_blindness_recovery
        ):
            return False
        damage_bounds = [0]
        if maximum_level >= 3:
            damage_bounds.append(16 + maximum_level // 2)
        if maximum_level >= 7:
            damage_bounds.append(5 * maximum_level)
        if maximum_level >= 9:
            damage_bounds.append(18 + maximum_level)
        if maximum_level >= 10:
            damage_bounds.append(5 * maximum_level)
        if maximum_level >= 13:
            damage_bounds.append(6 * maximum_level)
        if maximum_level >= 15:
            damage_bounds.append(100)
        # The special only selects spells whose minimum level the mobile has
        # reached. Dispel magic stays behind the sanctuary recovery boundary.
        worst_special_damage = max(damage_bounds)
    elif specials == {"spec_cast_druid"} and rejections == {
        "target has special procedure spec_cast_druid"
    }:
        # At source levels 10-14, spec_cast_druid can reach flamestrike but
        # not fear, moonray, sunray, or wither. At level 15 fear can force an
        # uncontrolled flee, and level 18 opens sunray blindness, so the
        # higher-level exception requires the same sanctuary/cure reserve as
        # the other audited caster specials. Moonray's clear, dark, full-moon
        # path is the largest source pulse: 9d(level) * 1.5 * 1.4, bounded
        # conservatively at 19*level before saves.
        if candidate.equipped_weapons:
            return False
        if maximum_level >= 15:
            if not _state_has_sanctuary_reserve(state):
                return False
            if (
                "blindness" in source_effects
                and not _has_named_affect(state.get("affects"), "sanctuary")
                and not _state_has_blindness_recovery_reserve(state)
                and not healer_blindness_recovery
            ):
                return False
            worst_special_damage = maximum_level * 19
        else:
            worst_special_damage = maximum_level * 6
    elif specials == {"spec_breath_any"} and rejections == {
        "target has special procedure spec_breath_any"
    }:
        if not ancient_gold_dragon_breath:
            return False
        # The exact Ofcol exception is bounded by the source breath pulse and
        # the required Sanctuary reserve; carried-object damage remains live
        # evidence rather than a reason to pretend the target is harmless.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_breath_gas"} and rejections == {
        "target has special procedure spec_breath_gas"
    }:
        # The exact famous gas route has healer-backed nausea recovery.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_breath_lightning"} and rejections == {
        "target has special procedure spec_breath_lightning"
    }:
        # special.c delegates this variant to dragon(), and magic.c applies
        # only the direct hp/8+1..hp/4 lightning pulse plus save/resistance
        # mitigation. It does not damage carried objects or add an affect.
        worst_special_damage = max(10, candidate.estimated_base_hp_range[1]) // 4
    elif specials == {"spec_cast_undead"} and rejections == {
        "target has special procedure spec_cast_undead"
    }:
        # special.c only runs this procedure after the player is fighting. Its
        # spell table is level-gated: energy drain begins at 15, harm at 18,
        # and gate at 20. The exact level-40 Master Elf is the first bounded
        # exception: Sanctuary and a remaining blindness cure are required,
        # and any summoned crowd still belongs to the live combat abort path.
        # Other undead casters remain research-only at these levels.
        if maximum_level >= 15:
            if not (
                _source_ranked_master_elf_risk_shape_allowed(
                    candidate,
                    source_world,
                )
                and maximum_level <= _SOURCE_MASTER_ELF_MAXIMUM_FUZZ_LEVEL
                and _state_has_sanctuary_reserve(state)
                and _state_has_blindness_recovery_reserve(
                    state,
                    required_purple_count=1,
                )
            ):
                return False
            worst_special_damage = 100
        else:
            if (
                maximum_level >= 9
                and not _state_has_blindness_recovery_reserve(
                    state,
                    required_purple_count=1,
                )
            ):
                return False
            chill_damage = maximum_level + 20 if maximum_level >= 6 else 0
            blindness_damage = (
                maximum_level // 2 + 10 if maximum_level >= 9 else 0
            )
            worst_special_damage = max(chill_damage, blindness_damage)
    elif specials == {"spec_guard"} and rejections == {
        "target has special procedure spec_guard"
    }:
        # special.c only makes a guard attack a normal player when the player
        # is already fighting. In combat it chooses headbutt, smash, or kick;
        # fight.c bounds the NPC headbutt at level/2 + 3*level, while smash
        # replaces a normal hit and kick is bounded below that value. Charge
        # only the headbutt's excess over one normal hit, since the special
        # pulse replaces that round's ordinary attack.
        headbutt_damage = maximum_level // 2 + maximum_level * 3
        normal_attack_count = 6 if maximum_level >= 20 else 5
        normal_hit_bound = candidate.estimated_peak_round_damage // normal_attack_count
        worst_special_damage = max(0, headbutt_damage - normal_hit_bound)
    elif specials == {"spec_warrior"} and rejections == {
        "target has special procedure spec_warrior"
    }:
        profile = source_special_profile("spec_warrior")
        if (
            candidate.mobile_vnum != 9510
            or candidate.room_vnum != 9523
            or source_world is None
            or not _vampire_catacombs_grok_source_shape_allowed(source_world)
            or profile.xp_bonus != 10
            or profile.risk != "moderate-combat"
            or profile.status_effects
            or not _state_has_sanctuary_reserve(state)
        ):
            return False
        loadout = single_weapon_loadout(
            candidate,
            source_world,
            allow_specials={"spec_warrior"},
        )
        if loadout is None:
            return False
        # Headbutt can critically double after sanctuary halves the damage, so
        # the protected bound keeps one full headbutt pulse rather than halving
        # it again. Grok has no shield, making his smash branch harmless.
        worst_special_damage = maximum_level // 2 + maximum_level * 3
        protected_incoming_peak_override = (
            (candidate.estimated_peak_round_damage + 1) // 2
            + worst_special_damage
        )
    elif specials == {"spec_vampire"} and rejections == {
        "target has special procedure spec_vampire"
    }:
        # special.c selects at most one bite or gaze per invocation.  The bite
        # is one_hit(gsn_suck): fight.c adds 50%, then up to 10% for high rage.
        # The gaze applies a two-pulse wait but adds no damage; violence_update
        # continues the ordinary combat round during that wait.  Admit only a
        # singleton, unarmed sentinel with an echo-only greeting program.
        profile = source_special_profile("spec_vampire")
        if (
            profile.risk != "combat-only"
            or profile.xp_bonus != 10
            or not _source_ranked_vampire_target_shape_allowed(
                candidate,
                source_world,
            )
        ):
            return False
        normal_hit_bound = _apply_mobile_damage_modifier(
            _mobile_normal_hit_damage(maximum_level, wielding=False),
            candidate.source_damage_modifier,
        )
        suck_damage = normal_hit_bound + normal_hit_bound // 2
        worst_special_damage = suck_damage + suck_damage // 10
    elif specials == {"spec_assassin"} and rejections == {
        "target has special procedure spec_assassin"
    }:
        # The source combat branch chooses dirt kick, trip, or circle.  Only
        # circle adds damage, and it is one ordinary NPC hit at most; dirt
        # kick is covered by the blindness reserve above.  An aggressive
        # assassin can backstab before consider, so keep that pre-entry case
        # research-gated even when its combat branch is otherwise bounded.
        if "target is aggressive" in set(candidate.hazards):
            return False
        normal_attack_count = 6 if maximum_level >= 20 else 5
        normal_hit_bound = (
            candidate.estimated_peak_round_damage + normal_attack_count - 1
        ) // normal_attack_count
        worst_special_damage = max(
            10,
            normal_hit_bound + normal_hit_bound // 2,
        )
    elif specials == {"spec_cast_psionicist"} and rejections == {
        "target has special procedure spec_cast_psionicist"
    }:
        # Below source level 14 the psionicist table can select mind thrust
        # or ego whip only. mind thrust is 1d10 + level/2; ego whip is a
        # hitroll/save debuff with no direct damage. Energy drain opens at
        # level 14 and disintegrate at level 35. Both remain hard research
        # boundaries: the player-side spell bypass is limited to Phoenix form
        # or a player-killer room; Crysomer lore is not a combat-code hook,
        # and ordinary resistance is not immunity.
        if maximum_level >= PSIONICIST_DISINTEGRATE_LEVEL:
            return False
        if maximum_level >= PSIONICIST_ENERGY_DRAIN_LEVEL:
            return False
        worst_special_damage = 10 + maximum_level // 2
    elif len(specials) == 1 and next(iter(specials)) not in ECONOMIC_SPECIALS:
        special = next(iter(specials))
        expected_rejection = {f"target has special procedure {special}"}
        # Source parsing intentionally omits an autonomy rejection for a
        # proven noncombat special. Accept both the modern empty form and the
        # legacy serialized form that retained a synthetic rejection.
        if rejections not in (set(), expected_rejection):
            return False
        profile = source_special_profile(special)
        if special in SAFE_NONCOMBAT_SPECIALS:
            # db.c assigns these procedures no XP bonus and special.c does
            # not issue a combat action against an ordinary player.
            if profile.xp_bonus != 0:
                return False
            worst_special_damage = 0
        elif special in WEAK_DEBILITATING_SPECIALS:
            # Poison is a withdrawal-triggering affect, not direct damage.
            # StarterBotRunner already recalls and waits for healer recovery
            # while the affect remains active.
            if profile.xp_bonus != 5:
                return False
            worst_special_damage = 0
        elif special in WEAK_EXTRA_ATTACK_SPECIALS:
            # These weak procedures issue one additional ordinary attack at
            # most. Bound that hit separately from the source round peak.
            if profile.xp_bonus != 5:
                return False
            normal_attack_count = 6 if maximum_level >= 20 else 5
            worst_special_damage = max(
                1,
                candidate.estimated_peak_round_damage
                // normal_attack_count,
            )
        elif special in WEAK_DIRECT_DAMAGE_SPECIALS:
            # special.c calls high explosive; magic.c bounds its damage at
            # six dice per caster level before saves.
            if profile.xp_bonus != 5:
                return False
            worst_special_damage = maximum_level * 6
        else:
            return False
    elif specials == {"spec_thief"} and rejections == {
        "target has special procedure spec_thief"
    }:
        # special.c returns before its theft branch unless the mobile is
        # standing, and the standing branch is skipped once it is fighting.
        # Its maximum theft is 20 percent of the player's carried coins;
        # keep that bounded resource loss explicit before entering the room.
        carried_coins = _state_copper_value(dict(state))
        if (
            carried_coins * 20 // 100
            > _SPEC_THIEF_MAX_EXPOSURE_COINS
        ):
            return False
        if source_special_profile("spec_thief").xp_bonus != 0:
            return False
        worst_special_damage = 0
    else:
        return False
    if character_max_hp is None or character_max_hp <= 0:
        return False
    sanctuary_bound_special = bool(
        specials & _SOURCE_SANCTUARY_SPECIALS
        or (
            specials == {"spec_cast_druid"}
            and maximum_level >= 15
        )
    )
    if protected_incoming_damage and not _state_has_sanctuary_reserve(state):
        return False
    if (
        sanctuary_bound_special
        and not _state_has_sanctuary_reserve(state)
        and not healer_blindness_recovery
    ):
        # The exact Caerlin carrier has a source-proven healer return path for
        # its cleric blind/curse branch.  It is the bounded Sanctuary source
        # being acquired, so requiring that same reserve before selection
        # would make the recovery route self-contradictory.
        return False
    if specials == {"spec_vampire"}:
        health_floor = math.ceil(character_max_hp * 0.20)
        current_hp = state.get("hp")
        if type(current_hp) is not int or current_hp <= health_floor:
            return False
    return True


def _interrupted_run_target_evidence(
    storage: RunStorage,
    run_id: int,
    candidate: HuntCandidate | Mapping[str, Any] | None,
) -> tuple[bool | None, bool | None]:
    """Recover target presence and consider evidence from a stopped run."""
    if candidate is None:
        return None, None
    def candidate_value(key: str, default: Any = None) -> Any:
        if isinstance(candidate, Mapping):
            return candidate.get(key, default)
        return getattr(candidate, key, default)

    expected_vnum = str(candidate_value("mobile_vnum") or "")
    target_identity = str(
        candidate_value("target_identity")
        or candidate_value("target_keyword")
        or candidate_value("target")
        or ""
    ).casefold()
    target_seen = False
    consider_viable: bool | None = None
    for event in storage.list_events(run_id):
        try:
            payload = json.loads(event["payload_json"])
        except (TypeError, json.JSONDecodeError):
            continue
        if event["kind"] == "game_event" and payload.get("type") == "enemies_changed":
            data = payload.get("data")
            values = data.get("value") if isinstance(data, Mapping) else None
            if isinstance(values, list):
                target_seen = target_seen or any(
                    isinstance(enemy, Mapping)
                    and (
                        not expected_vnum
                        or str(enemy.get("isnpc") or "") == expected_vnum
                    )
                    and (
                        not target_identity
                        or target_identity in str(enemy.get("name") or "").casefold()
                    )
                    for enemy in values
                )
        elif event["kind"] == "response":
            text = str(payload.get("text") or "").casefold()
            if target_identity and target_identity in text and "kill" in text:
                target_seen = True
            if "looks like an easy kill" in text:
                consider_viable = True
                target_seen = True
            elif consider_viable is None and (
                "looks like a difficult kill" in text
                or "would be a difficult kill" in text
                or "would be impossible" in text
            ):
                consider_viable = False
                target_seen = True
    return (True if target_seen else None), consider_viable


def _reconcile_interrupted_segment(
    storage: RunStorage,
    campaign_id: int,
    segment: Any,
    *,
    character_name: str,
    preserve_failure: bool = False,
) -> bool:
    """Reconcile a stopped segment with its best durable run evidence."""
    phase = str(segment["phase"] or "")
    ready_source_timeout = (
        segment["status"] == "ready"
        and _is_source_ranked_timeout_failure(segment["error"])
    )
    if segment["status"] != "failed" and not (
        segment["status"] == "ready"
        and (phase == "provision-funding" or ready_source_timeout)
    ):
        return False
    run = (
        storage.get_run(int(segment["run_id"]))
        if segment["run_id"] is not None
        else _run_for_failed_segment(
            storage,
            segment,
            character_name=character_name,
        )
    )
    if run is None:
        return False
    run_status = str(run["status"])
    if segment["status"] == "ready":
        try:
            existing_end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            existing_end_state = {}
        last_attempt = existing_end_state.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
        recovered_evidence = (
            last_attempt.get("recovery_evidence")
            if isinstance(last_attempt, Mapping)
            else None
        )
        if (
            isinstance(recovered_evidence, Mapping)
            and str(recovered_evidence.get("run_id") or "")
            == str(run["id"])
        ):
            return False
    segment_error = str(segment["error"] or "").casefold()
    completed_after_timeout = (
        run_status in {"ready", "success"}
        and "campaign runner exceeded" in segment_error
        and "outer cleanup grace" in segment_error
    )
    completed_linked_run = (
        segment["run_id"] is not None
        and run_status in {"ready", "success"}
        and bool(run["finished_at"])
    )
    if (
        run_status != "failed"
        and not completed_after_timeout
        and not completed_linked_run
    ):
        return False
    start_state = json.loads(segment["start_state_json"] or "{}")
    current_state = _run_latest_state(storage, int(run["id"]))
    if current_state is None:
        return False
    current_state = _campaign_failure_state_from_run(
        storage,
        int(run["id"]),
        current_state,
        character_name=character_name,
    )
    objective_kills = _objective_kills_for_execution(
        storage,
        int(run["id"]),
        execution=phase,
    ) or []
    end_state = _campaign_segment_end_state(
        start_state,
        current_state,
        execution=(
            "source-ranked-hunt"
            if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            else phase
        ),
        policy_id=phase if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX) else None,
    )
    end_state["campaign_policy_revision"] = _CAMPAIGN_POLICY_REVISION
    if phase == "provision-funding":
        end_state = _record_provision_funding_kills(
            end_state,
            objective_kills,
        )
        end_state.pop("campaign_completed_kills", None)
        end_state.pop("campaign_objective_kills", None)
        funding_evidence = _interrupted_provision_funding_evidence(
            storage,
            int(run["id"]),
            start_state=start_state,
            end_state=end_state,
            objective_kills=objective_kills,
        )
        if funding_evidence is not None:
            end_state = _record_provision_funding_attempt_details(
                end_state,
                candidate_key=str(funding_evidence["candidate_key"]),
                target=str(funding_evidence["target"]),
                room_vnum=int(funding_evidence["room_vnum"]),
                boot_id=start_state.get("world_boot_id"),
                completed_kill=True,
                character_level=int(funding_evidence["level"]),
                evidence=funding_evidence,
            )
            end_state = _apply_flight_funding_state_transition(
                start_state,
                end_state,
                execution=phase,
                funding_completed=True,
            )
    else:
        end_state["campaign_last_policy"] = phase
        end_state["campaign_completed_kills"] = objective_kills
        end_state["campaign_objective_kills"] = objective_kills

    if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        candidate = _source_ranked_candidate_from_record(
            start_state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            source_revision=start_state.get(_SOURCE_REVISION_KEY),
        )
        target_seen, consider_viable = _interrupted_run_target_evidence(
            storage,
            int(run["id"]),
            candidate,
        )
        if objective_kills:
            target_seen = True
            consider_viable = True
        target_evidence_incomplete = target_seen is None
        if target_evidence_incomplete:
            end_state.pop("campaign_fastwalk_target_present_observed", None)
            end_state.pop("campaign_fastwalk_target_absent", None)
            end_state.pop("campaign_fastwalk_consider_outcomes", None)
            end_state["campaign_fastwalk_abort_reason"] = (
                "field route interrupted before target evaluation"
            )
        else:
            end_state["campaign_fastwalk_target_present_observed"] = True
            end_state["campaign_fastwalk_target_absent"] = False
            end_state["campaign_fastwalk_consider_outcomes"] = (
                {
                    str(
                        (
                            candidate.get("target_identity")
                            if isinstance(candidate, Mapping)
                            else candidate.target_identity
                        )
                        or "target"
                    ): consider_viable
                }
                if candidate is not None and consider_viable is not None
                else {}
            )
            end_state["campaign_fastwalk_abort_reason"] = None
        policy = replace(
            _SOURCE_RANKED_HUNT_POLICY,
            policy_id=phase,
            minimum_level=_level(start_state),
            maximum_level=_level(start_state),
        )
        end_state = _merge_campaign_research_result(
            start_state,
            end_state,
            policy=policy,
            preserve_prior_result=target_evidence_incomplete,
        )
        end_state = _merge_protection_recovery_metadata(
            end_state,
            policy=policy,
            xp_delta=_xp_delta(start_state, end_state),
            previous=start_state,
            loss_event_id=int(segment["id"]),
        )
        interrupted_without_completion = str(segment["error"] or "").casefold() == (
            "previous campaign worker was interrupted before the next invocation"
        )
        if (
            (
                _is_source_ranked_timeout_failure(segment["error"])
                or interrupted_without_completion
            )
            and not (completed_after_timeout and objective_kills)
        ):
            end_state = _source_ranked_timeout_failure_state(
                end_state,
                policy_id=phase,
                error=str(segment["error"] or ""),
                objective_kill_count=len(objective_kills),
            )
        elif completed_after_timeout and objective_kills:
            end_state = _clear_source_ranked_timeout_after_productive_kill(
                end_state,
                objective_kills=objective_kills,
                xp_delta=_xp_delta(start_state, end_state),
            )

    run_id = int(run["id"])
    preserve_failure = (preserve_failure and not completed_after_timeout) or bool(
        end_state.get("dead")
        or str(end_state.get("area") or "").casefold() == "purgatory"
    )
    status = "failed" if preserve_failure else "ready"
    funding_evidence = (
        _interrupted_provision_funding_evidence(
            storage,
            run_id,
            start_state=start_state,
            end_state=current_state,
            objective_kills=objective_kills,
        )
        if phase == "provision-funding"
        else None
    )
    funding_metrics = (
        {
            "objective_scope": "campaign-provision-funding",
            "funding_only": True,
            **funding_evidence,
        }
        if funding_evidence is not None
        else None
    )
    storage.finish_campaign_segment(
        int(segment["id"]),
        status=status,
        run_id=run_id,
        end_state=end_state,
        command_count=storage.count_events(run_id, kind="command"),
        duration_seconds=_run_duration(run),
        error=segment["error"],
        objective_outcome=(
            "achieved" if funding_evidence is not None else None
        ),
        prefer_segment_objective_outcome=funding_evidence is not None,
        metrics=funding_metrics,
    )
    storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=run_id,
        phase=phase,
        reason=(
            "segment_completed_after_campaign_timeout"
            if completed_after_timeout
            else (
                "segment_interrupted_observed"
                if preserve_failure else "segment_interrupted_recovered"
            )
        ),
        state=end_state,
    )
    storage.finish_campaign(
        campaign_id,
        status=status,
        error=(
            str(segment["error"])
            if preserve_failure
            else (
                f"{phase} run {run_id} completed and was reconciled after the "
                "campaign runner deadline; its checkpoint is resumable."
                if completed_after_timeout
                else (
                    f"{phase} run {run_id} was reconciled after interruption; "
                    "its observed outcomes are retained."
                )
            )
        ),
    )
    return True


def _reconcile_orphaned_source_ranked_segment(
    storage: RunStorage,
    campaign_id: int,
    segment: Any,
) -> bool:
    """Rotate an unbound source route that stopped before a run was created."""
    phase = str(segment["phase"] or "")
    if not (
        segment["status"] == "failed"
        and phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and segment["run_id"] is None
        and segment["command_count"] in (None, 0)
    ):
        return False
    checkpoint = storage.get_latest_campaign_checkpoint(campaign_id)
    state = _checkpoint_state(checkpoint)
    if not state:
        return False
    state["campaign_last_policy"] = phase
    state["campaign_completed_kills"] = []
    state["campaign_objective_kills"] = []
    state["campaign_policy_revision"] = _CAMPAIGN_POLICY_REVISION
    state = _source_ranked_timeout_failure_state(
        state,
        policy_id=phase,
        error=str(segment["error"] or "source route stopped before live work"),
    )
    storage.finish_campaign_segment(
        int(segment["id"]),
        status="ready",
        run_id=None,
        end_state=state,
        command_count=None,
        duration_seconds=None,
        error=segment["error"],
    )
    checkpoint_id = storage.record_campaign_checkpoint(
        campaign_id,
        segment_id=int(segment["id"]),
        run_id=None,
        phase=phase,
        reason="segment_route_timeout",
        state=state,
    )
    storage.finish_campaign(
        campaign_id,
        status="ready",
        error=(
            f"{phase} orphaned route rotated from failed segment "
            f"{segment['id']} (checkpoint {checkpoint_id})."
        ),
    )
    return True


def _source_ranked_timeout_policy_ids(
    state: Mapping[str, Any],
) -> set[str]:
    """Return exact current-reboot routes deferred after an outer timeout."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return set()
    return {
        str(record["policy_id"])
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and record.get("level") in {None, level}
        and isinstance(record.get("policy_id"), str)
    }


def _source_ranked_timeout_revalidation_attempts(
    record: Mapping[str, Any],
) -> int:
    """Read the bounded retry count, including legacy one-shot markers."""
    try:
        attempts = int(
            record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD)
            or (
                1
                if record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                else 0
            )
        )
    except (TypeError, ValueError):
        attempts = 1 if record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) else 0
    return min(
        _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
        max(0, attempts),
    )


def _source_ranked_timeout_revalidation_exhausted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return False
    return any(
        isinstance(raw_record, Mapping)
        and raw_record.get("boot_id") == boot_id
        and raw_record.get("policy_id") == policy_id
        and _source_ranked_timeout_revalidation_attempts(raw_record)
        >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
        for raw_record in raw_records
    )


def _repair_recovered_source_interruption(
    state: Mapping[str, Any], segments: Collection[Mapping[str, Any]], *,
    storage: RunStorage,
) -> dict[str, Any]:
    """Attach actual recovery evidence without clearing the interrupted hunt."""
    updated = dict(state)
    records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if not isinstance(records, (list, tuple)):
        return updated

    def observed_number(value: Any) -> bool:
        return type(value) in (int, float) and math.isfinite(value)

    ordered = sorted((dict(row) for row in segments), key=lambda row: int(row["id"]))
    latest = {str(row["phase"]): row for row in ordered}
    repaired = []
    for raw in records:
        if not isinstance(raw, Mapping):
            continue
        record = dict(raw)
        repaired.append(record)
        if (
            record.get("boot_id") != state.get("world_boot_id")
            or record.get("level") != _level(state)
            or _source_ranked_timeout_revalidation_attempts(record) > 0
        ):
            continue
        record.pop("recovered_interruption", None)
        failed = latest.get(str(record.get("policy_id") or ""))
        if not failed or failed.get("error") not in {
            "previous campaign worker was interrupted before the next invocation",
            "database is locked",
        }:
            continue
        if not failed.get("run_id"):
            continue
        try:
            start = json.loads(failed["start_state_json"])
            failed_end = json.loads(failed["end_state_json"] or "{}")
        except (TypeError, ValueError):
            continue
        interrupted = _run_latest_state(storage, int(failed["run_id"])) or {}
        if not all(isinstance(value, Mapping) for value in (start, failed_end, interrupted)):
            continue
        if (
            start.get("world_boot_id") != state.get("world_boot_id")
            or _level(start) != _level(state)
            or _level(interrupted) != _level(state)
            or not all(observed_number(value) for value in (
                start.get("xp"), start.get("campaign_xp_loss_total"),
                interrupted.get("xp"), interrupted.get("hp"), interrupted.get("max_hp"),
            ))
            or interrupted["max_hp"] <= 0
            or _numeric_progress(dict(interrupted), "hp")
            < 0.75 * max(1, _numeric_progress(dict(interrupted), "max_hp"))
            or _xp_delta(start, interrupted) < 0
            or any(failed_end.get(key) or interrupted.get(key) for key in (
                "dead", "campaign_died_during_segment", "xp_loss_observed",
                "campaign_xp_loss_observed",
            ))
        ):
            continue
        for recovery in ordered:
            if (
                recovery["id"] <= failed["id"] or recovery["phase"] != "return-home"
                or recovery["status"] != "success" or not recovery.get("run_id")
            ):
                continue
            try:
                end = json.loads(recovery["end_state_json"] or "{}")
            except (TypeError, ValueError):
                continue
            observed = _run_latest_state(storage, int(recovery["run_id"])) or {}
            if not isinstance(end, Mapping) or not isinstance(observed, Mapping):
                continue
            recovery_room_flags = end.get("room_flags")
            recovered_healer_boundary = bool(
                str(end.get("room_vnum") or "") == "3054"
                and isinstance(recovery_room_flags, (list, tuple, set, frozenset))
                and {"safe", "no_mob"}.issubset(
                    {str(flag).casefold() for flag in recovery_room_flags}
                )
                and observed.get("in_combat") is False
            )
            enemy_snapshot_clear = bool(
                "enemies" in observed
                and _enemy_snapshot_empty(observed["enemies"])
            )
            if (
                end.get("world_boot_id") != state.get("world_boot_id")
                or not all(observed_number(observed.get(key)) for key in ("xp", "hp"))
                or _level(end) != _level(state) or _level(observed) != _level(state)
                or str(observed.get("room_vnum")) != "3054"
                or not (enemy_snapshot_clear or recovered_healer_boundary)
                or observed.get("in_combat") is not False
                or observed.get("dead") is not False
                or observed.get("position") not in {4, 5, 7}
                or _numeric_progress(dict(observed), "hp") <= 0
                or _xp_delta(start, observed) < 0
                or end.get("campaign_xp_loss_total") != start.get("campaign_xp_loss_total")
                or end.get("campaign_fastwalk_abort_reason")
                or any(end.get(key) or observed.get(key) for key in (
                    "dead", "campaign_died_during_segment", "xp_loss_observed",
                    "campaign_xp_loss_observed",
                ))
            ):
                continue
            record["recovered_interruption"] = {
                "interrupted_run_id": failed["run_id"],
                "recovery_run_id": recovery["run_id"],
                "boot_id": state.get("world_boot_id"),
                "level": _level(state),
                "source_revision": state.get(_SOURCE_REVISION_KEY),
                "reason": "later live healer recovery without observed XP loss",
            }
            break
    updated[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = repaired
    return updated


def _source_ranked_recovered_interruption_candidate(
    candidate: HuntCandidate, state: Mapping[str, Any], *, character_level: int,
) -> bool:
    """Extend the existing one-shot retry only to bounded, plain population research."""
    policy_id = _source_ranked_policy_id(candidate, character_level=character_level)
    if (
        not _source_ranked_capacity_research_candidate(candidate, character_level=character_level)
        or candidate.equipped_weapons or candidate.specials
        or _source_ranked_xp_loss_record(state, policy_id) is not None
    ):
        return False
    records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if not isinstance(records, (list, tuple)):
        return False
    for record in records:
        if not isinstance(record, Mapping):
            continue
        proof = record.get("recovered_interruption")
        if (
            record.get("boot_id") == state.get("world_boot_id")
            and record.get("level") == character_level and record.get("policy_id") == policy_id
            and isinstance(proof, Mapping)
            and type(proof.get("interrupted_run_id")) is int
            and type(proof.get("recovery_run_id")) is int
            and 0 < proof["interrupted_run_id"] < proof["recovery_run_id"]
        ):
            attempts = _source_ranked_timeout_revalidation_attempts(record)
            return attempts == 0 or (
                attempts == 1 and state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) == policy_id
            )
    return False


def _source_ranked_timeout_revalidation_candidate(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None = None,
    source_policy_latest_xp: Mapping[str, int] | None = None,
    character_max_hp: int | None = None,
) -> HuntCandidate | None:
    """Find one safe route whose only current block is an old timeout.

    A bounded worker timeout can happen after a route spends its budget on
    navigation, before the target is ever evaluated. Reopen one such route
    once when the current source catalog still proves it is a special-free,
    current-band hunt. A route past the ordinary kill-count cap also needs a
    meaningful same-boot kill from that exact policy before its one retry.
    All live research evidence remains authoritative.
    """
    if state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY):
        return None
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return None
    recovered_policy_ids = {
        _source_ranked_policy_id(candidate, character_level=character_level)
        for candidate in candidates
        if _source_ranked_recovered_interruption_candidate(
            candidate, state, character_level=character_level,
        )
    }
    recovered_route_policy_ids: set[str] = set()
    current_healer_recovery = bool(
        _is_safe_healer_checkpoint(state)
        and not state.get("xp_loss_observed")
        and not state.get("campaign_xp_loss_observed")
        and not state.get("campaign_died_during_segment")
        and not state.get("dead")
        and not state.get("in_combat")
    )
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        proof = raw_record.get("recovered_interruption")
        policy_id = raw_record.get("policy_id")
        if (
            raw_record.get("boot_id") != boot_id
            or raw_record.get("level") != character_level
            or raw_record.get("reason")
            != "previous campaign worker was interrupted before the next invocation"
            or raw_record.get("objective_kill_count") != 0
            or _source_ranked_timeout_revalidation_attempts(raw_record) != 0
            or not isinstance(policy_id, str)
            or not isinstance(proof, Mapping)
            or proof.get("boot_id") != boot_id
            or proof.get("level") != character_level
            or proof.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
            or proof.get("reason")
            != "later live healer recovery without observed XP loss"
            or type(proof.get("interrupted_run_id")) is not int
            or type(proof.get("recovery_run_id")) is not int
            or proof["recovery_run_id"] <= proof["interrupted_run_id"]
        ):
            continue
        recovered_route_policy_ids.add(policy_id)
    eligible_policy_ids: set[str] = set()
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        if raw_record.get("boot_id") != boot_id:
            continue
        if raw_record.get("level") not in {None, character_level}:
            continue
        policy_id = raw_record.get("policy_id")
        if not isinstance(policy_id, str):
            continue
        if (
            _source_ranked_timeout_revalidation_attempts(raw_record)
            >= _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS
        ):
            continue
        if raw_record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) is True:
            continue
        try:
            objective_kill_count = int(
                raw_record.get("objective_kill_count") or 0
            )
        except (TypeError, ValueError):
            objective_kill_count = 1
        if objective_kill_count > 0:
            continue
        reason = str(raw_record.get("reason") or "")
        if not (
            reason == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD
            or _is_source_ranked_timeout_failure(reason)
            or policy_id in recovered_policy_ids
            or policy_id in recovered_route_policy_ids
            or (
                reason
                == "previous campaign worker was interrupted before the next invocation"
                and current_healer_recovery
            )
        ):
            continue
        eligible_policy_ids.add(policy_id)
    if not eligible_policy_ids:
        return None

    choices: list[HuntCandidate] = []
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if policy_id not in eligible_policy_ids:
            continue
        recovered_capacity = _source_ranked_recovered_interruption_candidate(
            candidate, state, character_level=character_level,
        )
        familiar_probe = bool(
            source_world is not None
            and _source_ranked_familiar_probe_allowed(
                candidate,
                state,
                character_level=character_level,
                source_world=source_world,
            )
        )
        if not (
            candidate.autonomous_safe or recovered_capacity or familiar_probe
        ):
            continue
        if candidate.specials and not (
            source_world is not None
            and _source_ranked_aggressive_special_output_allowed(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                source_world=source_world,
            )
        ):
            continue
        if _source_ranked_candidate_excluded_by_below_band_evidence(
            candidate,
            state,
            character_level=character_level,
        ):
            continue
        runtime_boundary_result = _source_ranked_runtime_boundary_result(
            state,
            policy_id,
        )
        runtime_boundary_consider_result = (
            _source_ranked_runtime_boundary_consider_result(
                state,
                policy_id,
            )
        )
        try:
            previous_policy_xp = int(
                (source_policy_latest_xp or {}).get(policy_id, 0) or 0
            )
        except (TypeError, ValueError):
            previous_policy_xp = 0
        productive_timeout_repeat = bool(
            candidate.boot_kills >= 3
            and (
                runtime_boundary_result
                or (
                    policy_id in recovered_route_policy_ids
                    and runtime_boundary_consider_result
                )
            )
            and previous_policy_xp
            >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        )
        if not (_source_ranked_candidate_in_current_band(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            allow_repeated_kills=productive_timeout_repeat,
        ) or (recovered_capacity and _source_ranked_capacity_research_in_current_band(
            candidate, state, character_level=character_level,
        ))):
            continue
        result_status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        if result_status != "fresh" and not (
            (
                runtime_boundary_result
                or runtime_boundary_consider_result
            )
            and result_status in {"cooldown", "retryable"}
        ):
            continue
        # Temporarily remove only this timeout marker while checking the
        # remaining protection gates. Sanctuary, XP-loss, and route-hazard
        # requirements must still reject the candidate.
        probe_state = dict(state)
        probe_records = [
            dict(raw_record)
            for raw_record in raw_records
            if not (
                isinstance(raw_record, Mapping)
                and raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            )
        ]
        if probe_records:
            probe_state[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = probe_records
        else:
            probe_state.pop(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, None)
        probe_state[_SOURCE_RANKED_REVALIDATION_POLICY_KEY] = policy_id
        if _source_ranked_candidate_blocked_by_protection_recovery(
            candidate,
            probe_state,
            character_level=character_level,
            source_world=source_world,
        ):
            continue
        choices.append(candidate)
    if not choices:
        return None
    return max(
        choices,
        key=lambda candidate: (
            float(candidate.estimated_level_range[1]),
            candidate.score,
            -len(candidate.route),
            candidate.source_value,
        ),
    )


def _mark_source_ranked_timeout_revalidation(
    state: dict[str, Any],
    *,
    policy_id: str,
) -> None:
    """Consume one bounded timeout revalidation before live work starts."""
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return
    records: list[dict[str, Any]] = []
    marked = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if (
            record.get("boot_id") == boot_id
            and record.get("policy_id") == policy_id
        ):
            attempts = _source_ranked_timeout_revalidation_attempts(record)
            record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
                _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
                max(0, attempts) + 1,
            )
            record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD] = True
            marked = True
        records.append(record)
    if marked:
        state[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]


def _rearm_source_ranked_timeout_revalidation_after_reset(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Allow one final timeout retry after an automatic reset wait.

    A reset wait is the only continuation that may consume reboot-local route
    evidence. Keep the retry bounded: a route that times out twice remains
    quarantined for this reboot.
    """
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return dict(state)
    records: list[dict[str, Any]] = []
    changed = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if (
            record.get("boot_id") == boot_id
            and record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) is True
        ):
            attempts = _source_ranked_timeout_revalidation_attempts(record)
            if attempts <= 0:
                attempts = 1
            if attempts < _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS:
                record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
                    _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
                    max(1, attempts),
                )
                record.pop(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD, None)
                changed = True
        records.append(record)
    if not changed:
        return dict(state)
    rearmed = dict(state)
    rearmed[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]
    rearmed.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
    return rearmed


def _repair_source_ranked_timeout_history(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Restore reboot-local route quarantine lost by an older selector."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    if boot_id is None or level <= 0:
        return dict(state)

    def segment_order(segment: Mapping[str, Any], fallback: int) -> tuple[int, int]:
        for key in ("sequence", "id"):
            try:
                return (0, int(segment.get(key)))
            except (AttributeError, TypeError, ValueError):
                continue
        return (1, fallback)

    ordered_segments = tuple(
        segment
        for _order, segment in sorted(
            (
                (segment_order(dict(segment), index), dict(segment))
                for index, segment in enumerate(campaign_segments)
            ),
            key=lambda item: item[0],
        )
    )
    updated = dict(state)
    timeout_policy_ids = _source_ranked_timeout_policy_ids(updated)
    # A timeout can be recorded before its bounded revalidation completes.
    # If a later segment produced a safe source-matched kill, the positive
    # result is stronger evidence and must clear only the matching marker.
    # Older productive kills do not clear a newer timeout for the same route.
    timeout_orders: dict[str, int] = {}
    timeout_reasons: dict[str, str] = {}
    productive_orders: dict[str, int] = {}
    for order, segment in enumerate(ordered_segments):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (KeyError, TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start_state, Mapping) or not isinstance(
            end_state, Mapping
        ):
            continue
        if end_state.get("world_boot_id") != boot_id:
            continue
        objective_kills = _segment_objective_kills(None, segment)
        killed_policy_ids = _source_ranked_kill_policy_ids(objective_kills)
        if killed_policy_ids and _xp_delta(start_state, end_state) >= 0 and not any(
            end_state.get(key)
            for key in (
                "dead",
                "campaign_died_during_segment",
                "xp_loss_observed",
                "campaign_xp_loss_observed",
            )
        ):
            for policy_id in killed_policy_ids:
                productive_orders[policy_id] = order

        error = str(segment.get("error") or "")
        end_timeout_policy = str(
            end_state.get("campaign_source_ranked_timeout_policy") or ""
        )
        end_timeout_reason = str(
            end_state.get("campaign_source_ranked_timeout_reason") or ""
        )
        interrupted_without_completion = error.casefold() == (
            "previous campaign worker was interrupted before the next invocation"
        )
        error_is_timeout = (
            _is_source_ranked_timeout_failure(error)
            or error == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD
            or interrupted_without_completion
        )
        end_reason_is_timeout = (
            _is_source_ranked_timeout_failure(end_timeout_reason)
            or end_timeout_reason == _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD
        )
        timeout_reason = (
            error
            if error_is_timeout
            else end_timeout_reason
            if end_timeout_policy == phase
            and end_reason_is_timeout
            else ""
        )
        if (
            not timeout_reason
            or objective_kills
            or end_state.get("world_boot_id") != boot_id
            or _level(end_state) != level
        ):
            continue
        timeout_orders[phase] = order
        timeout_reasons[phase] = timeout_reason

    raw_records = updated.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    clear_policy_ids: set[str] = set()
    if isinstance(raw_records, (list, tuple)):
        for record in raw_records:
            if not isinstance(record, Mapping) or record.get("boot_id") != boot_id:
                continue
            policy_id = str(record.get("policy_id") or "")
            if not policy_id:
                continue
            timeout_order = timeout_orders.get(policy_id)
            productive_order = productive_orders.get(policy_id)
            if productive_order is not None and (
                timeout_order is None or productive_order > timeout_order
            ):
                clear_policy_ids.add(policy_id)
    if clear_policy_ids and isinstance(raw_records, (list, tuple)):
        retained = [
            dict(record)
            for record in raw_records
            if not (
                isinstance(record, Mapping)
                and record.get("boot_id") == boot_id
                and record.get("policy_id") in clear_policy_ids
            )
        ]
        if retained:
            updated[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = retained
        else:
            updated.pop(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, None)
        if updated.get("campaign_source_ranked_timeout_policy") in clear_policy_ids:
            updated.pop("campaign_source_ranked_timeout_policy", None)
            updated.pop("campaign_source_ranked_timeout_reason", None)
        timeout_policy_ids = _source_ranked_timeout_policy_ids(updated)

    # Restore markers that were lost by an older checkpoint writer. A prior
    # positive kill must not suppress a later timeout for the same policy.
    for policy_id, timeout_order in timeout_orders.items():
        if policy_id in timeout_policy_ids:
            continue
        productive_order = productive_orders.get(policy_id)
        if productive_order is not None and productive_order > timeout_order:
            continue
        updated = _remember_source_ranked_timeout(
            updated,
            policy_id=policy_id,
            level=level,
            boot_id=boot_id,
            reason=timeout_reasons[policy_id],
        )
        timeout_policy_ids.add(policy_id)
    revalidation_policy_id = str(
        updated.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or ""
    )
    if revalidation_policy_id and _source_ranked_timeout_revalidation_exhausted(
        updated,
        revalidation_policy_id,
    ):
        updated.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
    return updated


def _repair_source_ranked_partial_timeout_retry(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover one clean partial-timeout retry from durable segment history."""
    existing = state.get(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == state.get("world_boot_id")
        and existing.get("level") in {None, _level(state)}
    ):
        if existing.get("attempted") is True:
            policy_id = str(existing.get("policy_id") or "")
            for raw_segment in reversed(campaign_segments):
                segment = dict(raw_segment)
                if str(segment.get("phase") or "") != policy_id:
                    continue
                try:
                    start = json.loads(
                        segment.get("start_state_json") or "{}"
                    )
                    end = json.loads(segment.get("end_state_json") or "{}")
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
                if not isinstance(start, Mapping) or not isinstance(
                    end, Mapping
                ):
                    continue
                start_marker = start.get(
                    _SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY
                )
                abort_reason = str(
                    end.get("campaign_fastwalk_abort_reason") or ""
                )
                if not (
                    isinstance(start_marker, Mapping)
                    and start_marker.get("attempted") is True
                    and start_marker.get("policy_id") == policy_id
                    and start.get("world_boot_id")
                    == state.get("world_boot_id")
                    and end.get("world_boot_id") == state.get("world_boot_id")
                    and _level(start) == _level(state)
                    and _level(end) == _level(state)
                    and not _segment_objective_kills(None, segment)
                    and _FIELD_REQUIRED_SANCTUARY_ABORT_FRAGMENT
                    in abort_reason
                ):
                    continue
                repaired = dict(state)
                repaired[_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY] = {
                    **dict(existing),
                    "attempted": False,
                    "rearmed_after_segment_id": segment.get("id"),
                }
                return repaired
        return dict(state)
    boot_id = state.get("world_boot_id")
    character_level = _level(state)
    if boot_id is None or character_level <= 0:
        return dict(state)
    for raw_segment in reversed(campaign_segments):
        segment = dict(raw_segment)
        phase = str(segment.get("phase") or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if (
            start.get("world_boot_id") != boot_id
            or end.get("world_boot_id") != boot_id
            or _level(start) != character_level
            or _level(end) != character_level
            or _segment_objective_kills(None, segment)
        ):
            continue
        policy = ProgressionPolicy(
            policy_id=phase,
            minimum_level=character_level,
            maximum_level=character_level,
            status="research",
            execution="source-ranked-hunt",
            summary="recovered partial-timeout retry",
            evidence=(),
            practice_skill=None,
        )
        record = _source_ranked_partial_timeout_retry_record(
            start,
            end,
            policy=policy,
            xp_delta=_xp_delta(start, end),
            loss_event_id=segment.get("id"),
        )
        if record is not None:
            repaired = dict(state)
            repaired[_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY] = record
            return repaired
    return dict(state)


def _source_ranked_candidate_blocked_by_timeout(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Defer one timed-out route until another source route gets a turn."""
    return (
        _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        in _source_ranked_timeout_policy_ids(state)
    )


def _remember_source_ranked_timeout(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    reason: str,
    objective_kill_count: int = 0,
) -> dict[str, Any]:
    """Persist a route timeout without treating productive work as unsafe."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) or boot_id is None:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    records: list[dict[str, Any]] = []
    revalidation_attempted = False
    revalidation_attempts = 0
    if isinstance(raw_records, (list, tuple)):
        for raw_record in raw_records:
            if not isinstance(raw_record, Mapping):
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
                and raw_record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD)
                is True
            ):
                revalidation_attempted = True
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            ):
                revalidation_attempts = max(
                    revalidation_attempts,
                    _source_ranked_timeout_revalidation_attempts(raw_record),
                )
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") != policy_id
            ):
                records.append(dict(raw_record))
    record = {
            "boot_id": boot_id,
            "level": level,
            "policy_id": policy_id,
            "reason": reason,
            "objective_kill_count": max(0, int(objective_kill_count)),
        }
    if revalidation_attempted:
        record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD] = True
    if revalidation_attempts:
        record[_SOURCE_RANKED_TIMEOUT_REVALIDATION_COUNT_FIELD] = min(
            _SOURCE_RANKED_TIMEOUT_REVALIDATION_MAX_ATTEMPTS,
            revalidation_attempts,
        )
    records.append(record)
    updated = dict(state)
    updated[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = records[-64:]
    return updated


def _source_ranked_timeout_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
    objective_kill_count: int = 0,
) -> dict[str, Any]:
    """Record an outer-cap result and force one source-route rotation."""
    updated = _remember_source_ranked_timeout(
        state,
        policy_id=policy_id,
        level=_level(state),
        boot_id=state.get("world_boot_id"),
        reason=error,
        objective_kill_count=objective_kill_count,
    )
    updated["campaign_source_ranked_timeout_policy"] = policy_id
    updated["campaign_source_ranked_timeout_reason"] = error
    return updated


def _clear_source_ranked_timeout_after_productive_kill(
    state: Mapping[str, Any],
    *,
    objective_kills: Collection[Any],
    xp_delta: int,
) -> dict[str, Any]:
    """Clear stale timeout quarantine after a confirmed safe objective kill.

    A timeout revalidation can later finish with a real source kill. Keeping
    that same policy's old timeout marker would quarantine the route forever,
    even though the successful segment is the stronger evidence. Do not clear
    the marker when the segment lost XP, died, or has no source-policy-matched
    objective kill; those outcomes still need their existing recovery gates.
    """
    if not objective_kills or xp_delta < 0:
        return dict(state)
    if any(
        state.get(key)
        for key in (
            "dead",
            "campaign_died_during_segment",
            "xp_loss_observed",
            "campaign_xp_loss_observed",
        )
    ):
        return dict(state)
    killed_policy_ids = set(_source_ranked_kill_policy_ids(objective_kills))
    if not killed_policy_ids:
        return dict(state)
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return dict(state)
    retained = [
        dict(record)
        for record in raw_records
        if not (
            isinstance(record, Mapping)
            and record.get("boot_id") == boot_id
            and record.get("policy_id") in killed_policy_ids
        )
    ]
    if len(retained) == len(raw_records):
        return dict(state)
    updated = dict(state)
    if retained:
        updated[_SOURCE_RANKED_TIMEOUT_POLICIES_KEY] = retained
    else:
        updated.pop(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY, None)
    if updated.get("campaign_source_ranked_timeout_policy") in killed_policy_ids:
        updated.pop("campaign_source_ranked_timeout_policy", None)
        updated.pop("campaign_source_ranked_timeout_reason", None)
    return updated


def _source_ranked_protection_recovery_fallback_active(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    character_level: int,
) -> bool:
    """Return whether a selected hunt carries the elevated fallback gate."""
    marker = state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    return bool(
        isinstance(marker, Mapping)
        and isinstance(protection, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and protection.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and protection.get("level") in {None, character_level}
        and str(marker.get("policy_id") or "") == policy_id
    )


def _source_ranked_protection_recovery_fallback_attempted_policy_ids(
    marker: Mapping[str, Any] | None,
) -> frozenset[str]:
    """Read distinct fallback probes, including the legacy one-shot marker."""
    if not isinstance(marker, Mapping):
        return frozenset()
    attempted: set[str] = set()
    raw_policy_ids = marker.get("attempted_policy_ids")
    if isinstance(raw_policy_ids, (list, tuple, set, frozenset)):
        attempted.update(
            str(policy_id)
            for policy_id in raw_policy_ids
            if policy_id
        )
    if marker.get("attempted") is True:
        policy_id = str(marker.get("policy_id") or "")
        if policy_id:
            attempted.add(policy_id)
    return frozenset(attempted)


def _source_locator_event_policy_ids(state: Mapping[str, Any]) -> frozenset[str]:
    """Return bounded prior locators whose event evidence can arm one retry."""
    fallback_ids = _source_ranked_protection_recovery_fallback_attempted_policy_ids(
        state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    )
    policy_ids = (
        set(fallback_ids)
        if len(fallback_ids) <= _PROTECTION_RECOVERY_ORDINARY_FALLBACK_MAX_PROBES
        else set()
    )
    ground_probe = state.get(_FLIGHT_FUNDING_GROUND_PROBE_KEY)
    if (
        isinstance(ground_probe, Mapping)
        and ground_probe.get("boot_id") == state.get("world_boot_id")
        and ground_probe.get("level") == _level(state)
        and ground_probe.get("policy_id")
    ):
        policy_ids.add(str(ground_probe["policy_id"]))
    return frozenset(policy_ids)


def _source_ranked_protection_recovery_loss_count(
    state: Mapping[str, Any],
    protection: Mapping[str, Any],
) -> int | None:
    """Return the reboot-local loss count behind a protection marker.

    Older checkpoints carried only the protection marker, whose presence
    implies one loss. Newer checkpoints also retain an exact loss-ledger
    record. Keep the legacy interpretation here so the second-loss exception
    below cannot accidentally reopen a malformed or unrelated marker.
    """
    protection_policy_id = str(protection.get("policy_id") or "")
    loss_record = _source_ranked_xp_loss_record(state, protection_policy_id)
    if (
        loss_record is not None
        and loss_record.get("source_revision") is not None
        and state.get(_SOURCE_REVISION_KEY) is not None
        and loss_record.get("source_revision") != state.get(_SOURCE_REVISION_KEY)
    ):
        # A protection marker can survive source refreshes, but an old
        # source-specific loss row must not overwrite its newer accumulated
        # count and reopen a terminal recovery loop.
        loss_record = None
    record_count = (
        _source_ranked_xp_loss_count(loss_record)
        if loss_record is not None
        else None
    )
    raw_loss_count = protection.get("loss_count")
    if raw_loss_count is None:
        return record_count if record_count is not None else 1
    try:
        marker_count = int(raw_loss_count)
    except (TypeError, ValueError):
        marker_count = None
    if marker_count is None:
        return record_count
    if record_count is None:
        return marker_count
    return max(marker_count, record_count)


def _source_ranked_terminal_sanctuary_failure(
    state: Mapping[str, Any],
) -> bool:
    """Return whether exhausted Sanctuary recovery permits one plain fallback."""
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(protection, Mapping):
        return False
    loss_count = _source_ranked_protection_recovery_loss_count(
        state,
        protection,
    )
    return bool(
        loss_count is not None
        and loss_count >= 3
        and _research_fatal_failure_active(
            state,
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
        )
    )


def _source_locator_revalidation_pending(state: Mapping[str, Any], policy_id: str) -> bool:
    entries = state.get(_SOURCE_LOCATOR_REVALIDATIONS_KEY)
    record = entries.get(policy_id) if isinstance(entries, Mapping) else None
    return bool(
        isinstance(record, Mapping) and record.get("status") == "pending"
        and record.get("boot_id") == state.get("world_boot_id")
        and record.get("level") == _level(state)
        and record.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and policy_id not in _source_ranked_timeout_policy_ids(state)
        and _source_ranked_xp_loss_record(state, policy_id) is None
    )


def _consume_source_locator_revalidation(state: dict[str, Any], policy_id: str) -> None:
    if _source_locator_revalidation_pending(state, policy_id):
        entries = dict(state[_SOURCE_LOCATOR_REVALIDATIONS_KEY])
        entries[policy_id] = {**entries[policy_id], "status": "consumed"}
        state[_SOURCE_LOCATOR_REVALIDATIONS_KEY] = entries


def _offer_source_locator_revalidations(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    world: WorldSource,
    segments: Collection[Mapping[str, Any]],
    run_events: Mapping[int, Collection[Mapping[str, Any]]],
) -> None:
    """Offer one expanded search without deleting the old fallback attempt."""
    fallback = state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    if isinstance(fallback, Mapping) and fallback.get("failed"):
        return
    level = _level(state)
    boot = str(state.get("world_boot_id") or "")
    if not boot:
        return
    attempted = set(
        _source_ranked_protection_recovery_fallback_attempted_policy_ids(
            fallback
        )
    )
    ground_probe = state.get(_FLIGHT_FUNDING_GROUND_PROBE_KEY)
    ground_probe_policy_id = ""
    if (
        isinstance(ground_probe, Mapping)
        and ground_probe.get("boot_id") == boot
        and ground_probe.get("level") == level
    ):
        ground_probe_policy_id = str(ground_probe.get("policy_id") or "")
        if ground_probe_policy_id:
            attempted.add(ground_probe_policy_id)
    if isinstance(fallback, Mapping) and (
        fallback.get("boot_id") != boot or fallback.get("level") != level
    ):
        attempted.difference_update(
            _source_ranked_protection_recovery_fallback_attempted_policy_ids(
                fallback
            )
        )
    if not attempted:
        return
    latest = {
        str(row["phase"]): row
        for row in sorted(segments, key=lambda item: int(item["sequence"]))
        if str(row["phase"]) in attempted
    }
    entries = dict(state.get(_SOURCE_LOCATOR_REVALIDATIONS_KEY) or {})
    for policy_id, record in tuple(entries.items()):
        if isinstance(record, Mapping) and record.get("status") == "pending":
            row = latest.get(policy_id)
            if row is None or row["id"] != record.get("segment_id"):
                entries[policy_id] = {**record, "status": "consumed"}
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(candidate, character_level=level)
        existing = entries.get(policy_id)
        ground_probe_miss = policy_id == ground_probe_policy_id
        if (
            policy_id not in attempted
            or isinstance(existing, Mapping) and existing.get("boot_id") == boot
            or policy_id not in latest
            or _source_ranked_xp_loss_record(state, policy_id) is not None
            or policy_id in _source_ranked_timeout_policy_ids(state)
            or (
                _source_ranked_result_status(
                    candidate,
                    state,
                    character_level=level,
                )
                != "fresh"
                and not (
                    ground_probe_miss
                    and _campaign_research_results(state)
                    .get(policy_id, {})
                    .get("absent") is True
                )
            )
        ):
            continue
        mobile = world.mobiles.get(candidate.mobile_vnum)
        if mobile is None or not mobile.wanders or mobile.stay_area or mobile.confused:
            continue
        row = latest[policy_id]
        evidence = single_area_locator_miss(
            row, run_events.get(int(row["run_id"] or 0), ()), boot_id=boot, level=level,
            keyword=candidate.target_keyword, reset_room=candidate.room_vnum,
        )
        if evidence is None:
            continue
        stops = _source_ranked_hunt_stops(
            candidate,
            world,
            character_level=level,
            state=state,
        )
        locator = stops[0] if stops else None
        if locator is None:
            continue
        if ground_probe_miss:
            if not locator.continue_after_where_absent or len(stops) < 2:
                continue
        elif not locator.where_neighbor_route_vnums:
            continue
        entries[policy_id] = {
            **evidence, "status": "pending", "source_revision": state.get(_SOURCE_REVISION_KEY),
            "neighbor_area_file": locator.where_neighbor_area_file,
            "neighbor_route_vnums": list(locator.where_neighbor_route_vnums),
            "room_sweep_vnums": [
                str(stop.route_vnums[-1])
                for stop in stops[1:]
                if stop.route_vnums
            ],
            "reason": (
                "one expanded global-wanderer room search after a saved "
                "noncombat funding-ground-probe miss"
                if ground_probe_miss
                else "one expanded locator search after an expired noncombat single-area miss"
            ),
        }
    if entries:
        state[_SOURCE_LOCATOR_REVALIDATIONS_KEY] = entries


def _source_ranked_flight_purchase_ready_for_fallback(
    state: Mapping[str, Any],
    *,
    source_world: WorldSource | None,
) -> bool:
    """Keep a flight-only fallback visible until its healer purchase runs."""
    if source_world is None:
        return False
    if str(state.get("room_vnum") or "") != "3054":
        return False
    if state.get("dead") or state.get("in_combat"):
        return False
    if state.get("magic_shop_purchase_failed") is True:
        return False
    if state.get(_SHOP_REARM_REPUTATION_BLOCKED_KEY) is True:
        return False
    if int(state.get(_FLIGHT_PURCHASE_COOLDOWN_KEY) or 0) > 0:
        return False
    if _state_copper_value(dict(state)) < _flight_purchase_minimum(dict(state)):
        return False
    if not state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY):
        return True
    transit = state.get(CITY_TRANSIT_KEY)
    return bool(
        isinstance(transit, Mapping)
        and transit.get("status") == "admitted"
        and bounded_city_shop_transit_available(source_world, state)
    )


def _source_ranked_terminal_no_reserve_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Keep ordinary source hunts open after Sanctuary recovery is exhausted.

    A terminal Sanctuary result is a resource failure, not proof that the
    current-band frontier is empty. Reopen only a source-identified singleton
    with a plain, non-scripted endpoint and no hard route hazard. The normal
    selector still applies route, status, current-band, crowd, live-consider,
    and combat-health gates; this helper only prevents the recovery branch from
    hiding otherwise ordinary candidates.
    """
    if source_world is None or _state_has_sanctuary_reserve(state):
        return False
    if candidate.is_coin_stash or candidate.status == "reject":
        return False
    if (
        candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.specials
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or candidate.requires_detect_invisibility
        or candidate.requires_water_breathing
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if mobile is None:
        return False
    if (
        mobile.aggressive
        or mobile.programs
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or candidate.mobile_vnum in source_world.shopkeepers
        or source_world.mobile_specials.get(candidate.mobile_vnum)
    ):
        return False
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float))
        and not isinstance(raw_max_hp, bool)
        and raw_max_hp > 0
        else None
    )
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    return bool(
        0 < minimum_level <= maximum_level
        and maximum_level > character_level - 5
        and minimum_level <= character_level + 5
    )


def _source_ranked_terminal_fresh_plain_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Keep a fresh bounded plain population in the XP frontier.

    This is separate from the singleton receipt above: a passive, plain
    reset with a bounded source population can still be a useful live
    consider probe after Sanctuary recovery is terminal. Current absence,
    crowd, loss, route and live isolation checks remain authoritative.
    """
    if (
        source_world is None
        or _state_has_sanctuary_reserve(state)
        or not _source_ranked_terminal_sanctuary_failure(state)
        or candidate.is_coin_stash
        or candidate.status == "reject"
        or not candidate.autonomous_safe
        or not candidate.target_selection_safe
        or candidate.autonomy_rejections
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.requires_detect_invisibility
        or candidate.requires_water_breathing
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or not (
            (
                candidate.source_spawn_limit == 1
                and candidate.room_spawn_count == 1
            )
            or plain_bounded_population(candidate, source_world)
            or (
                plain_bounded_mobile_population(
                    candidate.mobile_vnum,
                    source_world,
                )
                and candidate.source_spawn_limit in {2, 3, 4}
                and candidate.room_spawn_count == 1
            )
        )
        or _source_ranked_candidate_has_absence_cooldown(
            candidate,
            state,
            character_level=character_level,
        )
        or _source_ranked_xp_loss_record(
            state,
            _source_ranked_policy_id(candidate, character_level=character_level),
        ) is not None
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    if (
        mobile is None
        or mobile.aggressive
        or (
            mobile.programs
            and not source_reviewed_noncombat_programs_only(mobile.programs)
        )
        or mobile.attack_programs
        or mobile.fear_aura
        or mobile.non_corporeal
        or mobile.costs_fame
        or candidate.mobile_vnum in source_world.shopkeepers
        or source_world.mobile_specials.get(candidate.mobile_vnum)
    ):
        return False
    result = _campaign_research_results(state).get(
        _source_ranked_policy_id(candidate, character_level=character_level)
    )
    if isinstance(result, Mapping) and result.get("boot_id") == state.get(
        "world_boot_id"
    ):
        # A fresh probe must not overwrite same-reboot absence, crowd, or
        # consider evidence. The normal selector handles those receipts.
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=(
            int(state.get("max_hp"))
            if isinstance(state.get("max_hp"), (int, float))
            and state.get("max_hp", 0) > 0
            else None
        ),
    ):
        return False
    return _source_ranked_level_admission_available(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    )


def _source_ranked_protection_recovery_fallback_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None = None,
) -> bool:
    """Allow one tightly bounded plain hunt when reserve recovery is absent."""
    if character_max_hp is None or character_max_hp <= 0:
        return False
    raw_max_hp = state.get("max_hp")
    if isinstance(raw_max_hp, (int, float)) and raw_max_hp > 0:
        character_max_hp = int(raw_max_hp)
    if _state_has_sanctuary_reserve(state):
        return False
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(protection, Mapping):
        return False
    if (
        protection.get("boot_id") != state.get("world_boot_id")
        or protection.get("level") not in {None, character_level}
    ):
        return False
    protection_policy_id = str(protection.get("policy_id") or "")
    protection_loss_count = _source_ranked_protection_recovery_loss_count(
        state,
        protection,
    )
    terminal_sanctuary_failure = _source_ranked_terminal_sanctuary_failure(
        state
    )
    if protection_loss_count not in {1, 2} and not terminal_sanctuary_failure:
        return False
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if _source_ranked_xp_loss_record(state, candidate_policy_id) is not None:
        # A protection fallback is a fresh independent probe.  It must never
        # turn an earlier exact XP-loss record into permission to replay that
        # target, even after the Sanctuary route becomes terminal.
        return False
    locator_revalidation = _source_locator_revalidation_pending(state, candidate_policy_id)
    city_route_revalidation = _source_ranked_city_route_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    )
    current_result = _campaign_research_results(state).get(candidate_policy_id)
    clean_consider_retry = bool(
        isinstance(current_result, Mapping)
        and current_result.get("boot_id") == state.get("world_boot_id")
        and current_result.get("retryable_failure") is True
        and current_result.get("consider_viable") is True
        and current_result.get("completed_kill") is not True
        and current_result.get("xp_loss_observed") not in {True, 1}
        and not _source_ranked_current_result_blocks_loss_retry(
            state,
            candidate_policy_id,
        )
    )
    if (
        isinstance(current_result, Mapping)
        and current_result.get("boot_id") == state.get("world_boot_id")
        and (
            _source_ranked_current_result_blocks_loss_retry(
                state,
                candidate_policy_id,
            )
            or (
                current_result.get("viable") is False
                and not clean_consider_retry
            )
            or current_result.get("low_reward") is True
            or current_result.get("fatal_failure") is True
        )
        and not (
            locator_revalidation
            or city_route_revalidation
            or _source_locator_revalidation_pending(
                state,
                candidate_policy_id,
            )
            or _source_ranked_consider_fuzz_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_dynamic_city_route_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_endpoint_revalidation_pending(
                state,
                policy_id=candidate_policy_id,
            )
            or _source_ranked_route_loss_revalidation_pending(
                state,
                policy_id=candidate_policy_id,
            )
            or _source_ranked_maze_index_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_locator_rebase_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
                source_world=source_world,
            )
            or _source_ranked_pouch_audit_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_alignment_crowd_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_armed_transit_revalidation_pending(
                candidate,
                state,
                character_level=character_level,
            )
            or _source_ranked_flight_route_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or _source_ranked_preparation_abort_revalidation_pending(
                state,
                candidate,
                character_level=character_level,
            )
            or inspection_revalidation_pending(
                state,
                candidate,
                candidate_policy_id,
            )
            or population_search_revalidation_pending(
                state,
                candidate,
                candidate_policy_id,
            )
            or recall_route_revalidation_pending(
                state,
                candidate,
                candidate_policy_id,
            )
            or str(state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or "")
            == candidate_policy_id
        )
    ):
        # Protection recovery is allowed to open an independent plain target,
        # not to erase a same-boot absence, crowd, route, or viability result.
        # Only an explicit, persisted one-shot revalidation may change that
        # decision before the next live segment.
        return False
    fallback = state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    attempted_fallback_policy_ids: frozenset[str] = frozenset()
    if isinstance(fallback, Mapping):
        if (
            fallback.get("boot_id") != state.get("world_boot_id")
            or fallback.get("level") not in {None, character_level}
        ):
            return False
        # A failed fallback closes the exact target that was tested, but it
        # must not turn a live reboot into a general XP holiday.  Keep the
        # distinct-policy budget below authoritative so independent plain
        # targets can still be tried when the protection route is unavailable.
        attempted_fallback_policy_ids = (
            _source_ranked_protection_recovery_fallback_attempted_policy_ids(
                fallback
            )
        )
        if (
            (
                candidate_policy_id in attempted_fallback_policy_ids
                and not locator_revalidation
                and not city_route_revalidation
            )
            or (
                len(attempted_fallback_policy_ids)
                >= _PROTECTION_RECOVERY_ORDINARY_FALLBACK_MAX_PROBES
                and not city_route_revalidation
            )
        ):
            return False
    route_program_preflight_allowed = (
        _source_ranked_route_program_preflight_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    )
    familiar_probe_allowed = bool(
        source_world is not None
        and _source_ranked_familiar_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )
    target_mobile = (
        source_world.mobiles.get(candidate.mobile_vnum)
        if source_world is not None
        else None
    )
    source_fixed_plain_endpoint = bool(
        target_mobile is not None
        and not target_mobile.aggressive
        and not target_mobile.wanders
        and not target_mobile.programs
        and not target_mobile.attack_programs
        and not target_mobile.fear_aura
        and not target_mobile.non_corporeal
        and not target_mobile.costs_fame
        and not candidate.specials
        and not (
            source_world is not None
            and source_world.mobile_specials.get(candidate.mobile_vnum)
        )
    )
    passive_fixed_endpoint = bool(
        source_fixed_plain_endpoint
        and not candidate.equipped_weapons
    )
    terminal_plain_endpoint = bool(
        terminal_sanctuary_failure and source_fixed_plain_endpoint
    )
    route_specials_noncombat_only = _source_ranked_route_specials_noncombat_only(
        candidate,
        source_world,
    )
    armed_fixed_endpoint = bool(
        source_fixed_plain_endpoint
        and candidate.autonomous_safe
        and candidate.target_selection_safe
        and len(candidate.equipped_weapons) == 1
        and candidate.source_spawn_limit == 1
        and candidate.room_spawn_count == 1
        and not candidate.route_preflight_hard_hazard
        and not candidate.route_hard_hazard_targets
        and not candidate.route_attack_program_mobile_vnums
        and route_specials_noncombat_only
    )
    fresh_plain_endpoint_after_second_loss = bool(
        source_world is not None
        and passive_fixed_endpoint
        and not candidate.route_preflight_hard_hazard
        and not candidate.route_hard_hazard_targets
        and not candidate.route_attack_program_mobile_vnums
        and (
            not candidate.route_special_mobile_vnums
            or route_specials_noncombat_only
        )
    )
    terminal_safe_singleton_endpoint = bool(
        terminal_sanctuary_failure
        and source_world is not None
        and target_mobile is not None
        and not target_mobile.aggressive
        and not target_mobile.wanders
        and not target_mobile.programs
        and not target_mobile.attack_programs
        and not target_mobile.fear_aura
        and not target_mobile.non_corporeal
        and not target_mobile.costs_fame
        and candidate.autonomous_safe
        and candidate.room_spawn_count == 1
        and candidate.source_spawn_limit == 1
        and candidate.specials
        and set(candidate.specials) <= SAFE_NONCOMBAT_SPECIALS
        and not candidate.route_special_mobile_vnums
        and not candidate.route_attack_program_mobile_vnums
        and not candidate.route_hard_hazard_targets
        and route_specials_noncombat_only
    )
    # A plain singleton aggressive mobile is still a valid no-Sanctuary
    # frontier when its source record supports a fresh live-consider probe.
    # Sanctuary recovery being terminal must not silently turn that ordinary
    # current-band target into an automatic wait; the live controller retains
    # identity, isolation, consider, output, and health-floor checks.
    aggressive_consider_endpoint = bool(
        source_world is not None
        and target_mobile is not None
        and not target_mobile.programs
        and (
            _source_ranked_aggressive_consider_probe_allowed(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                source_world=source_world,
            )
            or _source_ranked_plain_aggressive_current_band_fallback_allowed(
                candidate,
                state,
                character_level=character_level,
                character_max_hp=character_max_hp,
                source_world=source_world,
            )
            or _source_ranked_fixed_aggressive_route_risk_allowed(
                candidate,
                character_level=character_level,
                source_world=source_world,
                state=state,
            )
        )
    )
    if terminal_sanctuary_failure and not (
        terminal_plain_endpoint
        or armed_fixed_endpoint
        or terminal_safe_singleton_endpoint
        or aggressive_consider_endpoint
    ):
        # Once the source-verified Sanctuary recovery frontier is terminal and
        # the ordinary fallback has already seen several losses, keep a narrow
        # XP path open: a fixed, plain singleton or a source-audited singleton
        # whose only target special is explicitly noncombat. A source-audited
        # fixed aggressive route is also allowed to reach live consider; its
        # route interruptions remain live combat evidence, not paper denial.
        # This does not reopen the failed recovery route or permit an arena
        # detour.
        return False
    if familiar_probe_allowed:
        # The familiar route has its own source output, staging, and
        # invisibility checks. Let it use the same bounded recovery handoff,
        # but never retry the original loss or a previously attempted fallback.
        if (
            candidate_policy_id == protection_policy_id
            or candidate_policy_id in attempted_fallback_policy_ids
        ):
            return False
        if protection_loss_count == 2 and not route_program_preflight_allowed:
            return False
        return True
    if protection_loss_count == 2:
        # A second loss quarantines the failed route, but it should not make a
        # healthy campaign wait forever when source evidence identifies one
        # genuinely independent fresh endpoint. A fixed, unarmed, plain
        # source reset has no combat program or target weapon to inherit from
        # the failed route; it still passes the route, current-band, live
        # consider, identity, and health gates below. Route-program hazards
        # retain their exact ``where`` preflight contract.
        if (
            not route_program_preflight_allowed
            and not fresh_plain_endpoint_after_second_loss
            and not aggressive_consider_endpoint
            or candidate_policy_id == protection_policy_id
            or _source_ranked_xp_loss_record(state, candidate_policy_id)
            is not None
            or (
                isinstance(fallback, Mapping)
                and fallback.get("second_loss_program_preflight_used") is True
            )
        ):
            return False
    if (
        candidate.is_coin_stash
        or (
            candidate.specials
            and not terminal_safe_singleton_endpoint
        )
        or (not candidate.autonomous_safe and not aggressive_consider_endpoint)
        or (
            candidate.requires_flight
            and not _source_ranked_flight_handoff_available(candidate, state)
            and not _source_ranked_flight_purchase_ready_for_fallback(
                state,
                source_world=source_world,
            )
        )
        or (
            candidate.route_preflight_hard_hazard
            and not route_program_preflight_allowed
        )
        or candidate.route_hard_hazard_targets
    ):
        return False
    has_runtime_class = isinstance(state.get("character_class"), str) and bool(
        state.get("character_class", "").strip()
    )
    if source_world is not None and not (
        passive_fixed_endpoint
        or armed_fixed_endpoint
        or terminal_plain_endpoint
        or terminal_safe_singleton_endpoint
        or aggressive_consider_endpoint
    ):
        return False
    # This emergency allowance has no sanctuary reserve. Route aggressors
    # still need the source-exact output bound below; only a singleton target
    # that already passed its separate live-consider probe may be aggressive.
    route_aggressors_bounded = _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    )
    if not route_aggressors_bounded:
        return False
    if candidate.route_attack_program_mobile_vnums and not (
        route_program_preflight_allowed
    ):
        return False
    if candidate.route_special_mobile_vnums and not route_specials_noncombat_only:
        return False
    for hazard in candidate.hazards:
        normalized_hazard = str(hazard).casefold()
        if normalized_hazard.startswith("positive alignment target"):
            # Alignment is source/report metadata, not an attack or transit
            # hazard. Do not let it close an otherwise plain no-Sanctuary
            # fallback target before live consider decides the fight.
            continue
        if not normalized_hazard.startswith(
            (
                "route:",
                "route program attacker:",
                "route combat-joining special:",
                "reachable wanderer:",
                "reachable program attacker:",
                "reachable special mobile:",
                "reachable combat-joining special:",
            )
        ):
            continue
        if route_program_preflight_allowed and normalized_hazard.startswith(
            ("route program attacker:", "reachable program attacker:")
        ):
            continue
        if (
            route_specials_noncombat_only
            and normalized_hazard.startswith("reachable special mobile:")
        ):
            # ``economic_hunt_candidate`` retains the exact source VNUMs for
            # the runtime purse guard but removes the generic rejection. The
            # corresponding display hazard is safe to ignore only after the
            # dedicated route-special audit above has accepted every VNUM.
            continue
        if (
            route_aggressors_bounded
            and candidate.route_aggressive_mobile_vnums
            and normalized_hazard.startswith(("route:", "reachable wanderer:"))
        ):
            continue
        return False
    if (
        _source_ranked_aggressive_target_below_useful_floor(
            candidate,
            character_level=character_level,
        )
        and not aggressive_consider_endpoint
    ):
        return False
    minimum_level, maximum_level = candidate.estimated_level_range
    if minimum_level <= 0 or maximum_level < minimum_level:
        return False
    source_level_ceiling = character_level + 5
    if (
        maximum_level <= character_level - 5
        or candidate.level > source_level_ceiling
    ):
        return False
    # Source HP and predicted target output remain report evidence. The live
    # target's level/consider, route hazards, and the player's own floor are
    # checked by the execution path.
    if (
        isinstance(fallback, Mapping)
        and fallback.get("policy_id")
        and str(fallback.get("policy_id")) == candidate_policy_id
        and fallback.get("attempted") is True
        and not locator_revalidation
        and not city_route_revalidation
    ):
        return False
    if candidate_policy_id in {
        str(protection.get("policy_id") or ""),
        str(fallback.get("policy_id") or "")
        if isinstance(fallback, Mapping)
        else "",
    }:
        return False
    return True


def _source_ranked_city_route_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Match the one pending city-greeter retry to its exact source reset."""
    marker = state.get(_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY)
    if not isinstance(marker, Mapping):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    try:
        mobile_vnum = int(marker.get("source_mobile_vnum") or 0)
        room_vnum = int(marker.get("source_room_vnum") or 0)
    except (TypeError, ValueError):
        return False
    return bool(
        marker.get("status") == "pending"
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("policy_id") == policy_id
        and candidate.mobile_vnum == mobile_vnum == 10247
        and candidate.room_vnum == room_vnum == 10312
        and policy_id == f"{_SOURCE_RANKED_POLICY_PREFIX}solace-10247-10312-{character_level}"
    )


def _mark_source_ranked_city_route_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the city-greeter retry immediately before live dispatch."""
    if not _source_ranked_city_route_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = state.get(_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY)
    assert isinstance(marker, Mapping)
    state[_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _arm_source_ranked_city_route_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    segments: Collection[Any] = (),
) -> dict[str, Any]:
    """Reopen only the Secretary hunt blocked by the prior live city check."""
    boot_id = state.get("world_boot_id")
    fallback = state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    if (
        not boot_id
        or character_level != 25
        or character_max_hp is None
        or character_max_hp <= 0
        or source_world is None
        or not isinstance(fallback, Mapping)
        or fallback.get("boot_id") != boot_id
        or fallback.get("level") != character_level
        or fallback.get("attempted") is not True
    ):
        return state
    existing = state.get(_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") == character_level
        and existing.get("status")
        in {"pending", "attempted", "closed", "succeeded"}
    ):
        return state

    attempted_ids = _source_ranked_protection_recovery_fallback_attempted_policy_ids(
        fallback
    )
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            policy_id != f"{_SOURCE_RANKED_POLICY_PREFIX}solace-10247-10312-25"
            or candidate.mobile_vnum != 10247
            or candidate.room_vnum != 10312
            or policy_id not in attempted_ids
            or str(fallback.get("policy_id") or "") != policy_id
            or candidate.route_preflight_room_vnum != "3001"
            or candidate.route_preflight_command.casefold() != "where drunk"
            or candidate.route_preflight_target.casefold() != "the drunk"
            or 3064 not in candidate.route_attack_program_mobile_vnums
            or candidate.route_preflight_hard_hazard is not True
            or "temple square"
            not in {
                str(name).casefold()
                for name in candidate.route_preflight_route_room_names
            }
            or not _source_ranked_route_program_candidate_allowed(
                candidate,
                character_level=character_level,
                source_world=source_world,
                character_max_hp=character_max_hp,
            )
        ):
            continue

        matching_segment: Mapping[str, Any] | None = None
        for raw_segment in reversed(tuple(segments)):
            if isinstance(raw_segment, Mapping):
                segment = raw_segment
            else:
                try:
                    segment = {
                        key: raw_segment[key] for key in raw_segment.keys()
                    }
                except (AttributeError, KeyError, TypeError):
                    continue
            if str(segment.get("phase") or "") == policy_id:
                matching_segment = segment
                break
        if matching_segment is None or matching_segment.get("status") != "success":
            continue
        try:
            start = json.loads(matching_segment.get("start_state_json") or "{}")
            end = json.loads(matching_segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        try:
            xp_unchanged = int(start.get("xp")) == int(end.get("xp"))
            at_full_healer = (
                str(end.get("room_vnum") or "") == "3054"
                and int(end.get("hp")) == int(end.get("max_hp"))
                and int(end.get("max_hp")) > 0
            )
            no_loss = int(end.get("xp_loss_total")) == 0
            combat_timing = end.get("campaign_combat_timing")
            no_combat = (
                isinstance(combat_timing, Mapping)
                and int(combat_timing.get("sent", -1)) == 0
                and int(combat_timing.get("acknowledged", -1)) == 0
                and end.get("campaign_completed_kills") == []
                and end.get("campaign_objective_kills") == []
                and end.get("in_combat") in {False, 0}
                and end.get("campaign_fastwalk_target_present_observed")
                in {False, 0}
            )
        except (TypeError, ValueError):
            continue
        route_locations = end.get("campaign_fastwalk_route_preflight_locations")
        transit = end.get("campaign_city_shop_transit")
        if not (
            start.get("world_boot_id") == boot_id
            and end.get("world_boot_id") == boot_id
            and start.get("level") == character_level
            and end.get("level") == character_level
            and xp_unchanged
            and no_loss
            and at_full_healer
            and no_combat
            and end.get("xp_loss_observed") not in {True, 1}
            and end.get("campaign_fastwalk_route_preflight_hazard_observed")
            in {True, 1}
            and str(end.get("campaign_fastwalk_abort_reason") or "").casefold()
            == _SOURCE_RANKED_CITY_ROUTE_ABORT_REASON.casefold()
            and isinstance(route_locations, (list, tuple))
            and "the temple square" in {
                str(location).casefold() for location in route_locations
            }
            and isinstance(transit, Mapping)
            and transit.get("status") == "admitted"
            and transit.get("source_mobile_vnum") == 3064
        ):
            continue

        marker = {
            "boot_id": boot_id,
            "level": character_level,
            "policy_id": policy_id,
            "source_mobile_vnum": candidate.mobile_vnum,
            "source_room_vnum": candidate.room_vnum,
            "hazard_mobile_vnum": 3064,
            "hazard_room_vnum": 3005,
            "prior_segment_id": matching_segment.get("id"),
            "status": "pending",
            "reason": (
                "one fresh Temple Square greeter check after a clean, pre-combat "
                "city-route abort"
            ),
        }
        probe_state = dict(state)
        probe_state[_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY] = marker
        if not _source_ranked_protection_recovery_fallback_candidate_allowed(
            candidate,
            probe_state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        ):
            continue
        state[_SOURCE_RANKED_CITY_ROUTE_REVALIDATION_KEY] = marker
        break
    return state


def _source_ranked_dynamic_city_route_revalidation_pending(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    marker = state.get(_SOURCE_RANKED_DYNAMIC_CITY_ROUTE_REVALIDATION_KEY)
    if not isinstance(marker, Mapping):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    try:
        mobile_vnum = int(marker.get("source_mobile_vnum") or 0)
        room_vnum = int(marker.get("source_room_vnum") or 0)
    except (TypeError, ValueError):
        return False
    source_route = marker.get("source_route")
    result = _campaign_research_results(state).get(policy_id)
    route_hazard = marker.get("route_hazard")
    return bool(
        marker.get("status") == "pending"
        and marker.get("attempted") is not True
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") == character_level
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("repeat_after_kill_cap")
        is (candidate.boot_kills >= 3)
        and isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is False
        and result.get("retryable_failure") is True
        and result.get("route_hazard") == route_hazard
        and (
            result.get("run_id") is None
            or result.get("run_id") == marker.get("prior_run_id")
        )
        and isinstance(route_hazard, str)
        and route_hazard.startswith(_SOURCE_RANKED_PREFLIGHT_ROUTE_HAZARD_PREFIX)
        and isinstance(marker.get("prior_locations"), (list, tuple))
        and any(
            _normalise_room_label(location) == "temple square"
            for location in marker["prior_locations"]
        )
        and type(marker.get("prior_segment_id")) is int
        and marker.get("prior_segment_id", 0) > 0
        and type(marker.get("prior_run_id")) is int
        and marker.get("prior_run_id", 0) > 0
        and candidate.mobile_vnum == mobile_vnum
        and candidate.room_vnum == room_vnum
        and isinstance(source_route, (list, tuple))
        and list(candidate.route) == list(source_route)
        and candidate.route_preflight_hard_hazard is True
        and str(candidate.route_preflight_room_vnum or "") == "3001"
        and str(candidate.route_preflight_command or "").casefold()
        == "where drunk"
        and str(candidate.route_preflight_target or "").casefold()
        == "the drunk"
        and 3064 in candidate.route_attack_program_mobile_vnums
        and "temple square"
        in {
            _normalise_room_label(name)
            for name in candidate.route_preflight_route_room_names
        }
    )


def _mark_source_ranked_dynamic_city_route_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    if not _source_ranked_dynamic_city_route_revalidation_pending(
        state,
        candidate,
        character_level=character_level,
    ):
        return False
    marker = state.get(_SOURCE_RANKED_DYNAMIC_CITY_ROUTE_REVALIDATION_KEY)
    assert isinstance(marker, Mapping)
    state[_SOURCE_RANKED_DYNAMIC_CITY_ROUTE_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _arm_source_ranked_dynamic_city_route_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    segments: Collection[Any],
    excluded_policy_ids: Collection[str] = (),
    allow_repeated_policy_ids: Collection[str] = (),
) -> str | None:
    """Reopen one exact current-band hunt after a safe dynamic route block."""
    boot_id = state.get("world_boot_id")
    revision = state.get(_SOURCE_REVISION_KEY)
    if (
        not boot_id
        or not revision
        or source_world is None
        or not _is_safe_healer_checkpoint(state)
        or _campaign_needs_healer_recovery(state)
        or _level(state) != character_level
        or character_max_hp is None
        or character_max_hp <= 0
    ):
        return None

    existing = state.get(_SOURCE_RANKED_DYNAMIC_CITY_ROUTE_REVALIDATION_KEY)
    legacy_pre_dispatch_gate_close = False
    if isinstance(existing, Mapping):
        if (
            existing.get("boot_id") == boot_id
            and existing.get("level") == character_level
        ):
            if existing.get("status") == "pending":
                return str(existing.get("policy_id") or "") or None
            legacy_pre_dispatch_gate_close = bool(
                existing.get("status") == "closed"
                and existing.get("attempted") is False
                and "repeat_after_kill_cap" not in existing
                and existing.get("source_revision") == revision
                and existing.get("reason")
                == (
                    "the exact revalidated route failed ordinary source or "
                    "current-band gates"
                )
            )
            if not legacy_pre_dispatch_gate_close:
                return None

    excluded = {str(value) for value in excluded_policy_ids}
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            (
                legacy_pre_dispatch_gate_close
                and existing.get("policy_id") != policy_id
            )
            or (
                legacy_pre_dispatch_gate_close
                and (
                    existing.get("source_mobile_vnum")
                    != candidate.mobile_vnum
                    or existing.get("source_room_vnum") != candidate.room_vnum
                    or existing.get("source_route") != list(candidate.route)
                )
            )
            or policy_id in excluded
            or (
                candidate.boot_kills >= 3
                and policy_id not in allow_repeated_policy_ids
            )
            or candidate.is_coin_stash
            or candidate.is_food_stash
            or candidate.specials
            or candidate.equipped_weapons
            or candidate.route_hard_hazard_targets
            or not candidate.autonomous_safe
            or candidate.estimated_level_range[0] <= character_level - 5
            or candidate.estimated_level_range[1] > character_level + 1
            or not _source_ranked_route_program_candidate_allowed(
                candidate,
                character_level=character_level,
                source_world=source_world,
                character_max_hp=character_max_hp,
            )
        ):
            continue
        if not (
            candidate.route_preflight_hard_hazard is True
            and str(candidate.route_preflight_room_vnum or "") == "3001"
            and str(candidate.route_preflight_command or "").casefold()
            == "where drunk"
            and str(candidate.route_preflight_target or "").casefold()
            == "the drunk"
            and 3064 in candidate.route_attack_program_mobile_vnums
            and "temple square"
            in {
                _normalise_room_label(name)
                for name in candidate.route_preflight_route_room_names
            }
        ):
            continue
        result = _campaign_research_results(state).get(policy_id)
        absence_cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
        try:
            current_cooldown = int(
                absence_cooldowns.get(policy_id, 0)
                if isinstance(absence_cooldowns, Mapping)
                else 0
            )
        except (TypeError, ValueError):
            current_cooldown = 0
        if not (
            isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("observed") is False
            and result.get("retryable_failure") is True
            and current_cooldown > 0
            and not any(
                result.get(key)
                for key in (
                    "absent",
                    "crowded",
                    "unattackable",
                    "target_vnum_mismatch",
                    "consider_viable",
                    "completed_kill",
                )
            )
            and isinstance(result.get("route_hazard"), str)
            and result["route_hazard"].startswith(
                _SOURCE_RANKED_PREFLIGHT_ROUTE_HAZARD_PREFIX
            )
            and "while observing from room 3001" in result["route_hazard"]
            and (
                not legacy_pre_dispatch_gate_close
                or result.get("route_hazard")
                == existing.get("route_hazard")
            )
        ):
            continue

        matching_segment: Mapping[str, Any] | None = None
        for raw_segment in reversed(tuple(segments)):
            try:
                segment = (
                    raw_segment
                    if isinstance(raw_segment, Mapping)
                    else {key: raw_segment[key] for key in raw_segment.keys()}
                )
            except (AttributeError, KeyError, TypeError):
                continue
            result_run_id = result.get("run_id")
            if (
                segment.get("phase") == policy_id
                and segment.get("status") == "success"
                and (
                    result_run_id is None
                    or segment.get("run_id") == result_run_id
                )
            ):
                matching_segment = segment
                break
        if matching_segment is None:
            continue
        try:
            run_id = int(matching_segment.get("run_id"))
            start = json.loads(matching_segment.get("start_state_json") or "{}")
            end = json.loads(matching_segment.get("end_state_json") or "{}")
            unchanged_progress = (
                int(start.get("xp")) == int(end.get("xp"))
                and int(start.get("xp_loss_total"))
                == int(end.get("xp_loss_total"))
                and int(state.get("xp")) == int(end.get("xp"))
                and int(state.get("xp_loss_total"))
                == int(end.get("xp_loss_total"))
            )
            end_full_health = (
                int(end.get("hp")) == int(end.get("max_hp")) > 0
            )
            no_combat = (
                isinstance(end.get("campaign_combat_timing"), Mapping)
                and int(end["campaign_combat_timing"].get("sent", -1)) == 0
                and int(end["campaign_combat_timing"].get("acknowledged", -1)) == 0
            )
        except (AttributeError, TypeError, ValueError, json.JSONDecodeError):
            continue
        recorded = _source_ranked_candidate_from_record(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY),
            source_revision=start.get(_SOURCE_REVISION_KEY),
        )
        locations = end.get("campaign_fastwalk_route_preflight_locations")
        hazard = str(end.get("campaign_fastwalk_abort_reason") or "")
        if not (
            run_id > 0
            and isinstance(start, Mapping)
            and isinstance(end, Mapping)
            and start.get("world_boot_id") == boot_id
            and end.get("world_boot_id") == boot_id
            and _level(dict(start)) == character_level
            and _level(dict(end)) == character_level
            and start.get(_SOURCE_REVISION_KEY) == revision
            and end.get(_SOURCE_REVISION_KEY) == revision
            and str(state.get("campaign_last_policy") or "") == policy_id
            and unchanged_progress
            and end_full_health
            and no_combat
            and str(end.get("room_vnum") or "") == "3054"
            and end.get("dead") not in {True, 1}
            and end.get("in_combat") not in {True, 1}
            and end.get("xp_loss_observed") not in {True, 1}
            and end.get("campaign_fastwalk_route_preflight_complete") is True
            and end.get("campaign_fastwalk_route_preflight_hazard_observed")
            in {True, 1}
            and type(end.get("campaign_fastwalk_route_preflight_retry_attempts")) is int
            and end["campaign_fastwalk_route_preflight_retry_attempts"] >= 3
            and isinstance(locations, (list, tuple))
            and any(
                _normalise_room_label(location) == "temple square"
                for location in locations
            )
            and hazard == result.get("route_hazard")
            and hazard.endswith("while observing from room 3001")
            and end.get("campaign_fastwalk_target_present_observed")
            in {False, 0}
            and end.get("campaign_consider_result") is None
            and not end.get("campaign_completed_kills")
            and not end.get("campaign_objective_kills")
            and recorded is not None
            and recorded.mobile_vnum == candidate.mobile_vnum
            and recorded.room_vnum == candidate.room_vnum
            and list(recorded.route) == list(candidate.route)
            and (
                not legacy_pre_dispatch_gate_close
                or (
                    existing.get("prior_segment_id")
                    == matching_segment.get("id")
                    and existing.get("prior_run_id") == run_id
                    and existing.get("prior_locations") == list(locations)
                )
            )
            and _source_ranked_policy_id(
                recorded,
                character_level=character_level,
            ) == policy_id
        ):
            continue
        state[_SOURCE_RANKED_DYNAMIC_CITY_ROUTE_REVALIDATION_KEY] = {
            "boot_id": boot_id,
            "level": character_level,
            "source_revision": revision,
            "policy_id": policy_id,
            "source_mobile_vnum": candidate.mobile_vnum,
            "source_room_vnum": candidate.room_vnum,
            "source_route": list(candidate.route),
            "route_hazard": hazard,
            "repeat_after_kill_cap": candidate.boot_kills >= 3,
            "prior_segment_id": matching_segment.get("id"),
            "prior_run_id": run_id,
            "prior_locations": list(locations),
            "status": "pending",
            "attempted": False,
            "pre_dispatch_gate_repaired": legacy_pre_dispatch_gate_close,
            "reason": (
                "one fresh source-route preflight after the exact Drunk "
                "blocked the prior route before target combat"
            ),
        }
        return policy_id
    return None


def _source_ranked_protection_recovery_productive_result_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    allow_repeated_kills: bool = False,
) -> bool:
    """Allow one already-proven, low-frequency fallback route.

    A fresh candidate is preferred, but current-reboot evidence can exhaust
    every fresh option while leaving one safe route with fewer than three
    kills. Reusing that route is bounded by its positive live result and the
    ordinary fallback marker; it must not reopen an absent, crowded, or
    low-reward target. The productive-transit repair may explicitly reuse
    the same evidence after the ordinary three-kill search cap, because its
    own one-shot marker and exact route blocker provide the additional bound.
    """
    if not allow_repeated_kills:
        try:
            if int(candidate.boot_kills) >= 3:
                return False
        except (TypeError, ValueError):
            return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if not (
        result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
    ):
        return False
    if any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "route_hazard",
            "unattackable",
            "target_vnum_mismatch",
        )
    ) or result.get("low_reward") is True:
        return False
    if "max_objective_kill_xp" in result:
        try:
            if (
                int(result.get("max_objective_kill_xp") or 0)
                < _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
            ):
                return False
        except (TypeError, ValueError):
            return False
    return True


def _source_ranked_protection_recovery_retryable_result_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Allow one safe-return retry after a non-combat runtime boundary."""
    try:
        if int(candidate.boot_kills) >= 3:
            return False
    except (TypeError, ValueError):
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return False
    if result.get("boot_id") != state.get("world_boot_id"):
        return False
    if not (
        result.get("observed") is False
        and result.get("viable") is False
        and result.get("retryable_failure") is True
        and result.get("completed_kill") is not True
        and result.get("route_hazard")
        == _SOURCE_RANKED_SAFE_RETURN_RUNTIME_HAZARD
    ):
        return False
    if any(
        result.get(key)
        for key in (
            "absent",
            "crowded",
            "crowd_exhausted",
            "unattackable",
            "target_vnum_mismatch",
            "low_reward",
        )
    ):
        return False
    return _source_ranked_xp_loss_record(state, policy_id) is None


def _source_ranked_partial_timeout_retry_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None = None,
    allow_attempted: bool = False,
) -> bool:
    """Allow the one recorded retry for a clean partial-timeout route."""
    marker = state.get(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY)
    if not isinstance(marker, Mapping) or (
        marker.get("attempted") is True and not allow_attempted
    ):
        return False
    if marker.get("boot_id") != state.get("world_boot_id"):
        return False
    if marker.get("level") not in {None, character_level}:
        return False
    if _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    ) != str(marker.get("policy_id") or ""):
        return False
    try:
        marker_mobile_vnum = int(marker.get("mobile_vnum") or 0)
    except (TypeError, ValueError):
        marker_mobile_vnum = 0
    try:
        marker_room_vnum = int(marker.get("room_vnum") or 0)
    except (TypeError, ValueError):
        marker_room_vnum = 0
    if (
        marker_mobile_vnum <= 0
        or candidate.mobile_vnum != marker_mobile_vnum
        or marker_room_vnum <= 0
        or candidate.room_vnum != marker_room_vnum
        or candidate.area_file != str(marker.get("area_file") or "")
    ):
        return False
    if not _source_ranked_capacity_research_candidate(
        candidate,
        character_level=character_level,
    ):
        return False
    if candidate.specials or candidate.equipped_weapons:
        return False
    if candidate.route_preflight_hard_hazard or candidate.route_hard_hazard_targets:
        return False
    return True


def _source_ranked_partial_timeout_retry_record(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
    *,
    policy: ProgressionPolicy,
    xp_delta: int,
    loss_event_id: Any = None,
) -> dict[str, Any] | None:
    """Record one clean target retry after a bounded partial timeout."""
    if (
        policy.execution != "source-ranked-hunt"
        or policy.status != "research"
        or xp_delta >= 0
        or current.get("campaign_objective_kills")
        or current.get("dead")
        or current.get("campaign_died_during_segment")
    ):
        return None
    abort_reason = str(current.get("campaign_fastwalk_abort_reason") or "")
    if "runtime boundary" not in abort_reason:
        return None
    if current.get("campaign_fastwalk_target_present_observed") is not True:
        return None
    consider_outcomes = current.get("campaign_fastwalk_consider_outcomes")
    if not (
        isinstance(consider_outcomes, Mapping)
        and any(value is True for value in consider_outcomes.values())
    ):
        return None
    if any(
        current.get(key)
        for key in (
            "campaign_fastwalk_target_absent",
            "campaign_fastwalk_crowded",
            "campaign_fastwalk_route_preflight_hazard_observed",
            "campaign_fastwalk_target_vnum_mismatch",
            "campaign_fastwalk_unattackable_target",
        )
    ):
        return None
    if current.get("campaign_fastwalk_route_hazards"):
        return None
    raw_hp = current.get("hp")
    raw_max_hp = current.get("max_hp")
    if not (
        isinstance(raw_hp, (int, float))
        and isinstance(raw_max_hp, (int, float))
        and raw_max_hp > 0
        and raw_hp / raw_max_hp >= 0.9
    ):
        return None
    candidate = _source_ranked_candidate_from_record(
        previous.get(_SOURCE_RANKED_CANDIDATE_KEY),
        source_revision=previous.get(_SOURCE_REVISION_KEY),
    )
    if candidate is None or not _source_ranked_capacity_research_candidate(
        candidate,
        character_level=_level(previous),
    ):
        return None
    if candidate.specials or candidate.equipped_weapons:
        return None
    if candidate.route_preflight_hard_hazard or candidate.route_hard_hazard_targets:
        return None
    existing = current.get(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == current.get("world_boot_id")
        and existing.get("level") in {None, _level(current)}
        and existing.get("attempted") is True
    ):
        return None
    return {
        "boot_id": current.get("world_boot_id"),
        "level": _level(current),
        "policy_id": policy.policy_id,
        "area_file": candidate.area_file,
        "mobile_vnum": candidate.mobile_vnum,
        "room_vnum": candidate.room_vnum,
        "source_peak_round_damage": candidate.estimated_peak_round_damage,
        "source_critical_hit_damage": candidate.estimated_critical_hit_damage,
        "xp_delta": xp_delta,
        "loss_event_id": loss_event_id,
        "reason": (
            "one clean unarmed partial-timeout retry; live target was isolated, "
            "considered viable, and ended above 90% character HP"
        ),
        "attempted": False,
    }


def _source_ranked_source_refresh_productive_result_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    """Let later current-source progress retire a one-shot refresh quarantine.

    A source-refresh receipt protects one failed audit attempt.  It must not
    become a permanent ban after a later live segment has already produced a
    useful, loss-free kill for the same source policy.
    """
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    boot_id = state.get("world_boot_id")
    source_revision = state.get(_SOURCE_REVISION_KEY)
    if not policy_id or not boot_id or not source_revision:
        return False
    matching_refresh_records = tuple(
        record
        for record in _source_refresh_history_records(state)
        if (
            record.get("policy_id") == policy_id
            and record.get("boot_id") == boot_id
            and record.get("level") in {None, character_level}
            and record.get("source_revision") == source_revision
            and record.get("status") in {"attempted", "closed", "succeeded"}
        )
    )
    if not matching_refresh_records:
        return False
    result = _campaign_research_results(state).get(policy_id)
    # A successful source-refresh segment is itself current-source productive
    # evidence. A later absence scan may replace the live research row, but it
    # must not turn that proven route into a permanent quarantine. Keep this
    # fallback limited to an exact completed-kill receipt and a clean current
    # absence; fatal, crowd, route, and loss evidence remain authoritative.
    refresh_kill_succeeded = any(
        record.get("status") == "succeeded"
        and record.get("outcome") == "completed_kill"
        for record in matching_refresh_records
    )
    if refresh_kill_succeeded and _source_ranked_xp_loss_record(
        state,
        policy_id,
    ) is None:
        if result is None:
            return True
        if (
            result.get("absent") is True
            and result.get("observed") is False
            and result.get("viable") is False
            and not any(
                result.get(key)
                for key in (
                    "crowded",
                    "crowd_exhausted",
                    "fatal_failure",
                    "route_hazard",
                    "unattackable",
                    "target_vnum_mismatch",
                    "consider_viable",
                    "xp_loss_observed",
                )
            )
        ):
            return True
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == boot_id
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "route_hazard",
                "unattackable",
                "target_vnum_mismatch",
                "xp_loss_observed",
            )
        )
    ):
        return False
    result_revision = result.get("source_revision")
    if result_revision is not None and result_revision != source_revision:
        return False
    try:
        maximum_kill_xp = int(result.get("max_objective_kill_xp") or 0)
    except (TypeError, ValueError):
        maximum_kill_xp = 0
    return bool(
        _source_ranked_multi_kill_reward_allowed(result)
        or maximum_kill_xp >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
    )


def _source_ranked_candidate_blocked_by_protection_recovery(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None = None,
    allow_protection_recovery_fallback: bool = False,
    allow_plain_sentinel_risk_revalidation: bool = False,
    source_world: WorldSource | None = None,
) -> bool:
    """Defer the exact hunt that caused a current-reboot XP loss."""
    candidate_policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        allow_plain_sentinel_risk_revalidation
        and _source_ranked_plain_sentinel_risk_revalidation_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
            require_marker=False,
        )
    ):
        # The exact one-shot receipt repairs only the old preparation stop;
        # keep the route, identity, consider, output, and health gates live.
        return False
    if _source_ranked_mrinthas_armed_preflight_revalidation_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        # This exact repair is already source-audited and no-combat. Do not
        # let the historical generic route timeout quarantine it before the
        # armed transit contract gets one live pass.
        return False
    if _source_ranked_mrinthas_route_identity_revalidation_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        # The exact M'rinthas retry repairs a live endpoint-name alias after a
        # route-only timeout. Keep its source, Sanctuary, health, and no-loss
        # gates, but do not let the generic timeout quarantine reject the
        # source-audited target merely because it has spec_guard.
        return False
    if _source_ranked_mrinthas_route_handoff_revalidation_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
        source_world=source_world,
    ):
        # The final route-handoff repair is still a no-combat controller
        # correction. Preserve the source, Sanctuary, health, and no-loss
        # gates while keeping the exact retry visible to the selector.
        return False
    protection_retry_marker = state.get(
        _SOURCE_RANKED_PROTECTION_RETRY_REVALIDATION_KEY
    )
    if (
        isinstance(protection_retry_marker, Mapping)
        and protection_retry_marker.get("policy_id") == candidate_policy_id
        and protection_retry_marker.get("boot_id") == state.get("world_boot_id")
        and protection_retry_marker.get("level") in {None, character_level}
        and protection_retry_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
        and protection_retry_marker.get("policy_revision")
        == _SOURCE_RANKED_PROTECTION_RETRY_REVALIDATION_REVISION
    ):
        if protection_retry_marker.get("status") in {
            "attempted",
            "closed",
            "succeeded",
        }:
            if (
                protection_retry_marker.get("status") in {"attempted", "succeeded"}
                and _source_ranked_protection_retry_productive_result_allowed(
                    candidate,
                    state,
                    character_level=character_level,
                    marker=protection_retry_marker,
                )
            ):
                # The repair itself remains consumed, but its successful
                # protected kill is now ordinary productive evidence. Let
                # the normal repeat selector consider the exact route again;
                # it still performs fresh identity, consider, output, and
                # withdrawal checks before dispatch.
                return False
            # The fresh-reserve retry is consumed before connection. Preserve
            # the original loss and never let an interrupted segment replay it.
            return True
        if protection_retry_marker.get("status") == "pending":
            # The dedicated selector has already checked that this is the
            # exact plain, non-psionic candidate admitted by the refill proof.
            return False
    source_refresh_marker = state.get(
        _SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_KEY
    )
    if (
        isinstance(source_refresh_marker, Mapping)
        and source_refresh_marker.get("policy_id") == candidate_policy_id
        and source_refresh_marker.get("boot_id")
        == state.get("world_boot_id")
        and source_refresh_marker.get("level")
        in {None, character_level}
        and source_refresh_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
        and source_refresh_marker.get("revision")
        == _SOURCE_RANKED_SOURCE_REFRESH_REVALIDATION_REVISION
    ):
        if source_refresh_marker.get("status") in {
            "attempted",
            "closed",
            "succeeded",
        }:
            if _source_ranked_source_refresh_productive_result_allowed(
                candidate,
                state,
                character_level=character_level,
            ):
                # A later current-source productive result supersedes the
                # old one-shot audit quarantine without deleting its receipt.
                return False
            # This source-refresh contract is one-shot. Preserve the old
            # loss even if the worker ended before a normal result arrived.
            return True
        if source_refresh_marker.get("status") == "pending":
            # The selector armed this exact current-source audit; all live
            # identity, consider, route, output, and health gates still run.
            return False
    if any(
        record.get("policy_id") == candidate_policy_id
        and record.get("boot_id") == state.get("world_boot_id")
        and record.get("level") in {None, character_level}
        and record.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and record.get("status") in {"attempted", "closed", "succeeded"}
        and not _source_ranked_source_refresh_productive_result_allowed(
            candidate,
            state,
            character_level=character_level,
        )
        for record in _source_refresh_history_records(state)
    ):
        # A completed per-target audit is one-shot even after another target
        # becomes the active handoff.
        return True
    arena_route_recovery_marker = state.get(
        _OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_KEY
    )
    if (
        isinstance(arena_route_recovery_marker, Mapping)
        and arena_route_recovery_marker.get("policy_id") == candidate_policy_id
        and arena_route_recovery_marker.get("boot_id")
        == state.get("world_boot_id")
        and arena_route_recovery_marker.get("level")
        in {None, character_level}
        and arena_route_recovery_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
        and arena_route_recovery_marker.get("revision")
        == _OTAAR_ARENA_ROUTE_RECOVERY_REVALIDATION_REVISION
    ):
        if arena_route_recovery_marker.get("status") in {
            "attempted",
            "closed",
            "succeeded",
        }:
            return True
        if arena_route_recovery_marker.get("status") == "pending":
            return False
    arena_source_refresh_marker = state.get(
        _OTAAR_ARENA_SOURCE_REFRESH_REVALIDATION_KEY
    )
    if (
        isinstance(arena_source_refresh_marker, Mapping)
        and arena_source_refresh_marker.get("policy_id") == candidate_policy_id
        and arena_source_refresh_marker.get("boot_id")
        == state.get("world_boot_id")
        and arena_source_refresh_marker.get("level")
        in {None, character_level}
        and arena_source_refresh_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
    ):
        if arena_source_refresh_marker.get("status") in {
            "attempted",
            "closed",
            "succeeded",
        }:
            # The source-refresh retry is one-shot. Keep the older timeout and
            # loss evidence intact even if the worker was interrupted.
            return True
        if arena_source_refresh_marker.get("status") == "pending":
            # The selector armed this exact retry from a complete current
            # source audit; all live route and combat gates still apply.
            return False
    arena_marker = state.get(_OTAAR_ARENA_FAVOUR_GATE_REVALIDATION_KEY)
    if (
        isinstance(arena_marker, Mapping)
        and arena_marker.get("policy_id") == candidate_policy_id
        and arena_marker.get("boot_id") == state.get("world_boot_id")
        and arena_marker.get("level") in {None, character_level}
        and arena_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
    ):
        if arena_marker.get("status") in {
            "attempted",
            "closed",
            "succeeded",
        }:
            # The corrected arena retry is one-shot. A worker interruption or
            # no-kill result must not replay the same changed contract.
            return True
        if arena_marker.get("status") == "pending":
            # The selector armed this exact retry from a source-matched,
            # no-loss favour-gate correction; ordinary live gates still run.
            return False
    wanderer_no_invis_marker = state.get(
        _SOURCE_RANKED_WANDERER_NO_INVIS_REVALIDATION_KEY
    )
    if (
        isinstance(wanderer_no_invis_marker, Mapping)
        and wanderer_no_invis_marker.get("policy_id") == candidate_policy_id
        and wanderer_no_invis_marker.get("boot_id")
        == state.get("world_boot_id")
        and wanderer_no_invis_marker.get("level") in {None, character_level}
        and wanderer_no_invis_marker.get("source_revision")
        == state.get(_SOURCE_REVISION_KEY)
    ):
        if wanderer_no_invis_marker.get("status") in {
            "attempted",
            "succeeded",
        }:
            # The source-corrected entry is one-shot. Preserve the original
            # preparation abort and do not turn it into a retry loop.
            return True
        if wanderer_no_invis_marker.get("status") == "closed":
            if (
                wanderer_no_invis_marker.get("policy_revision")
                < _SOURCE_RANKED_WANDERER_NO_INVIS_REVALIDATION_REVISION
                and wanderer_no_invis_marker.get("reason")
                == "the exact target did not pass the ordinary current-band selector"
                and wanderer_no_invis_marker.get("attempted") is not True
            ):
                # Revision 1 could close before the retry selector received
                # its own policy block-set exception. Permit that exact
                # pre-connection repair once under revision 2.
                return False
            return True
        if wanderer_no_invis_marker.get("status") == "pending":
            return False
    abyss_marker = state.get(_ABYSS_SAFE_FIDO_REVALIDATION_KEY)
    if (
        isinstance(abyss_marker, Mapping)
        and abyss_marker.get("policy_id") == candidate_policy_id
        and abyss_marker.get("boot_id") == state.get("world_boot_id")
        and abyss_marker.get("level") in {None, character_level}
    ):
        if abyss_marker.get("status") in {"attempted", "closed", "succeeded"}:
            # The marker is consumed before the socket opens. A worker
            # interruption must not replay the same changed-input route.
            return True
        if abyss_marker.get("status") == "pending":
            return False
    if _source_ranked_familiar_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # The familiar retry is consumed at segment start; a worker
        # interruption, a no-kill result, or even a completed kill must not
        # silently turn the one-shot changed contract into a repeat loop. A
        # later source/resource policy must establish a fresh combat contract.
        return True
    if _source_ranked_familiar_revalidation_pending(
        state,
        policy_id=candidate_policy_id,
    ):
        # A learned familiar is a changed combat contract, not a generic
        # protection bypass. The exact candidate still passes the familiar
        # probe before this marker can be armed.
        return False
    if _source_ranked_displaced_sentinel_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # The changed-input retry is consumed at segment start, so an
        # interruption cannot turn it into a repeat loop.
        return True
    if _source_ranked_displaced_sentinel_revalidation_pending(
        state,
        policy_id=candidate_policy_id,
    ):
        return False
    if _source_ranked_route_loss_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # A route-only retry is consumed at segment start, so a worker
        # interruption or a no-kill result must not reopen it.
        return True
    if _source_ranked_route_loss_revalidation_pending(
        state,
        policy_id=candidate_policy_id,
    ):
        # This exact marker is the sole exception to the ordinary current-
        # reboot loss quarantine; the selector armed it from route evidence
        # and the candidate still passes every source/live gate.
        return False
    if _source_ranked_damage_window_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # An interrupted one-use revalidation is closed by its durable start
        # marker; do not reopen the same route after a worker interruption.
        return True
    if _source_ranked_special_hp_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # The special-HP retry is likewise closed at segment start, even when
        # the worker is interrupted before a normal segment result is written.
        return True
    if _source_ranked_combat_output_revalidation_attempted(
        state,
        policy_id=candidate_policy_id,
    ):
        # A retired output retry is also closed by its durable marker. Its
        # target-specific HP evidence never becomes a same-reboot combat loop.
        return True
    if _source_ranked_combat_output_revalidation_allowed(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
    ):
        # Retired output-window retries never reopen an exact target after a
        # loss; fresh source/live selection must find it independently.
        return False
    if _source_ranked_special_hp_revalidation_pending(
        state,
        policy_id=candidate_policy_id,
    ):
        # This exact marker is the explicit exception to the current-reboot
        # loss quarantine; all source and live-entry gates still apply.
        return False
    if _source_ranked_partial_timeout_retry_candidate_allowed(
        candidate,
        state,
        character_level=character_level,
        character_max_hp=character_max_hp,
    ):
        # The marker is created only after a clean isolated exchange and is
        # consumed at the segment boundary; do not let the normal loss and
        # timeout quarantines hide its one allowed continuation.
        return False
    retry_marker = state.get(_PROTECTION_RECOVERY_RETRY_KEY)
    if (
        isinstance(retry_marker, Mapping)
        and retry_marker.get("boot_id") == state.get("world_boot_id")
        and retry_marker.get("level") in {None, character_level}
        and retry_marker.get("policy_id") == candidate_policy_id
        and retry_marker.get("attempted") is True
        and _source_ranked_xp_loss_record(state, candidate_policy_id)
        is not None
    ):
        return True
    protection_fallback_allowed = (
        allow_protection_recovery_fallback
        and _source_ranked_protection_recovery_fallback_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    familiar_probe_allowed = bool(
        source_world is not None
        and _source_ranked_familiar_probe_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    )
    safe_noncombat_timeout_special = bool(
        candidate.specials
        and candidate.autonomous_safe
        and set(candidate.specials) <= SAFE_NONCOMBAT_SPECIALS
        and source_world is not None
        and _source_ranked_aggressive_special_output_allowed(
            candidate,
            state,
            character_level=character_level,
            character_max_hp=character_max_hp,
            source_world=source_world,
        )
    )
    timeout_revalidation_exception = bool(
        candidate_policy_id
        == str(state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or "")
        and (candidate.autonomous_safe or familiar_probe_allowed)
        and (
            not candidate.specials
            or safe_noncombat_timeout_special
        )
    )
    fallback_marker = state.get(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY)
    if candidate_policy_id in (
        _source_ranked_protection_recovery_fallback_attempted_policy_ids(
            fallback_marker
        )
    ) and not protection_fallback_allowed and not timeout_revalidation_exception:
        # A fallback probe is a distinct-policy allowance. Once selected, its
        # policy must rotate out even when the candidate itself had no prior
        # loss record.
        return True
    timeout_revalidation_policy_id = str(
        state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or ""
    )
    timeout_revalidation_spent = any(
        isinstance(record, Mapping)
        and record.get("boot_id") == state.get("world_boot_id")
        and record.get("policy_id") == candidate_policy_id
        and record.get(_SOURCE_RANKED_TIMEOUT_REVALIDATION_FIELD) is True
        for record in (state.get(_SOURCE_RANKED_TIMEOUT_POLICIES_KEY) or ())
    )
    timeout_revalidation_productive = (
        _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        == "productive"
    )
    if (
        timeout_revalidation_spent
        and candidate_policy_id != timeout_revalidation_policy_id
        and not timeout_revalidation_productive
    ):
        # The one-shot repair was already dispatched. Protection fallback
        # must not turn an absent or interrupted result into a second try;
        # only a real productive result can return the route to normal rank.
        return True
    recovered_capacity = _source_ranked_recovered_interruption_candidate(
        candidate, state, character_level=character_level,
    )
    if (
        candidate_policy_id in _source_ranked_timeout_policy_ids(state)
        and _source_ranked_timeout_revalidation_exhausted(
            state,
            candidate_policy_id,
        )
        and not protection_fallback_allowed
        and not timeout_revalidation_productive
    ):
        return True
    if (
        candidate_policy_id in _source_ranked_timeout_policy_ids(state)
        and (
            candidate_policy_id != timeout_revalidation_policy_id
            or not (
                candidate.autonomous_safe
                or recovered_capacity
                or familiar_probe_allowed
            )
            or (
                bool(candidate.specials)
                and not safe_noncombat_timeout_special
            )
        )
        and not protection_fallback_allowed
    ):
        return True
    if (
        candidate_policy_id
        == str(state.get(_SOURCE_RANKED_REVALIDATION_POLICY_KEY) or "")
        and (
            candidate.autonomous_safe
            or recovered_capacity
            or familiar_probe_allowed
        )
        and (
            not candidate.specials
            or safe_noncombat_timeout_special
        )
    ):
        # A targeted repair marker is allowed one direct revalidation after a
        # single old loss.  Keep this exception source-safe and special-free;
        # durable timeout and second-loss quarantine still win above/below it.
        loss_record = _source_ranked_xp_loss_record(
            state,
            candidate_policy_id,
        )
        if loss_record is None or _source_ranked_xp_loss_count(loss_record) < 2:
            return False
    if candidate_policy_id in _source_ranked_xp_loss_policy_ids(state):
        # Permit one protected retry only after an unprotected first loss. A
        # protected failure or second loss is already complete route evidence;
        # otherwise the same bad route can consume a new potion on every
        # recovery cycle.
        loss_record = _source_ranked_xp_loss_record(
            state,
            candidate_policy_id,
        )
        if _source_ranked_xp_loss_was_protected(loss_record):
            return True
        if loss_record is not None and _source_ranked_xp_loss_count(
            loss_record
        ) >= 2:
            return True
        # Source-audited non-combat procedures such as fido and janitor do
        # not add an attack to the route. Keep them eligible for the same one
        # protected retry as an ordinary mobile when the candidate has no
        # other autonomy rejection. Combat-capable specials remain closed.
        safe_noncombat_special = bool(
            candidate.specials
            and candidate.autonomous_safe
            and set(candidate.specials) <= SAFE_NONCOMBAT_SPECIALS
        )
        if candidate.specials and not safe_noncombat_special:
            return True
        if protection_fallback_allowed:
            return False
        return not _state_has_sanctuary_reserve(state)
    if not _protection_recovery_required(state):
        return False
    record = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("level") not in {None, character_level}:
        return False
    policy_id = record.get("policy_id")
    if not isinstance(policy_id, str):
        return False
    if candidate_policy_id != policy_id:
        return False
    # The protection marker is also used by recovery policies that do not
    # have a source-hunt loss-ledger row of their own. Once the marker records
    # two failed exchanges, do not reopen that exact recovery route again.
    return _source_ranked_protection_recovery_loss_count(state, record) >= 2


def _source_ranked_protection_retry_productive_result_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    marker: Mapping[str, Any],
) -> bool:
    """Recognize the successful result of the one-shot protected retry."""
    if (
        marker.get("mobile_vnum") != candidate.mobile_vnum
        or marker.get("level") not in {None, character_level}
        or marker.get("boot_id") != state.get("world_boot_id")
    ):
        return False
    result = _campaign_research_results(state).get(
        _source_ranked_policy_id(candidate, character_level=character_level)
    )
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("observed") is True
        and result.get("consider_viable") is True
        and result.get("viable") is True
        and result.get("completed_kill") is True
        and not any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "fatal_failure",
                "route_hazard",
                "unattackable",
                "target_vnum_mismatch",
                "xp_loss_observed",
            )
        )
    ):
        return False
    try:
        maximum_kill_xp = int(result.get("max_objective_kill_xp") or 0)
    except (TypeError, ValueError):
        return False
    return bool(
        _source_ranked_multi_kill_reward_allowed(result)
        or maximum_kill_xp >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
    )


def _source_ranked_negative_incomplete_policy_ids(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    policy_xp_deltas: Mapping[str, int],
) -> frozenset[str]:
    """Defer current-reboot incomplete hunts whose latest result lost XP.

    A retryable research marker is normally useful for a route that reached a
    live target but ended without a kill. It must not, however, outrank a
    fresh target after the same policy has already produced a negative
    objective result. Explicit XP-loss records retain their separate
    sanctuary-protected retry contract.
    """
    boot_id = state.get("world_boot_id")
    research_results = _campaign_research_results(state)
    blocked: set[str] = set()
    for candidate in candidates:
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        try:
            latest_xp_delta = int(policy_xp_deltas.get(policy_id) or 0)
        except (TypeError, ValueError):
            latest_xp_delta = 0
        if latest_xp_delta >= 0:
            continue
        result = research_results.get(policy_id)
        if not isinstance(result, Mapping) or result.get("boot_id") != boot_id:
            continue
        if result.get("completed_kill") is True:
            continue
        if _source_ranked_xp_loss_record(state, policy_id) is not None:
            # The protection-recovery gate owns the one protected retry for a
            # first explicit loss and the durable quarantine after the second.
            continue
        if not (
            result.get("retryable_failure") is True
            or result.get("viable") is False
            or result.get("completed_kill") is False
        ):
            continue
        blocked.add(policy_id)
    return frozenset(blocked)


def _source_ranked_xp_loss_records(
    state: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    """Return source-hunt XP-loss records for the current reboot."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return ()
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        return ()
    return tuple(
        record
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and isinstance(record.get("policy_id"), str)
    )


def _campaign_profile_identity_matches(
    expected: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    """Match a saved campaign to the same character, not just its name."""
    for field in ("name", "race", "character_class", "subclass"):
        expected_value = str(expected.get(field) or "").strip().casefold()
        candidate_value = str(candidate.get(field) or "").strip().casefold()
        if field != "subclass" and not expected_value:
            return False
        if expected_value != candidate_value:
            return False
    return True


def _profile_source_kill_clears_loss(
    storage: RunStorage,
    *,
    character_profile_path: Path,
    character_state: Mapping[str, Any],
    policy_id: str,
    loss_event_id: int,
) -> bool:
    boot_id = character_state.get("world_boot_id")
    if not isinstance(boot_id, str) or not boot_id:
        return False
    loader = getattr(storage, "list_profile_source_kill_segments_after", None)
    if not callable(loader):
        return False
    try:
        segments = loader(
            character_profile_path,
            character_name=str(character_state.get("name") or ""),
            boot_id=boot_id,
            policy_id=policy_id,
            after_segment_id=loss_event_id,
        )
    except (AttributeError, TypeError, ValueError):
        return False
    expected_level = _level(character_state)
    for raw_segment in segments:
        segment = (
            raw_segment
            if isinstance(raw_segment, Mapping)
            else {key: raw_segment[key] for key in raw_segment.keys()}
        )
        if (
            segment.get("status") not in {"success", "ready"}
            or segment.get("run_id") is None
        ):
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if (
            not _campaign_profile_identity_matches(character_state, start)
            or not _campaign_profile_identity_matches(character_state, end)
            or start.get("world_boot_id") != boot_id
            or end.get("world_boot_id") != boot_id
            or _level(start) != expected_level
            or _level(end) != expected_level
            or _xp_delta(start, end) <= 0
        ):
            continue
        objective_kills = _segment_objective_kills(storage, segment)
        if policy_id not in _source_ranked_kill_policy_ids(objective_kills):
            continue
        failed_policy_ids = set(source_combat_loss_records(end))
        if (
            _xp_loss_event_observed(start, end)
            and not failed_policy_ids
        ) or policy_id in failed_policy_ids:
            continue
        return True
    return False


def _reconcile_same_profile_source_ranked_losses(
    storage: RunStorage,
    *,
    campaign_id: int,
    character_profile_path: Path,
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Carry exact current-band losses across duplicate campaign records."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    if (
        not isinstance(boot_id, str)
        or not boot_id
        or level <= 0
        or not _campaign_profile_identity_matches(state, state)
    ):
        return dict(state)
    loader = getattr(storage, "list_latest_campaign_checkpoints_for_profile", None)
    if not callable(loader):
        return dict(state)
    try:
        checkpoints = loader(
            character_profile_path,
            exclude_campaign_id=campaign_id,
        )
    except (AttributeError, TypeError, ValueError):
        return dict(state)

    sources: list[Mapping[str, Any]] = [state]
    for checkpoint in checkpoints:
        try:
            foreign_state = json.loads(checkpoint["state_json"])
        except (KeyError, TypeError, json.JSONDecodeError):
            continue
        if (
            not isinstance(foreign_state, Mapping)
            or not _campaign_profile_identity_matches(state, foreign_state)
            or foreign_state.get("world_boot_id") != boot_id
            or _level(foreign_state) != level
        ):
            continue
        sources.append(foreign_state)

    grouped: dict[str, list[dict[str, Any]]] = {}
    historical_records = [
        dict(record)
        for record in _source_ranked_xp_loss_records(state)
        if record.get("level") != level
    ]
    for source in sources:
        for raw_record in _source_ranked_xp_loss_records(source):
            policy_id = str(raw_record.get("policy_id") or "")
            if (
                not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                or raw_record.get("level") != level
            ):
                continue
            record = dict(raw_record)
            try:
                loss_event_id = int(record.get("loss_event_id"))
            except (TypeError, ValueError):
                loss_event_id = 0
            if (
                loss_event_id > 0
                and _profile_source_kill_clears_loss(
                    storage,
                    character_profile_path=character_profile_path,
                    character_state=state,
                    policy_id=policy_id,
                    loss_event_id=loss_event_id,
                )
            ):
                continue
            grouped.setdefault(policy_id, []).append(record)

    def loss_event_id(record: Mapping[str, Any]) -> int:
        try:
            return int(record.get("loss_event_id"))
        except (TypeError, ValueError):
            return 0

    merged_records: list[dict[str, Any]] = list(historical_records)
    for policy_id, records in grouped.items():
        records.sort(
            key=lambda record: (
                loss_event_id(record) > 0,
                loss_event_id(record),
            )
        )
        merged = dict(records[-1])
        merged["loss_count"] = max(
            max(_source_ranked_xp_loss_count(record) for record in records),
            len({loss_event_id(record) for record in records if loss_event_id(record) > 0}),
        )
        if any(_source_ranked_xp_loss_was_protected(record) for record in records):
            merged["sanctuary_protected"] = True
        if any(loss_event_id(record) <= 0 for record in records):
            merged.pop("loss_event_id", None)
        merged_records.append(merged)
    merged_records.sort(
        key=lambda record: (
            loss_event_id(record),
            str(record.get("policy_id") or ""),
        )
    )
    updated = dict(state)
    original = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if merged_records:
        if original == merged_records:
            return updated
        updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = merged_records
    elif original:
        updated.pop(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY, None)
    return updated


def _source_ranked_xp_loss_record(
    state: Mapping[str, Any],
    policy_id: str,
) -> Mapping[str, Any] | None:
    """Return one current-reboot loss record for an exact source policy."""
    return next(
        (
            record
            for record in _source_ranked_xp_loss_records(state)
            if record.get("policy_id") == policy_id
        ),
        None,
    )


def _source_ranked_xp_loss_for_stop(
    state: Mapping[str, Any],
    *,
    mobile_vnum: int,
    room_vnum: int,
) -> Mapping[str, Any] | None:
    """Return current-boot XP loss evidence for one exact source stop."""
    try:
        expected_identity = (int(mobile_vnum), int(room_vnum), _level(state))
    except (TypeError, ValueError):
        return None
    return next(
        (
            record
            for record in _source_ranked_xp_loss_records(state)
            if source_stop_identity(str(record.get("policy_id") or ""))
            == expected_identity
        ),
        None,
    )


def _source_ranked_xp_loss_was_protected(
    record: Mapping[str, Any] | None,
) -> bool:
    """Return whether sanctuary already failed to make this route viable."""
    return bool(
        isinstance(record, Mapping)
        and record.get("sanctuary_protected") is True
    )


def _source_ranked_loss_used_sanctuary(state: Mapping[str, Any]) -> bool:
    """Recover explicit or legacy evidence that a failed fight had sanctuary."""
    return bool(
        state.get("campaign_fastwalk_sanctuary_consumed_in_combat") is True
        or _has_named_affect(state.get("affects"), "sanctuary")
    )


def _record_source_ranked_protection_recovery_retry(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> None:
    """Spend the one protected retry when its exact route is selected.

    A route can fail before combat starts, for example when a live endpoint
    reveals a poison-capable bystander. That is still an attempted recovery
    retry: remembering the selection prevents the next segment from reopening
    the same route while preserving the reserve for an independent candidate.
    """
    protection = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(protection, Mapping):
        if not _source_ranked_unprotected_reserve_retry_allowed(
            candidate,
            state,
            character_level=character_level,
        ):
            return
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        state[_PROTECTION_RECOVERY_RETRY_KEY] = {
            "boot_id": state.get("world_boot_id"),
            "level": character_level,
            "policy_id": policy_id,
            "attempted": True,
            "reason": "one Sanctuary-backed retry after an unprotected first loss",
        }
        return
    if (
        protection.get("boot_id") != state.get("world_boot_id")
        or protection.get("level") not in {None, character_level}
    ):
        return
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if str(protection.get("policy_id") or "") != policy_id:
        return
    loss_record = _source_ranked_xp_loss_record(state, policy_id)
    if (
        loss_record is None
        or _source_ranked_xp_loss_count(loss_record) != 1
        or _source_ranked_xp_loss_was_protected(loss_record)
        or not _state_has_sanctuary_reserve(state)
    ):
        return
    existing = state.get(_PROTECTION_RECOVERY_RETRY_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == state.get("world_boot_id")
        and existing.get("policy_id") == policy_id
        and existing.get("level") in {None, character_level}
    ):
        return
    state[_PROTECTION_RECOVERY_RETRY_KEY] = {
        "boot_id": state.get("world_boot_id"),
        "level": character_level,
        "policy_id": policy_id,
        "attempted": True,
        "reason": "one protected recovery retry selected",
    }


def _source_ranked_xp_loss_count(record: Mapping[str, Any]) -> int:
    """Return the number of current-reboot losses represented by a record."""
    try:
        return max(1, int(record.get("loss_count") or 1))
    except (TypeError, ValueError):
        return 1


_SOURCE_RANKED_ROUTE_ONLY_LOSS_HAZARD_PREFIX = (
    "transit below-band attacker:"
)


def _source_ranked_state_has_objective_kills(
    state: Mapping[str, Any],
) -> bool:
    """Ignore incidental below-band kills when classifying a route loss."""
    for key in ("campaign_objective_kills", "campaign_completed_kills", "completed_kills"):
        value = state.get(key)
        if not value:
            continue
        if not isinstance(value, (list, tuple)):
            return True
        for kill in value:
            if isinstance(kill, Mapping) and kill.get("objective_eligible") is False:
                continue
            return True
    return False


def _source_ranked_route_only_loss_hazards(
    state: Mapping[str, Any],
    *,
    policy_id: str | None = None,
) -> tuple[str, ...]:
    """Return exact evidence for a pre-combat transit-only XP loss.

    This is intentionally stricter than the ordinary loss ledger.  A retry is
    useful only when the target was never engaged, the character returned in
    good health, and the sole recorded hazard was a source-labelled
    below-band transit interruption.
    """
    if policy_id and not str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return ()
    if any(
        state.get(key)
        for key in (
            "dead",
            "died_during_run",
            "campaign_died",
            "in_combat",
            "combat_target",
            "enemies",
        )
    ):
        return ()
    if _source_ranked_state_has_objective_kills(state):
        return ()
    if state.get("campaign_fastwalk_target_present_observed") is not False:
        return ()
    if state.get("campaign_fastwalk_target_absent") is True:
        return ()
    outcomes = state.get("campaign_fastwalk_consider_outcomes")
    if isinstance(outcomes, Mapping) and any(
        value is True for value in outcomes.values()
    ):
        return ()
    try:
        hp = int(state.get("hp"))
        max_hp = int(state.get("max_hp"))
    except (TypeError, ValueError):
        return ()
    if max_hp <= 0 or hp <= 0 or hp * 10 < max_hp * 9:
        return ()
    raw_hazards = state.get("campaign_fastwalk_route_hazards")
    if not isinstance(raw_hazards, (list, tuple, set, frozenset)):
        return ()
    hazards = tuple(
        sorted(
            {
                str(hazard).strip()
                for hazard in raw_hazards
                if str(hazard).strip()
            }
        )
    )
    if len(hazards) != 1 or not hazards[0].casefold().startswith(
        _SOURCE_RANKED_ROUTE_ONLY_LOSS_HAZARD_PREFIX
    ):
        return ()
    abort_reason = " ".join(
        str(state.get("campaign_fastwalk_abort_reason") or "")
        .casefold()
        .split()
    )
    if "field hunt" not in abort_reason or "recalled" not in abort_reason:
        return ()
    return hazards


def _source_ranked_route_loss_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether the one-shot route-loss retry has been consumed."""
    marker = state.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("policy_id") == policy_id
        and marker.get("status") in {"attempted", "closed", "succeeded"}
    )


def _source_ranked_endpoint_revalidation_result(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> Mapping[str, Any] | None:
    """Return one exact, no-combat endpoint-observation failure."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return None
    hazard = " ".join(str(result.get("route_hazard") or "").casefold().split())
    if (
        result.get("boot_id") != state.get("world_boot_id")
        or result.get("observed") is not False
        or result.get("viable") is not False
        or not hazard.startswith(_SOURCE_RANKED_ENDPOINT_NOT_OBSERVED_PREFIX)
        or any(
            result.get(key)
            for key in (
                "absent",
                "crowded",
                "crowd_exhausted",
                "unattackable",
                "target_vnum_mismatch",
                "consider_viable",
                "completed_kill",
                "xp_loss_observed",
            )
        )
    ):
        return None
    return result


def _source_ranked_endpoint_revalidation_attempted(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether the exact endpoint retry has already been consumed."""
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") in {"attempted", "closed", "succeeded"}
    )


def _source_ranked_endpoint_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether one exact endpoint retry is ready for dispatch."""
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    )


def _source_ranked_endpoint_revalidation_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    """Admit one plain source route whose endpoint was not observed."""
    if source_world is None:
        return False
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    if (
        candidate.status == "reject"
        or not candidate.autonomous_safe
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.route_preflight_hard_hazard
        or candidate.route_hard_hazard_targets
        or not (
            1
            <= candidate.source_spawn_limit
            <= _SOURCE_CAPACITY_RESEARCH_MAX_GLOBAL_POPULATION
        )
        or candidate.room_spawn_count != 1
        or _source_ranked_xp_loss_record(state, policy_id) is not None
        or _source_ranked_endpoint_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        ) is None
        or not _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            allow_repeated_kills=True,
        )
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    room = source_world.rooms.get(candidate.room_vnum)
    if (
        mobile is None
        or room is None
        or mobile.aggressive
        or mobile.programs
        or source_world.mobile_specials.get(candidate.mobile_vnum)
    ):
        return False
    return True


def _source_ranked_endpoint_frontier_is_closed(
    candidates: Collection[HuntCandidate],
    state: Mapping[str, Any],
    *,
    character_level: int,
    source_world: WorldSource,
) -> bool:
    """Avoid pre-empting a normal current-band route with route repair."""
    for candidate in candidates:
        if (
            not candidate.autonomous_safe
            or candidate.specials
            or candidate.equipped_weapons
            or candidate.source_spawn_limit != 1
            or candidate.room_spawn_count != 1
            or candidate.route_preflight_hard_hazard
            or candidate.route_hard_hazard_targets
        ):
            continue
        policy_id = _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
        if _source_ranked_endpoint_revalidation_result(
            state,
            candidate,
            character_level=character_level,
        ) is not None:
            continue
        if _source_ranked_xp_loss_record(state, policy_id) is not None:
            continue
        if not _source_ranked_candidate_in_current_band(
            candidate,
            state,
            world=source_world,
            character_level=character_level,
            allow_repeated_kills=True,
        ):
            continue
        if (
            _source_ranked_candidate_requires_sanctuary_for_state(
                candidate,
                state,
                character_level=character_level,
                source_world=source_world,
            )
            and not _state_has_sanctuary_reserve(state)
        ):
            continue
        status = _source_ranked_result_status(
            candidate,
            state,
            character_level=character_level,
        )
        if (
            status == "fresh"
            and _source_ranked_useful_fuzz_probability(
                candidate,
                character_level=character_level,
            )
            < _SOURCE_RANKED_MIN_FRESH_USEFUL_FUZZ_PROBABILITY
        ):
            # A source range that only occasionally reaches the useful band
            # is research, not an executable current-band route.
            continue
        if status in {"fresh", "productive", "retryable"}:
            return False
    return True


def _arm_source_ranked_endpoint_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    source_world: WorldSource | None,
) -> dict[str, Any]:
    """Arm one exact no-combat route endpoint recheck at a closed frontier."""
    boot_id = state.get("world_boot_id")
    if boot_id is None or source_world is None or not candidates:
        return state
    existing = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and existing.get("status") in {"pending", "attempted", "closed", "succeeded"}
    ):
        return state
    eligible = [
        candidate
        for candidate in candidates
        if _source_ranked_endpoint_revalidation_candidate_allowed(
            candidate,
            state,
            character_level=character_level,
            source_world=source_world,
        )
    ]
    if not eligible:
        return state
    candidate = max(
        eligible,
        key=lambda item: (
            float(item.score),
            item.estimated_level_range[1],
            -len(item.route),
            item.source_value,
        ),
    )
    state[_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY] = {
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        ),
        "source_revision": state.get(_SOURCE_REVISION_KEY),
        "source_mobile_vnum": candidate.mobile_vnum,
        "source_room_vnum": candidate.room_vnum,
        "route_hazard": str(
            _source_ranked_endpoint_revalidation_result(
                state,
                candidate,
                character_level=character_level,
            ).get("route_hazard")
        ),
        "status": "pending",
        "reason": "one exact retry after a safe route endpoint was not observed",
    }
    return state


def _mark_source_ranked_endpoint_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the endpoint retry immediately before live dispatch."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("source_revision") == state.get(_SOURCE_REVISION_KEY)
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    ):
        return False
    state[_SOURCE_RANKED_ENDPOINT_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _source_ranked_route_loss_revalidation_pending(
    state: Mapping[str, Any],
    *,
    policy_id: str,
) -> bool:
    """Return whether the one-shot route-loss retry remains available."""
    marker = state.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
    return bool(
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, _level(state)}
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    )


def _mark_source_ranked_route_loss_revalidation(
    state: dict[str, Any],
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> bool:
    """Consume the route-loss retry immediately before live dispatch."""
    policy_id = _source_ranked_policy_id(
        candidate,
        character_level=character_level,
    )
    marker = state.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
    if not (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
        and marker.get("level") in {None, character_level}
        and marker.get("policy_id") == policy_id
        and marker.get("status") == "pending"
    ):
        return False
    state[_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY] = {
        **dict(marker),
        "status": "attempted",
        "attempted": True,
    }
    return True


def _source_ranked_route_loss_revalidation_candidate_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
) -> bool:
    """Admit one plain target for a route-only retry."""
    if (
        source_world is None
        or character_max_hp is None
        or character_max_hp <= 0
        or candidate.status == "reject"
        or not candidate.autonomous_safe
        or candidate.is_coin_stash
        or candidate.is_food_stash
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.route_hard_hazard_targets
        or candidate.route_special_mobile_vnums
        or candidate.source_spawn_limit != 1
        or candidate.room_spawn_count != 1
        or candidate.boot_kills >= 3
    ):
        return False
    if not _source_ranked_candidate_in_current_band(
        candidate,
        state,
        world=source_world,
        character_level=character_level,
        character_max_hp=character_max_hp,
        allow_repeated_kills=True,
    ):
        return False
    if not _source_candidate_fits_movement(
        candidate,
        state,
        world=source_world,
    ):
        return False
    if not _source_ranked_route_aggressors_are_bounded(
        candidate,
        character_level=character_level,
        source_world=source_world,
        character_max_hp=character_max_hp,
    ):
        return False
    if candidate.route_preflight_hard_hazard and not (
        _source_ranked_route_program_candidate_allowed(
            candidate,
            character_level=character_level,
            source_world=source_world,
        )
    ):
        return False
    mobile = source_world.mobiles.get(candidate.mobile_vnum)
    room = source_world.rooms.get(candidate.room_vnum)
    if mobile is None or room is None:
        return False
    if (
        mobile.aggressive
        or mobile.attack_programs
        or source_world.mobile_specials.get(mobile.vnum)
        or _source_ranked_normalized_target(candidate.target)
        != _source_ranked_normalized_target(mobile.short_description)
        or _source_ranked_target_identity(candidate)
        != _source_ranked_normalized_target(mobile.short_description)
    ):
        return False
    return True


def _source_ranked_route_loss_hazards_from_segments(
    state: Mapping[str, Any],
    record: Mapping[str, Any],
    segments: Collection[Any],
) -> tuple[str, ...]:
    """Recover route-only evidence for a legacy loss record."""
    raw_hazards = record.get("route_loss_hazards")
    if record.get("route_only_loss") is True and isinstance(
        raw_hazards, (list, tuple)
    ):
        hazards = tuple(str(value).strip() for value in raw_hazards if str(value).strip())
        if hazards:
            return hazards
    policy_id = str(record.get("policy_id") or "")
    raw_loss_event_id = record.get("loss_event_id")
    for raw_segment in reversed(tuple(segments)):
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {key: raw_segment[key] for key in raw_segment.keys()}
            except (AttributeError, KeyError, TypeError):
                continue
        if str(segment.get("phase") or "") != policy_id:
            continue
        if raw_loss_event_id is not None and str(segment.get("id")) != str(
            raw_loss_event_id
        ):
            continue
        try:
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end, Mapping) or end.get("world_boot_id") != state.get(
            "world_boot_id"
        ):
            continue
        hazards = _source_ranked_route_only_loss_hazards(
            end,
            policy_id=policy_id,
        )
        if hazards:
            return hazards
    return ()


def _arm_source_ranked_route_loss_revalidation(
    state: dict[str, Any],
    candidates: Collection[HuntCandidate],
    *,
    character_level: int,
    character_max_hp: int | None,
    source_world: WorldSource | None,
    segments: Collection[Any] = (),
) -> dict[str, Any]:
    """Arm one exact retry after a pre-combat transit loss."""
    boot_id = state.get("world_boot_id")
    if (
        boot_id is None
        or character_max_hp is None
        or character_max_hp <= 0
        or not candidates
    ):
        return state
    existing = state.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
        and existing.get("level") in {None, character_level}
        and existing.get("status") in {"pending", "attempted", "closed", "succeeded"}
    ):
        return state
    eligible: list[tuple[float, HuntCandidate, Mapping[str, Any], tuple[str, ...]]] = []
    for record in _source_ranked_xp_loss_records(state):
        if (
            record.get("level") not in {None, character_level}
            or _source_ranked_xp_loss_count(record) != 1
            or _source_ranked_xp_loss_was_protected(record)
        ):
            continue
        hazards = _source_ranked_route_loss_hazards_from_segments(
            state,
            record,
            segments,
        )
        if not hazards:
            continue
        policy_id = str(record.get("policy_id") or "")
        for candidate in candidates:
            if (
                _source_ranked_policy_id(
                    candidate,
                    character_level=character_level,
                )
                != policy_id
                or _source_ranked_candidate_has_absence_cooldown(
                    candidate,
                    state,
                    character_level=character_level,
                )
                or not _source_ranked_route_loss_revalidation_candidate_allowed(
                    candidate,
                    state,
                    character_level=character_level,
                    character_max_hp=character_max_hp,
                    source_world=source_world,
                )
            ):
                continue
            eligible.append((float(candidate.score), candidate, record, hazards))
    if not eligible:
        return state
    _score, candidate, record, hazards = max(
        eligible,
        key=lambda item: (
            item[0],
            item[1].estimated_level_range[1],
            -len(item[1].route),
        ),
    )
    updated = dict(state)
    if record.get("route_only_loss") is not True:
        updated = _remember_source_ranked_xp_loss(
            updated,
            policy_id=str(record.get("policy_id") or ""),
            level=character_level,
            boot_id=boot_id,
            xp_delta=int(record.get("xp_delta") or 0),
            observed_loss_count=1,
            loss_event_id=record.get("loss_event_id"),
            sanctuary_protected=False,
            route_only_loss=True,
            route_loss_hazards=hazards,
        )
    updated[_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY] = {
        "boot_id": boot_id,
        "level": character_level,
        "policy_id": str(record.get("policy_id") or ""),
        "source_revision": updated.get(_SOURCE_REVISION_KEY),
        "loss_event_id": record.get("loss_event_id"),
        "source_mobile_vnum": candidate.mobile_vnum,
        "source_room_vnum": candidate.room_vnum,
        "route_loss_hazards": list(hazards),
        "status": "pending",
        "reason": (
            "one source-backed retry after a pre-combat transit-only XP loss"
        ),
    }
    # The runner passes its live checkpoint dictionary through several
    # preparation helpers before dispatch; preserve the marker on that same
    # object so the later segment-boundary consumer can persist it.
    state.clear()
    state.update(updated)
    return state


def _repair_campaign_xp_loss_total(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Retain durable loss counters and verified per-segment loss floors."""
    highest = _campaign_xp_loss_total(state) or 0
    for segment in campaign_segments:
        endpoints: dict[str, Mapping[str, Any]] = {}
        for state_field in ("start_state_json", "end_state_json"):
            if isinstance(segment, Mapping):
                raw_state = segment.get(state_field)
            else:
                try:
                    raw_state = segment[state_field]
                except (KeyError, IndexError, TypeError):
                    raw_state = None
            if not isinstance(raw_state, str):
                continue
            try:
                segment_state = json.loads(raw_state)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if not isinstance(segment_state, Mapping):
                continue
            endpoints[state_field] = segment_state
            highest = max(highest, _campaign_xp_loss_total(segment_state) or 0)
            observed = bool(
                segment_state.get("xp_loss_observed")
                or segment_state.get("campaign_xp_loss_observed")
            )
            segment_total = _xp_loss_total(segment_state)
            if observed and segment_total is not None:
                highest = max(highest, segment_total)
        start = endpoints.get("start_state_json", {})
        end = endpoints.get("end_state_json", {})
        # Use each saved starting counter, never the running high-water mark:
        # overlapping history windows must not charge a disconnected loss twice.
        highest = max(
            highest,
            (_campaign_xp_loss_total(start) or 0)
            + _verified_net_xp_loss(start, end),
        )
    if highest <= 0 or highest == (_campaign_xp_loss_total(state) or 0):
        return dict(state)
    updated = dict(state)
    updated["campaign_xp_loss_total"] = highest
    return updated


def _repair_source_ranked_xp_loss_attempt_counts(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
    *,
    storage: RunStorage | None = None,
    campaign_id: int | None = None,
    source_world: WorldSource | None = None,
) -> dict[str, Any]:
    """Rebuild exact loss counts without replaying one segment repeatedly.

    Normal startup only loads a bounded segment tail. When storage is
    available, fetch the complete history for the policies already recorded
    in the loss ledger so an old inflated count can be corrected safely.
    """
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return dict(state)

    policy_ids = {
        str(record.get("policy_id") or "")
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and record.get("policy_id")
    }
    segments_to_scan: Collection[Mapping[str, Any]] = campaign_segments
    if storage is not None and campaign_id is not None and policy_ids:
        try:
            index_available = getattr(
                storage,
                "campaign_phase_index_available",
                None,
            )
            if callable(index_available) and not index_available():
                complete_segments = []
            else:
                complete_segments = storage.list_campaign_segments_for_phases(
                    campaign_id,
                    policy_ids,
                )
        except (AttributeError, OSError, sqlite3.Error):
            complete_segments = []
        if complete_segments:
            segments_to_scan = complete_segments

    observed = Counter()
    observed_sanctuary_protected: set[str] = set()
    observed_output_revalidation_losses: set[tuple[str, str | None]] = set()
    observed_segment_ids: dict[str, set[str]] = {}
    loss_segment_end_states: dict[tuple[str, str], Mapping[str, Any]] = {}
    for index, segment in enumerate(segments_to_scan):
        try:
            phase = str(segment["phase"] or "")
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (KeyError, TypeError, json.JSONDecodeError):
            continue
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if not isinstance(start, dict) or not isinstance(end, dict):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        for segment_state in (start, end):
            marker = segment_state.get(
                _SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY
            )
            loss_record = _source_ranked_xp_loss_record(
                segment_state,
                phase,
            )
            evidence = (
                loss_record.get("target_hp_evidence")
                if isinstance(loss_record, Mapping)
                else None
            )
            if (
                not isinstance(marker, Mapping)
                or not isinstance(loss_record, Mapping)
                or not isinstance(evidence, Mapping)
                or marker.get("attempted") is not True
                or marker.get("boot_id") != boot_id
                or marker.get("level") not in {None, loss_record.get("level")}
                or marker.get("policy_id") != phase
                or marker.get("target") != evidence.get("target")
                or marker.get("mobile_vnum") != evidence.get("mobile_vnum")
                or marker.get("room_vnum") != evidence.get("room_vnum")
                or marker.get("observed_max_hp")
                != evidence.get("observed_max_hp")
                or marker.get("previous_output_ceiling")
                != evidence.get("source_output_ceiling")
                or (
                    marker.get("revalidation_loss_event_id") is not None
                    and marker.get("revalidation_loss_event_id")
                    != loss_record.get("loss_event_id")
                )
            ):
                continue
            observed_loss_event = loss_record.get("loss_event_id")
            observed_output_revalidation_losses.add(
                (
                    phase,
                    str(observed_loss_event)
                    if observed_loss_event is not None
                    else None,
                )
            )
        has_loss = _xp_delta(start, end) < 0 or _xp_loss_event_observed(start, end)
        failed_policy_ids = tuple(source_combat_loss_records(end)) if has_loss else ()
        if not failed_policy_ids and has_loss and not _segment_objective_kills(None, segment):
            failed_policy_ids = (phase,)
        for failed_policy_id in failed_policy_ids:
            try:
                raw_segment_id = segment["id"]
            except (KeyError, IndexError, TypeError):
                raw_segment_id = None
            segment_id = (
                str(raw_segment_id)
                if raw_segment_id is not None
                else f"tail-{index}"
            )
            seen_ids = observed_segment_ids.setdefault(failed_policy_id, set())
            if segment_id in seen_ids:
                continue
            seen_ids.add(segment_id)
            observed[failed_policy_id] += 1
            loss_segment_end_states[(failed_policy_id, segment_id)] = end
            if _source_ranked_loss_used_sanctuary(end):
                observed_sanctuary_protected.add(failed_policy_id)

    updated_records: list[dict[str, Any]] = []
    changed = False
    for raw_record in raw_records:
        if not isinstance(raw_record, Mapping):
            continue
        record = dict(raw_record)
        if record.get("boot_id") == boot_id:
            policy_id = str(record.get("policy_id") or "")
            observed_count = int(observed.get(policy_id, 0))
            loss_count = (
                observed_count
                if observed_count > 0
                else _source_ranked_xp_loss_count(record)
            )
            if record.get("exact_stop_loss") is True:
                # Phase indexes omit secondary circuit stops. Their verified
                # counts cannot be reduced by an incomplete parent-phase scan.
                loss_count = max(loss_count, _source_ranked_xp_loss_count(record))
            if record.get("loss_count") != loss_count:
                record["loss_count"] = loss_count
                changed = True
            loss_event_id = record.get("loss_event_id")
            if (
                (
                    policy_id,
                    str(loss_event_id) if loss_event_id is not None else None,
                )
                in observed_output_revalidation_losses
            ):
                if record.get("combat_output_revalidation_attempted") is not True:
                    record["combat_output_revalidation_attempted"] = True
                    changed = True
                if (
                    loss_event_id is not None
                    and record.get("combat_output_revalidation_loss_event_id")
                    != loss_event_id
                ):
                    record["combat_output_revalidation_loss_event_id"] = (
                        loss_event_id
                    )
                    changed = True
            if (
                policy_id in observed_sanctuary_protected
                and not _source_ranked_xp_loss_was_protected(record)
            ):
                record["sanctuary_protected"] = True
                changed = True
            old_evidence = record.get("target_hp_evidence")
            if (
                source_world is not None
                and record.get("level") == _level(state)
                and _source_ranked_xp_loss_count(record) == 1
                and isinstance(old_evidence, Mapping)
                and old_evidence.get("failure_kind") == "damage_window"
                and not old_evidence.get("source_output_ceiling")
            ):
                raw_loss_event_id = record.get("loss_event_id")
                segment_state = (
                    loss_segment_end_states.get(
                        (policy_id, str(raw_loss_event_id))
                    )
                    if raw_loss_event_id is not None
                    else None
                )
                if (
                    segment_state is not None
                    and segment_state.get("world_boot_id") == boot_id
                    and _level(dict(segment_state)) == record.get("level")
                ):
                    rebuilt = _source_ranked_target_hp_gate_evidence(
                        segment_state,
                        policy_id=policy_id,
                        source_world=source_world,
                    )
                    if (
                        rebuilt is not None
                        and rebuilt.get("failure_kind") == "damage_window"
                        and rebuilt.get("source_output_ceiling", 0) > 0
                        and all(
                            rebuilt.get(key) == old_evidence.get(key)
                            for key in (
                                "target",
                                "mobile_vnum",
                                "room_vnum",
                                "observed_max_hp",
                            )
                        )
                    ):
                        repaired_evidence = {
                            **dict(old_evidence),
                            "source_output_ceiling": rebuilt[
                                "source_output_ceiling"
                            ],
                        }
                        if rebuilt.get("source_revision"):
                            repaired_evidence["source_revision"] = rebuilt[
                                "source_revision"
                            ]
                        if rebuilt.get("weapon"):
                            repaired_evidence["weapon"] = rebuilt["weapon"]
                        record["target_hp_evidence"] = repaired_evidence
                        changed = True
        updated_records.append(record)
    if not changed:
        return dict(state)
    updated = dict(state)
    updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = updated_records
    return updated


def _source_ranked_xp_loss_policy_ids(
    state: Mapping[str, Any],
) -> set[str]:
    """Return exact source-hunt policies blocked by a current-reboot XP loss."""
    return {
        str(record["policy_id"])
        for record in _source_ranked_xp_loss_records(state)
    }


def _source_ranked_unsafe_terminal_state(
    state: Mapping[str, Any],
) -> bool:
    """Recognize a source hunt that ended in a plainly unsafe state.

    A live segment can recover from Purgatory before its final snapshot.  The
    durable death marker is therefore part of the unsafe evidence even when
    the character is healthy at the healer by segment completion.
    """
    return bool(
        state.get("dead") in {True, 1}
        or str(state.get("area") or "").strip().casefold() == "purgatory"
        or state.get("campaign_died_during_segment") in {True, 1}
    )


def _source_ranked_unsafe_policy_ids(
    state: Mapping[str, Any],
    *,
    boot_id: Any = None,
    level: int | None = None,
) -> set[str]:
    """Return same-boot source policies whose route ended unsafely."""
    expected_boot = state.get("world_boot_id") if boot_id is None else boot_id
    expected_level = _level(state) if level is None else level
    if expected_boot is None or expected_level <= 0:
        return set()
    raw_records = state.get(_SOURCE_RANKED_UNSAFE_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        return set()
    return {
        str(record.get("policy_id") or "")
        for record in raw_records
        if (
            isinstance(record, Mapping)
            and record.get("boot_id") == expected_boot
            and record.get("level") == expected_level
            and str(record.get("policy_id") or "").startswith(
                _SOURCE_RANKED_POLICY_PREFIX
            )
        )
    }


def _remember_source_ranked_unsafe_policy(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    reason: str,
    segment_id: Any = None,
) -> dict[str, Any]:
    """Quarantine one source route that ended dead or in Purgatory."""
    if (
        not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        or boot_id is None
        or level <= 0
    ):
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_UNSAFE_POLICIES_KEY)
    records = [
        dict(record)
        for record in raw_records
        if isinstance(record, Mapping)
    ] if isinstance(raw_records, (list, tuple)) else []
    if any(
        record.get("boot_id") == boot_id
        and record.get("level") == level
        and record.get("policy_id") == policy_id
        for record in records
    ):
        return dict(state)
    record: dict[str, Any] = {
        "boot_id": boot_id,
        "level": level,
        "policy_id": policy_id,
        "reason": reason,
    }
    if segment_id is not None:
        record["segment_id"] = segment_id
    updated = dict(state)
    updated[_SOURCE_RANKED_UNSAFE_POLICIES_KEY] = [*records, record][-64:]
    return updated


def _repair_source_ranked_unsafe_policy_ledger(
    state: Mapping[str, Any],
    segments: Collection[Any],
) -> dict[str, Any]:
    """Rebuild unsafe route quarantine from the campaign's durable segments."""
    boot_id = state.get("world_boot_id")
    level = _level(state)
    if boot_id is None or level <= 0:
        return dict(state)
    repaired = dict(state)
    for raw_segment in segments:
        if isinstance(raw_segment, Mapping):
            segment = raw_segment
        else:
            try:
                segment = {
                    key: raw_segment[key]
                    for key in raw_segment.keys()
                }
            except (AttributeError, KeyError, TypeError):
                continue
        phase = str(segment.get("phase") or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if str(segment.get("safety_outcome") or "").casefold() == "safe":
            continue
        try:
            end_state = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        if (
            end_state.get("world_boot_id") != boot_id
            or _level(end_state) != level
            or not _source_ranked_unsafe_terminal_state(end_state)
        ):
            continue
        repaired = _remember_source_ranked_unsafe_policy(
            repaired,
            policy_id=phase,
            level=level,
            boot_id=boot_id,
            reason="source-ranked segment ended dead or in Purgatory",
            segment_id=segment.get("id"),
        )
    return repaired


def _remember_source_ranked_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    xp_delta: int,
    source_revision: str | None = None,
    observed_loss_count: int | None = None,
    loss_event_id: Any = None,
    sanctuary_protected: bool = False,
    target_hp_evidence: Mapping[str, Any] | None = None,
    route_only_loss: bool | None = None,
    route_loss_hazards: Collection[str] | None = None,
    exact_stop_loss: bool = False,
) -> dict[str, Any]:
    """Persist one exact source route that withdrew with explicit XP-loss evidence.

    Live segment completion increments the count. Startup history repair passes
    the number observed in the bounded segment history so replay is idempotent.
    A segment identity makes repeated finalization of the same event idempotent
    as well.
    """
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) or boot_id is None:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    records: list[dict[str, Any]] = []
    previous_loss_count = 0
    previous_sanctuary_protected = False
    previous_target_hp_evidence: Mapping[str, Any] | None = None
    previous_route_only_loss = False
    previous_route_loss_hazards: tuple[str, ...] = ()
    previous_output_revalidation_attempted = False
    previous_output_revalidation_loss_event_id: Any = None
    previous_exact_stop_loss = False
    duplicate_loss_event = False
    if isinstance(raw_records, (list, tuple)):
        for raw_record in raw_records:
            if not isinstance(raw_record, Mapping):
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            ):
                previous_loss_count = _source_ranked_xp_loss_count(raw_record)
                previous_exact_stop_loss = raw_record.get("exact_stop_loss") is True
                previous_sanctuary_protected = (
                    _source_ranked_xp_loss_was_protected(raw_record)
                )
                raw_target_hp_evidence = raw_record.get("target_hp_evidence")
                if isinstance(raw_target_hp_evidence, Mapping):
                    previous_target_hp_evidence = raw_target_hp_evidence
                previous_route_only_loss = (
                    raw_record.get("route_only_loss") is True
                )
                previous_output_revalidation_attempted = (
                    raw_record.get("combat_output_revalidation_attempted")
                    is True
                )
                previous_output_revalidation_loss_event_id = raw_record.get(
                    "combat_output_revalidation_loss_event_id"
                )
                raw_route_loss_hazards = raw_record.get("route_loss_hazards")
                if isinstance(raw_route_loss_hazards, (list, tuple)):
                    previous_route_loss_hazards = tuple(
                        str(value).strip()
                        for value in raw_route_loss_hazards
                        if str(value).strip()
                    )
                duplicate_loss_event = bool(
                    loss_event_id is not None
                    and raw_record.get("loss_event_id") == loss_event_id
                )
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") != policy_id
            ):
                records.append(dict(raw_record))
    if duplicate_loss_event:
        loss_count = previous_loss_count
    elif observed_loss_count is None:
        loss_count = max(1, previous_loss_count + 1)
    else:
        try:
            replayed_loss_count = max(1, int(observed_loss_count))
        except (TypeError, ValueError):
            replayed_loss_count = 1
        loss_count = max(1, previous_loss_count, replayed_loss_count)
    record = {
        "boot_id": boot_id,
        "level": level,
        "policy_id": policy_id,
        "xp_delta": xp_delta,
        "loss_count": loss_count,
        "reason": (
            "source-ranked stop withdrew with explicit XP-loss evidence"
        ),
    }
    if loss_event_id is not None:
        record["loss_event_id"] = loss_event_id
    if exact_stop_loss or previous_exact_stop_loss:
        record["exact_stop_loss"] = True
    recorded_source_revision = (
        source_revision or state.get(_SOURCE_REVISION_KEY)
    )
    if recorded_source_revision:
        record["source_revision"] = str(recorded_source_revision)
    if previous_output_revalidation_attempted:
        record["combat_output_revalidation_attempted"] = True
        if previous_output_revalidation_loss_event_id is not None:
            record["combat_output_revalidation_loss_event_id"] = (
                previous_output_revalidation_loss_event_id
            )
    if sanctuary_protected or previous_sanctuary_protected:
        record["sanctuary_protected"] = True
    if target_hp_evidence is not None:
        record["target_hp_evidence"] = dict(target_hp_evidence)
    elif previous_target_hp_evidence is not None:
        record["target_hp_evidence"] = dict(previous_target_hp_evidence)
    inferred_route_loss_hazards = (
        _source_ranked_route_only_loss_hazards(
            state,
            policy_id=policy_id,
        )
        if route_only_loss is not False
        else ()
    )
    route_only = bool(
        previous_route_only_loss
        or route_only_loss is True
        or bool(inferred_route_loss_hazards)
    )
    if route_only:
        record["route_only_loss"] = True
        retained_route_loss_hazards = tuple(
            str(value).strip()
            for value in (route_loss_hazards or inferred_route_loss_hazards)
            if str(value).strip()
        )
        if not retained_route_loss_hazards:
            retained_route_loss_hazards = previous_route_loss_hazards
        if retained_route_loss_hazards:
            record["route_loss_hazards"] = list(retained_route_loss_hazards)
    records.append(record)
    updated = dict(state)
    updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = records[-64:]
    return updated


def _clear_source_ranked_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_ids: Collection[str],
) -> dict[str, Any]:
    """Clear only source routes that have since produced their own kill."""
    target_policy_ids = {str(policy_id) for policy_id in policy_ids}
    if not target_policy_ids:
        return dict(state)
    raw_records = state.get(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        updated = dict(state)
        marker = updated.get(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY)
        if (
            isinstance(marker, Mapping)
            and str(marker.get("policy_id") or "") in target_policy_ids
        ):
            updated.pop(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY, None)
        route_marker = updated.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
        if (
            isinstance(route_marker, Mapping)
            and str(route_marker.get("policy_id") or "") in target_policy_ids
        ):
            updated.pop(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY, None)
        return updated
    retained = [
        dict(record)
        for record in raw_records
        if isinstance(record, Mapping)
        and str(record.get("policy_id") or "") not in target_policy_ids
    ]
    updated = dict(state)
    if retained:
        updated[_SOURCE_RANKED_XP_LOSS_POLICIES_KEY] = retained
    else:
        updated.pop(_SOURCE_RANKED_XP_LOSS_POLICIES_KEY, None)
    marker = updated.get(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY)
    if (
        isinstance(marker, Mapping)
        and str(marker.get("policy_id") or "") in target_policy_ids
    ):
        updated.pop(_SOURCE_RANKED_COMBAT_OUTPUT_REVALIDATION_KEY, None)
    route_marker = updated.get(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY)
    if (
        isinstance(route_marker, Mapping)
        and str(route_marker.get("policy_id") or "") in target_policy_ids
    ):
        updated.pop(_SOURCE_RANKED_ROUTE_LOSS_REVALIDATION_KEY, None)
    return updated


def _is_source_ranked_research_policy_id(policy_id: str) -> bool:
    """Recognize source-ranked hunt and fixed resource policy identities."""
    return (
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        or policy_id.startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX)
        or policy_id in _SANCTUARY_RESOURCE_POLICY_IDS
        or policy_id == _SOURCE_RANKED_FLIGHT_RESERVE_POLICY.policy_id
        or policy_id
        in {
            _SOURCE_RANKED_CURE_CRITICAL_RESERVE_POLICY.policy_id,
            _SOURCE_RANKED_FOOD_RESERVE_POLICY.policy_id,
        }
    )


def _registered_research_xp_loss_records(
    state: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    """Return reboot-local loss records for registered non-source routes."""
    boot_id = state.get("world_boot_id")
    raw_records = state.get(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY)
    if boot_id is None or not isinstance(raw_records, (list, tuple)):
        return ()
    return tuple(
        record
        for record in raw_records
        if isinstance(record, Mapping)
        and record.get("boot_id") == boot_id
        and str(record.get("policy_id") or "")
        and not _is_source_ranked_research_policy_id(
            str(record.get("policy_id") or "")
        )
    )


def _registered_research_xp_loss_record(
    state: Mapping[str, Any],
    policy_id: str,
) -> Mapping[str, Any] | None:
    """Return the exact current-reboot loss record for one registered route."""
    return next(
        (
            record
            for record in _registered_research_xp_loss_records(state)
            if record.get("policy_id") == policy_id
        ),
        None,
    )


def _remember_registered_research_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    level: int,
    boot_id: Any,
    xp_delta: int,
    loss_event_id: Any = None,
) -> dict[str, Any]:
    """Persist one loss for a registered research route.

    Source-ranked routes have a separate candidate ledger because their policy
    ids are generated from source VNUMs. Fixed class routes need the same
    evidence boundary, however: a safe withdrawal must rotate the next
    selection instead of disappearing into a generic latest-XP number.
    """
    if (
        not policy_id
        or _is_source_ranked_research_policy_id(policy_id)
        or boot_id is None
    ):
        return dict(state)
    raw_records = state.get(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY)
    records: list[dict[str, Any]] = []
    previous_loss_count = 0
    duplicate_loss_event = False
    if isinstance(raw_records, (list, tuple)):
        for raw_record in raw_records:
            if not isinstance(raw_record, Mapping):
                continue
            if (
                raw_record.get("boot_id") == boot_id
                and raw_record.get("policy_id") == policy_id
            ):
                try:
                    previous_loss_count = max(
                        0,
                        int(raw_record.get("loss_count") or 0),
                    )
                except (TypeError, ValueError):
                    previous_loss_count = 0
                duplicate_loss_event = bool(
                    loss_event_id is not None
                    and raw_record.get("loss_event_id") == loss_event_id
                )
                continue
            records.append(dict(raw_record))
    if duplicate_loss_event:
        records.append(
            {
                "boot_id": boot_id,
                "level": level,
                "policy_id": policy_id,
                "xp_delta": xp_delta,
                "loss_count": max(1, previous_loss_count),
                "reason": (
                    "registered research route withdrew with an XP loss "
                    "before an objective kill"
                ),
                "loss_event_id": loss_event_id,
            }
        )
    else:
        record = {
            "boot_id": boot_id,
            "level": level,
            "policy_id": policy_id,
            "xp_delta": xp_delta,
            "loss_count": max(1, previous_loss_count + 1),
            "reason": (
                "registered research route withdrew with an XP loss before "
                "an objective kill"
            ),
        }
        if loss_event_id is not None:
            record["loss_event_id"] = loss_event_id
        records.append(record)
    updated = dict(state)
    updated[_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY] = records[-64:]
    return updated


def _clear_registered_research_xp_loss(
    state: Mapping[str, Any],
    *,
    policy_ids: Collection[str],
) -> dict[str, Any]:
    """Clear registered-route loss evidence after a positive objective kill."""
    target_policy_ids = {str(policy_id) for policy_id in policy_ids}
    if not target_policy_ids:
        return dict(state)
    raw_records = state.get(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY)
    if not isinstance(raw_records, (list, tuple)):
        return dict(state)
    retained = [
        dict(record)
        for record in raw_records
        if isinstance(record, Mapping)
        and str(record.get("policy_id") or "") not in target_policy_ids
    ]
    updated = dict(state)
    if retained:
        updated[_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY] = retained
    else:
        updated.pop(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY, None)
    return updated


def _registered_research_xp_loss_policy_ids(
    state: Mapping[str, Any],
) -> frozenset[str]:
    """Return registered routes blocked by a fresh reboot-local loss."""
    return frozenset(
        str(record.get("policy_id"))
        for record in _registered_research_xp_loss_records(state)
        if record.get("policy_id")
    )


def _repair_registered_research_xp_loss_history(
    state: Mapping[str, Any],
    campaign_segments: Collection[Mapping[str, Any]],
    *,
    storage: RunStorage | None = None,
    campaign_id: int | None = None,
) -> dict[str, Any]:
    """Rebuild registered-route loss evidence from current-reboot segments."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)
    segments: Collection[Mapping[str, Any]] = campaign_segments
    full_history_loaded = False
    if storage is not None and campaign_id is not None:
        # Only registered policies can change this ledger.  Loading every
        # historical segment forces SQLite to materialize gigabytes of state
        # JSON on large campaigns, while a phase-scoped query retains the
        # complete evidence needed for the current records.
        policy_ids = {
            str(record.get("policy_id") or "")
            for record in state.get(
                _REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY,
                (),
            )
            if isinstance(record, Mapping)
            and record.get("boot_id") == boot_id
            and record.get("policy_id")
        }
        try:
            phase_loader = getattr(
                storage,
                "list_campaign_segments_for_phases",
            )
            index_available = getattr(
                storage,
                "campaign_phase_index_available",
                None,
            )
            if not callable(index_available) or index_available():
                segments = phase_loader(campaign_id, policy_ids)
                full_history_loaded = True
        except (AttributeError, OSError, sqlite3.Error):
            # Lightweight legacy adapters may expose only the full-history
            # method.  Preserve their existing behavior for compatibility.
            try:
                segments = storage.list_campaign_segments(campaign_id)
                full_history_loaded = True
            except (AttributeError, OSError, sqlite3.Error):
                segments = campaign_segments
    ordered_segments = sorted(
        (dict(segment) for segment in segments),
        key=lambda segment: (
            int(segment.get("sequence") or 0),
            int(segment.get("id") or 0),
        ),
    )
    # With durable history available, rebuild from zero so repeating startup
    # repair cannot count the same segment loss again. If a small legacy tail
    # is all that is available, preserve the current checkpoint's records and
    # merge the bounded evidence we were given.
    records: dict[str, dict[str, Any]] = {}
    if not full_history_loaded:
        records = {
            str(record.get("policy_id")): dict(record)
            for record in state.get(
                _REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY,
                (),
            )
            if isinstance(record, Mapping)
            and record.get("boot_id") == boot_id
            and record.get("policy_id")
        }
    for segment in ordered_segments:
        phase = str(segment.get("phase") or "")
        policy = _POLICY_BY_ID.get(phase)
        if policy is None or policy.status not in {"research", "verified"}:
            continue
        if _is_source_ranked_research_policy_id(phase):
            continue
        if policy.execution in _MAINTENANCE_EXECUTIONS:
            continue
        if segment.get("status") not in {"success", "ready"}:
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        objective_kills = _segment_objective_kills(storage, segment)
        xp_delta = _xp_delta(dict(start), dict(end))
        loss_observed = bool(
            xp_delta < 0 or _xp_loss_event_observed(start, end)
        )
        positive_objective_kill = bool(
            xp_delta > 0
            and objective_kills
            and not end.get("campaign_died_during_segment")
        )
        if positive_objective_kill:
            records.pop(phase, None)
            continue
        if not objective_kills and loss_observed:
            prior = records.get(phase)
            try:
                loss_count = int(prior.get("loss_count") or 0) + 1
            except (AttributeError, TypeError, ValueError):
                loss_count = 1
            records[phase] = {
                "boot_id": boot_id,
                "level": _level(end),
                "policy_id": phase,
                "xp_delta": xp_delta,
                "loss_count": max(1, loss_count),
                "reason": (
                    "registered research route withdrew with an XP loss "
                    "before an objective kill"
                ),
                "loss_event_id": segment.get("id"),
            }
    existing = [
        dict(record)
        for record in state.get(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY, ())
        if isinstance(record, Mapping)
        and record.get("boot_id") != boot_id
    ]
    repaired_records = existing + list(records.values())
    updated = dict(state)
    if repaired_records:
        updated[_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY] = repaired_records[-64:]
    else:
        updated.pop(_REGISTERED_RESEARCH_XP_LOSS_POLICIES_KEY, None)
    return updated


def _source_food_policy_id(
    candidate: HuntCandidate,
    *,
    character_level: int,
) -> str:
    """Return a reset-specific identity for one ground-food acquisition."""
    area = re.sub(
        r"[^a-z0-9]+",
        "-",
        Path(candidate.area_file).stem.casefold(),
    ).strip("-") or "area"
    object_identity = "-".join(
        str(vnum) for vnum in candidate.ground_loot_object_vnums
    ) or re.sub(
        r"[^a-z0-9]+",
        "-",
        candidate.target_keyword.casefold(),
    ).strip("-")
    return (
        f"{_SOURCE_RANKED_FOOD_POLICY_PREFIX}{area}-"
        f"{candidate.room_vnum}-{object_identity}-{character_level}"
    )


def _field_city_route_policy_id(
    *,
    policy_id: str,
    execution: str | None,
    candidate: HuntCandidate,
    character_level: int,
) -> str:
    """Use the exact source reset identity for a field-route cooldown."""
    if execution == "source-ranked-food-reserve":
        return _source_food_policy_id(
            candidate,
            character_level=character_level,
        )
    if execution in {"provision-funding", "source-ranked-hunt"}:
        return _source_ranked_policy_id(
            candidate,
            character_level=character_level,
        )
    return policy_id


def _urgent_food_fullness_requirement(state: Mapping[str, Any]) -> int:
    """Return the minimum verified food value for an active starvation state."""
    hunger = state.get("hunger")
    if isinstance(hunger, bool) or not isinstance(hunger, (int, float)):
        return 0
    if hunger > 0:
        return 0
    return max(1, int(-hunger) + _URGENT_FOOD_FULLNESS_BUFFER)


def _source_ranked_field_food_reserve_needed(
    state: Mapping[str, Any],
    food_units: int,
) -> bool:
    """Require food when none is carried, or two units at low fullness."""
    if food_units >= _SOURCE_RANKED_MIN_FIELD_FOOD_UNITS:
        return False
    if food_units <= 0:
        return True
    hunger = state.get("hunger")
    if not isinstance(hunger, (int, float)) or isinstance(hunger, bool):
        # Missing vitals remain conservative for offline and legacy states.
        return True
    return hunger <= _SOURCE_RANKED_FIELD_FOOD_RESERVE_HUNGER_THRESHOLD


def _source_food_candidate_transit_exception(candidate: HuntCandidate) -> bool:
    """Allow only the audited below-band crowd on a food route."""
    return bool(
        candidate.is_food_stash
        and candidate.ground_loot_object_vnums
        and candidate.autonomy_rejections
        and set(candidate.autonomy_rejections).issubset(
            _SOURCE_FOOD_TRANSIT_REJECTIONS
        )
        and not candidate.route_preflight_hard_hazard
        and not candidate.route_hard_hazard_targets
    )


def _source_food_absence_rotation_exhausted(
    state: Mapping[str, Any],
) -> bool:
    """Return whether this level's direct-food frontier needs a shop fallback."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return False
    level_suffix = f"-{_level(state)}"
    absent_count = sum(
        1
        for policy_id, result in _campaign_research_results(state).items()
        if (
            str(policy_id).startswith(_SOURCE_RANKED_FOOD_POLICY_PREFIX)
            and str(policy_id).endswith(level_suffix)
            and isinstance(result, Mapping)
            and result.get("boot_id") == boot_id
            and result.get("absent") is True
        )
    )
    return absent_count >= _SOURCE_RANKED_FOOD_ABSENCE_ROTATION_LIMIT


def _urgent_food_survival_retry_allowed(state: Mapping[str, Any]) -> bool:
    """Allow a nourishing food retry when starvation has become dangerous."""
    hunger = state.get("hunger")
    hp = state.get("hp")
    max_hp = state.get("max_hp")
    return bool(
        isinstance(hunger, (int, float))
        and not isinstance(hunger, bool)
        and hunger <= 0
        and isinstance(hp, (int, float))
        and not isinstance(hp, bool)
        and isinstance(max_hp, (int, float))
        and not isinstance(max_hp, bool)
        and max_hp > 0
        and hp / max_hp <= _URGENT_FOOD_SURVIVAL_HEALTH_RATIO
    )


def _urgent_food_reset_retry_allowed(state: Mapping[str, Any]) -> bool:
    """Allow one more source reset when starvation consumed the reserve."""
    hunger = state.get("hunger")
    if (
        state.get("dead")
        or state.get("in_combat")
        or not isinstance(hunger, (int, float))
        or isinstance(hunger, bool)
        or hunger > 0
        or "inventory" not in state
    ):
        return False
    # A successful source route is normally closed until an area reset. If it
    # was immediately consumed and the character is still hungry, the next
    # source reset is an urgent survival attempt rather than a duplicate hunt.
    return not _has_campaign_food(dict(state), gear_catalog=None)


def _foodless_fame_hunt_allowed(state: Mapping[str, Any]) -> bool:
    """Allow productive hunting while fed when direct food is temporarily unavailable."""
    hunger = state.get("hunger")
    hp = state.get("hp")
    max_hp = state.get("max_hp")
    return bool(
        not state.get("dead")
        and not state.get("in_combat")
        and isinstance(hunger, (int, float))
        and not isinstance(hunger, bool)
        and hunger > 0
        and isinstance(hp, (int, float))
        and not isinstance(hp, bool)
        and isinstance(max_hp, (int, float))
        and not isinstance(max_hp, bool)
        and max_hp > 0
        and hp / max_hp >= _FOODLESS_FAME_HUNT_MIN_HEALTH_RATIO
    )


def _source_food_bakery_preferred(
    state: Mapping[str, Any], *, source_world: WorldSource | None,
) -> bool:
    """Prefer nourishing food when the selection budget includes flight."""
    if (
        source_world is None
        or str(state.get("room_vnum") or "") != "3054"
        or state.get("dead") or state.get("in_combat")
        or _state_fame(state) is None or _state_fame(state) < 0
        or int(state.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0) > 0
        or state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        or state.get("campaign_last_policy") == _RESTOCK_POLICY.policy_id
    ):
        return False
    pie = source_world.objects.get(3009)
    if (
        pie is None or pie.item_type != ITEM_FOOD
        or len(pie.values) < 4 or pie.values[3] != 0
        or pie.values[0] <= 0 or pie.source_cost <= 0
        or "pie" not in pie.keywords.casefold().split()
    ):
        return False
    # Source cost is a selection budget, not a shop quote. The existing live
    # purchase flow must still confirm price, stock and carry-safe quantity.
    return _state_copper_value(state) >= (
        2 * pie.source_cost + _flight_purchase_minimum(state)
    )


def _select_source_food_candidate(
    state: Mapping[str, Any],
    *,
    source_directory: Path,
    source_world: WorldSource | None = None,
    allow_pending_flight: bool = False,
    allow_cooldown_retry: bool = False,
) -> HuntCandidate | None:
    """Choose a safe direct food reset that does not require a shopkeeper."""
    character_level = _level(state)
    if character_level < 2 or not source_directory.is_dir():
        return None
    world = source_world or load_world_source(
        source_directory,
        include_all_areas=True,
    )
    candidates = rank_food_stashes(
        world,
        character_level=character_level,
        include_all_areas=True,
    )
    minimum_fullness = _urgent_food_fullness_requirement(state)
    if minimum_fullness:
        nourishing = tuple(
            candidate
            for candidate in candidates
            if candidate.source_value >= minimum_fullness
        )
        candidates = (
            *nourishing,
            *(candidate for candidate in candidates if candidate not in nourishing),
        )
    active_flight = any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    survival_retry = _urgent_food_survival_retry_allowed(state)
    depleted_reserve_retry = _urgent_food_reset_retry_allowed(state)
    if (
        _source_food_absence_rotation_exhausted(state)
        and not (survival_retry or depleted_reserve_retry)
    ):
        # A normal food reserve can use the baker after three exact misses.
        # Starvation recovery remains allowed to reopen a known reset.
        return None
    movement_state: Mapping[str, Any] = state
    if allow_pending_flight and not active_flight:
        # Evaluate a pending-flight food route with the movement cost it will
        # have after the purchase, while keeping the live route gate in charge
        # until the affect is actually observed.
        movement_state = {**state, "affects": [[{"name": "fly"}]]}
    for candidate in candidates:
        transit_exception = _source_food_candidate_transit_exception(candidate)
        if (
            (candidate.status == "reject" and not transit_exception)
            or (not candidate.autonomous_safe and not transit_exception)
            or not candidate.loot
            or not candidate.ground_loot_object_vnums
            or not _source_candidate_fits_movement(candidate, movement_state)
        ):
            continue
        if candidate.requires_flight and not active_flight and not allow_pending_flight:
            continue
        if not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate,
            character_level=character_level,
        ):
            continue
        policy_id = _source_food_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            _field_city_departure_blocked_current_reboot(
                state,
                policy_id=policy_id,
            )
            or policy_id in _field_city_route_attempted_policy_ids(state)
        ):
            continue
        research_result = _campaign_research_results(dict(state)).get(policy_id)
        if (
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("required_object_acquired") is True
            and not (survival_retry or depleted_reserve_retry)
        ):
            # A successful ground-food reset is a consumed resource, not a
            # fresh target. Keep it closed until the area-reset retry path.
            continue
        retryable_route_hazard = bool(
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("completed_kill") is not True
            and _is_retryable_dynamic_route_hazard(
                policy_id,
                research_result.get("route_hazard"),
            )
        )
        if retryable_route_hazard and not (
            survival_retry or allow_cooldown_retry
        ):
            # A source route that was blocked by a transient, observed hazard
            # must rotate before it is replayed. Urgent survival and the
            # explicit bounded retry path may still reopen it.
            continue
        if (
            allow_cooldown_retry
            and state.get("campaign_last_policy") == policy_id
        ):
            # A bounded retry may reopen a cooled reset, but it must rotate
            # after the same food policy just ran without leaving a reserve.
            continue
        if (
            state.get("campaign_last_policy") == policy_id
            and str(state.get("campaign_fastwalk_abort_reason") or "")
            .startswith("field-route movement did not")
        ):
            continue
        if _research_fatal_failure_active(state, policy_id):
            continue
        if (
            _research_retry_cooldown_active(state, policy_id)
            and not (survival_retry or allow_cooldown_retry)
        ):
            continue
        return candidate
    return None


def _select_source_food_reserve_companion(
    state: Mapping[str, Any],
    primary: HuntCandidate,
    *,
    source_world: WorldSource,
    character_level: int,
) -> tuple[HuntCandidate, tuple[str, ...], int] | None:
    """Choose a distinct same-area food reset for a starvation reserve."""
    if (
        character_level < 2
        or not primary.is_food_stash
        or not primary.loot
        or not primary.ground_loot_object_vnums
    ):
        return None
    active_flight = any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    survival_retry = _urgent_food_survival_retry_allowed(state)
    blocked_rooms = _source_ranked_area_circuit_blocked_rooms(
        source_world,
        character_level=character_level,
        state=state,
    )
    inter_paths = _shortest_paths_from(
        source_world.rooms,
        primary.room_vnum,
        blocked_rooms=blocked_rooms,
    )
    primary_description = normalize_item_name(primary.loot[0])
    primary_object_vnums = set(primary.ground_loot_object_vnums)
    candidates = rank_food_stashes(
        source_world,
        character_level=character_level,
        include_all_areas=True,
    )
    for candidate in candidates:
        if (
            candidate.area_file.casefold() != primary.area_file.casefold()
            or candidate.room_vnum == primary.room_vnum
            or not candidate.loot
            or not candidate.ground_loot_object_vnums
            or normalize_item_name(candidate.loot[0]) == primary_description
            or primary_object_vnums.intersection(
                candidate.ground_loot_object_vnums
            )
        ):
            continue
        transit_exception = _source_food_candidate_transit_exception(candidate)
        if (
            (candidate.status == "reject" and not transit_exception)
            or (not candidate.autonomous_safe and not transit_exception)
            or (candidate.requires_flight and not active_flight)
            or not _source_ranked_route_has_static_safe_live_navigation_path(
                source_world,
                candidate,
                character_level=character_level,
            )
        ):
            continue
        policy_id = _source_food_policy_id(
            candidate,
            character_level=character_level,
        )
        if (
            _field_city_departure_blocked_current_reboot(
                state,
                policy_id=policy_id,
            )
            or policy_id in _field_city_route_attempted_policy_ids(state)
        ):
            continue
        research_result = _campaign_research_results(dict(state)).get(policy_id)
        if (
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("required_object_acquired") is True
            and not survival_retry
        ):
            continue
        if (
            isinstance(research_result, Mapping)
            and research_result.get("boot_id") == state.get("world_boot_id")
            and research_result.get("completed_kill") is not True
            and _is_retryable_dynamic_route_hazard(
                policy_id,
                research_result.get("route_hazard"),
            )
            and not survival_retry
        ):
            continue
        if (
            state.get("campaign_last_policy") == policy_id
            and str(state.get("campaign_fastwalk_abort_reason") or "")
            .startswith("field-route movement did not")
        ):
            continue
        if _research_fatal_failure_active(state, policy_id):
            continue
        if _research_retry_cooldown_active(state, policy_id) and not survival_retry:
            continue
        inter_route = _source_ranked_inter_candidate_route(
            source_world,
            primary,
            candidate,
            character_level=character_level,
            blocked_rooms=blocked_rooms,
            state=state,
        )
        if not inter_route:
            continue
        inter_path = inter_paths.get(candidate.room_vnum)
        if inter_path is not None and inter_path[2]:
            continue
        inter_move_cost = len(inter_route)
        if inter_path is not None:
            inter_move_cost = source_route_movement_cost(
                source_world,
                inter_path[1],
                flying=active_flight,
            )
        maximum_move = state.get("max_move")
        if isinstance(maximum_move, (int, float)) and maximum_move > 0:
            primary_move_cost = (
                primary.estimated_flying_move_cost
                if active_flight and primary.estimated_flying_move_cost > 0
                else primary.estimated_move_cost
            )
            if primary_move_cost <= 0:
                primary_move_cost = len(primary.route)
            if (
                primary_move_cost
                + inter_move_cost
                + _SOURCE_ROUTE_MOVEMENT_RESERVE
                > int(maximum_move)
            ):
                continue
        return candidate, inter_route, inter_move_cost
    return None


def _source_dwarven_key_route_with_alternate_carrier(
    world: WorldSource,
    candidate: HuntCandidate,
) -> HuntCandidate | None:
    """Add the bounded source route to the alternate Dwarven key room."""
    normalized_route = tuple(
        str(command).casefold().strip() for command in candidate.route
    )
    try:
        unlock_index = normalized_route.index("unlock west")
    except ValueError:
        return None
    prefix = candidate.route[:unlock_index]
    prefix_rooms = _source_route_room_vnums(world, RECALL_VNUM, prefix)
    if (
        not prefix_rooms
        or prefix_rooms[-1] != _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUM
    ):
        return None
    if _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS[1] not in prefix_rooms:
        if not prefix or str(prefix[-1]).casefold().strip() != "west":
            return None
        approach_prefix = prefix[:-1]
        approach_rooms = _source_route_room_vnums(
            world,
            RECALL_VNUM,
            approach_prefix,
        )
        if not approach_rooms or approach_rooms[-1] != 6503:
            return None
        expanded_prefix = (
            *approach_prefix,
            *_DWARVEN_SANCTUARY_KEY_CARRIER_ALTERNATE_DETOUR,
        )
        expanded_rooms = _source_route_room_vnums(
            world,
            RECALL_VNUM,
            expanded_prefix,
        )
        if (
            not expanded_rooms
            or expanded_rooms[-1] != _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUM
            or _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS[1]
            not in expanded_rooms
        ):
            return None
        route = (*expanded_prefix, *candidate.route[unlock_index:])
    else:
        route = tuple(candidate.route)
    room_vnums = _source_route_room_vnums(world, RECALL_VNUM, route)
    if (
        not room_vnums
        or room_vnums[-1] != candidate.room_vnum
        or _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS[1]
        not in room_vnums
    ):
        return None
    if room_vnums.index(
        _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS[1]
    ) >= room_vnums.index(_DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUM):
        return None
    return replace(
        candidate,
        route=tuple(route),
        estimated_move_cost=source_route_movement_cost(
            world,
            room_vnums,
        ),
        estimated_flying_move_cost=source_route_movement_cost(
            world,
            room_vnums,
            flying=True,
        ),
        requires_flight=source_route_requires_flight(world, room_vnums),
    )


def _source_dwarven_key_gate_requirements(
    world: WorldSource | None,
    *,
    character_level: int,
    character_alignment: int | None,
) -> tuple[bool, bool]:
    """Return sanctuary and live-alignment gates for possible source joiners.

    Missing source identity fails closed. DD4's assist check admits mobiles
    from three levels below the player through six levels above; the reset's
    level fuzz is included by ``source_mobile_can_join_player_fight``. If the
    current good alignment prevents a join, require it again at the live gate
    so a changed alignment cannot invalidate the source safety calculation.
    """
    if world is None:
        return True, True
    guard = world.mobiles.get(_DWARVEN_SANCTUARY_KEY_CARRIER_MOBILE_VNUM)
    if guard is None:
        return True, True
    could_join_by_level = source_mobile_can_join_player_fight(
        world,
        guard,
        character_level=character_level,
        character_alignment=None,
    )
    if not could_join_by_level:
        return False, False
    could_join_now = source_mobile_can_join_player_fight(
        world,
        guard,
        character_level=character_level,
        character_alignment=character_alignment,
    )
    return could_join_now, not could_join_now


def _source_dwarven_key_route_proven(
    world: WorldSource,
    candidate: HuntCandidate,
) -> bool:
    """Prove that the Catacombs route can acquire its pickproof-door key."""
    guard = world.mobiles.get(_DWARVEN_SANCTUARY_KEY_CARRIER_MOBILE_VNUM)
    key = world.objects.get(_DWARVEN_SANCTUARY_DOOR_KEY_VNUM)
    if guard is None or key is None:
        return False
    for room_vnum in _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS:
        gate_resets = tuple(
            reset
            for reset in world.mob_resets
            if reset.mobile_vnum == _DWARVEN_SANCTUARY_KEY_CARRIER_MOBILE_VNUM
            and reset.room_vnum == room_vnum
        )
        if (
            len(gate_resets) != 2
            or any(
                reset.maximum_count != _DWARVEN_SANCTUARY_KEY_GATE_INSTANCE_LIMIT
                for reset in gate_resets
            )
            or sum(
                _DWARVEN_SANCTUARY_DOOR_KEY_VNUM in _reset_object_vnums(reset)
                for reset in gate_resets
            )
            != 1
            or tuple(
                index
                for index, reset in enumerate(gate_resets)
                if _DWARVEN_SANCTUARY_DOOR_KEY_VNUM
                in _reset_object_vnums(reset)
            )
            != (0,)
        ):
            return False
    key_resets = _source_key_carrier_resets(
        world,
        (_DWARVEN_SANCTUARY_DOOR_KEY_VNUM,),
        mobile_vnums=(_DWARVEN_SANCTUARY_KEY_CARRIER_MOBILE_VNUM,),
        room_vnums=_DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS,
    )
    if (
        len(key_resets) != len(_DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS)
        or {
            reset.room_vnum
            for reset in key_resets
        }
        != set(_DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS)
        or any(reset.maximum_count < 1 for reset in key_resets)
    ):
        return False
    if (
        world.mobile_specials.get(_DWARVEN_SANCTUARY_KEY_CARRIER_MOBILE_VNUM)
        or guard.attack_programs
        or guard.non_corporeal
        or guard.alignment < 350
        or not guard.hp_modifier_known
        or not guard.damage_modifier_known
    ):
        return False
    normalized_route = tuple(
        str(command).casefold().strip() for command in candidate.route
    )
    try:
        unlock_index = normalized_route.index("unlock west")
    except ValueError:
        return False
    door_rooms = _source_route_room_vnums(
        world,
        RECALL_VNUM,
        candidate.route[:unlock_index],
    )
    if (
        not door_rooms
        or door_rooms[-1] != _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUM
        or _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUMS[1] not in door_rooms
    ):
        return False
    door = world.rooms.get(door_rooms[-1])
    door_exit = door.exits.get("west") if door is not None else None
    return bool(
        door_exit is not None
        and door_exit.closed
        and door_exit.locked
        and door_exit.key_vnum == _DWARVEN_SANCTUARY_DOOR_KEY_VNUM
    )


def _source_dwarven_level_25_transit_candidate(
    candidate: HuntCandidate,
    world: WorldSource,
    *,
    character_level: int,
    character_max_hp: int,
) -> HuntCandidate | None:
    """Remove one exact, bounded Catacombs transit special for validation.

    At level 25 DD4's ordinary aggression test is strict ``> 10`` levels,
    so a loaded level-15 zombie mage can initiate combat at the route's exact
    cutoff.  Its ``spec_cast_mage`` only acts after combat has begun; the
    live runner still requires an exact GMCP VNUM and treats the interruption
    as non-XP transit combat.  This helper is deliberately source-specific:
    any changed VNUM, special, route program, source damage bound, or extra
    route rejection closes the exception.
    """
    legacy_route_preflight = (
        candidate.route_attack_program_mobile_vnums
        == (_DWARVEN_LEVEL_25_TRANSIT_PROGRAM_MOBILE_VNUM,)
        and candidate.route_preflight_command == "where drunk"
        and candidate.route_preflight_target == "the drunk"
        and candidate.route_preflight_hard_hazard
    )
    current_source_route = (
        not candidate.route_attack_program_mobile_vnums
        and not candidate.route_preflight_command
        and not candidate.route_preflight_target
        and not candidate.route_preflight_checks
        and not candidate.route_preflight_hard_hazard
    )
    if (
        character_level != 25
        or character_max_hp <= 0
        or candidate.mobile_vnum != _DWARVEN_SANCTUARY_CARRIER_MOBILE_VNUM
        or candidate.room_vnum != _DWARVEN_SANCTUARY_ROOM_VNUM
        or candidate.area_file.casefold() != "dwarven_catacombs.are"
        or candidate.route_special_mobile_vnums
        != (_DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM,)
        or candidate.autonomy_rejections
        != (_DWARVEN_LEVEL_25_TRANSIT_AUTONOMY_REJECTION,)
        or not (legacy_route_preflight or current_source_route)
        or candidate.route_hard_hazard_targets
        or _DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM
        not in candidate.route_hazard_mobile_vnums
        or _DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM
        not in candidate.route_aggressive_mobile_vnums
    ):
        return None
    mobile = world.mobiles.get(_DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM)
    if mobile is None:
        return None
    specials = tuple(
        str(special).strip().casefold()
        for special in world.mobile_specials.get(mobile.vnum, ())
    )
    if (
        not mobile.aggressive
        or mobile.programs
        or mobile.attack_programs
        or specials != (_DWARVEN_LEVEL_25_TRANSIT_SPECIAL_NAME,)
        or not source_special_is_transit_safe(_DWARVEN_LEVEL_25_TRANSIT_SPECIAL_NAME)
        or not mobile.hp_modifier_known
        or not mobile.damage_modifier_known
    ):
        return None
    resets = tuple(
        reset
        for reset in world.mob_resets
        if reset.mobile_vnum == mobile.vnum
    )
    if not resets or any(reset.equipment for reset in resets):
        return None
    try:
        maximum_level = _mobile_level_range(mobile.level)[1]
    except (TypeError, ValueError):
        return None
    if maximum_level != character_level - 10:
        return None
    peak_damage = _mobile_peak_round_damage(
        maximum_level,
        wielding=False,
        dual_wielding=False,
        damage_modifier=mobile.damage_modifier,
    )
    critical_damage = _mobile_critical_hit_damage(
        maximum_level,
        wielding=False,
        damage_modifier=mobile.damage_modifier,
    )
    expected_damage = mobile_expected_round_damage(
        maximum_level,
        wielding=False,
        dual_wielding=False,
        damage_modifier=mobile.damage_modifier,
    )
    if (
        peak_damage > character_max_hp * 0.25
        or critical_damage > character_max_hp * 0.10
        or expected_damage > character_max_hp * 0.10
    ):
        return None
    return replace(
        candidate,
        autonomy_rejections=tuple(
            rejection
            for rejection in candidate.autonomy_rejections
            if rejection != _DWARVEN_LEVEL_25_TRANSIT_AUTONOMY_REJECTION
        ),
        route_special_mobile_vnums=tuple(
            vnum
            for vnum in candidate.route_special_mobile_vnums
            if int(vnum) != _DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM
        ),
        route_aggressive_mobile_vnums=tuple(
            vnum
            for vnum in candidate.route_aggressive_mobile_vnums
            if int(vnum) != _DWARVEN_LEVEL_25_TRANSIT_SPECIAL_MOBILE_VNUM
        ),
    )


def _source_dwarven_sanctuary_route_gate_candidate_allowed(
    candidate: HuntCandidate,
    world: WorldSource,
    *,
    character_level: int,
) -> bool:
    """Admit the source-proven Catacombs required-loot transit route.

    This route has no program-bearing transit mobile to locate with ``where``.
    Its low-level route aggressors are instead covered by the dedicated live
    gate in ``run_source_consumable_reserve``; keep this exception scoped to
    the exact sanctuary carrier and retain the ordinary source aggressor and
    navigation audits.
    """
    if (
        character_level < _DWARVEN_SANCTUARY_MINIMUM_LEVEL
        or candidate.area_file.casefold() != "dwarven_catacombs.are"
        or candidate.mobile_vnum != _DWARVEN_SANCTUARY_CARRIER_MOBILE_VNUM
        or candidate.room_vnum != _DWARVEN_SANCTUARY_ROOM_VNUM
        or candidate.route_origin_room_vnum != RECALL_VNUM
        or candidate.specials
        or candidate.equipped_weapons
        or candidate.route_hard_hazard_targets
        or candidate.route_attack_program_mobile_vnums
        or candidate.route_special_mobile_vnums
        or candidate.autonomy_rejections
        or not candidate.route_aggressive_mobile_vnums
        or not _source_ranked_route_specials_noncombat_only(candidate, world)
        or not _source_ranked_route_program_aggressors_allowed(
            candidate,
            character_level=character_level,
            source_world=world,
        )
        or not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate,
            character_level=character_level,
        )
    ):
        return False
    return True


def _select_source_dwarven_sanctuary_candidate(
    state: Mapping[str, Any],
    *,
    source_directory: Path,
    source_world: WorldSource | None = None,
    allow_training_pick_lock: bool = False,
) -> tuple[HuntCandidate, tuple[int, ...]] | None:
    """Select the exact key-gated route to the Catacombs holy water.

    The entrance is pickproof, so every class uses the source-reset key
    carrier. The live runner handles that carrier as one isolated, considered
    below-band route gate; it never becomes ordinary progression XP.
    """
    character_level = _level(state)
    if (
        character_level < _DWARVEN_SANCTUARY_MINIMUM_LEVEL
        or not source_directory.is_dir()
    ):
        return None
    raw_known_skills = state.get("campaign_known_skills")
    if isinstance(raw_known_skills, str):
        known_skills = (raw_known_skills,)
    elif isinstance(raw_known_skills, (list, tuple, set, frozenset)):
        known_skills = tuple(str(skill) for skill in raw_known_skills)
    else:
        known_skills = ()
    known_skill_levels = _skill_levels_from_state(state)
    world = source_world or load_world_source(
        source_directory,
        include_all_areas=True,
    )
    raw_max_hp = state.get("max_hp")
    character_max_hp = (
        int(raw_max_hp)
        if isinstance(raw_max_hp, (int, float))
        and not isinstance(raw_max_hp, bool)
        and raw_max_hp > 0
        else None
    )
    if character_max_hp is None:
        return None
    source_character_class = str(state.get("character_class") or "").strip()
    if not source_character_class:
        return None
    candidates = rank_hunt_candidates(
        world,
        character_level=character_level,
        character_class=source_character_class,
        character_subclass=_live_subclass(state),
        known_skills=known_skills,
        known_skill_levels=known_skill_levels,
        character_alignment=_state_alignment(state),
        include_below_band=True,
        character_max_hp=character_max_hp,
        include_level_ceiling_candidates=True,
        level_ceiling_offset=1,
        include_all_areas=True,
        required_loot_object_vnums={_DWARVEN_SANCTUARY_POTION_OBJECT_VNUM},
        route_key_object_vnums={_DWARVEN_SANCTUARY_DOOR_KEY_VNUM},
        recall_origins=_source_ranked_recall_origins(state),
    )
    eligible: list[HuntCandidate] = []
    for candidate in candidates:
        if (
            candidate.mobile_vnum != _DWARVEN_SANCTUARY_CARRIER_MOBILE_VNUM
            or candidate.room_vnum != _DWARVEN_SANCTUARY_ROOM_VNUM
            or candidate.area_file.casefold() != "dwarven_catacombs.are"
            or not _source_dwarven_key_drop_room_is_safe(
                world,
                _DWARVEN_SANCTUARY_KEY_CARRIER_ROOM_VNUM,
            )
            or candidate.source_spawn_limit != 1
            or candidate.room_spawn_count != 1
            or candidate.equipped_weapons
            or candidate.specials
            or candidate.route_hard_hazard_targets
        ):
            continue
        keyed_candidate = _source_dwarven_key_route_with_alternate_carrier(
            world,
            candidate,
        )
        if keyed_candidate is None:
            continue
        candidate = keyed_candidate
        route_program_candidate = candidate
        if candidate.autonomy_rejections or candidate.route_special_mobile_vnums:
            route_program_candidate = _source_dwarven_level_25_transit_candidate(
                candidate,
                world,
                character_level=character_level,
                character_max_hp=character_max_hp,
            )
            if route_program_candidate is None:
                continue
        if not _source_dwarven_key_route_proven(world, candidate):
            continue
        matching_resets = [
            reset
            for reset in world.mob_resets
            if reset.mobile_vnum == candidate.mobile_vnum
            and reset.room_vnum == candidate.room_vnum
            and _DWARVEN_SANCTUARY_POTION_OBJECT_VNUM
            in _reset_object_vnums(reset)
        ]
        if len(matching_resets) != 1:
            continue
        if not (
            _source_ranked_route_program_candidate_allowed(
                route_program_candidate,
                character_level=character_level,
                source_world=world,
            )
            or _source_dwarven_sanctuary_route_gate_candidate_allowed(
                route_program_candidate,
                world,
                character_level=character_level,
            )
        ):
            continue
        if not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate,
            character_level=character_level,
        ):
            continue
        raw_max_move = state.get("max_move")
        if (
            isinstance(raw_max_move, (int, float))
            and not isinstance(raw_max_move, bool)
            and raw_max_move > 0
            and _source_candidate_required_move(candidate, state)
            + _SOURCE_ROUTE_MOVEMENT_RESERVE
            > int(raw_max_move)
        ):
            continue
        normalized_route = tuple(
            str(command).casefold().strip() for command in candidate.route
        )
        try:
            pick_index = normalized_route.index("unlock west")
        except ValueError:
            continue
        if (
            normalized_route.count("unlock west") != 1
            or pick_index + 1 >= len(normalized_route)
            or normalized_route[pick_index + 1] != "open west"
            or any(
                command.startswith("unlock ")
                for command in normalized_route
                if command != "unlock west"
            )
        ):
            continue
        door_rooms = _source_route_room_vnums(
            world,
            RECALL_VNUM,
            candidate.route[:pick_index],
        )
        if not door_rooms:
            continue
        door = world.rooms.get(door_rooms[-1])
        door_exit = door.exits.get("west") if door is not None else None
        if (
            door_exit is None
            or not door_exit.closed
            or not door_exit.locked
            or door_exit.key_vnum != _DWARVEN_SANCTUARY_DOOR_KEY_VNUM
        ):
            continue
        eligible.append(candidate)
    if not eligible:
        return None
    return min(
        eligible,
        key=lambda candidate: (
            len(candidate.route),
            candidate.mobile_vnum,
            candidate.room_vnum,
        ),
    ), (_DWARVEN_SANCTUARY_POTION_OBJECT_VNUM,)


def _source_dwarven_key_drop_room_is_safe(
    world: WorldSource,
    room_vnum: int,
) -> bool:
    """Reject source areas where scavengers or janitors can take a dropped key."""
    room = world.rooms.get(room_vnum)
    if room is None or not room.area_file:
        return False
    area_file = room.area_file.casefold()
    for mobile in world.mobiles.values():
        if mobile.area_file.casefold() != area_file:
            continue
        if mobile.act_flags & ACT_SCAVENGER:
            return False
        if any(
            "janitor" in special.casefold()
            for special in world.mobile_specials.get(mobile.vnum, ())
        ):
            return False
    return True


def _source_sanctuary_carrier_output_allowed(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    policy_id: str,
    character_level: int,
    source_world: WorldSource | None,
) -> bool:
    if policy_id in {
        _MORIA_SANCTUARY_FIXED_RESET_POLICY_ID,
        _MORIA_SANCTUARY_SECOND_FIXED_RESET_POLICY_ID,
    }:
        return True
    return _source_ranked_caster_output_can_cover(
        candidate,
        state,
        character_level=character_level,
        source_world=source_world,
        target_hp_ceiling=(
            candidate.estimated_base_hp_range[1]
            if candidate.estimated_base_hp_range[1] > 0
            else None
        ),
    )


def _select_source_consumable_candidate(
    state: Mapping[str, Any],
    *,
    spell_name: str,
    short_description: str | None,
    source_directory: Path,
    source_world: WorldSource | None = None,
    exclude_object_vnums: Collection[int] = (),
    require_unarmed: bool = False,
    character_class: str | None = None,
    subclass: str | None = None,
    required_reset: tuple[int, int] | None = None,
    level_ceiling_offset: int = 1,
    allowed_target_specials: Collection[str] = (),
) -> tuple[HuntCandidate, tuple[int, ...]] | None:
    """Choose a bounded carrier by source effect rather than mobile identity."""
    character_level = _level(state)
    if character_level < 2 or not source_directory.is_dir():
        return None
    if not isinstance(level_ceiling_offset, int) or not 0 <= level_ceiling_offset <= 5:
        raise ValueError("source consumable level ceiling must be between 0 and 5")
    world = source_world or load_world_source(
        source_directory,
        include_all_areas=True,
    )
    required_spell = spell_name.casefold()
    required_description = (
        normalize_item_name(short_description)
        if short_description
        else None
    )
    source_character_class = character_class or state.get("character_class")
    source_subclass = subclass or state.get("subclass")
    resource_item_types = {
        ITEM_POTION,
        ITEM_PILL,
        ITEM_SCROLL,
        ITEM_WAND,
        ITEM_STAFF,
    }
    excluded_object_vnums = {int(vnum) for vnum in exclude_object_vnums}
    object_vnums = {
        item.vnum
        for item in world.objects.values()
        if item.item_type in resource_item_types
        and item.vnum not in excluded_object_vnums
        and (
            required_description is None
            or normalize_item_name(item.short_description)
            == required_description
        )
        and resource_activation_for_object(
            item,
            effect=required_spell,
        )
        is not None
        and (
            item.item_type not in {ITEM_POTION, ITEM_PILL}
            or not (
                set(
                    potion_spell_names(item)
                    if item.item_type == ITEM_POTION
                    else pill_spell_names(item)
                )
                & _UNSAFE_SELF_POTION_SPELLS
            )
        )
        and (
            not source_character_class
            or character_can_use_item(
                item,
                character_class=str(source_character_class),
                subclass=(
                    str(source_subclass) if source_subclass is not None else None
                ),
                character_alignment=_state_alignment(state),
            )
        )
        and _source_resource_command_keyword(
            world,
            item,
            required_spell=required_spell,
        )
        is not None
    }
    if not object_vnums:
        return None
    max_hp = state.get("max_hp")
    candidates = rank_hunt_candidates(
        world,
        character_level=character_level,
        include_below_band=True,
        character_max_hp=(
            int(max_hp)
            if isinstance(max_hp, (int, float)) and max_hp > 0
            else None
        ),
        character_alignment=_state_alignment(state),
        include_level_ceiling_candidates=True,
        level_ceiling_offset=level_ceiling_offset,
        include_all_areas=True,
        required_loot_object_vnums=object_vnums,
    )
    eligible: list[tuple[HuntCandidate, tuple[int, ...]]] = []
    for candidate in candidates:
        caerlin_staff_endpoint = _source_caerlin_staff_candidate_shape_allowed(
            candidate,
            world,
        )
        if caerlin_staff_endpoint:
            purse = known_purse(state.get("currencies"))
            if (
                purse is None
                or purse > ECONOMIC_HUNT_MAX_COPPER
                or not passive_economic_hunt_mobile(
                    world,
                    _CAERLIN_STAFF_ROUTE_ECONOMIC_MOBILE_VNUM,
                    level=character_level,
                )
            ):
                continue
            candidate_for_selection = replace(
                candidate,
                status="caution",
                autonomy_rejections=tuple(
                    sorted(
                        set(candidate.autonomy_rejections)
                        - {
                            "an economic special mobile can reach the route"
                        }
                    )
                ),
                route_economic_hunt_mobile_vnums=(
                    _CAERLIN_STAFF_ROUTE_ECONOMIC_MOBILE_VNUM,
                ),
                route_economic_source_rejections=(
                    "an economic special mobile can reach the route",
                ),
            )
        else:
            candidate_for_selection = candidate
        if required_reset is not None and (
            candidate_for_selection.mobile_vnum,
            candidate_for_selection.room_vnum,
        ) != required_reset:
            continue
        if (
            required_spell == "sanctuary"
            and _source_ranked_xp_loss_for_stop(
                state,
                mobile_vnum=candidate_for_selection.mobile_vnum,
                room_vnum=candidate_for_selection.room_vnum,
            )
            is not None
        ):
            # A same-boot XP loss closes this exact carrier. Retrying it can
            # repeat a known failure even when the surrounding policy is
            # still eligible to choose a different resource route.
            continue
        reset = next(
            (
                value
                for value in world.mob_resets
                if value.mobile_vnum == candidate_for_selection.mobile_vnum
                and value.room_vnum == candidate_for_selection.room_vnum
                and any(
                    object_vnum in object_vnums
                    for object_vnum in _reset_object_vnums(value)
                )
            ),
            None,
        )
        if reset is None:
            continue
        matching_vnums = tuple(
            dict.fromkeys(
                object_vnum
                for object_vnum in _reset_object_vnums(reset)
                if object_vnum in object_vnums
            )
        )
        remaining_rejections = set(
            candidate_for_selection.autonomy_rejections
        ).difference(
            {
                "target reset capacity exceeds one",
                # Utility scavengers are resource endpoints rather than
                # ordinary XP targets. Required-loot acquisition still has
                # its own exact carrier, isolation, and live confirmation
                # gates, so this source-role marker is cleared only here.
                _SOURCE_NONCOMBAT_RESOURCE_CARRIER_REJECTION,
                # Required-loot acquisition has its own exact carrier,
                # isolation, health, and item-confirmation gates. A large
                # below-band crowd is still rejected for ordinary XP hunts,
                # but must not make every source-backed healing reserve
                # unreachable when the carrier itself is otherwise safe.
                "route crosses a large below-band aggressive crowd",
            }
        )
        allowed_specials = {
            str(special).casefold().strip()
            for special in allowed_target_specials
            if str(special).strip()
        }
        if allowed_specials and {
            str(special).casefold().strip()
            for special in candidate_for_selection.specials
        } != allowed_specials:
            continue
        for special in allowed_specials:
            remaining_rejections.discard(
                f"target has special procedure {special}"
            )
        if caerlin_staff_endpoint:
            if not _audited_source_special_candidate_allowed(
                candidate_for_selection,
                state=state,
                character_max_hp=(
                    int(max_hp)
                    if isinstance(max_hp, (int, float)) and max_hp > 0
                    else None
                ),
                source_world=world,
            ):
                continue
            remaining_rejections.discard(
                f"target has special procedure {_CAERLIN_STAFF_SPECIAL}"
            )
        if remaining_rejections:
            continue
        if require_unarmed and candidate_for_selection.equipped_weapons:
            # A sanctuary carrier is itself an unprotected fight when the
            # reserve is empty. Do not spend the last safe recovery boundary
            # on an armed source mobile.
            continue
        # A one- or two-capacity reset is admissible only as an exact-one
        # live probe.  Check both the reset's maximum count and the number of
        # reset entries in the room; omitting the former can admit a source
        # reset that loads three same-prototype mobiles at the endpoint.
        if (
            candidate_for_selection.source_spawn_limit > 2
            or candidate_for_selection.room_spawn_count > 2
        ):
            continue
        if not _source_ranked_route_has_static_safe_live_navigation_path(
            world,
            candidate_for_selection,
            character_level=character_level,
        ):
            continue
        eligible.append((candidate_for_selection, matching_vnums))
    if not eligible:
        return None
    return min(
        eligible,
        key=lambda value: (
            len(value[0].route),
            value[0].room_spawn_count,
            value[0].mobile_vnum,
            value[0].room_vnum,
        ),
    )


def _source_ranked_sanctuary_candidate_research_open(
    state: Mapping[str, Any],
    candidate: HuntCandidate,
    *,
    policy_id: str | None = None,
) -> bool:
    """Keep an exact same-boot Sanctuary carrier miss closed."""
    if _source_ranked_xp_loss_for_stop(
        state,
        mobile_vnum=candidate.mobile_vnum,
        room_vnum=candidate.room_vnum,
    ) is not None:
        return False
    policy_id = policy_id or _source_ranked_policy_id(
        candidate,
        character_level=_level(state),
    )
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, Mapping):
        return True
    result_boot_id = result.get("boot_id")
    current_boot_id = state.get("world_boot_id")
    # A historical result without both boot identities cannot prove that the
    # carrier disappeared on this reboot or became available after one. Keep
    # it closed until a fresh live/source-bound result supplies that boundary.
    if not result_boot_id or not current_boot_id:
        return False
    if result_boot_id != current_boot_id:
        return True
    result_source_revision = result.get(_SOURCE_REVISION_KEY)
    current_source_revision = state.get(_SOURCE_REVISION_KEY)
    if (
        result_source_revision
        and current_source_revision
        and result_source_revision != current_source_revision
    ):
        return True
    dispatch_repair = state.get(_SOURCE_RESOURCE_DISPATCH_CONTRACT_REPAIR_KEY)
    if (
        policy_id
        == _SOURCE_RANKED_OLYMPUS_HEPHAESTUS_SANCTUARY_POLICY.policy_id
        and isinstance(dispatch_repair, Mapping)
        and dispatch_repair.get("status") == "invalidated"
        and dispatch_repair.get("policy_id") == policy_id
        and dispatch_repair.get("boot_id") == current_boot_id
        and dispatch_repair.get("source_revision")
        == current_source_revision
        and result.get("required_object_acquired") is True
    ):
        try:
            result_objects = {
                int(value)
                for value in (result.get("required_object_vnums") or ())
            }
            observed_objects = {
                int(value)
                for value in (
                    dispatch_repair.get("observed_object_vnums") or ()
                )
            }
            expected_objects = {
                int(value)
                for value in (
                    dispatch_repair.get("expected_object_vnums") or ()
                )
            }
        except (TypeError, ValueError):
            result_objects = observed_objects = expected_objects = set()
        if (
            result_objects
            and observed_objects
            and expected_objects
            and result_objects == observed_objects
            and observed_objects != expected_objects
        ):
            # A historical generic executor claimed the wrong object. The
            # receipt remains useful audit evidence, but it must not close the
            # exact Hephaestus reset that still needs a fresh live attempt.
            return True
    if result.get("required_object_acquired") is True:
        return False
    if result.get("completed_kill") is True:
        return False
    return not any(
        (
            result.get("absent") is True,
            result.get("crowded") is True,
            result.get("crowd_exhausted") is True,
            result.get("fatal_failure") is True,
            result.get("unattackable") is True,
            result.get("target_vnum_mismatch") is True,
            result.get("viable") is False,
            bool(result.get("route_hazard")),
        )
    )


def _select_source_ranked_olympus_sanctuary_candidate(
    state: Mapping[str, Any],
    *,
    source_directory: Path,
    source_world: WorldSource | None,
) -> tuple[HuntCandidate, tuple[int, ...]] | None:
    """Select the exact Olympus Alchemist Sanctuary staff reset."""
    selection = _select_source_consumable_candidate(
        state,
        spell_name="sanctuary",
        short_description="an ivory staff",
        source_directory=source_directory,
        source_world=source_world,
        require_unarmed=True,
        required_reset=(
            _OLYMPUS_SANCTUARY_CARRIER_MOBILE_VNUM,
            _OLYMPUS_SANCTUARY_CARRIER_ROOM_VNUM,
        ),
    )
    if selection is None:
        return None
    candidate, object_vnums = selection
    if (
        candidate.mobile_vnum != _OLYMPUS_SANCTUARY_CARRIER_MOBILE_VNUM
        or candidate.room_vnum != _OLYMPUS_SANCTUARY_CARRIER_ROOM_VNUM
        or candidate.area_file.casefold() != "olympus.are"
        or _OLYMPUS_SANCTUARY_STAFF_OBJECT_VNUM not in object_vnums
    ):
        return None
    if not _source_ranked_sanctuary_candidate_research_open(
        state,
        candidate,
        policy_id=_SOURCE_RANKED_OLYMPUS_SANCTUARY_POLICY.policy_id,
    ):
        return None
    if not _source_sanctuary_carrier_output_allowed(
        candidate,
        state,
        policy_id=_SOURCE_RANKED_OLYMPUS_SANCTUARY_POLICY.policy_id,
        character_level=_level(state),
        source_world=source_world,
    ):
        return None
    return candidate, object_vnums


